def svg_path(d):
    """Tiny SVG path reader (M/m, c, l, z) for the drawn icons."""
    import re
    from PyQt5.QtGui import QPainterPath
    path = QPainterPath(); x = y = 0.0; cmd = None
    toks = re.findall(r'[MmCcLlZz]|-?\d*\.?\d+', d); i = 0
    while i < len(toks):
        t = toks[i]
        if t in 'MmCcLlZz': cmd = t; i += 1
        if cmd in 'Zz': path.closeSubpath(); continue
        n = [float(v) for v in toks[i:i+(6 if cmd in 'Cc' else 2)]]; i += len(n)
        if cmd == 'M': x, y = n; path.moveTo(x, y); cmd = 'L'
        elif cmd == 'm': x, y = x+n[0], y+n[1]; path.moveTo(x, y); cmd = 'l'
        elif cmd == 'l': x, y = x+n[0], y+n[1]; path.lineTo(x, y)
        elif cmd == 'L': x, y = n; path.lineTo(x, y)
        elif cmd == 'c': path.cubicTo(x+n[0], y+n[1], x+n[2], y+n[3], x+n[4], y+n[5]); x, y = x+n[4], y+n[5]
        elif cmd == 'C': path.cubicTo(*n); x, y = n[4], n[5]
    return path

def havuz_icon(height=24):
    """PDF Havuzu: a flying pigeon carrying a PDF letter in its beak."""
    from PyQt5.QtGui import QFont
    k = 4; w, h = 120, 96
    pix = QPixmap(w*k, h*k); pix.fill(Qt.transparent)
    p = QPainter(pix); p.setRenderHint(QPainter.Antialiasing); p.scale(k, k); p.setPen(Qt.NoPen)
    p.setBrush(QColor('#edf4ff')); p.drawPath(svg_path('M14 54c10-2 20 0 28 6 6-14 18-22 32-22-6 6-10 12-12 20 10-2 18 0 24 6-14 4-30 6-44 4-10 6-22 6-28-2 0 0-4-8 0-12z'))
    p.setBrush(QColor('#b9d4f3')); p.drawPath(svg_path('M44 58c-8-14-6-28 4-40 6 12 8 26 4 38z'))
    p.setBrush(QColor('#dbe8f8')); p.drawPath(svg_path('M58 42c4-14 14-24 28-28-2 14-10 26-24 32z'))
    p.setBrush(QColor('#122034')); p.drawEllipse(QPointF(82, 58), 2.4, 2.4)
    p.setBrush(QColor('#ffb02e')); p.drawPolygon(QPolygonF([QPointF(88, 60), QPointF(95, 62), QPointF(88, 65)]))
    p.save(); p.translate(104, 70); p.rotate(10); p.translate(-104, -70)
    p.setBrush(QColor('#fff8e6')); p.setPen(QPen(QColor('#c9a96b'), 1.4)); p.drawRoundedRect(QRectF(92, 60, 24, 17), 2, 2)
    p.drawPolyline(QPolygonF([QPointF(92, 60), QPointF(104, 69), QPointF(116, 60)]))
    p.setPen(Qt.NoPen); p.setBrush(QColor('#e23b4d')); p.drawRoundedRect(QRectF(96, 70, 16, 6), 1, 1)
    f = QFont('DejaVu Sans'); f.setPixelSize(5); f.setBold(True); p.setFont(f); p.setPen(QColor('white'))
    p.drawText(QRectF(96, 70, 16, 6), Qt.AlignCenter, 'PDF'); p.restore(); p.end()
    pix = pix.copy(QRect(8*k, 12*k, 112*k, 72*k))   # trim empty margins so the bird fills the button
    return QIcon(pix.scaledToHeight(height*2, Qt.SmoothTransformation))

UI_FONT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'fonts')
_FONTS = {}
def ui_fonts():
    """Pakette gelen yazı tipleri (bir kez yüklenir): Poppins arayüz yazısı, Phosphor ikonları, Patrick Hand (Atlas cevapları, el yazısı; OFL)."""
    if not _FONTS and QApplication.instance() is not None:
        from PyQt5.QtGui import QFontDatabase
        for name in ('Poppins-Regular', 'Poppins-Medium', 'Poppins-Bold', 'Phosphor-Fill', 'PatrickHand-Regular'):
            path = os.path.join(UI_FONT_DIR, name + '.ttf'); fam = None
            if os.path.isfile(path):
                i = QFontDatabase.addApplicationFont(path)
                fams = QFontDatabase.applicationFontFamilies(i) if i >= 0 else []
                fam = fams[0] if fams else None
            _FONTS[name] = fam
    return _FONTS

