def _drop_icons():   # ikon önbelleği Qt kapanmadan boşaltılır (kapanışta çökmesin)
    _ICONS.clear()
import atexit; atexit.register(_drop_icons)
def premium_icon(label, size=64):
    app = QApplication.instance()
    if app is not None and not getattr(app, '_umal_icons_hook', False):
        app.aboutToQuit.connect(_drop_icons); app._umal_icons_hook = True
    g = PREMIUM_ICONS.get(label)
    fam = ui_fonts().get('Phosphor-Fill') if g else None
    if not g or not fam: return None
    if label in _ICONS: return _ICONS[label]
    from PyQt5.QtGui import QFont, QLinearGradient, QRadialGradient
    code, color = g; pix = QPixmap(size, size); pix.fill(Qt.transparent)
    p = QPainter(pix); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing)
    r = QRectF(2, 2, size-4, size-4); base = QColor(color)
    grad = QLinearGradient(r.topLeft(), r.bottomLeft()); grad.setColorAt(0, base.lighter(128)); grad.setColorAt(1, base.darker(118))
    p.setPen(QPen(QColor(255, 255, 255, 95), size*.035)); p.setBrush(grad); p.drawEllipse(r)
    gloss = QRadialGradient(QPointF(size*.34, size*.24), size*.5); gloss.setColorAt(0, QColor(255, 255, 255, 150)); gloss.setColorAt(.55, QColor(255, 255, 255, 25)); gloss.setColorAt(1, QColor(255, 255, 255, 0))
    p.setPen(Qt.NoPen); p.setBrush(gloss); p.drawEllipse(r)
    f = QFont(fam); f.setPixelSize(int(size*.5)); p.setFont(f); p.setPen(QColor(0, 0, 0, 55)); p.drawText(r.translated(0, size*.025), Qt.AlignCenter, chr(code))
    p.setPen(QColor('#ffffff')); p.drawText(r, Qt.AlignCenter, chr(code)); p.end()
    _ICONS[label] = QIcon(pix); return _ICONS[label]

def glyph_style(code, px, extra=''):
    """Düğmede ikon fontundan tek işaret (ok, artı, eksi): yeni ikonlarla aynı aileden."""
    fam = ui_fonts().get('Phosphor-Fill')
    return (chr(code), ('font-family:"%s";font-size:%dpx;font-weight:normal;' % (fam, px) if fam else 'font-size:%dpx;' % px) + extra)

