COLOR_TOOLS = ('pen','highlight','line','arrow','rect','circle','dash','laser')
SHAPE_TOOLS = ('line','arrow','rect','circle','triangle','dash')   # grouped under the Şekiller button
DASH_PATTERN = (2, 3)   # in pen widths; with round caps: dash 3w, gap 2w

def stroke_pen(s, offset=0):
    pen = QPen(QColor(s['color']), s['width'], Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)
    if s.get('dash'):
        pen.setDashPattern(list(DASH_PATTERN)); pen.setDashOffset(offset / max(s['width'], .1))
    return pen

PEN_STYLES = (('fluid','Akıcı'),('laser','Neon (söner)'))
# Only these two tips are offered; writing made earlier with Normal, Tebeşir,
# Keçeli, Kurşun kalem or Neon still draws exactly as before.
# 'laser' in the tips row is the Neon kalem tool (glows, then fades; not saved).
# Tebeşir was removed from the row; old chalk writing still draws as before.
STYLE_SPAN = {'fluid':1, 'felt':1.7, 'chalk':1.6, 'pencil':1, 'neon':5.5, 'laser':8}   # drawn width ÷ pen width
STYLED_TOOLS = ('pen','line','rect','circle','laser')   # snapped shapes keep the style

def fluid_outline(s):
    """Akıcı kalem: outline of a stroke whose width follows the stored
    per-point factors (speed + tapered ends), as one polygon."""
    pts, ws, half = s['points'], s['w'], s['width']/2
    if len(pts) < 2: return None
    left, right = [], []
    for i, (x, y) in enumerate(pts):
        a, b = pts[max(0, i-1)], pts[min(len(pts)-1, i+1)]
        dx, dy = b[0]-a[0], b[1]-a[1]; d = math.hypot(dx, dy)
        nx, ny = (-dy/d, dx/d) if d > 1e-6 else (0, 1)
        r = max(.25, half*ws[i]); left.append([x+nx*r, y+ny*r]); right.append([x-nx*r, y-ny*r])
    return left+right[::-1]

def mix_color(c, other, t):
    c, o = QColor(c), QColor(other)
    return QColor.fromRgbF(c.redF()+(o.redF()-c.redF())*t, c.greenF()+(o.greenF()-c.greenF())*t, c.blueF()+(o.blueF()-c.blueF())*t)

_masks = {}
def style_mask(kind):
    """Soft grain (alpha only) laid over a whole chalk / pencil stroke at once.
    Coarse blotches + fine speckle, so it reads as chalk dust or graphite
    on the board instead of hard pixel noise."""
    if kind not in _masks:
        import random
        rng = random.Random(7 if kind == 'chalk' else 23); N = 128
        def noise(n):
            img = QImage(n, n, QImage.Format_Grayscale8)
            for y in range(n):
                for x in range(n): img.setPixel(x, y, QColor.fromHsv(0, 0, rng.randrange(256)).rgb())
            return img
        def tile(img):   # 3×3 tiling before smoothing keeps the edges seamless
            big = QImage(img.width()*3, img.height()*3, QImage.Format_Grayscale8); p = QPainter(big)
            for i in range(3):
                for j in range(3): p.drawImage(i*img.width(), j*img.height(), img)
            p.end(); s = big.scaled(N*3, N*3, Qt.IgnoreAspectRatio, Qt.SmoothTransformation); return s.copy(N, N, N, N)
        coarse = tile(noise(N//8)); mid = tile(noise(N//3)); fine = noise(N)
        out = QImage(N, N, QImage.Format_ARGB32_Premultiplied)
        for y in range(N):
            for x in range(N):
                c, m, f = QColor(coarse.pixel(x, y)).red()/255, QColor(mid.pixel(x, y)).red()/255, QColor(fine.pixel(x, y)).red()/255
                if kind == 'chalk': a = .9*c + .6*m + .55*f - .28
                else: a = .62 + .18*m + .28*f
                a = max(0., min(1., a)); out.setPixel(x, y, QColor(255, 255, 255, int(a*255)).rgba())
        _masks[kind] = QPixmap.fromImage(out)
    return _masks[kind]

def style_passes(s):
    """How a styled stroke is painted: a list of (pen, opacity, mask) passes.
    Each pass is drawn solid on its own layer and only then made see-through
    or grainy, so overlapping pieces never darken or speckle."""
    st = s.get('style'); w = s['width']; c = QColor(s['color'])
    if s['tool'] not in STYLED_TOOLS or st not in STYLE_SPAN or st == 'fluid': return None
    pen = lambda col, k: QPen(QColor(col), max(.6, w*k), Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)
    if st == 'felt': return [(pen(c, 1.7), 1, None)]
    if st == 'chalk': return [(pen(mix_color(c, '#ffffff', .12), 1.6), .95, 'chalk')]
    if st == 'pencil': return [(pen(mix_color(c, '#4a4f57', .35), .85), 1, 'pencil')]
    if st == 'laser':   # Neon kalem: geniş ışıma + beyaz-sıcak çekirdek
        return [(pen(c, 8), .07, None), (pen(c, 5.5), .12, None), (pen(c, 3.4), .28, None), (pen(c, 1.8), .9, None),
                (pen(mix_color(c, '#ffffff', .8), .65), 1, None)]
    return [(pen(c, 5.5), .16, None), (pen(c, 3), .42, None), (pen('#ffffff', .7), 1, None), (pen(c, .35), .95, None)]

def arrow_points(a, b, width):
    """Ok: the shaft and both head strokes as one polyline (a plain 'line'
    stroke, so drawing, erasing, saving and the PDF work unchanged)."""
    d = math.hypot(b[0]-a[0], b[1]-a[1])
    if d < 3: return [a, b]
    ux, uy = (b[0]-a[0])/d, (b[1]-a[1])/d; L = min(d*.45, max(12, width*4.5)); s, c = math.sin(math.radians(28)), math.cos(math.radians(28))
    h1 = [b[0]-L*(ux*c-uy*s), b[1]-L*(uy*c+ux*s)]; h2 = [b[0]-L*(ux*c+uy*s), b[1]-L*(uy*c-ux*s)]
    return [a, b, h1, b, h2]

def stroke_path(pts):
    from PyQt5.QtGui import QPainterPath
    path = QPainterPath(QPointF(*pts[0]))
    for pt in pts[1:]: path.lineTo(QPointF(*pt))
    if len(pts) == 1: path.lineTo(QPointF(pts[0][0]+.01, pts[0][1]))
    return path

def apply_mask(q, kind, r):
    """Cut the grain into a layer; q is set up in widget pixels (r = area)."""
    from PyQt5.QtGui import QBrush
    q.save(); q.resetTransform(); q.translate(-r.x(), -r.y())
    q.setCompositionMode(QPainter.CompositionMode_DestinationIn); q.fillRect(QRectF(r), QBrush(style_mask(kind))); q.restore()

def paint_passes(p, path, passes, clip, dpr=1):
    """Finished styled stroke: every pass on a small clear layer, then laid
    over the page — the same result as while it was being written."""
    t = p.transform()
    for pen, opacity, mask in passes:
        if opacity >= 1 and not mask:   # plain opaque pass: straight onto the page
            p.setPen(pen); p.drawPath(path); continue
        pad = pen.widthF()/2 + 2
        r = (t.mapRect(path.boundingRect().adjusted(-pad, -pad, pad, pad)) & clip).toAlignedRect()
        if r.isEmpty(): continue
        img = QImage(max(1, int(r.width()*dpr)), max(1, int(r.height()*dpr)), QImage.Format_ARGB32_Premultiplied)
        img.setDevicePixelRatio(dpr); img.fill(Qt.transparent)
        q = QPainter(img); q.setRenderHint(QPainter.Antialiasing)
        q.translate(-r.x(), -r.y()); q.setTransform(t, True); q.setPen(pen); q.drawPath(path)
        if mask: apply_mask(q, mask, r)
        q.end()
        p.save(); p.resetTransform(); p.setOpacity(p.opacity()*opacity); p.drawImage(QRectF(r), img); p.restore()

def style_icon(key, size=26, ink='#ffffff'):
    pix = QPixmap(size*2, size*2); pix.fill(Qt.transparent)
    p = QPainter(pix); p.setRenderHint(QPainter.Antialiasing); p.scale(2, 2)
    s = dict(tool='pen', color=ink, width=size/10 if key != 'neon' else size/14,
             points=[[size*.16+i*size*.68/20, size*.5+math.sin(i/20*2*math.pi)*size*.2] for i in range(21)])
    if key != 'normal': s['style'] = key
    if key == 'fluid': s['width'] = size/8
    passes = style_passes(s); path = stroke_path(s['points'])
    if passes: paint_passes(p, path, passes, QRectF(0, 0, size*2, size*2))
    elif s.get('w'):
        p.setPen(Qt.NoPen); p.setBrush(QColor(ink)); p.drawPolygon(QPolygonF([QPointF(*q) for q in fluid_outline(s)]), Qt.WindingFill)
    else: p.setPen(stroke_pen(s)); p.drawPath(path)
    p.end(); return QIcon(pix)

def paint_tool_buttons(buttons, labels, tool, color):
    """The selected drawing tool's button takes the current ink colour, so
    the chosen colour is always visible on the tool itself."""
    q = QColor(color); light = .299*q.redF()+.587*q.greenF()+.114*q.blueF() > .6
    ink = '#122034' if light else '#ffffff'
    for key, b in buttons.items():
        if key == tool and key in COLOR_TOOLS:
            b.setStyleSheet('QPushButton:checked{background:%s;color:%s;border:3px solid #ffffff;}' % (color, ink))
            b.setIcon(tool_icon(labels[key], ink))
        else:
            b.setStyleSheet(''); b.setIcon(tool_icon(labels[key]))

BOARD_FILLS = {'dark': (.025,.065,.13), 'green': (.13,.30,.22), 'black': (.07,.07,.08),
               'kt_kareli': (.114,.149,.176), 'kt_gece': (.043,.102,.2), 'kt_yesil': (.102,.208,.161), 'kt_klasik': (.169,.353,.267)}
def kt_desen(bg, x0, y0, x1, y1):
    """K-351: kara tahta deseni (sayfa birimi): [('c', x1, y1, x2, y2, rgb, opaklık, kalınlık) çizgi | ('n', x, y, r, rgb, opaklık) nokta |
    ('e', cx, cy, rx, ry, rgb, opaklık) silinmiş tebeşir izi]. Hep aynı çıkar (540 birimlik dilimlerde sabit tohum): PDF ve ekran aynı."""
    import random as _r
    out = []
    if bg == 'kt_kareli':
        a = 24
        for x in range(int(x0//a)*a, int(x1) + a, a): out.append(('c', x, y0, x, y1, (1, 1, 1), .07, .7))
        for y in range(int(y0//a)*a, int(y1) + a, a): out.append(('c', x0, y, x1, y, (1, 1, 1), .07, .7))
        if x0 <= 48 <= x1: out.append(('c', 48, y0, 48, y1, (1, .54, .54), .22, 1.25))
        return out
    if bg == 'kt_gece':
        a = 20
        for x in range(max(a, int(x0//a)*a), int(x1) + a, a):
            for y in range(max(a, int(y0//a)*a), int(y1) + a, a): out.append(('n', x, y, .8, (.5, .85, 1), .16))
    for dilim in range(int(y0//540), int(y1//540) + 1):
        rnd = _r.Random(dilim*7919 + sum(map(ord, bg))*104729)
        if bg == 'kt_gece':
            for _ in range(18):
                x, y = rnd.uniform(0, 960), dilim*540 + rnd.uniform(0, 540)
                if x0 - 2 <= x <= x1 + 2 and y0 - 2 <= y <= y1 + 2: out.append(('n', x, y, rnd.choice((.5, .5, .7, 1.0)), (.75, .91, 1), rnd.choice((.18, .25, .35))))
        else:
            for _ in range(6):
                cx, cy, rx, ry = rnd.uniform(40, 920), dilim*540 + rnd.uniform(30, 510), rnd.uniform(80, 210), rnd.uniform(15, 35)
                if cx + rx >= x0 and cx - rx <= x1 and cy + ry >= y0 and cy - ry <= y1: out.append(('e', cx, cy, rx, ry, (1, 1, 1), .025))
    return out
BLANK_H = 1080   # yeni boş tahta: iki ekran boyu (sonsuz; yazdıkça uzar)
def make_board(background='white', width=960, height=540):
    doc = fitz.open(); page = doc.new_page(width=width,height=height)
    if background in BOARD_FILLS:
        page.draw_rect(page.rect,color=None,fill=BOARD_FILLS[background])
        if background in KARA_TAHTALAR:
            gruplar = {}   # aynı renk / opaklıktakiler tek yol: PDF hafif kalır
            ds_ = kt_desen(background, 0, 0, width, height)
            if background == 'kt_gece':   # K-422: ızgara noktaları tek tek daire değil, satır başına bir noktalı çizgi (uzun tahtada uzatma 10 sn donduruyordu)
                izg = lambda d: d[0] == 'n' and d[3] == .8 and d[4] == (.5, .85, 1) and d[5] == .16
                xs_ = sorted({d[1] for d in ds_ if izg(d)}); ys_ = sorted({d[2] for d in ds_ if izg(d)})
                if xs_ and ys_:
                    sh = page.new_shape()
                    for y_ in ys_: sh.draw_line((xs_[0], y_), (xs_[-1], y_))
                    sh.finish(color=(.5, .85, 1), width=1.6, stroke_opacity=.16, dashes='[0 20] 0', lineCap=1); sh.commit()
                ds_ = [d for d in ds_ if not izg(d)]
            for d in ds_:
                anahtar = (d[0], d[5], d[6], d[7]) if d[0] == 'c' else (d[0], d[4], d[5]) if d[0] == 'n' else (d[0], d[5], d[6])
                gruplar.setdefault(anahtar, []).append(d)
            for anahtar, ds in gruplar.items():
                sh = page.new_shape()
                for d in ds:
                    if d[0] == 'c': sh.draw_line((d[1], d[2]), (d[3], d[4]))
                    elif d[0] == 'n': sh.draw_circle((d[1], d[2]), d[3])
                    else: sh.draw_oval(fitz.Rect(d[1]-d[3], d[2]-d[4], d[1]+d[3], d[2]+d[4]))
                if anahtar[0] == 'c': sh.finish(color=anahtar[1], width=anahtar[3], stroke_opacity=anahtar[2])
                else: sh.finish(color=None, fill=anahtar[1], fill_opacity=anahtar[2])
                sh.commit()
    elif background == 'grid':
        shape = page.new_shape()
        for x in range(0,int(width)+1,24): shape.draw_line((x,0),(x,height))
        for y in range(0,int(height)+1,24): shape.draw_line((0,y),(width,y))
        shape.finish(color=(.55,.64,.76),width=.9); shape.commit()
    elif background == 'dots':
        shape = page.new_shape()
        for x in range(24,int(width),24):
            for y in range(24,int(height),24): shape.draw_circle((x,y),1.6)
        shape.finish(color=None,fill=(.40,.50,.64)); shape.commit()
    doc.set_metadata({'title':APP_NAME,'keywords':'UMAL-board:'+background})
    return doc

def nib_outline(stroke):
    """Same directional nib geometry for the screen and vector PDF export."""
    if stroke.get('w') and len(stroke['w']) == len(stroke['points']): return fluid_outline(stroke)
    if stroke['tool'] != 'pen' or stroke.get('nib') not in ('fountain','marker'): return None
    pts = stroke['points']; width = stroke['width']; nib = stroke['nib']
    if len(pts) == 1 or all(math.dist(pts[0],p)<.01 for p in pts):
        x,y = pts[0]; radius = width*(1 if nib=='marker' else .55)
        return [[x+radius*math.cos(i*math.pi/12),y+radius*math.sin(i*math.pi/12)] for i in range(24)]
    left,right = [],[]
    distances = [0.0]
    for a,b in zip(pts,pts[1:]): distances.append(distances[-1]+math.dist(a,b))
    for i,(x,y) in enumerate(pts):
        a,b = pts[max(0,i-2)],pts[min(len(pts)-1,i+2)]
        dx,dy = b[0]-a[0],b[1]-a[1]; length = math.hypot(dx,dy)
        nx,ny = (-dy/length,dx/length) if length>.0001 else (0,1)
        angle = abs((nx+ny)*.70710678)
        if nib == 'fountain':
            taper = .35+.65*min(1,distances[i]/max(width*2,1),(distances[-1]-distances[i])/max(width*2,1))
            half = width*(.22+.65*angle)*taper
        else: half = width*(.65+.55*angle)
        left.append([x+nx*half,y+ny*half]); right.append([x-nx*half,y-ny*half])
    return left+right[::-1]

def catmull_rom(p0, p1, p2, p3, steps):
    """Centripetal Catmull–Rom from p1 to p2 (p1 excluded, p2 included).
    It passes through the pen samples themselves, so small loops and letter
    joins keep their size, and the centripetal form makes no cusps or loops
    at sharp turns."""
    def knot(t, a, b):
        return t + max(1e-6, math.hypot(b[0]-a[0], b[1]-a[1])) ** .5
    t0 = 0.0; t1 = knot(t0, p0, p1); t2 = knot(t1, p1, p2); t3 = knot(t2, p2, p3)
    out = []
    for k in range(1, steps+1):
        t = t1 + (t2-t1)*k/steps
        def lerp(a, b, ta, tb): u = (t-ta)/(tb-ta); return (a[0]+(b[0]-a[0])*u, a[1]+(b[1]-a[1])*u)
        a1 = lerp(p0, p1, t0, t1); a2 = lerp(p1, p2, t1, t2); a3 = lerp(p2, p3, t2, t3)
        b1 = lerp(a1, a2, t0, t2); b2 = lerp(a2, a3, t1, t3)
        c = lerp(b1, b2, t1, t2); out.append([c[0], c[1]])
    out[-1] = list(p2)
    return out

def cr_steps(a, b, scale):
    return max(2, min(24, int(math.hypot(b[0]-a[0], b[1]-a[1])*scale/1.5)+1))

def cr_points(raw, scale):
    """Whole-stroke reference of Board.smooth_append() for Akıcı (tests)."""
    if len(raw) < 3: return [list(p) for p in raw]
    pts = [list(raw[0])]
    for n in range(3, len(raw)+1):
        p0 = raw[n-4] if n >= 4 else raw[n-3]
        pts.extend(catmull_rom(p0, raw[n-3], raw[n-2], raw[n-1], cr_steps(raw[n-3], raw[n-2], scale)))
    pts.append(list(raw[-1])); return pts

def smooth_points(raw):
    """Quadratic midpoint interpolation suppresses jitter without sharp corners."""
    if len(raw) < 3: return list(raw)
    result = [raw[0]]
    start = raw[0]
    for i in range(1,len(raw)-1):
        control = raw[i]
        end = [(raw[i][j]+raw[i+1][j])/2 for j in (0,1)]
        steps = max(2,min(16,int(math.hypot(end[0]-start[0],end[1]-start[1])/1.2)+1))
        for k in range(1,steps+1):
            t = k/steps
            result.append([(1-t)**2*start[j]+2*(1-t)*t*control[j]+t*t*end[j] for j in (0,1)])
        start = end
    result.append(raw[-1])
    return result

def export_document(doc, marks, target, solutions=None):
    """Write atomically; keep original PDF and its existing annotations intact."""
    out = fitz.open(stream=doc.tobytes(), filetype='pdf')
    try:
        if solutions is not None:
            if SOLUTIONS_FILE in out.embfile_names(): out.embfile_del(SOLUTIONS_FILE)
            if solutions:
                data = {k: dict(v, marks={str(p): m for p, m in v['marks'].items()}) for k, v in solutions.items()}
                out.embfile_add(SOLUTIONS_FILE, json.dumps(data, ensure_ascii=False).encode('utf-8'),
                                desc='Ümraniye Merkez Anadolu Lisesi soru çözümleri')
        for n, strokes in marks.items():
            page = out[n]
            for s in strokes:
                if s['tool'] == 'geo':   # koordinat düzlemi: görünmez taşıyıcı + çizimin kendisi
                    a = page.add_ink_annot([[(1, 1), (1.01, 1.01)]]); a.set_opacity(0); a.set_info(title=TAG, content=json.dumps(s)); a.update()
                    try:
                        for sub_ in geo_strokes(s, page.rect.width, page.rect.height):
                            g = page.add_ink_annot([[tuple(q) for q in sub_['points']]]); c_ = QColor(sub_['color'])
                            g.set_colors(stroke=(c_.redF(), c_.greenF(), c_.blueF())); g.set_border(width=sub_['width']); g.set_info(title=TAG_FX); g.update()
                    except Exception: pass
                    continue
                outline = nib_outline(s)
                if outline:
                    points = [fitz.Point(*pt)*page.derotation_matrix for pt in outline]
                    a = page.add_polygon_annot([(pt.x,pt.y) for pt in points])
                    c = QColor(s['color']); rgb = (c.redF(),c.greenF(),c.blueF())
                    a.set_colors(stroke=rgb,fill=rgb); a.set_border(width=0)
                    a.set_info(title=TAG,content=json.dumps(s)); a.update()
                    continue
                if s['tool'] == 'whiteout':
                    rect = fitz.Rect(*s['points'][0], *s['points'][1]) * page.derotation_matrix
                    a = page.add_rect_annot(rect)
                    a.set_colors(stroke=(1,1,1), fill=(1,1,1))
                    a.set_border(width=0)
                    a.set_info(title=TAG, content=json.dumps(s))
                    a.update()
                    continue
                pts = [fitz.Point(*p) * page.derotation_matrix for p in s['points']]
                if len(pts) == 1:
                    pts.append(pts[0] + fitz.Point(.01, .01))
                ink = [[(p.x,p.y) for p in pts]]
                c = QColor(s['color']); width = s['width']; opacity = .3 if s['tool'] == 'highlight' else 1
                style = s.get('style') if s['tool'] in STYLED_TOOLS else None
                # Pen styles outside the app: plain ink that looks close to them.
                if style == 'felt': width *= 1.7
                elif style == 'chalk': width *= 1.6; c = mix_color(c, '#ffffff', .12); opacity = .85
                elif style == 'pencil': width = max(.6, width*.85); c = mix_color(c, '#4a4f57', .35); opacity = .85
                elif style == 'neon':
                    for k, alpha, col in ((5.5, .16, c), (3, .42, c), (.7, 1, QColor('#ffffff'))):
                        g = page.add_ink_annot(ink); g.set_colors(stroke=(col.redF(), col.greenF(), col.blueF()))
                        g.set_border(width=max(.6, width*k)); g.set_opacity(alpha); g.set_info(title=TAG_FX); g.update()
                    width = max(.6, width*.35)
                a = page.add_ink_annot(ink)
                a.set_colors(stroke=(c.redF(), c.greenF(), c.blueF()))
                if s.get('dash'): a.set_border(width=s['width'], dashes=[DASH_PATTERN[0]*s['width']+s['width'], DASH_PATTERN[1]*s['width']-s['width']])
                else: a.set_border(width=width)
                a.set_opacity(opacity)
                a.set_info(title=TAG, content=json.dumps(s))
                a.update()
        fd, tmp = tempfile.mkstemp(suffix='.pdf', dir=os.path.dirname(os.path.abspath(target)))
        os.close(fd)
        try:
            # garbage=3/deflate re-compress every image of large textbooks
            # (10+ s, UI freeze); garbage=1 keeps output valid and fast.
            out.save(tmp, garbage=1)
            os.replace(tmp, target)
        finally:
            if os.path.exists(tmp): os.unlink(tmp)
    finally:
        out.close()

SOLUTIONS_FILE = 'umal-cozumler.json'

def read_solutions(doc):
    """Saved question solutions travel inside the PDF as an embedded file."""
    try:
        if SOLUTIONS_FILE in doc.embfile_names():
            data = json.loads(doc.embfile_get(SOLUTIONS_FILE).decode('utf-8'))
            return {k: dict(v, marks=load_marks(v.get('marks'))) for k, v in data.items()
                    if len(v.get('rect', [])) == 4}
    except Exception: pass
    return {}

def solution_overlap(a, b):
    ra, rb = fitz.Rect(a), fitz.Rect(b); inter = ra & rb
    if inter.is_empty: return 0
    area = lambda r: max(0, r.width) * max(0, r.height)
    union = area(ra) + area(rb) - area(inter)
    return area(inter) / union if union else 0

def recover_marks(doc, silinen=None):
    """PDF'in içindeki Atlas yazılarını (açıklama olarak saklanan) geri alır ve belgeden çıkarır.
    K-438: açıklaması (/Annots) olmayan sayfa hiç yüklenmez — 400 sayfalık kitapta bütün sayfaları tek tek açmak saniyeler sürüyordu.
    silinen: liste verilirse belgeden çıkarılan her açıklama için bir öğe eklenir (boşsa belge değişmedi)."""
    marks = {}
    for i in range(len(doc)):
        marks[i] = []
        try:
            if doc.xref_get_key(doc.page_xref(i), 'Annots')[0] == 'null': continue
        except Exception: pass
        page = doc[i]
        for a in list(page.annots() or []):
            if a.info.get('title') == TAG_FX:
                page.delete_annot(a)
                if silinen is not None: silinen.append(i)
                continue
            if a.info.get('title') != TAG: continue
            try:
                s = json.loads(a.info['content'])
                assert s['tool'] in ('pen', 'highlight', 'line', 'rect', 'circle', 'whiteout', 'geo')
                assert 0 < float(s['width']) <= 100
                assert s['points'] and all(len(p) == 2 and all(math.isfinite(float(v)) for v in p) for p in s['points'])
                assert QColor(s['color']).isValid()
                if s['tool'] == 'whiteout':
                    assert len(s['points']) == 2
                    assert s['points'][1][0] > s['points'][0][0] and s['points'][1][1] > s['points'][0][1]
                marks[page.number].append(s)
                page.delete_annot(a)
                if silinen is not None: silinen.append(i)
            except (ValueError, KeyError, TypeError, AssertionError):
                pass
    return marks

def load_marks(data):
    """Validated marks from autosave JSON (same rules as recover_marks)."""
    marks = {}
    for key, strokes in (data or {}).items():
        page = int(key); marks[page] = []
        for s in strokes:
            try:
                assert s['tool'] in ('pen', 'highlight', 'line', 'rect', 'circle', 'whiteout', 'geo')
                assert 0 < float(s['width']) <= 100
                assert s['points'] and all(len(p) == 2 and all(math.isfinite(float(v)) for v in p) for p in s['points'])
                assert QColor(s['color']).isValid()
                marks[page].append(s)
            except (ValueError, KeyError, TypeError, AssertionError):
                pass
    return marks

def segment_distance(p, a, b):
    dx, dy = b[0]-a[0], b[1]-a[1]
    d = dx*dx+dy*dy
    t = max(0, min(1, ((p[0]-a[0])*dx+(p[1]-a[1])*dy)/d)) if d else 0
    return math.hypot(p[0]-a[0]-t*dx, p[1]-a[1]-t*dy)

def stroke_bounds(stroke):
    pts=stroke['points']; pad=stroke['width']/2
    x0=min(p[0] for p in pts)-pad;y0=min(p[1] for p in pts)-pad
    return QRectF(x0,y0,max(p[0] for p in pts)+pad-x0,max(p[1] for p in pts)+pad-y0)

def is_scribble(points, scale=1):
    """Back-and-forth scratching (≥5 reversals, very long for its size)."""
    if len(points) < 10: return False
    xs = [p[0] for p in points]; ys = [p[1] for p in points]
    w, h = max(xs)-min(xs), max(ys)-min(ys)
    if max(w, h)*scale < 24: return False
    length = sum(math.dist(a, b) for a, b in zip(points, points[1:]))
    if length < 3*(w+h): return False
    def reversals(vals, extent):
        hyst = max(4/scale, .18*extent); count = 0; direction = 0; anchor = vals[0]
        for v in vals[1:]:
            if direction >= 0 and v < anchor-hyst:
                count += direction > 0; direction = -1; anchor = v
            elif direction <= 0 and v > anchor+hyst:
                count += direction < 0; direction = 1; anchor = v
            elif (direction > 0 and v > anchor) or (direction < 0 and v < anchor): anchor = v
        return count
    return max(reversals(xs, w), reversals(ys, h)) >= 5

def scribble_hits(strokes, scribble, scale=1):
    """Strokes lying mostly under the scribble."""
    xs = [p[0] for p in scribble['points']]; ys = [p[1] for p in scribble['points']]
    pad = max(4/scale, scribble.get('width', 3))
    x0, x1, y0, y1 = min(xs)-pad, max(xs)+pad, min(ys)-pad, max(ys)+pad
    hits = []
    for s in strokes:
        if s is scribble or s['tool'] == 'whiteout' or not s['points']: continue
        inside = sum(1 for q in s['points'] if x0 <= q[0] <= x1 and y0 <= q[1] <= y1)
        if inside >= .5*len(s['points']): hits.append(s)
    return hits

def recognize_triangle(points, diag, length):
    """Kapalı ve üç köşeli el çizimi → düzgün üçgen (köşeler el çiziminden)."""
    def far(pts, a, b):
        return max(range(len(pts)), key=lambda k: segment_distance(pts[k], a, b) if a != b else math.dist(pts[k], a))
    p0 = points[0]; i1 = max(range(len(points)), key=lambda k: math.dist(points[k], p0)); A = points[i1]
    i2 = max(range(len(points)), key=lambda k: math.dist(points[k], A)); B = points[i2]
    i3 = far(points, A, B); C = points[i3]
    corners = [A, B, C]
    sides = [math.dist(A, B), math.dist(B, C), math.dist(C, A)]
    if min(sides) < diag*.25: return None
    per = sum(sides)
    if not (.85*per < length < 1.18*per): return None
    edges = [(A, B), (B, C), (C, A)]
    err = [min(segment_distance(p, a, b) for a, b in edges) for p in points]
    if sum(e < diag*.06 for e in err)/len(err) < .9: return None
    # her köşenin yakınından geçilmiş olmalı (dörtgen/daire elensin)
    def ang(p, q, r):
        v1 = (q[0]-p[0], q[1]-p[1]); v2 = (r[0]-p[0], r[1]-p[1])
        c = (v1[0]*v2[0] + v1[1]*v2[1])/max(1e-9, math.hypot(*v1)*math.hypot(*v2)); return math.degrees(math.acos(max(-1, min(1, c))))
    if min(ang(A, B, C), ang(B, C, A), ang(C, A, B)) < 12: return None
    return [list(A), list(B), list(C), list(A)]

SHAPE_MIN_PX = 150   # şekil düzeltme yalnızca ekranda bu boydan büyük çizimlerde (harfler ~30–80 px)
def recognize_shape(points):
    """Conservative axis-aligned shapes; called only after an intentional hold."""
    if len(points)<3:return None
    xs=[p[0] for p in points];ys=[p[1] for p in points]
    x0,x1=min(xs),max(xs);y0,y1=min(ys),max(ys)
    w,h=x1-x0,y1-y0;diag=math.hypot(w,h)
    if diag<20:return None
    # Remove sampling jitter and resample uniformly. Touch screens often send
    # many points while stationary and only a few during a fast straight stroke.
    def simplify(pts):
        keep={0,len(pts)-1};stack=[(0,len(pts)-1)]
        while stack:
            a,b=stack.pop()
            if b-a<2:continue
            i=max(range(a+1,b),key=lambda k:segment_distance(pts[k],pts[a],pts[b]))
            if segment_distance(pts[i],pts[a],pts[b])>max(1.5,diag*.012):
                keep.add(i);stack.extend([(a,i),(i,b)])
        return [pts[i] for i in sorted(keep)]
    filtered=simplify(points)
    samples=[]
    for a,b in zip(filtered,filtered[1:]):
        steps=max(1,min(200,int(math.dist(a,b)/max(1,diag/80))))
        samples.extend([[a[0]+(b[0]-a[0])*i/steps,a[1]+(b[1]-a[1])*i/steps] for i in range(steps)])
    points=samples+[filtered[-1]]
    length=sum(math.dist(a,b) for a,b in zip(points,points[1:]))
    chord=math.dist(points[0],points[-1])
    if chord>.8*diag and length<chord*1.2 and max(segment_distance(p,points[0],points[-1]) for p in points)<max(2.5,diag*.04):
        return 'line',[points[0],points[-1]]
    if min(w,h)<12 or chord>diag*.2:return None
    tri=recognize_triangle(points,diag,length)
    if tri:return 'triangle',tri
    perimeter=2*(w+h)
    if .8*perimeter<length<1.2*perimeter:
        errors=[min(abs(x-x0),abs(x-x1),abs(y-y0),abs(y-y1)) for x,y in points]
        corners=[[x0,y0],[x1,y0],[x1,y1],[x0,y1]]
        if sum(e<min(w,h)*.07 for e in errors)/len(errors)>.9 and all(min(math.dist(c,p) for p in points)<diag*.09 for c in corners):
            return 'rect',corners+[corners[0]]
    cx,cy=(x0+x1)/2,(y0+y1)/2;rx,ry=w/2,h/2
    error=sum(abs(math.hypot((x-cx)/rx,(y-cy)/ry)-1) for x,y in points)/len(points)
    angles=[math.atan2((y-cy)/ry,(x-cx)/rx) for x,y in points]
    sweep=sum((b-a+math.pi)%(2*math.pi)-math.pi for a,b in zip(angles,angles[1:]))
    if error<.09 and 5.4<abs(sweep)<7.1:
        return 'circle',[[cx+rx*math.cos(t*math.pi/32),cy+ry*math.sin(t*math.pi/32)] for t in range(65)]
    return None

