HERSHEY['°'] = [12, [[[6 + 3*math.cos(t*math.pi/8), -9 + 3*math.sin(t*math.pi/8)] for t in range(17)]]]
def text_strokes(text, x, y, h, color, width, anchor='c'):
    """Yazıyı kalem çizgilerine çevirir (h: büyük harf yüksekliği, sayfa birimi).
    anchor: 'c' ortası (x, y), 'l' sol-orta, 'r' sağ-orta."""
    k = h/21.0; glyphs = [HERSHEY.get(ch, HERSHEY.get(ch.upper(), [12, []])) for ch in text]
    total = sum(g[0] for g in glyphs)*k
    cx = x - total/2 if anchor == 'c' else x - total if anchor == 'r' else x
    out = []
    for adv, polys in glyphs:
        for poly in polys:
            out.append(dict(tool='pen', color=color, width=width, points=[[cx + gx*k, y + (gy + 1.5)*k] for gx, gy in poly]))
        cx += adv*k
    return out

def fmt_num(v, nd=2):
    """Türkçe ondalık: 5,29 · tam sayıysa 6."""
    if abs(v - round(v)) < 1e-9: return str(int(round(v)))
    return ('{:.%df}' % nd).format(v).rstrip('0').rstrip('.').replace('.', ',')

def tri_points(a, b):
    """Sürükleyerek çizilen sıradan üçgen: tabanı alt kenar, tepesi biraz solda."""
    x0, x1 = min(a[0], b[0]), max(a[0], b[0]); y0, y1 = min(a[1], b[1]), max(a[1], b[1])
    apex = [x0 + .38*(x1 - x0), y0]
    return [[x0, y1], [x1, y1], apex, [x0, y1]]

PEN_DEFAULT = '#111111'   # canlı palet: siyah, kırmızı, mavi, yeşil, mor, pembe, sarı, beyaz
def koyu_sayfa(m):
    """Sayfa koyu mu (kara tahta ya da grafik sayfası): üstüne yazılan beyaz olmalı."""
    try: return m.background in DARK_BACKGROUNDS or ((m.doc.metadata or {}).get('keywords') or '') == 'UMAL-graph'
    except Exception: return False
def okunur_renk(m, renk=None):
    """Tahtada okunacak kalem rengi: koyu sayfada koyu renk beyaza, açık sayfada beyaz siyaha döner."""
    renk = renk or getattr(m, 'color', None) or PEN_DEFAULT
    try:
        h_ = renk.lstrip('#'); h_ = ''.join(ch*2 for ch in h_) if len(h_) == 3 else h_[:6]
        r_, g_, b_ = int(h_[0:2], 16), int(h_[2:4], 16), int(h_[4:6], 16)
    except Exception: r_ = g_ = b_ = 17
    l = (0.299*r_ + 0.587*g_ + 0.114*b_)/255
    if koyu_sayfa(m): return renk if l >= 0.45 else '#ffffff'
    return renk if l <= 0.85 else PEN_DEFAULT
SIDE_ARROW_W, SIDE_ARROW_H = 56, 116
