def pdf_fonts():
    """Mizanpaj yazı tipleri: pakette gelen Poppins; yoksa sistemdeki Türkçe karakterli yazı tipi.
    Döner: {'r': normal, 'm': orta, 'b': kalın} dosya yolları (None: PDF'in yerleşik yazısı)."""
    pop = {k: os.path.join(FONT_DIR, 'Poppins-%s.ttf' % n) for k, n in (('r', 'Regular'), ('m', 'Medium'), ('b', 'Bold'))}
    if all(os.path.isfile(v) for v in pop.values()): return pop
    pairs = [('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'),
             ('/usr/share/fonts/dejavu/DejaVuSans.ttf', '/usr/share/fonts/dejavu/DejaVuSans-Bold.ttf')]
    win = os.path.join(os.environ.get('WINDIR', 'C:\\Windows'), 'Fonts')
    pairs += [(os.path.join(win, 'segoeui.ttf'), os.path.join(win, 'segoeuib.ttf')), (os.path.join(win, 'arial.ttf'), os.path.join(win, 'arialbd.ttf'))]
    for a, b in pairs:
        if os.path.isfile(a): b = b if os.path.isfile(b) else a; return {'r': a, 'm': b, 'b': b}
    return {'r': None, 'm': None, 'b': None}

def bake(doc):
    """Kalem izleri PDF'te not (annotation) olarak durur; başka sayfaya gömülürken
    görünmeleri için sayfa içeriğine işlenir."""
    if hasattr(doc, 'bake'): doc.bake(annots=True, widgets=False)
    else:   # eski PyMuPDF: sayfayı resim olarak yeniden çiz
        for i in range(len(doc)):
            pg = doc[i]; pix = pg.get_pixmap(matrix=fitz.Matrix(3, 3), alpha=False); r = pg.rect
            for a in list(pg.annots() or []): pg.delete_annot(a)
            pg.clean_contents(); pg.insert_image(r, pixmap=pix, overlay=True)

def find_questions(page):
    """Sayfadaki soruları bulur (yazısı seçilebilen PDF; test kitapları: tek başına duran "1." numaraları,
    bir ya da iki sütun). Her soru: numarasından aynı sütundaki bir sonraki numaraya (ya da sütun sonuna) kadar.
    Döner: [(numara, fitz.Rect)]. Taranmış (yazısız) sayfada boş liste."""
    import re
    W, H = page.rect.width, page.rect.height; top, bot = H*0.06, H*0.95   # üst başlık bandı ve alt bilgi dışarıda
    lines = []
    try: blocks = page.get_text('dict', flags=fitz.TEXT_PRESERVE_WHITESPACE | fitz.TEXT_MEDIABOX_CLIP)['blocks']   # resimler çözülmez: ~200 ms → ~6 ms
    except Exception: return []
    for b in blocks:
        for l in b.get('lines', []):
            t = ''.join(sp['text'] for sp in l['spans']).replace('\t', ' ')
            if t.strip(): lines.append((l['bbox'], t))
    starts = []
    for (x0, y0, x1, y1), t in lines:
        m = re.match(r'^\s*(\d{1,2})\s*\.\s*$', t)
        if m and top <= y0 <= bot and x0 < W*0.62 and x1 - x0 < 24 and 1 <= int(m.group(1)) <= 40: starts.append((int(m.group(1)), x0, y0))
    if not starts:   # numarası yazıyla aynı satırda olan sorular ("1. Table below ...")
        for (x0, y0, x1, y1), t in lines:
            m = re.match(r'^\s*(\d{1,2})\s*[\.\)]\s+\S', t)
            if m and top <= y0 <= bot and x0 < W*0.62 and 1 <= int(m.group(1)) <= 40: starts.append((int(m.group(1)), x0, y0))
    if not starts: return []
    cols = []
    for st in sorted(starts, key=lambda q: q[1]):
        for c in cols:
            if abs(c[0] - st[1]) < 25: c[1].append(st); break
        else: cols.append([st[1], [st]])
    cols.sort(key=lambda c: c[0]); out = []
    for ci, (cx, ss) in enumerate(cols):
        x0 = cx - 6; x1 = (cols[ci + 1][0] - 8) if ci + 1 < len(cols) else W - 22
        ys = [bb[3] for bb, t in lines if bb[0] >= x0 - 4 and bb[2] <= x1 + 30 and top < bb[1] < bot]
        cb = max(ys) if ys else bot
        ss = sorted(ss, key=lambda q: q[2])
        for i, (n, _, y) in enumerate(ss):
            y1 = (ss[i + 1][2] - 6) if i + 1 < len(ss) else cb + 8
            r = fitz.Rect(x0, y - 4, x1, min(y1, bot))
            if r.height >= 30 and r.width >= 60: out.append((n, r))
    return out

def content_box(page, clip, marks):
    """Çerçevenin içinde gözle görülen kısım: alan resim gibi çizilir ve beyaz olmayan
    noktaların kutusu alınır. (PDF'teki görünmez yazı katmanı, beyaz kutu, kırpma
    alanı gibi nesneler hesaba katılmaz; kenar boşlukları kesilir, soru büyük çıkar.)"""
    clip = fitz.Rect(clip)
    if clip.is_empty: return clip
    try:
        z = min(4.0, 1400/max(clip.width, clip.height))
        pix = page.get_pixmap(matrix=fitz.Matrix(z, z), clip=clip, colorspace=fitz.csGRAY, alpha=False)
        w, h, st, data = pix.width, pix.height, pix.stride, pix.samples
        ink = bytes(1 if v < 225 else 0 for v in range(256))   # açık gri kâğıt dokusu sayılmaz
        x0, x1, y0, y1 = w, -1, None, None
        for y in range(h):
            row = data[y*st:y*st+w].translate(ink)
            a = row.find(1)
            if a < 0: continue
            if y0 is None: y0 = y
            y1 = y; x0 = min(x0, a); x1 = max(x1, row.rfind(1))
        r = fitz.Rect() if y0 is None else fitz.Rect(clip.x0 + x0/z, clip.y0 + y0/z, clip.x0 + (x1+1)/z, clip.y0 + (y1+1)/z)
    except Exception: return clip
    for st_ in marks or []:
        if st_.get('tool') == 'whiteout' or not st_.get('points'): continue
        xs = [q[0] for q in st_['points']]; ys = [q[1] for q in st_['points']]; lw = st_.get('width', 3)
        b = fitz.Rect(min(xs)-lw, min(ys)-lw, max(xs)+lw, max(ys)+lw) & clip
        if not b.is_empty: r |= b
    return clip if r.is_empty or r.width < 8 or r.height < 8 else r

def legacy_card(clip):
    """Eski çözüm alanı yerleşimi (en çok 300 birim yükseklik): eski çözümler yerinde açılsın."""
    clip = fitz.Rect(clip); h = min(300, GUNUN_CARD*clip.height/max(clip.width, 1))
    s = min(GUNUN_CARD/max(clip.width, 1), h/max(clip.height, 1)); w = clip.width*s; x0 = 48 + (GUNUN_CARD - w)/2
    return [x0, 36, x0 + w, 36 + clip.height*s]
SOLUTION_CARD_SHARE = .62   # soru kartı ekranın en çok bu kadarını kaplar; kalanı çözüm için boş kalır
def fit_card(clip, vw, vh):
    """Çözüm alanı: tahta genişliğe sığar, soru olabildiğince büyük; kart ekran yüksekliğinin
    en çok SOLUTION_CARD_SHARE'i kadar. Döner: (soru görüntüsünün yeri, yakınlaştırma)."""
    clip = fitz.Rect(clip); zoom = max(.5, (vw - 8)/960); seen = (vh - 8)/zoom
    hmax = max(120, seen*SOLUTION_CARD_SHARE - 52)   # kart çerçevesi: üstte 36, altta 16 birim
    w = GUNUN_CARD; h = w*clip.height/max(clip.width, 1)
    if h > hmax: h = hmax; w = h*clip.width/max(clip.height, 1)
    x0 = 480 - w/2
    return [x0, 36, x0 + w, 36 + h], zoom
def question_card(src, page_no, page_marks, clip, ink=None, card=None):
    """Soru (+ çözüm mürekkebi) tek sayfalık PDF, çözüm alanıyla aynı yerleşimde
    (soru 864 birim genişlikte; mürekkep koordinatları birebir tutar).
    Döner: (pdf baytları, tüm kırpma, yalnız soru kırpması)."""
    clip = fitz.Rect(clip)
    box = content_box(src[page_no], clip, page_marks)
    with tempfile.TemporaryDirectory() as folder:
        single = fitz.open(); single.insert_pdf(src, from_page=page_no, to_page=page_no)
        path = os.path.join(folder, 'soru.pdf'); export_document(single, {0: page_marks or []}, path); single.close()
        qdoc = fitz.open(path); bake(qdoc)   # notlar sayfaya işlenir (gömülünce kaybolmasın)
        cr = fitz.Rect(card or legacy_card(clip)); s = cr.width/max(clip.width, 1); x0 = cr.x0
        q = fitz.Rect(x0 + (box.x0-clip.x0)*s, cr.y0 + (box.y0-clip.y0)*s, x0 + (box.x1-clip.x0)*s, cr.y0 + (box.y1-clip.y0)*s)
        full = fitz.Rect(q)
        for st in ink or []:
            if not st.get('points'): continue
            w = st.get('width', 3); xs = [p_[0] for p_ in st['points']]; ys = [p_[1] for p_ in st['points']]
            full |= fitz.Rect(min(xs)-w, min(ys)-w, max(xs)+w, max(ys)+w)
        height = max(800, full.y1 + 40)
        doc = fitz.open(); page = doc.new_page(width=960, height=height)
        page.show_pdf_page(cr, qdoc, 0, clip=clip)
        qdoc.close()
        out = os.path.join(folder, 'kart.pdf'); export_document(doc, {0: ink or []}, out); doc.close()
        kd = fitz.open(out); bake(kd); data = kd.tobytes(garbage=3, deflate=True); kd.close()
    pad = lambda r, k: [max(0, r.x0-k), max(0, r.y0-k), min(960, r.x1+k), min(height, r.y1+k)]
    return data, pad(full, 10), pad(q, 6)

def daily_grid(n, W, H, aspects, gap):
    """1 ya da 2 sütun: soruların en büyük çıktığı düzen (aspects: yükseklik/genişlik)."""
    best = None
    for cols in (1, 2):
        if cols > n: break
        rows = math.ceil(n/cols); cw = (W - gap*(cols-1))/cols; ch = (H - gap*(rows-1))/rows
        sc = min(min(cw, ch/a) for a in aspects)
        if best is None or sc > best[0] + .01: best = (sc, cols, rows, cw, ch)
    return best[1:]

def build_daily_pdf(items, folder, date_text, topic, teacher, target):
    """Kareli defter mizanpajı (A4). Önce soruların boş hâli (altı kareli çözüm alanı),
    sonra yeni sayfadan çözümler, aynı numaralarla. Sayfada en çok 4 soru; sorular
    sayfaya yayılır, kenar boşlukları kesilip olabildiğince büyük konur."""
    W, H, M = 595, 842, 30
    TEAL = (.04, .43, .4); LIGHT = (.9, .96, .95); DARK = (.1, .12, .15); GRID = (.8, .9, .89)
    fonts = pdf_fonts(); out = fitz.open()
    def width_of(t, size, f):
        return fitz.Font(fontfile=fonts[f]).text_length(t, fontsize=size) if fonts[f] else fitz.get_text_length(t, fontsize=size)
    def text(pg, x, y, t, size, f='r', color=DARK, right=False, center=False):
        if right: x -= width_of(t, size, f)
        if center: x -= width_of(t, size, f)/2
        if fonts[f]: pg.insert_text((x, y), t, fontsize=size, fontname='umal' + f, fontfile=fonts[f], color=color)
        else: pg.insert_text((x, y), t, fontsize=size, color=color)
    srcs = {}
    def src(name):
        if name not in srcs: srcs[name] = fitz.open(os.path.join(folder, name))
        return srcs[name]
    def place(pg, rect, name, clip):
        clip = fitz.Rect(clip); s = min(rect.width/clip.width, rect.height/clip.height)
        r = fitz.Rect(rect.x0, rect.y0, rect.x0 + clip.width*s, rect.y0 + clip.height*s)
        pg.show_pdf_page(r, src(name), 0, clip=clip); return r.height
    pages = []   # (bölüm başlığı, ilk sayfa mı, [(no, dosya, kırpma)], boş mu)
    blank = [(n+1, it.get('qsnap') or it['snap'], it.get('qcrop') or it['crop']) for n, it in enumerate(items)]
    solved = [(n+1, it['snap'], it['crop']) for n, it in enumerate(items) if it['done']]
    for title, cards, is_blank in (('Günün soruları', blank, True), ('Çözümler', solved, False)):
        for k in range(0, len(cards), 4): pages.append((title, k == 0, cards[k:k+4], is_blank))
    for pi, (title, first, cards, is_blank) in enumerate(pages):
        pg = out.new_page(width=W, height=H)
        if pi == 0:
            pg.draw_rect(fitz.Rect(M, 28, M+6, 80), color=None, fill=TEAL)
            text(pg, M+16, 52 if topic else 60, title, 22, 'b')
            if topic: text(pg, M+16, 72, topic, 11, 'm', TEAL)
            r = fitz.Rect(W-M-140, 34, W-M, 74); pg.draw_rect(r, color=None, fill=LIGHT, radius=.25)
            text(pg, r.x0+70, 50, 'TARİH', 7.5, 'm', TEAL, center=True); text(pg, r.x0+70, 66, date_text, 9.5, 'm', center=True)
            top = 100
        else:
            pg.draw_rect(fitz.Rect(M, 28, M+6, 56), color=None, fill=TEAL)
            text(pg, M+16, 48, title if first or title == 'Çözümler' else title, 16, 'b'); text(pg, W-M, 48, date_text, 9.5, 'r', (.4, .45, .45), right=True)
            top = 74
        area = fitz.Rect(M, top, W-M, H-50); gap = 14
        aspects = [(2.2 if is_blank else 1.0)*fitz.Rect(c).height/fitz.Rect(c).width + 44/max(fitz.Rect(c).width, 1) for _, _, c in cards]
        cols, rows, cw, ch = daily_grid(len(cards), area.width - 44*0, area.height, aspects, gap)
        for k, (no, name, clip) in enumerate(cards):
            row, col = divmod(k, cols)
            if cols == 2 and len(cards) % 2 and k == len(cards)-1: x = area.x0 + (area.width-cw)/2   # tek kalan: ortada
            else: x = area.x0 + col*(cw+gap)
            cell = fitz.Rect(x, area.y0 + row*(ch+gap), x+cw, area.y0 + row*(ch+gap) + ch)
            pg.draw_rect(cell, color=(.78, .86, .85), fill=(1, 1, 1), width=.7, radius=min(.03, 8/max(cell.height, 1)))
            tab = fitz.Rect(cell.x0-1, cell.y0+12, cell.x0+28, cell.y0+38); pg.draw_rect(tab, color=None, fill=TEAL)
            text(pg, tab.x0+14.5, tab.y0+18, str(no), 12, 'b', (1, 1, 1), center=True)
            inner = fitz.Rect(cell.x0+34, cell.y0+10, cell.x1-10, cell.y1-10)
            if is_blank:
                h = place(pg, fitz.Rect(inner.x0, inner.y0, inner.x1, inner.y0 + inner.height*.5), name, clip)
                a = fitz.Rect(cell.x0+10, inner.y0+h+10, cell.x1-10, cell.y1-10); step = 12
                if a.height > step:
                    x_ = a.x0
                    while x_ <= a.x1 + .1: pg.draw_line((x_, a.y0), (x_, a.y1), color=GRID, width=.4); x_ += step
                    y_ = a.y0
                    while y_ <= a.y1 + .1: pg.draw_line((a.x0, y_), (a.x1, y_), color=GRID, width=.4); y_ += step
            else: place(pg, inner, name, clip)
        text(pg, W/2, H-26, '%d / %d' % (pi+1, len(pages)), 8.5, 'r', (.45, .5, .5), center=True)
        if teacher and pi == len(pages)-1: text(pg, W-M, H-26, 'Öğretmen: ' + teacher, 9, 'm', TEAL, right=True)
    for d in srcs.values(): d.close()
    try: out.subset_fonts()
    except Exception: pass
    out.save(target, garbage=3, deflate=True); out.close()

class DailyStrip(QWidget):
    """Günün soruları listesi: yazı alanının sağ üstünde 1, 2, 3… ve +."""
    S, GAP = 46, 10
    def __init__(self, main):
        super().__init__(main.scroll); self.main = main; self.setCursor(Qt.PointingHandCursor); self.hide()
    def sync(self):
        n = len(self.main.daily['items'])
        self.setFixedSize(self.S + 12, (n + 1)*(self.S + self.GAP) + 4)
        self.setVisible(n > 0 or self.main.tool == 'pick'); self.update()
    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); f = p.font(); f.setPixelSize(18); f.setBold(True); p.setFont(f)
        cur = self.main.daily_current()
        for i, it in enumerate(self.main.daily['items'] + [None]):
            r = QRectF(5, 5 + i*(self.S + self.GAP), self.S, self.S)
            if it is None:
                p.setPen(QPen(QColor('#8fa3bd'), 1.5, Qt.DashLine)); p.setBrush(QColor(11, 31, 58, 215)); p.drawRoundedRect(r, 10, 10)
                p.setPen(QPen(QColor('#dbe6f5'), 2.4)); c = r.center()
                p.drawLine(QPointF(c.x()-8, c.y()), QPointF(c.x()+8, c.y())); p.drawLine(QPointF(c.x(), c.y()-8), QPointF(c.x(), c.y()+8)); continue
            now = i == cur
            p.setPen(QPen(QColor('#ffe14d' if now else '#6fa8ff' if it['done'] else '#3a5577'), 2))
            p.setBrush(QColor('#1d4f8f') if it['done'] else QColor(11, 31, 58, 225)); p.drawRoundedRect(r, 10, 10)
            p.setPen(QColor('#ffe14d' if now else '#ffffff')); p.drawText(r, Qt.AlignCenter, str(i+1))
            if it['done']:
                b = QRectF(r.right()-12, r.top()-4, 16, 16); p.setPen(Qt.NoPen); p.setBrush(QColor('#00a24a')); p.drawEllipse(b)
                p.setPen(QPen(QColor('white'), 2)); p.drawPolyline(QPolygonF([QPointF(b.x()+4, b.y()+8.5), QPointF(b.x()+7, b.y()+11.5), QPointF(b.x()+12.5, b.y()+5)]))
    def mousePressEvent(self, e):
        i = int((e.pos().y() - 5)//(self.S + self.GAP)); n = len(self.main.daily['items'])
        if 0 <= i < n: self.main.daily_open(i)
        elif i == n: self.main.set_tool('pick')

class DailyDialog(QDialog):
    """Günün soruları: tarih, isteğe bağlı konu ve öğretmen adı; soruları seç, önizle, gönder."""
    def __init__(self, main):
        super().__init__(main); self.main = main
        from PyQt5.QtWidgets import QCheckBox, QLineEdit, QGridLayout
        self.setWindowTitle('Günün soruları'); self.setModal(True)
        scr = QApplication.primaryScreen().availableGeometry(); self.resize(min(820, scr.width()-80), min(640, scr.height()-80))
        box = QVBoxLayout(self); box.setContentsMargins(20, 18, 20, 18); box.setSpacing(12)
        self.title = QLabel(); self.title.setStyleSheet('font-size:20px;font-weight:bold;'); box.addWidget(self.title)
        cfg = main.daily_cfg(); grid = QGridLayout(); grid.setHorizontalSpacing(14); grid.setVerticalSpacing(12); box.addLayout(grid)
        grid.addWidget(QLabel('Tarih'), 0, 0); grid.addWidget(QLabel(daily_date_text()), 0, 1)
        self.topic_on = QCheckBox('Konu'); self.topic_on.setChecked(cfg.get('konu_on', True)); grid.addWidget(self.topic_on, 1, 0)
        self.topic = QLineEdit(cfg.get('konu', '') if cfg.get('konu_gun') == daily_today() else ''); grid.addWidget(self.topic, 1, 1)
        self.teacher_on = QCheckBox('Öğretmen'); self.teacher_on.setChecked(cfg.get('ogretmen_on', False)); grid.addWidget(self.teacher_on, 2, 0)
        self.teacher = QLineEdit(cfg.get('ogretmen', '')); self.teacher.setPlaceholderText('Ad Soyad'); grid.addWidget(self.teacher, 2, 1)
        for c in (self.topic, self.teacher): c.setMinimumHeight(48); c.installEventFilter(self)
        self.keyboard = TouchKeyboard(self); self.keyboard.hide()
        self.note = QLabel(); self.note.setWordWrap(True); self.note.setStyleSheet('color:#a9b9cf;'); box.addWidget(self.note)
        self.chips = QWidget(); self.chip_row = QHBoxLayout(self.chips); self.chip_row.setContentsMargins(0, 0, 0, 0); self.chip_row.setSpacing(8)
        box.addWidget(self.chips); box.addStretch(1); box.addWidget(self.keyboard)
        row = QHBoxLayout(); row.setSpacing(8); box.addLayout(row)
        for text, fn, name in (('Soru seç', self.pick, ''), ('Listeyi temizle', self.clear, ''), ('Önizle', self.preview, ''), ('Gönder', self.send, 'primary'), ('Kapat', self.close_save, '')):
            b = QPushButton(text); b.setObjectName(name); b.setMinimumHeight(52); b.clicked.connect(fn); row.addWidget(b, 1)
        self.refresh()
    def eventFilter(self, obj, e):
        # Tahtanın kendi klavyesi her zaman açılmıyor: alana dokununca uygulamanın klavyesi çıkar.
        if e.type() in (QEvent.MouseButtonPress, QEvent.FocusIn) and obj in (self.topic, self.teacher):
            self.keyboard.attach(obj)
            if self.keyboard.isHidden():
                self.keyboard.show(); scr = QApplication.primaryScreen().availableGeometry()
                self.resize(self.width(), min(scr.height()-40, max(self.height(), self.sizeHint().height())))
                self.move(self.x(), max(scr.top()+10, min(self.y(), scr.bottom()-self.height()-10)))
        return False
    def refresh(self):
        items = self.main.daily['items']
        while self.chip_row.count():
            w = self.chip_row.takeAt(0).widget()
            if w: w.deleteLater()
        for i, it in enumerate(items):
            b = QPushButton(str(i+1) + ('' if it['done'] else ' · çözülmedi')); b.setCheckable(True); b.setChecked(it.get('include', it['done']))
            b.setMinimumHeight(44); b.setStyleSheet('QPushButton{padding:0 14px;} QPushButton:!checked{color:#7f8fa6;text-decoration:line-through;}')
            b.toggled.connect(lambda v, it_=it: (it_.__setitem__('include', v), self.main.save_daily(), self.refresh_title())); self.chip_row.addWidget(b)
        self.chip_row.addStretch(1); self.refresh_title()
        self.note.setText('Numaraya dokunarak soruyu sayfaya alın ya da çıkarın. Seçilenler 1’den yeniden sıralanır.' if items else
                          'Henüz soru yok. Dersin başında “Soru seç” ile soruları çerçeveleyin; seçmezseniz derste açtığınız çözüm alanları buraya kendiliğinden gelir.')
    def refresh_title(self):
        k = len(self.main.daily_selected()); self.title.setText('Günün soruları · %d soru' % k)
    def values(self):
        topic = self.topic.text().strip() if self.topic_on.isChecked() else ''
        teacher = self.teacher.text().strip() if self.teacher_on.isChecked() else ''
        self.main.save_daily_cfg(dict(konu_on=self.topic_on.isChecked(), konu=self.topic.text().strip(), konu_gun=daily_today(),
                                      ogretmen_on=self.teacher_on.isChecked(), ogretmen=self.teacher.text().strip()))
        return topic, teacher
    def close_save(self): self.values(); self.accept()
    def pick(self): self.values(); self.accept(); self.main.set_tool('pick')
    def clear(self):
        if QMessageBox.question(self, 'Listeyi temizle', 'Günün soruları listesi boşaltılsın mı? (Çözümler kitapta kalır.)', QMessageBox.Yes|QMessageBox.No, QMessageBox.No) != QMessageBox.Yes: return
        self.main.clear_daily(); self.refresh()
    def preview(self):
        if not self.main.daily_selected(): self.note.setText('Sayfaya alınacak soru yok.'); return
        topic, teacher = self.values(); path = os.path.join(tempfile.gettempdir(), 'umal-gunun-onizleme.pdf')
        try: self.main.write_daily(path, topic, teacher)
        except Exception as e: QMessageBox.warning(self, 'Önizleme yapılamadı', str(e)); return
        d = QDialog(self); d.setWindowTitle('Önizleme'); scr = QApplication.primaryScreen().availableGeometry(); d.resize(min(900, scr.width()-60), scr.height()-80)
        lay = QVBoxLayout(d); sc = QScrollArea(); sc.setWidgetResizable(True); lay.addWidget(sc, 1); holder = QWidget(); v = QVBoxLayout(holder); v.setSpacing(16)
        doc = fitz.open(path); width = min(820, scr.width()-120)
        for pg in doc:
            z = width/pg.rect.width; pix = pg.get_pixmap(matrix=fitz.Matrix(z, z), alpha=False)
            lab = QLabel(); lab.setPixmap(QPixmap.fromImage(QImage(pix.samples, pix.width, pix.height, pix.stride, QImage.Format_RGB888).copy())); lab.setAlignment(Qt.AlignCenter); v.addWidget(lab)
        doc.close(); sc.setWidget(holder)
        b = QPushButton('Kapat'); b.setMinimumHeight(48); b.clicked.connect(d.accept); lay.addWidget(b); d.exec_()
    def send(self):
        if not self.main.daily_selected(): self.note.setText('Sayfaya alınacak soru yok.'); return
        topic, teacher = self.values()
        try: name = self.main.send_daily(topic, teacher)
        except Exception as e: QMessageBox.warning(self, 'Gönderilemedi', str(e)); return
        self.accept(); self.main.show_toast('Günün soruları hazır: %s\nDrive’daki “Günün Soruları” klasörüne yükleniyor.' % name)

def tr_kucuk(t): return (t or '').replace('I', 'ı').replace('İ', 'i').lower()

SISTEM_KLAVYE_RE = '(eta-?keyboard|onboard|florence|matchbox-keyboard|squeekboard|pardus-?(on-?screen-?)?(keyboard|klavye)|ekran.?klavye)'
_SK_IS = [None]
def sistem_klavyesini_gizle():
    """K-454: Pardus / ETAP ekran klavyesi (eta-keyboard, onboard…) Atlas klavyesinin üstünde açılırsa gizlenir. Arka planda (ekran beklemez);
    yalnız başka süreçlerin pencereleri (Atlas'ın kendi penceresine dokunulmaz). UMAL_SISTEM_KLAVYE=1 ise hiçbir şey yapmaz."""
    import subprocess, threading
    if os.environ.get('UMAL_SISTEM_KLAVYE') == '1' or not shutil.which('xdotool'): return
    if _SK_IS[0] is not None and _SK_IS[0].is_alive(): return
    def calis():
        ids = set()
        for kip in ('--classname', '--class', '--name'):
            try: ids |= set(subprocess.run(['xdotool', 'search', '--onlyvisible', kip, SISTEM_KLAVYE_RE], capture_output=True, text=True, timeout=2).stdout.split())
            except Exception: pass
        ben = os.getpid()
        for i in ids:
            try:
                if int(subprocess.run(['xdotool', 'getwindowpid', i], capture_output=True, text=True, timeout=2).stdout.strip() or 0) == ben: continue
                subprocess.run(['xdotool', 'windowunmap', i], capture_output=True, timeout=2); print('sistem klavyesi gizlendi', i)
            except Exception: pass
    _SK_IS[0] = threading.Thread(target=calis, daemon=True); _SK_IS[0].start()

class TouchKeyboard(QWidget):
    """Uygulamanın kendi Türkçe Q klavyesi (dokunmatik tahtada sistem klavyesi açılmayabiliyor).
    K-354: "∑ 123" ile matematik düzeni: = + − × ÷ ^ ² ³ √ π ≤ ≥ ≠ ° sin cos tan log ln…"""
    ROWS = [list('1234567890') + ['⌫'], list('qwertyuıopğü'), list('asdfghjklşi'), ['⇧'] + list('zxcvbnmöç.'), ['∑ 123', ',', '-', ' ', 'Tamam']]
    MATH = [['7', '8', '9', '+', '−', '×', '÷', '=', '(', ')', '⌫'], ['4', '5', '6', 'x', 'y', '²', '³', '^', '√', 'π', '°'],
            ['1', '2', '3', '0', ',', '.', '<', '>', '≤', '≥', '≠'], ['abc', '/', '%', '|', '∞', 'sin', 'cos', 'tan', 'log', 'ln', 'Tamam']]
    EKLE = {'sin': 'sin(', 'cos': 'cos(', 'tan': 'tan(', 'log': 'log(', 'ln': 'ln(', '√': '√('}
    def __init__(self, parent, buyuk=None):
        # K-355: her yerde aynı ferah görünüm; ekranın altındaki geniş klavyede (Atlas) tuşlar biraz daha büyük
        genis = buyuk is True; buyuk = True
        super().__init__(parent); self.target = None; self.shift = False; self.keys = []; self.buyuk = buyuk; self.kapat_cb = None; self.degisti = None
        H = 52 if genis else 62; FS = 23 if genis else 25; ARA = 8 if genis else 10   # K-387: geniş klavye normal boy
        lay = QVBoxLayout(self); lay.setContentsMargins(0, 6, 0, 0); lay.setSpacing(ARA if buyuk else 0)
        self.harf = QWidget(); self.mat = QWidget(); lay.addWidget(self.harf); lay.addWidget(self.mat); self.mat.hide()
        for kutu, satirlar in ((self.harf, self.ROWS), (self.mat, self.MATH)):
            v = QVBoxLayout(kutu); v.setContentsMargins(0, 0, 0, 0); v.setSpacing(ARA)
            for row in satirlar:
                r_ = QHBoxLayout(); r_.setSpacing(ARA); v.addLayout(r_)
                for k in row:
                    b = QPushButton(('' if buyuk else 'boşluk') if k == ' ' else k); b.setFocusPolicy(Qt.NoFocus); b.setFixedHeight(H)
                    b.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                    if buyuk:   # K-355: ferah klavye — büyük, aralıklı, yuvarlak, hafif gölgeli tuşlar
                        temel = 'QPushButton{font-size:%dpx;font-weight:600;padding:0;min-height:%dpx;max-height:%dpx;color:#eef6ff;background:#18304f;border:1.5px solid #2c4a72;border-radius:16px;border-bottom:4px solid #0a1628;} QPushButton:pressed{background:#22e8ff;color:#04202a;}' % (FS, H, H)
                        if k in ('⌫', '⇧', '∑ 123', 'abc', '↵'): temel = temel.replace('background:#18304f', 'background:#0f2440').replace('color:#eef6ff', 'color:#7ff6ff').replace('font-size:%dpx' % FS, 'font-size:%dpx' % (20 if genis else 24))
                        if k == 'Tamam': temel = temel.replace('background:#18304f', 'background:#22e8ff').replace('color:#eef6ff', 'color:#04202a').replace('font-weight:600', 'font-weight:800').replace('font-size:%dpx' % FS, 'font-size:%dpx' % (21 if genis else 26))
                        b.setStyleSheet(temel)
                    else:
                        b.setStyleSheet('QPushButton{font-size:22px;padding:0;min-height:56px;max-height:56px;}')
                        if k == 'Tamam': b.setObjectName('primary')
                        if k in ('∑ 123', 'abc'): b.setStyleSheet('QPushButton{font-size:20px;padding:0;min-height:56px;max-height:56px;border-color:#22e8ff;color:#7ff6ff;}')
                    b.clicked.connect(lambda checked=False, k_=k: self.press(k_)); r_.addWidget(b, 5 if k == ' ' and kutu is self.harf else 2 if k in ('Tamam', '⌫', '⇧', '∑ 123', 'abc', ' ') else 1)
                    if kutu is self.harf: self.keys.append((k, b))
                    else:   # matematikte tuşlar eşit genişlikte; uzun adlar (sin, log, Tamam) küçük yazı
                        b.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Fixed)
                        if len(k) > 1 and k not in ('⌫',) and not buyuk: b.setStyleSheet(b.styleSheet().replace('font-size:22px', 'font-size:17px').replace('font-size:20px', 'font-size:17px'))
    def showEvent(self, e):   # K-454: bizim klavye açıkken sistem klavyesi görünmesin
        super().showEvent(e); sistem_klavyesini_gizle()
        t_ = getattr(self, '_sk_t', None)
        if t_ is None: t_ = self._sk_t = QTimer(self); t_.setInterval(700); t_.timeout.connect(sistem_klavyesini_gizle)
        t_.start()
    def hideEvent(self, e):
        t_ = getattr(self, '_sk_t', None)
        if t_ is not None: t_.stop()
        super().hideEvent(e)
    def tus_boyu(self, H):
        """K-365: tuş yüksekliği verilen alana göre (klavye ekrandan taşmasın, tuşlar üst üste binmesin)."""
        import re as _re
        H = int(max(40, H)); self._H = H
        for kutu in (self.harf, self.mat):
            for b in kutu.findChildren(QPushButton):
                b.setFixedHeight(H); b.setStyleSheet(_re.sub(r'(min|max)-height:\d+px', lambda m_: '%s-height:%dpx' % (m_.group(1), H), b.styleSheet()))
    def attach(self, edit):
        edit.setAttribute(Qt.WA_InputMethodEnabled, False)   # K-353: sistem klavyesi açılmasın (iki klavye olmasın)
        self.target = edit; self.set_shift(not edit.text())   # boş alanda büyük harfle başla
    def set_shift(self, on):
        self.shift = on
        for k, b in self.keys:
            if len(k) == 1 and k.isalpha(): b.setText(self.upper(k) if on else k)
            if k == '⇧' and not self.buyuk: H_ = getattr(self, '_H', 56); b.setStyleSheet('QPushButton{font-size:22px;padding:0;min-height:%dpx;max-height:%dpx;%s}' % (H_, H_, 'background:#2f6fd6;color:white;' if on else ''))
            if k == '⇧' and self.buyuk: b.setText('⇧' if not on else '⬆')
    @staticmethod
    def upper(k): return {'i': 'İ', 'ı': 'I'}.get(k, k.upper())
    def matematik(self, ac):
        self.harf.setVisible(not ac); self.mat.setVisible(ac)
        if getattr(self, 'degisti', None): self.degisti()
    def press(self, k):
        t = self.target
        if k == 'Tamam': (self.kapat_cb or self.hide)(); return
        if k == '⇧': self.set_shift(not self.shift); return
        if k == '∑ 123': self.matematik(True); return
        if k == 'abc': self.matematik(False); return
        if t is None: return
        if k == '⌫': t.backspace(); return
        if self.mat.isVisible(): t.insert(self.EKLE.get(k, k)); return
        t.insert(self.upper(k) if self.shift and k.isalpha() else k)
        if self.shift: self.set_shift(False)

class GenisKlavye(QFrame):
    """K-355: ekranın altına boydan boya açılan ferah klavye (Atlas): üstte abc | ∑ 123, yazılan metin, Klavyeyi kapat."""
    def __init__(self, main):
        super().__init__(main); self.main = main; self.setObjectName('genisKlavye')
        self.setStyleSheet('#genisKlavye{background:qlineargradient(x1:0,y1:0,x2:0,y2:1,stop:0 #13284a,stop:1 #0b182b);border-top:3px solid #22e8ff;}'
                           'QLabel{color:#9fb3cc;font-size:20px;} QPushButton#sek{font-size:20px;font-weight:600;color:#9fb3cc;background:#0a1628;border:1.5px solid #2a4468;border-radius:20px;padding:8px 24px;}'
                           'QPushButton#sek:checked{background:#22e8ff;color:#04202a;border-color:#22e8ff;} QPushButton#kap{font-size:18px;color:#7ff6ff;background:#0a1628;border:1.5px solid #2a4468;border-radius:14px;padding:8px 16px;}')
        v = QVBoxLayout(self); v.setContentsMargins(22, 10, 22, 14); v.setSpacing(8)
        ust = QHBoxLayout(); ust.setSpacing(10); v.addLayout(ust)
        self.s_abc = QPushButton('abc'); self.s_mat = QPushButton('∑ 123')
        for b in (self.s_abc, self.s_mat): b.setObjectName('sek'); b.setCheckable(True); b.setFocusPolicy(Qt.NoFocus); ust.addWidget(b)
        self.s_abc.clicked.connect(lambda: self.kb.matematik(False)); self.s_mat.clicked.connect(lambda: self.kb.matematik(True))
        self.onz = QLabel(''); ust.addWidget(self.onz, 1)
        # K-365: sözcük önerisi (WhatsApp gibi): yazılan sözcüğün başına göre en sık 3 sözcük; dokununca tamamlanır
        self.oneri = []
        for i in range(3):
            b = QPushButton(''); b.setFocusPolicy(Qt.NoFocus); b.setMinimumHeight(42); b.hide()
            b.setStyleSheet('QPushButton{font-size:21px;font-weight:600;color:#eef6ff;background:#0a1628;border:1.5px solid #22e8ff;border-radius:18px;padding:3px 18px;}'
                            'QPushButton:pressed{background:#22e8ff;color:#04202a;}')
            b.clicked.connect(lambda c=False, i_=i: self.oneri_sec(i_)); ust.addWidget(b, 1); self.oneri.append(b)
        kap = QPushButton('⌄  Klavyeyi kapat'); kap.setObjectName('kap'); kap.setFocusPolicy(Qt.NoFocus); kap.clicked.connect(self.hide); ust.addWidget(kap)
        self.kb = TouchKeyboard(self, buyuk=True); self.kb.kapat_cb = self.hide; self.kb.degisti = self.esitle; v.addWidget(self.kb)
        self.zm = QTimer(self); self.zm.setInterval(150); self.zm.timeout.connect(self.esitle)
        self.hide()
    def ac(self, edit):
        self.kb.attach(edit); self.yerlestir(); self.esitle(); self.show(); self.raise_(); self.zm.start()
    def yerlestir(self):
        # K-387: normal ekran klavyesi boyu — ortada, ekran eninin ~%60'ı, yüksekliğin ~%34'ü (en çok 400 px)
        # K-389: Atlas paneli açıksa klavye panelin soluna sığar, panelin üstüne binmez
        m = self.main.rect(); h = min(400, int(m.height()*0.34)); alan = m.width()
        ap = getattr(self.main, 'atlas_panel', None)
        if ap is not None and ap.isVisible() and ap.x() > m.width()//3: alan = ap.x() - 12
        w = min(alan - 24, max(760, int(m.width()*0.6)))
        self.setGeometry(max(0, (alan - w)//2), m.height() - h, w, h)
        satir = 4 if self.kb.mat.isVisible() else 5
        self.kb.tus_boyu(max(34, (h - 10 - 14 - 52 - 8 - 6 - 16 - 8*(satir - 1))/satir))   # üst çubuk + kenarlar düşülür
    def kelime_listesi(self):
        if getattr(GenisKlavye, '_liste', None) is None:
            liste = []
            try:
                with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'kelimeler-tr.txt'), encoding='utf-8') as f:
                    for satir_ in f:
                        if satir_.startswith('#'): continue
                        p_ = satir_.split()
                        if len(p_) == 2: liste.append((p_[0], int(p_[1])))
            except (OSError, ValueError): pass
            GenisKlavye._liste = liste
            try:
                with open(os.path.join(self.main.data_dir, 'klavye-sozcukler.json'), encoding='utf-8') as f: GenisKlavye._ogren = json.load(f)
            except Exception: GenisKlavye._ogren = {}
        return GenisKlavye._liste
    def onerileri_bul(self, bas):
        b = tr_kucuk(bas)
        if not b: return []
        og = getattr(GenisKlavye, '_ogren', {}) or {}
        aday = [(w, n + og.get(w, 0)*100000) for w, n in self.kelime_listesi() if w.startswith(b) and w != b][:400]
        aday += [(w, c*100000) for w, c in og.items() if w.startswith(b) and w != b and not any(w == a_[0] for a_ in aday)]
        aday.sort(key=lambda t: -t[1]); sonuc = [w for w, _ in aday[:3]]
        if bas[:1].isupper(): sonuc = [TouchKeyboard.upper(w[0]) + w[1:] for w in sonuc]
        return sonuc
    def oneri_sec(self, i):
        t = self.kb.target; w = self.oneri[i].text()
        if t is None or not w: return
        yazi = t.text(); bas = yazi.split(' ')[-1]
        t.setText(yazi[:len(yazi) - len(bas)] + w + ' '); self.ogren(w); self.esitle()
    def ogren(self, w):
        w = tr_kucuk(w)
        if len(w) < 3: return
        self.kelime_listesi(); og = GenisKlavye._ogren; og[w] = og.get(w, 0) + 1
        if len(og) > 3000:
            for k_ in sorted(og, key=og.get)[:500]: og.pop(k_, None)
        try:
            with open(os.path.join(self.main.data_dir, 'klavye-sozcukler.json'), 'w', encoding='utf-8') as f: json.dump(og, f, ensure_ascii=False)
        except Exception: pass
    def esitle(self):
        mat = not self.kb.mat.isHidden(); self.s_abc.setChecked(not mat); self.s_mat.setChecked(mat)
        t = self.kb.target
        if t is not None:
            yazi = t.text() or ''
            self.onz.setText("Atlas'a yazılıyor: <b style='color:#ffffff'>%s</b><span style='color:#7ff6ff'>|</span>" % (yazi[-60:].replace('&', '&amp;').replace('<', '&lt;')))
            bas = yazi.split(' ')[-1] if not mat else ''
            if getattr(self, '_son_bas', None) != (bas, mat):
                self._son_bas = (bas, mat); on = self.onerileri_bul(bas) if bas and bas.isalpha() else []
                for i, b in enumerate(self.oneri): b.setText(on[i] if i < len(on) else ''); b.setVisible(i < len(on))
                self.onz.setVisible(not on)   # öneri varken yazılan metin satırı yerini önerilere bırakır
            if getattr(self, '_son_mat', None) != mat: self._son_mat = mat; self.yerlestir()
    def hideEvent(self, e):
        self.zm.stop(); t = self.kb.target
        try:   # yazılan sözcükler öğrenilir (öneride öne çıkar)
            for w in (t.text() if t is not None else '').split():
                if w.isalpha() and not w[0].isupper(): self.ogren(w)   # özel adlar (öğrenci adı vb.) öğrenilmez
        except Exception: pass
        super().hideEvent(e)

def attach_touch_keyboard(dlg, edit, layout):
    """Diyalogdaki yazı alanına dokununca uygulamanın klavyesi çıkar (tahtada sistem klavyesi açılmayabiliyor)."""
    from PyQt5.QtCore import QObject
    kb = TouchKeyboard(dlg); kb.hide(); layout.addWidget(kb); dlg._kb = kb; dlg._kb_edit = edit
    class _F(QObject):
        def eventFilter(self_, o, e):
            if e.type() == QEvent.MouseButtonPress and o is edit:
                kb.attach(edit)
                if kb.isHidden():
                    kb.show(); dlg.adjustSize(); scr = QApplication.primaryScreen().availableGeometry()
                    dlg.resize(dlg.width(), min(scr.height() - 40, max(dlg.height(), dlg.sizeHint().height())))
                    dlg.move(dlg.x(), max(scr.top() + 10, min(dlg.y(), scr.bottom() - dlg.height() - 10)))
            return False
    f = _F(dlg); edit.installEventFilter(f); dlg._kb_filter = f
    return kb

NEON_ARA_TEXT = 'Nerede sınava gireceğim?'
def neon_button(parent, on_click, font_px=22):
    """Neon tabela gibi parlayan düğme (camgöbeği kenar ve yazı, nefes alan ışıma): öğrenci araması için."""
    from PyQt5.QtWidgets import QGraphicsDropShadowEffect
    b = QPushButton(NEON_ARA_TEXT, parent); b.setFocusPolicy(Qt.NoFocus); b.setMinimumHeight(58); b.clicked.connect(on_click)
    b.setStyleSheet('QPushButton{background:rgba(8,14,30,0.92);color:#7ff6ff;border:3px solid #22e8ff;border-radius:18px;padding:0 30px;font-size:%dpx;font-weight:800;}'
                    'QPushButton:pressed{background:#0d2a3a;}' % font_px)
    fx = QGraphicsDropShadowEffect(b); fx.setColor(QColor(34, 232, 255)); fx.setOffset(0, 0); fx.setBlurRadius(30); b.setGraphicsEffect(fx)
    a = QVariantAnimation(b); a.setStartValue(16.0); a.setKeyValueAt(0.5, 44.0); a.setEndValue(16.0); a.setDuration(2200); a.setLoopCount(-1)
    a.valueChanged.connect(lambda v: fx.setBlurRadius(float(v))); a.start(); b._neon = a
    return b

OFFICE_EXTS = ('.pptx', '.ppt', '.ppsx', '.pps', '.odp', '.docx', '.doc', '.odt', '.rtf', '.pptm', '.potx')
PPTX_EXTS = ('.pptx', '.ppsx', '.pptm', '.potx')
def pptx_yedek_pdf(path, out):
    """K-393: LibreOffice yoksa PowerPoint (.pptx/.ppsx) Atlas'ın kendisiyle PDF'e çevrilir: her slayt bir sayfa;
    resimler ve yazılar yerinde (animasyon, grafik/SmartArt ve özel efektler yok). Döner: sayfa sayısı."""
    import zipfile, posixpath, re as _r
    import xml.etree.ElementTree as ET
    NS = dict(p='http://schemas.openxmlformats.org/presentationml/2006/main', a='http://schemas.openxmlformats.org/drawingml/2006/main',
              r='http://schemas.openxmlformats.org/officeDocument/2006/relationships', rel='http://schemas.openxmlformats.org/package/2006/relationships')
    RID = '{%s}id' % NS['r']; EMBED = '{%s}embed' % NS['r']
    z = zipfile.ZipFile(path)
    def oku(n):
        try: return ET.fromstring(z.read(n))
        except (KeyError, ET.ParseError): return None
    def iliski(n):
        d, b = posixpath.split(n); x = oku(posixpath.join(d, '_rels', b + '.rels')); res = {}
        if x is not None:
            for e in x.findall('rel:Relationship', NS):
                if e.get('TargetMode') == 'External': continue
                res[e.get('Id')] = posixpath.normpath(posixpath.join(d, e.get('Target')))
        return res
    pres = oku('ppt/presentation.xml')
    if pres is None: raise ValueError('PowerPoint dosyası okunamadı.')
    sz = pres.find('p:sldSz', NS); W = int(sz.get('cx', 12192000)) / 12700.0 if sz is not None else 960.0; H = int(sz.get('cy', 6858000)) / 12700.0 if sz is not None else 540.0
    prel = iliski('ppt/presentation.xml')
    slaytlar = [prel.get(e.get(RID)) for e in pres.findall('p:sldIdLst/p:sldId', NS)]
    fonts = pdf_fonts(); fr, fb = fonts.get('r'), fonts.get('b')
    renkler = {'tx1': '000000', 'bg1': 'FFFFFF', 'tx2': '1F3864', 'bg2': 'E7E6E6', 'accent1': '4472C4', 'accent2': 'ED7D31', 'accent3': 'A5A5A5', 'accent4': 'FFC000', 'accent5': '5B9BD5', 'accent6': '70AD47', 'dk1': '000000', 'lt1': 'FFFFFF', 'dk2': '1F3864', 'lt2': 'E7E6E6'}
    th = next((n for n in z.namelist() if _r.fullmatch(r'ppt/theme/theme\d+\.xml', n)), None); tx = oku(th) if th else None
    if tx is not None:
        cs = tx.find('.//a:clrScheme', NS)
        for c in list(cs) if cs is not None else []:
            k = c.tag.split('}')[1]; v = c.find('a:srgbClr', NS); s_ = c.find('a:sysClr', NS)
            v = v.get('val') if v is not None else (s_.get('lastClr') if s_ is not None else None)
            if v: renkler[k] = v
    def renk(el, vars_='000000'):
        if el is None: return vars_
        s = el.find('a:srgbClr', NS)
        if s is not None: return s.get('val', vars_)
        s = el.find('a:schemeClr', NS)
        if s is not None: return renkler.get(s.get('val'), vars_)
        return vars_
    rgb = lambda h: tuple(int(h[i:i+2], 16)/255.0 for i in (0, 2, 4)) if h and len(h) >= 6 else (0, 0, 0)
    def kutu(sp, ox=0.0, oy=0.0, sx=1.0, sy=1.0):
        x = sp.find('.//a:xfrm', NS)
        if x is None: x = sp.find('p:xfrm', NS)   # tablo/grafik çerçevesi
        if x is None: return None
        o = x.find('a:off', NS); e = x.find('a:ext', NS)
        if o is None or e is None: return None
        X = int(o.get('x', 0))/12700.0; Y = int(o.get('y', 0))/12700.0; Wd = int(e.get('cx', 0))/12700.0; Hd = int(e.get('cy', 0))/12700.0
        return fitz.Rect(ox + X*sx, oy + Y*sy, ox + (X + Wd)*sx, oy + (Y + Hd)*sy)
    def resim(page, r_, ad):
        try: page.insert_image(r_, stream=z.read(ad), keep_proportion=False, overlay=True)
        except Exception: pass
    def arka(page, x, rels):
        if x is None: return False
        bg = x.find('p:cSld/p:bg', NS)
        if bg is None: return False
        bl = bg.find('.//a:blip', NS)
        if bl is not None and rels.get(bl.get(EMBED)): resim(page, page.rect, rels[bl.get(EMBED)]); return True
        sf = bg.find('.//a:solidFill', NS)
        if sf is not None: page.draw_rect(page.rect, color=None, fill=rgb(renk(sf, 'FFFFFF'))); return True
        return False
    def yazi(page, sp, r_, baslik):
        tb = sp.find('p:txBody', NS)
        if tb is None: return
        satirlar = []; boy = None; rk = None; kalin = False; ortala = 0
        for p_ in tb.findall('a:p', NS):
            parca = []
            for rn in p_:
                t = rn.tag.split('}')[1]
                if t in ('r', 'fld'):
                    te = rn.find('a:t', NS); parca.append(te.text or '' if te is not None else '')
                    rp = rn.find('a:rPr', NS)
                    if rp is not None:
                        if boy is None and rp.get('sz'): boy = int(rp.get('sz'))/100.0
                        if rp.get('b') == '1': kalin = True
                        if rk is None and rp.find('a:solidFill', NS) is not None: rk = renk(rp.find('a:solidFill', NS))
                elif t == 'br': parca.append('\n')
            ppr = p_.find('a:pPr', NS)
            if ppr is not None and ppr.get('algn') == 'ctr': ortala = 1
            s = ''.join(parca)
            if s.strip():
                madde = (not baslik) and (ppr is None or ppr.find('a:buNone', NS) is None) and sp.find('.//p:nvPr/p:ph', NS) is not None
                satirlar.append(('• ' if madde else '') + s)
            elif satirlar: satirlar.append('')
        metin = '\n'.join(satirlar).strip('\n')
        if not metin: return
        boy = boy or (36.0 if baslik else 20.0); renk_ = rgb(rk or renkler.get('tx1', '000000'))
        ff = fb if (kalin or baslik) and fb else fr
        rr = fitz.Rect(r_.x0 + 4, r_.y0 + 2, max(r_.x1 - 4, r_.x0 + 40), max(r_.y1, r_.y0 + 20) + boy*0.6)
        for _ in range(14):   # sığmazsa küçült
            try:
                k = page.insert_textbox(rr, metin, fontsize=boy, fontname='ux' + ('b' if ff == fb else 'r'), fontfile=ff, color=renk_, align=ortala) if ff else page.insert_textbox(rr, metin, fontsize=boy, color=renk_, align=ortala)
            except Exception: k = -1
            if k >= 0: return
            boy *= 0.88
    def agac(page, kok, rels, yt, ox=0.0, oy=0.0, sx=1.0, sy=1.0):
        for el in kok:
            t = el.tag.split('}')[1]
            if t == 'grpSp':
                x = el.find('p:grpSpPr/a:xfrm', NS)
                if x is not None and x.find('a:chOff', NS) is not None:
                    o, e, co, ce = (x.find(q, NS) for q in ('a:off', 'a:ext', 'a:chOff', 'a:chExt'))
                    g = lambda q, k: int(q.get(k, 0))/12700.0
                    nsx = sx*(g(e, 'cx')/(g(ce, 'cx') or 1)); nsy = sy*(g(e, 'cy')/(g(ce, 'cy') or 1))
                    agac(page, el, rels, yt, ox + g(o, 'x')*sx - g(co, 'x')*nsx, oy + g(o, 'y')*sy - g(co, 'y')*nsy, nsx, nsy)
                else: agac(page, el, rels, yt, ox, oy, sx, sy)
            elif t == 'pic':
                bl = el.find('.//a:blip', NS); r_ = kutu(el.find('p:spPr', NS), ox, oy, sx, sy) if el.find('p:spPr', NS) is not None else None
                if bl is not None and r_ is not None and rels.get(bl.get(EMBED)): resim(page, r_, rels[bl.get(EMBED)])
            elif t == 'sp':
                ph = el.find('.//p:nvPr/p:ph', NS); spr = el.find('p:spPr', NS)
                r_ = kutu(spr, ox, oy, sx, sy) if spr is not None else None
                if r_ is None and ph is not None: r_ = yt.get(('i', ph.get('idx'))) or yt.get(('t', ph.get('type', 'body')))
                if r_ is None: continue
                if spr is not None:
                    sf = spr.find('a:solidFill', NS); bf = spr.find('a:blipFill/a:blip', NS)
                    if bf is not None and rels.get(bf.get(EMBED)): resim(page, r_, rels[bf.get(EMBED)])
                    elif sf is not None: page.draw_rect(r_, color=None, fill=rgb(renk(sf, 'FFFFFF')))
                baslik = ph is not None and ph.get('type') in ('title', 'ctrTitle')
                yazi(page, el, r_, baslik)
            elif t == 'graphicFrame':   # tablo: hücre yazıları satır satır
                r_ = kutu(el, ox, oy, sx, sy); tbl = el.find('.//a:tbl', NS)
                if r_ is None or tbl is None: continue
                rows = tbl.findall('a:tr', NS); hy = r_.height/max(1, len(rows))
                for i, tr in enumerate(rows):
                    cells = tr.findall('a:tc', NS); wx = r_.width/max(1, len(cells))
                    for j, tc in enumerate(cells):
                        cr = fitz.Rect(r_.x0 + j*wx, r_.y0 + i*hy, r_.x0 + (j + 1)*wx, r_.y0 + (i + 1)*hy); page.draw_rect(cr, color=(0.6, 0.6, 0.6), width=0.6)
                        s = ' '.join((te.text or '') for te in tc.iter('{%s}t' % NS['a'])).strip()
                        if s:
                            b_ = 14.0
                            for _ in range(10):
                                if (page.insert_textbox(cr + (3, 2, -3, 0), s, fontsize=b_, fontname='uxr', fontfile=fr) if fr else page.insert_textbox(cr + (3, 2, -3, 0), s, fontsize=b_)) >= 0: break
                                b_ *= 0.85
    doc = fitz.open()
    for ad in slaytlar:
        if not ad: continue
        x = oku(ad)
        if x is None: continue
        if x.get('show') == '0': continue   # gizli slayt
        rels = iliski(ad); page = doc.new_page(width=W, height=H)
        lay = next((v for v in rels.values() if 'slideLayout' in v), None); lrels = iliski(lay) if lay else {}
        mas = next((v for v in lrels.values() if 'slideMaster' in v), None); mrels = iliski(mas) if mas else {}
        if not arka(page, x, rels) and not (lay and arka(page, oku(lay), lrels)): arka(page, oku(mas) if mas else None, mrels)
        yt = {}
        for hedef, hr in ((lay, lrels), (mas, mrels)):
            hx = oku(hedef) if hedef else None
            if hx is None: continue
            for sp in hx.iter('{%s}sp' % NS['p']):
                ph = sp.find('.//p:nvPr/p:ph', NS); r_ = kutu(sp.find('p:spPr', NS)) if sp.find('p:spPr', NS) is not None else None
                if ph is not None and r_ is not None:
                    for k in (('t', ph.get('type', 'body')), ('i', ph.get('idx'))):
                        if k[1] is not None: yt.setdefault(k, r_)
        if lay:   # yerleşimdeki sabit resimler (logo, şerit)
            lx = oku(lay); st = lx.find('p:cSld/p:spTree', NS) if lx is not None else None
            if st is not None:
                for pic in st.findall('p:pic', NS):
                    bl = pic.find('.//a:blip', NS); r_ = kutu(pic.find('p:spPr', NS)) if pic.find('p:spPr', NS) is not None else None
                    if bl is not None and r_ is not None and lrels.get(bl.get(EMBED)): resim(page, r_, lrels[bl.get(EMBED)])
        st = x.find('p:cSld/p:spTree', NS)
        if st is not None: agac(page, st, rels, yt)
    if not doc.page_count: raise ValueError('PowerPoint dosyasında slayt bulunamadı.')
    n = doc.page_count; doc.save(out, garbage=3, deflate=True); doc.close(); return n

def sistem_olcum():
    """K-429: tahtanın donanım durumu (arka planda): boş bellek, takas, yük, sıcaklık. Donmanın donanımdan mı olduğu buradan görülür."""
    out = {}
    try:
        mi = {}
        with open('/proc/meminfo') as f:
            for l in f:
                k, v = l.split(':', 1); mi[k] = int(v.split()[0])
        out.update(bellek_mb=round(mi.get('MemTotal', 0)/1024), bos_mb=round(mi.get('MemAvailable', 0)/1024), takas_mb=round((mi.get('SwapTotal', 0) - mi.get('SwapFree', 0))/1024))
    except (OSError, ValueError): pass
    try:
        with open('/proc/loadavg') as f: out['yuk'] = float(f.read().split()[0])
        out['cekirdek'] = os.cpu_count() or 0
    except (OSError, ValueError): pass
    try:
        import glob as _g
        ts = []
        for z in _g.glob('/sys/class/thermal/thermal_zone*/temp'):
            try:
                with open(z) as f: v = int(f.read().strip())
                if 1000 < v < 130000: ts.append(v/1000)
            except (OSError, ValueError): pass
        if ts: out['sicaklik'] = round(max(ts))
    except Exception: pass
    try:
        st = os.statvfs('/'); out['disk_bos_gb'] = round(st.f_bavail*st.f_frsize/2**30, 1)
    except OSError: pass
    return out
class SurecBaslatici:
    """K-431: arka plan programlarını (havuz) ekran iş parçacığı dışından başlatır. Büyük bir Qt/Python sürecinden yeni süreç açmak
    (fork/exec) bellek sıkışıkken saniyeler sürebiliyor; burada sıraya girer, ayrı iş parçacığı açar, biten süreçler toplanır (zombi kalmaz)."""
    def __init__(self):
        import threading, queue
        self.q = queue.Queue(); self.canli = []
        threading.Thread(target=self._dongu, name='surec', daemon=True).start()
    def baslat(self, cmd): self.q.put(list(cmd))
    def _dongu(self):
        import subprocess, queue
        while True:
            try: cmd = self.q.get(timeout=5)
            except queue.Empty: cmd = None
            self.canli = [p_ for p_ in self.canli if p_.poll() is None]
            if not cmd: continue
            try: self.canli.append(subprocess.Popen(cmd, stdin=subprocess.DEVNULL, close_fds=True, start_new_session=True))
            except OSError as e: print('süreç:', cmd[:2], e)
_SB = []
def surec_baslat(cmd):
    if not _SB: _SB.append(SurecBaslatici())
    _SB[0].baslat(cmd)
def kalem_mesgul(o):
    """K-429: pencere yazı yazılıyor mu diyor (yoksa hayır). Aralıksız yazılsa da arka plan işi en çok 30 sn bekler."""
    f = getattr(o, 'kalem_yaziyor', None)
    if not (callable(f) and f()): o.__dict__.pop('_mesgul_t0', None); return False
    t0 = o.__dict__.setdefault('_mesgul_t0', time.time())
    if time.time() - t0 > 30: o.__dict__.pop('_mesgul_t0', None); return False
    return True
_DUSUK = []
def dusuk_oncelik():
    """K-429: arka plan işlemleri için 'nice -n 15 ionice -c 3' ön eki (araçlar yoksa boş)."""
    if not _DUSUK:
        n = shutil.which('nice'); io = shutil.which('ionice'); on = []
        if n: on += [n, '-n', '15']
        if io: on += [io, '-c', '3']
        _DUSUK.append(on)
    return list(_DUSUK[0])
def office_binary():
    """Tahtadaki LibreOffice (PowerPoint/Word dosyalarını PDF'e çevirmek için); yoksa None."""
    for n in ('libreoffice', 'soffice', '/usr/lib/libreoffice/program/soffice', '/opt/libreoffice/program/soffice'):
        p = shutil.which(n) if not n.startswith('/') else (n if os.access(n, os.X_OK) else None)
        if p: return p
    return None
def office_to_pdf(main, path):
    """PowerPoint/Word belgesini PDF'e çevirir (LibreOffice, ekransız); çevrilmiş kopya saklanır, ikinci açılış anında olur.
    Döner: (pdf yolu, sekme adı). Fotoğraf ve yazılar olduğu gibi; animasyon yok (sayfa sayfa)."""
    import hashlib, subprocess, threading
    st = os.stat(path); key = hashlib.sha1(('%s|%d|%d' % (os.path.realpath(path), st.st_size, int(st.st_mtime))).encode('utf-8')).hexdigest()[:16]
    name = os.path.splitext(os.path.basename(path))[0]
    folder = os.path.join(main.data_dir, 'ofis'); os.makedirs(folder, exist_ok=True)
    out = os.path.join(folder, '%s-%s.pdf' % (''.join(c for c in name if c not in '/\\:*?"<>|')[:60] or 'belge', key))
    if os.path.isfile(out) and os.path.getsize(out) > 0: return out, name
    exe = office_binary()
    if not exe and os.path.splitext(path)[1].lower() in PPTX_EXTS:   # K-393: LibreOffice yok → Atlas'ın kendi çeviricisi
        main.statusBar().showMessage('“%s” hazırlanıyor… (slaytlar sayfaya çevriliyor)' % name); QApplication.setOverrideCursor(Qt.WaitCursor)
        try: pptx_yedek_pdf(path, out)
        except Exception as e: raise ValueError('PowerPoint açılamadı: %s' % e)
        finally: QApplication.restoreOverrideCursor()
        main.statusBar().showMessage('“%s” açıldı · her slayt bir sayfa; üstüne yazabilirsiniz (animasyonlar yok)' % name)
        return out, name
    if not exe: raise ValueError('Bu tahtada LibreOffice bulunamadı; bu dosya türü (eski .ppt / Word) çevrilemiyor.\nPowerPoint\'te “Farklı kaydet → .pptx” ya da PDF olarak kaydedip açabilirsiniz.')
    tmp = tempfile.mkdtemp(prefix='umal-ofis-'); prof = os.path.join(tempfile.gettempdir(), 'umal-lo-profil')
    res = {}
    def work():
        try: res['r'] = subprocess.run([exe, '-env:UserInstallation=file://' + prof, '--headless', '--norestore', '--convert-to', 'pdf', '--outdir', tmp, path],
                                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180)
        except Exception as e: res['e'] = e
    th = threading.Thread(target=work, daemon=True); th.start()
    main.statusBar().showMessage('“%s” hazırlanıyor… (PowerPoint/Word sayfaları PDF’e çevriliyor, birkaç saniye sürer)' % name)
    QApplication.setOverrideCursor(Qt.WaitCursor)
    try:
        while th.is_alive(): QApplication.processEvents(); th.join(0.05)
    finally: QApplication.restoreOverrideCursor()
    if 'e' in res: raise ValueError('Belge çevrilemedi: %s' % res['e'])
    made = [f for f in os.listdir(tmp) if f.lower().endswith('.pdf')]
    if not made:
        err = (res.get('r').stderr or b'').decode('utf-8', 'replace')[-300:] if res.get('r') else ''
        raise ValueError('Belge PDF’e çevrilemedi.' + ('\n' + err if err.strip() else ''))
    shutil.move(os.path.join(tmp, made[0]), out); shutil.rmtree(tmp, ignore_errors=True)
    main.statusBar().showMessage('“%s” açıldı · sayfalar resim gibi; üstüne yazabilirsiniz' % name)
    return out, name

def daily_today():
    import datetime; return datetime.date.today().isoformat()
def daily_date_text():
    import datetime; d = datetime.date.today()
    return '%d %s %d %s' % (d.day, TR_MONTHS[d.month-1], d.year, TR_DAYS[d.weekday()])

class HavuzDialog(QDialog):
    """PDF Havuzu: every board's shared PDFs. Tap to open, remove from this
    board only, add a PDF for all boards, bring back removed ones."""
    def __init__(self, main):
        super().__init__(main); self.main = main
        self.setWindowTitle('PDF Havuzu'); self.setModal(True)
        scr = QApplication.primaryScreen().availableGeometry(); self.resize(min(900, scr.width()-80), min(760, scr.height()-80))
        box = QVBoxLayout(self); box.setContentsMargins(18, 16, 18, 16); box.setSpacing(10)
        title = QLabel('PDF Havuzu'); title.setStyleSheet('font-size:20px;font-weight:bold;'); box.addWidget(title)
        self.note = QLabel(); self.note.setWordWrap(True); self.note.setStyleSheet('color:#a9b9cf;'); box.addWidget(self.note)
        self.scroll = QScrollArea(); self.scroll.setWidgetResizable(True); box.addWidget(self.scroll, 1)
        row = QHBoxLayout(); row.setSpacing(8); box.addLayout(row)
        # One-time: link the pool to the school's Google account (opens the board's browser).
        self.link_button = QPushButton('Havuzu Google hesabına bağla (bir kez)'); self.link_button.setMinimumHeight(48)
        self.link_button.clicked.connect(self.link); self.link_button.hide(); box.insertWidget(2, self.link_button)
        for text, fn, name in (('Havuza PDF ekle', self.add_pdf, 'primary'), ('Şimdi eşitle', self.sync_now, ''), ('Kapat', self.accept, '')):
            b = QPushButton(text); b.setObjectName(name); b.setMinimumHeight(48); b.clicked.connect(fn); row.addWidget(b, 1)
        self.auth = None
        self.shown = None; self.show_removed = False
        self.timer = QTimer(self); self.timer.timeout.connect(self.refresh); self.timer.start(2000); self.refresh()
    def state(self):
        try:
            with open(os.path.join(havuz_data(), 'durum.json'), encoding='utf-8') as f: return json.load(f)
        except (OSError, ValueError): return {'known': {}, 'removed': []}
    def status(self):
        try:
            with open(os.path.join(havuz_data(), 'son.json'), encoding='utf-8') as f: return json.load(f)
        except (OSError, ValueError): return {}
    def refresh(self):
        os.makedirs(HAVUZ_DIR, exist_ok=True)
        files = sorted((n for n in os.listdir(HAVUZ_DIR) if n.lower().endswith('.pdf') and not n.startswith('.')), key=str.lower)
        busy = [n[len('.indiriliyor-'):] for n in os.listdir(HAVUZ_DIR) if n.startswith('.indiriliyor-')]
        removed = self.state().get('removed', []); st = self.status()
        self.link_button.setVisible(st.get('durum') == 'bagli-degil' and os.path.isfile(HAVUZ_RCLONE) and self.auth is None)
        if not havuz_ready(): note = 'Bu cihazda havuz eşitleyicisi kurulu değil; yalnızca bu tahtadaki PDF\'ler görünür.'
        elif st.get('durum') == 'bagli-degil': note = 'Havuz henüz okul hesabına bağlanmadı.'
        elif st.get('durum') == 'hata': note = 'Son eşitleme yapılamadı: ' + st.get('mesaj', '')
        elif st.get('zaman'): note = '%s · son eşitleme %s' % (st.get('mesaj', ''), time.strftime('%H:%M', time.localtime(st['zaman'])))
        else: note = 'İlk eşitleme bekleniyor…'
        if busy: note += '\nİndiriliyor: ' + ', '.join(busy)
        self.note.setText(note)
        key = (tuple(files), tuple(removed), self.show_removed)
        if key == self.shown: return
        self.shown = key
        holder = QWidget(); lay = QVBoxLayout(holder); lay.setContentsMargins(0, 0, 8, 0); lay.setSpacing(6)
        if not files:
            empty = QLabel('Havuzda henüz PDF yok. "Havuza PDF ekle" ile ilk dosyayı ekleyin; birkaç dakika içinde bütün tahtalarda görünür.')
            empty.setWordWrap(True); lay.addWidget(empty)
        for name in files:
            line = QHBoxLayout(); line.setSpacing(6)
            size = os.path.getsize(os.path.join(HAVUZ_DIR, name)) / 1048576
            b = QPushButton('%s   ·   %s MB' % (os.path.splitext(name)[0], ('%.1f' % size).replace('.', ','))); b.setIcon(tool_icon('PDF aç'))
            b.setStyleSheet('QPushButton{text-align:left;padding:8px 14px;font-size:16px;}'); b.setMinimumHeight(52)
            b.clicked.connect(lambda checked=False, n=name: self.open(n)); line.addWidget(b, 1)
            r = QPushButton('Bu tahtadan kaldır'); r.setMinimumHeight(52); r.clicked.connect(lambda checked=False, n=name: self.remove(n)); line.addWidget(r)
            lay.addLayout(line)
        if removed:
            t = QPushButton(('▾ ' if self.show_removed else '▸ ') + 'Bu tahtadan kaldırılanlar (%d)' % len(removed)); t.setMinimumHeight(44)
            t.setStyleSheet('QPushButton{text-align:left;padding:6px 14px;}'); t.clicked.connect(self.toggle_removed); lay.addWidget(t)
            if self.show_removed:
                for name in removed:
                    line = QHBoxLayout(); lab = QLabel('   ' + os.path.splitext(name)[0]); line.addWidget(lab, 1)
                    g = QPushButton('Geri al'); g.setMinimumHeight(44); g.clicked.connect(lambda checked=False, n=name: self.restore(n)); line.addWidget(g)
                    lay.addLayout(line)
        lay.addStretch(); self.scroll.setWidget(holder)
    def toggle_removed(self):
        self.show_removed = not self.show_removed; self.shown = None; self.refresh()
    def open(self, name):
        self.accept(); self.main.open_pdf_path(os.path.join(HAVUZ_DIR, name))
    def remove(self, name):
        if QMessageBox.question(self, 'Bu tahtadan kaldır', '“%s” bu tahtadan kaldırılsın mı?\n\nHavuzda ve diğer tahtalarda kalır. İsterseniz “Bu tahtadan kaldırılanlar” listesinden geri alabilirsiniz.' % os.path.splitext(name)[0],
                                QMessageBox.Yes | QMessageBox.No, QMessageBox.No) != QMessageBox.Yes: return
        try: os.remove(os.path.join(HAVUZ_DIR, name))
        except OSError as e: QMessageBox.warning(self, 'Kaldırılamadı', str(e)); return
        self.main.run_havuz('--hemen'); self.shown = None; self.refresh()
    def restore(self, name):
        self.main.run_havuz('--geri-al', name); self.note.setText('“%s” yeniden indiriliyor…' % os.path.splitext(name)[0])
    def add_pdf(self):
        paths, _ = QFileDialog.getOpenFileNames(self, 'Havuza PDF ekle', os.path.expanduser('~'), 'PDF dosyaları (*.pdf)')
        added = 0
        for path in paths:
            if os.path.realpath(os.path.dirname(path)) == os.path.realpath(HAVUZ_DIR): continue
            name = os.path.basename(path); target = os.path.join(HAVUZ_DIR, name); k = 2
            while os.path.exists(target): target = os.path.join(HAVUZ_DIR, '%s (%d).pdf' % (os.path.splitext(name)[0], k)); k += 1
            try: shutil.copy2(path, target); added += 1
            except OSError as e: QMessageBox.warning(self, 'Eklenemedi', str(e))
        if added:
            self.shown = None; self.refresh()
            self.note.setText('%d PDF eklendi, havuza gönderiliyor…' % added); self.main.run_havuz('--hemen')
    def sync_now(self):
        self.main.run_havuz('--hemen'); self.note.setText('Eşitleniyor…')
    def link(self):
        self.auth = QProcess(self); self.auth.setProcessChannelMode(QProcess.MergedChannels)
        self.auth.finished.connect(self.linked); self.link_button.hide()
        self.auth.start(HAVUZ_RCLONE, ['authorize', 'drive', '--drive-scope', 'drive.file'])
        self.note.setText('Tarayıcı açılıyor: okul hesabıyla giriş yapıp izin verin, sonra buraya dönün…')
    def linked(self, *args):
        out = bytes(self.auth.readAll()).decode('utf-8', 'replace'); self.auth = None
        token = token_from_authorize(out)
        if not token:
            self.note.setText('Bağlantı tamamlanamadı. Yeniden deneyin.'); self.shown = None; self.refresh(); return
        conf = '[havuz]\ntype = drive\nscope = drive.file\ntoken = %s\n' % token
        folder = havuz_data(); os.makedirs(folder, exist_ok=True); path = os.path.join(folder, 'rclone.conf')
        with open(path, 'w', encoding='utf-8') as f: f.write(conf)
        os.chmod(path, 0o600); self.main.run_havuz('--hemen')
        # Other boards get the link through the update: show it once to send to Claude.
        box = QDialog(self); box.setWindowTitle('Havuz bağlandı'); lay = QVBoxLayout(box)
        lab = QLabel('Bu tahta havuza bağlandı. Diğer tahtaların da bağlanması için aşağıdaki metni kopyalayıp Claude\'a gönderin; güncelleme ile bütün tahtalara dağıtılır.')
        lab.setWordWrap(True); lay.addWidget(lab)
        from PyQt5.QtWidgets import QPlainTextEdit
        text = QPlainTextEdit(conf); text.setReadOnly(True); text.setMinimumSize(700, 180); lay.addWidget(text)
        copy = QPushButton('Kopyala'); copy.setMinimumHeight(48); copy.clicked.connect(lambda: (QApplication.clipboard().setText(conf), copy.setText('Kopyalandı')))
        lay.addWidget(copy); box.exec_()
