def yonetim_istek(path, data, ctype='application/json', timeout=60):
    """Supabase'e POST; hata olursa sunucunun kendi iletisiyle RuntimeError."""
    import urllib.request, urllib.error
    body = json.dumps(data, ensure_ascii=False).encode('utf-8') if ctype == 'application/json' else data
    req = urllib.request.Request(YONETIM_URL + path, data=body, method='POST',
                                 headers={'apikey': YONETIM_KEY, 'Authorization': 'Bearer ' + YONETIM_KEY, 'Content-Type': ctype, 'Accept': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r: raw = r.read()
    except urllib.error.HTTPError as e:
        try: d = json.loads(e.read().decode('utf-8', 'replace')); msg = d.get('message') or d.get('error') or d.get('msg') or str(d)
        except Exception: msg = 'sunucu hatası %d' % e.code
        raise RuntimeError(msg)
    except urllib.error.URLError as e: raise RuntimeError('Sunucuya bağlanılamadı (%s)' % getattr(e, 'reason', e))
    return json.loads(raw.decode('utf-8')) if raw else None
def printer_list(resp):
    """umal_yazicilar_al yanıtı → [(etiket, cihaz, yazıcı)]. Liste ya da {"yazicilar": [...]} gelebilir."""
    items = resp.get('yazicilar', resp.get('liste', [])) if isinstance(resp, dict) else (resp or [])
    out = []
    for it in items if isinstance(items, list) else []:
        if not isinstance(it, dict): continue
        cihaz = it.get('cihaz') or it.get('cihaz_id') or it.get('hedef_cihaz') or ''
        yaz = it.get('yazici') or it.get('yazici_ad') or it.get('ad') or it.get('name') or ''
        pc = it.get('bilgisayar') or it.get('cihaz_ad') or it.get('konum') or ''
        if not (cihaz and yaz): continue
        etiket = yaz + (' · ' + pc if pc else '') + ('' if it.get('hazir', it.get('cevrimici', True)) else ' (kapalı)')
        out.append((etiket, cihaz, yaz))
    return out

def page_spec_error(text, n):
    """Özel sayfa aralığı: hata iletisi ya da None (geçerli)."""
    import re
    if not text: return 'Sayfaları yazın (ör. 1-3,5).'
    if not re.fullmatch(r'[0-9]+(-[0-9]+)?(,[0-9]+(-[0-9]+)?)*', text): return 'Biçim: 1-3,5 gibi; yalnız rakam, virgül ve tire.'
    for part in text.split(','):
        a, _, b = part.partition('-'); a = int(a); b = int(b) if b else a
        if a < 1 or b < 1: return 'Sayfa numarası 0 olamaz.'
        if a > n or b > n: return 'Belgede %d sayfa var.' % n
        if a > b: return 'Aralıkta baş sayfa son sayfadan büyük olamaz (%d-%d).' % (a, b)
    return None

