    # ---- Ayarlar: which buttons the left panel shows --------------------
    def apply_panel(self,hidden,save=True):
        self.panel_hidden=set(hidden)
        for key,label,widgets in self.panel_items:
            for w_ in widgets:w_.setVisible(key not in self.panel_hidden)
        self.layout_panel()
        if save: self.save_panel()
    # ---- Paneldeki düğmelerin yeri ----
    PANEL_HALF = ('perde', 'spot', 'geri_al', 'ileri_al', 'app:PDF kaydet', 'app:Araçlar', 'ayarlar')   # yan yana sığanlar ('Ekrana yaz' yarım genişlikte kesiliyordu: hep tam satır)
    PANEL_NAMES = {'renkler': 'Renkler', 'kalinlik': 'Kalınlık', 'kalem': 'Kalem uçları', 'tasi': 'Taşı', 'solution': 'Çözüm alanı', 'highlight': 'Fosforlu',
                   'eraser': 'Silgi', 'smart': 'Akıllı seçim', 'sekiller': 'Şekiller', 'postit': 'Post-it', 'perde': 'Perde', 'spot': 'Spot', 'alkis': 'Alkış', 'okul': 'Okul araçları', 'atlas': "Atlas'a sor",
                   'geri_al': 'Geri al', 'ileri_al': 'İleri al', 'app:Ekrana yaz': 'Ekrana yaz', 'app:PDF kaydet': 'Kaydet', 'app:Yazdır': 'Yazdır', 'app:Günün soruları': 'Günün soruları',
                   'app:Araçlar': 'Araçlar', 'ayarlar': 'Ayarlar'}
    def merge_order(self, order):
        known = [k for k in order if k in self.panel_units]
        for i, k in enumerate(self.panel_default):   # sonradan eklenen düğme: varsayılan komşusunun yanına
            if k not in known:
                prev = next((x for x in reversed(self.panel_default[:i]) if x in known), None)
                known.insert(known.index(prev) + 1 if prev else 0, k)
        return known
    def unit_visible(self, k):
        if k == 'ayarlar': return True   # Ayarlar hep görünür
        if k == 'kalem': return 'uclar' not in self.panel_hidden
        return k not in self.panel_hidden
    def panel_layout_rows(self):
        vis = [k for k in self.panel_order if self.unit_visible(k)]; rows = []; i = 0
        while i < len(vis):
            if vis[i] in self.PANEL_HALF and i + 1 < len(vis) and vis[i+1] in self.PANEL_HALF: rows.append(vis[i:i+2]); i += 2
            else: rows.append([vis[i]]); i += 1
        return rows
    def layout_panel(self):
        tools = self.panel_tools
        for row in self.panel_rows:
            lay = row.layout()
            while lay.count():
                w_ = lay.takeAt(0).widget()
                if w_ is not None: w_.setParent(self.panel_host)
            tools.removeWidget(row); row.deleteLater()
        self.panel_rows = []
        for k, w_ in self.panel_units.items():
            if not self.unit_visible(k): w_.setParent(self.panel_host)
        for n, keys in enumerate(self.panel_layout_rows()):
            row = QWidget(); h = QHBoxLayout(row); h.setContentsMargins(0, 0, 0, 0); h.setSpacing(4)
            for k in keys:
                w_ = self.panel_units[k]; h.addWidget(w_, 1); w_.show()
            tools.insertWidget(1 + n, row); self.panel_rows.append(row)
    def move_panel_unit(self, key, way):
        """Seçili düğmeyi panelde yukarı / aşağı / sola / sağa taşır."""
        rows = self.panel_layout_rows(); pos = next(((r, j) for r, ks in enumerate(rows) for j, k in enumerate(ks) if k == key), None)
        if pos is None: return False
        r, j = pos; order = self.panel_order
        if way in ('left', 'right'):
            if len(rows[r]) < 2 or (way == 'left') != (j == 1): return False
            a, b = order.index(rows[r][0]), order.index(rows[r][1]); order[a], order[b] = order[b], order[a]
        elif way == 'up':
            if r == 0: return False
            order.remove(key); order.insert(order.index(rows[r-1][0]), key)
        else:
            if r == len(rows) - 1: return False
            order.remove(key); order.insert(order.index(rows[r+1][-1]) + 1, key)
        self.layout_panel(); self.save_panel(); return True
    def save_panel(self):
        try:
            with open(os.path.join(self.data_dir,'panel.json'),'w',encoding='utf-8') as f:
                json.dump(dict(hidden=sorted(self.panel_hidden), order=self.panel_order, v27=True, v366=True), f, ensure_ascii=False)
        except OSError as e: self.statusBar().showMessage('Ayarlar kaydedilemedi: '+str(e))
    def panel_daralt(self, dar):
        """K-372: « / »: panel ince şeride iner, yazı alanı genişler; durum saklanır."""
        self.yeni_panel.setVisible(not dar); self.dar_serit.setVisible(dar)
        try:
            with open(os.path.join(self.data_dir,'panel-dar.json'),'w',encoding='utf-8') as f: json.dump({'dar': bool(dar)}, f)
        except OSError: pass
        QTimer.singleShot(0, self.place_overlays); QTimer.singleShot(120, self.place_overlays)
    def open_panel_settings(self):
        PanelSettings(self).exec_()
    def show_toast(self,text):
        if not text:return
        self.toast.setText(text);self.toast.show();self.place_overlays();self.toast_timer.start(4000)
    def eventFilter(self,obj,e):
        if obj is getattr(self,'scroll',None) and e.type() in (QEvent.Resize,QEvent.Show):self.place_overlays()
        return super().eventFilter(obj,e)
    def open_shapes(self):
        self.refresh_colors()   # a tap must not change the button's own state
        self.shape_popup.adjustSize()
        self.shape_popup.move(self.shape_button.mapToGlobal(QPoint(self.shape_button.width()+6,0)))
        self.shape_popup.show()
    def open_folder(self,popup,anchor):
        """Open a button's folder beside the panel, kept on screen."""
        self.refresh_colors();popup.adjustSize()
        screen=(self.windowHandle().screen() if self.windowHandle() else QApplication.primaryScreen()).availableGeometry()
        g=anchor.mapToGlobal(QPoint(anchor.width()+6,0))
        popup.move(max(screen.left(),min(g.x(),screen.right()-popup.width()-8)),max(screen.top()+8,min(g.y(),screen.bottom()-popup.height()-8)))
        if popup is self.erase_popup:self.unselect_button.setVisible(any(m['tool']=='whiteout' for m in self.marks.get(self.page,[])));popup.adjustSize()
        popup.show()
    def pick_shape(self,key):
        self.shape_popup.hide();self.set_tool(key)
