# Scientific calculator (touch friendly, safe evaluation — no eval()).
class Celebration(QWidget):
    """Alkış gösterisi: art arda roketler havada patlar, iki yandan ve üstten konfeti
    yağar; yaklaşık 6 saniye sonra kendiliğinden biter. Yazılara dokunmaz, dokunmayı engellemez."""
    DUR = 6.0; COLS = ['#e8132b', '#0057ff', '#00a24a', '#ffe14d', '#ff2d95', '#8a2be2', '#ff8a00', '#ffffff', '#38bdf8']
    def __init__(self, main):
        super().__init__(main); self.main = main
        self.setAttribute(Qt.WA_TransparentForMouseEvents); self.setAttribute(Qt.WA_NoSystemBackground); self.hide()
        self.timer = QTimer(self); self.timer.setInterval(30); self.timer.timeout.connect(self.step)
        self.cols = [QColor(c) for c in self.COLS]
    def start(self):
        import random
        R = random.Random(); self.rnd = R.uniform
        self.setGeometry(self.main.rect()); W, H = self.width(), self.height(); self.W, self.H = W, H; k = max(.6, H/1000)
        self.k = k; self.conf = []; self.sparks = []; self.rockets = []
        for side in (0, 1):   # konfeti topları
            x0 = W*(.97 if side else .03)
            for _ in range(230):
                a = R.uniform(.28, .62)*math.pi; v = R.uniform(14, 30)*k
                self.add_conf(x0, H*.98, (-1 if side else 1)*math.cos(a)*v, -math.sin(a)*v)
        for _ in range(200): self.add_conf(R.uniform(0, W), R.uniform(-H*.6, 0), R.uniform(-1, 1)*k, R.uniform(0, 3)*k)
        for i in range(9):   # roketler: alkış sesindeki gümbürtülerle aynı an (i·0.42 s'de kalkar, 0.95 s sonra patlar)
            self.rockets.append(dict(x=W*R.uniform(.15, .85), t=i*.42, vx=R.uniform(-1.5, 1.5)*k, c=R.randrange(7), peak=R.uniform(.55, .78), done=False, trail=[]))
        self.t0 = time.monotonic(); self.last = self.t0; self.show(); self.raise_(); self.timer.start()
    def add_conf(self, x, y, vx, vy):
        self.conf.append([x, y, vx, vy, self.rnd(8, 16)*self.k, self.rnd(4, 8)*self.k, self.rnd(0, 6), self.rnd(-.3, .3), int(self.rnd(0, len(self.COLS)-.01)), self.rnd(0, 6)])
    def rocket_pos(self, r, el):
        t = el - r['t']; H = self.H; fl = .95
        y = H - H*r['peak']*(1 - (1 - min(t, fl)/fl)**2); x = r['x'] + r['vx']*t*30
        return x, y
    def step(self):
        now = time.monotonic(); el = now - self.t0; f = min(3.0, (now - self.last)/.03); self.last = now
        if el > self.DUR: self.timer.stop(); self.hide(); self.conf = []; self.sparks = []; return
        g = .5*self.k*f
        for c in self.conf:
            c[3] += g; c[2] *= .985**f; c[3] *= .985**f; c[9] += .12*f
            c[0] += (c[2] + math.sin(c[9])*.8*self.k)*f; c[1] += c[3]*f; c[6] += c[7]*f
        for r in self.rockets:
            if el < r['t'] or r['done']: continue
            x, y = self.rocket_pos(r, el); r['trail'] = (r['trail'] + [(x, y)])[-12:]
            if el - r['t'] >= .95:
                r['done'] = True
                for i in range(80):
                    a = i/80*math.pi*2; v = self.rnd(4, 10)*self.k
                    self.sparks.append([x, y, math.cos(a)*v, math.sin(a)*v, 1.0, r['c'] if self.rnd(0, 1) > .25 else 7])
                for _ in range(30): self.add_conf(x, y, self.rnd(-7, 7)*self.k, self.rnd(-9, 3)*self.k)
        for s_ in self.sparks:
            s_[2] *= .96**f; s_[3] = s_[3]*.96**f + .12*self.k*f; s_[0] += s_[2]*f; s_[1] += s_[3]*f; s_[4] -= .016*f
        self.sparks = [s_ for s_ in self.sparks if s_[4] > 0]
        self.conf = [c for c in self.conf if c[1] < self.H + 40]
        self.update()
    def paintEvent(self, e):
        el = time.monotonic() - self.t0; p = QPainter(self)
        fade = 1.0 if el < 5.2 else max(0.0, 1 - (el - 5.2)/.8); p.setOpacity(fade); p.setPen(Qt.NoPen)
        for c in self.conf:   # dönen kâğıt: döndürülmüş dikdörtgen (dönüşümsüz, hızlı)
            x, y, w, h, r = c[0], c[1], c[4]/2, c[5]/2*abs(math.cos(c[6]*2)) + .5, c[6]
            ca, sa = math.cos(r), math.sin(r)
            p.setBrush(self.cols[c[8]])
            p.drawPolygon(QPolygonF([QPointF(x + ca*dx - sa*dy, y + sa*dx + ca*dy) for dx, dy in ((-w, -h), (w, -h), (w, h), (-w, h))]))
        p.setRenderHint(QPainter.Antialiasing)
        for r in self.rockets:
            if el < r['t'] or r['done'] or not r['trail']: continue
            n = len(r['trail'])
            for i, (x, y) in enumerate(r['trail']):
                a = (i + 1)/n; col = QColor(255, int(120 + 120*a), 40); col.setAlphaF(a); p.setBrush(col)
                rr = (1.5 + 3.5*a)*self.k; p.drawEllipse(QPointF(x, y + (n - i)*2*self.k), rr, rr)
            x, y = r['trail'][-1]; p.setBrush(self.cols[r['c']]); p.drawEllipse(QPointF(x, y), 4*self.k, 4*self.k)
        for s_ in self.sparks:
            col = QColor(self.cols[s_[5]]); col.setAlphaF(max(0.0, min(1.0, s_[4]))); p.setBrush(col)
            p.drawEllipse(QPointF(s_[0], s_[1]), 2.6*self.k, 2.6*self.k)

class MiniTimer(QWidget):
    """Küçük sayaç: tam ekran sayaç kapatılınca süre kenarda işlemeye devam eder.
    Dokun: tam ekrana döner · sürükle: yerini değiştirir · ✕: sayacı tamamen kapatır."""
    W, H = 236, 64
    def __init__(self, timer):
        super().__init__(None, Qt.Tool|Qt.FramelessWindowHint|Qt.WindowStaysOnTopHint)
        self.timer = timer; self.press = None; self.moved = False; self.placed = False
        self.setFixedSize(self.W, self.H); self.setCursor(Qt.PointingHandCursor)
        from PyQt5.QtGui import QPainterPath
        path = QPainterPath(); path.addRoundedRect(QRectF(0, 0, self.W, self.H), 16, 16)
        self.setMask(QRegion(path.toFillPolygon().toPolygon()))
        self.refresh = QTimer(self); self.refresh.setInterval(250); self.refresh.timeout.connect(self.update)
    def show_mini(self):
        if not self.placed:   # ilk kez: tahtanın sol üstü (oklar ve soru listesiyle çakışmaz)
            m = self.timer.main; vp = m.scroll.viewport(); g = vp.mapToGlobal(QPoint(14, 14)); self.move(g); self.placed = True
        self.refresh.start(); self.show(); self.raise_()
    def hideEvent(self, e): self.refresh.stop(); super().hideEvent(e)
    def close_rect(self): return QRectF(self.W-46, (self.H-34)/2, 34, 34)
    def paintEvent(self, e):
        t = self.timer; p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        done = t.state == 'done'; col = t.palette()[0]; paused = t.state == 'paused'
        p.setPen(QPen(col if done else QColor('#3a5577'), 2)); p.setBrush(QColor('#0f2442')); p.drawRoundedRect(QRectF(1, 1, self.W-2, self.H-2), 15, 15)
        c = QPointF(32, self.H/2); r = 18
        p.setPen(QPen(QColor('#24344f'), 5)); p.setBrush(Qt.NoBrush); p.drawEllipse(c, r, r)
        frac = 1.0 if done else (t.remaining/t.total if t.total else 0)
        p.setPen(QPen(col, 5, Qt.SolidLine, Qt.RoundCap)); p.drawArc(QRectF(c.x()-r, c.y()-r, 2*r, 2*r), 90*16, int(-360*16*frac))
        if paused:
            p.setPen(Qt.NoPen); p.setBrush(col); p.drawRect(QRectF(c.x()-6, c.y()-7, 4, 14)); p.drawRect(QRectF(c.x()+2, c.y()-7, 4, 14))
        f = p.font(); f.setPixelSize(19 if done else 26); f.setBold(True); p.setFont(f)
        p.setPen(col if (paused or done) else QColor('#f4f7ff'))
        p.drawText(QRectF(60, 0, self.W-112, self.H), Qt.AlignVCenter|Qt.AlignLeft, 'Süre doldu' if done else t.time_text())
        x = self.close_rect(); p.setPen(QPen(QColor(251, 113, 133, 160), 1)); p.setBrush(QColor(251, 113, 133, 40)); p.drawEllipse(x)
        p.setPen(QPen(QColor('#fb7185'), 2.2)); k = 6
        p.drawLine(QPointF(x.center().x()-k, x.center().y()-k), QPointF(x.center().x()+k, x.center().y()+k))
        p.drawLine(QPointF(x.center().x()-k, x.center().y()+k), QPointF(x.center().x()+k, x.center().y()-k))
    def mousePressEvent(self, e):
        self.press = (e.globalPos(), self.pos()); self.moved = False
    def mouseMoveEvent(self, e):
        if self.press is None: return
        d = e.globalPos() - self.press[0]
        if self.moved or abs(d.x()) + abs(d.y()) > 10: self.moved = True; self.move(self.press[1] + d)
    def mouseReleaseEvent(self, e):
        if self.press is None: return
        self.press = None
        if self.moved: return
        if self.close_rect().adjusted(-8, -8, 8, 8).contains(QPointF(e.pos())): self.timer.stop_timer()
        else: self.timer.open_timer()

def calc_evaluate(expr, degrees=True):
    import ast, re
    text = expr.replace('×','*').replace('÷','/').replace('−','-').replace(',','.').replace('π','pi').replace('^','**')
    text = text.replace('√','sqrt').replace('²','**2')
    text = re.sub(r'(\d+(?:\.\d+)?|\))\s*%', r'(\1/100)', text)
    # postfix factorial: number! or (...)!  ->  fact(...)
    while '!' in text:
        i = text.index('!'); j = i-1
        if j >= 0 and text[j] == ')':
            depth = 0
            while j >= 0:
                depth += text[j] == ')'; depth -= text[j] == '('
                if depth == 0: break
                j -= 1
        else:
            while j >= 0 and (text[j].isdigit() or text[j] == '.'): j -= 1
            j += 1
        if j < 0 or j >= i: raise ValueError('Hata')
        text = text[:j]+'fact('+text[j:i]+')'+text[i+1:]
    text = re.sub(r'(\d|\))\s*(?=\(|pi|e\b|sqrt|sin|cos|tan|ln|log|fact)', r'\1*', text)   # 2π, 3(4), 2sin(30)
    trig = (lambda f: (lambda x: f(math.radians(x)))) if degrees else (lambda f: f)
    def tan(x):
        a = math.radians(x) if degrees else x
        if abs(math.cos(a)) < 1e-12: raise ZeroDivisionError
        return math.tan(a)
    def fact(x):
        if x != int(x) or x < 0 or x > 170: raise ValueError('Hata')
        return float(math.factorial(int(x)))
    funcs = dict(sin=trig(math.sin), cos=trig(math.cos), tan=tan, ln=math.log, log=math.log10, sqrt=math.sqrt, fact=fact)
    names = dict(pi=math.pi, e=math.e)
    def ev(n):
        if isinstance(n, ast.Expression): return ev(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)): return float(n.value)
        if isinstance(n, ast.Name) and n.id in names: return names[n.id]
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub)):
            v = ev(n.operand); return v if isinstance(n.op, ast.UAdd) else -v
        if isinstance(n, ast.BinOp):
            a, b = ev(n.left), ev(n.right)
            if isinstance(n.op, ast.Add): return a+b
            if isinstance(n.op, ast.Sub): return a-b
            if isinstance(n.op, ast.Mult): return a*b
            if isinstance(n.op, ast.Div): return a/b
            if isinstance(n.op, ast.Pow):
                if abs(b) > 1000 or (abs(a) > 1 and abs(b*math.log10(abs(a))) > 300): raise OverflowError
                return a**b
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in funcs and len(n.args) == 1 and not n.keywords:
            return funcs[n.func.id](ev(n.args[0]))
        raise ValueError('Hata')
    value = ev(ast.parse(text, mode='eval'))
    if isinstance(value, complex) or math.isnan(value) or math.isinf(value): raise ValueError('Hata')
    return value

def calc_format(v):
    if abs(v) < 1e-12: v = 0.0
    if v == int(v) and abs(v) < 1e15: return '{:,}'.format(int(v)).replace(',', '.')
    s = ('%.12g' % v)
    if 'e' in s: m, ex = s.split('e'); return m.replace('.', ',')+' × 10^'+str(int(ex))
    return s.replace('.', ',')

class CalculatorPanel(QWidget):
    KEYS = [['sin','cos','tan','ln','log'],
            ['√','x²','xʸ','(',')'],
            ['π','e','n!','1/x','%'],
            ['7','8','9','÷','AC'],
            ['4','5','6','×','⌫'],
            ['1','2','3','−','Ans'],
            ['0',',','±','+','=']]
    def __init__(self, main):
        super().__init__(None, Qt.Window|Qt.FramelessWindowHint|Qt.WindowStaysOnTopHint)
        self.main = main; self.expr = ''; self.result = ''; self.ans = 0.0; self.degrees = True; self.drag_from = None; self.just_evaluated = False
        self.setWindowTitle('Hesap makinesi • '+PRODUCT); self.setWindowIcon(QIcon(LOGO))
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.setStyleSheet('''QWidget#calc{background:#0b1426;border:1px solid #2a3b57;border-radius:18px;}
            QLabel{color:#e8eefc;font-family:"DejaVu Sans";background:transparent;}
            QPushButton{font-family:"DejaVu Sans";font-size:22px;color:#e8eefc;background:#16233a;border:1px solid #24344f;border-radius:14px;}
            QPushButton:pressed{background:#24395c;}
            QPushButton#fn{font-size:19px;color:#a5c8ff;background:#111d31;}
            QPushButton#op{font-size:26px;color:#7dd3fc;background:#132a46;}
            QPushButton#eq{font-size:28px;font-weight:bold;background:#3b82f6;border:none;color:white;}
            QPushButton#ac{color:#fda4af;background:#2a1724;border:1px solid #4a2236;}
            QPushButton#mode{font-size:16px;border-radius:16px;padding:0 14px;}
            QPushButton#close{font-size:17px;border-radius:18px;padding:0 16px;color:#fecdd3;background:rgba(251,113,133,.16);border:1px solid rgba(251,113,133,.6);}''')
        outer = QVBoxLayout(self); outer.setContentsMargins(0,0,0,0)
        panel = QWidget(); panel.setObjectName('calc'); outer.addWidget(panel)
        layout = QVBoxLayout(panel); layout.setContentsMargins(16,12,16,16); layout.setSpacing(10)
        bar = QHBoxLayout(); layout.addLayout(bar)
        title = QLabel('⋮⋮  Hesap makinesi'); title.setStyleSheet('font-size:17px;font-weight:bold;color:#9fb3d1;'); bar.addWidget(title, 1)
        self.mode = QPushButton('DEG'); self.mode.setObjectName('mode'); self.mode.setFixedHeight(36); self.mode.setToolTip('Derece / Radyan')
        self.mode.clicked.connect(self.toggle_mode); bar.addWidget(self.mode)
        close = QPushButton('✕  Kapat'); close.setObjectName('close'); close.setFixedHeight(40); close.clicked.connect(self.hide); bar.addWidget(close)
        screen = QWidget(); screen.setStyleSheet('background:#060c18;border-radius:14px;'); sl = QVBoxLayout(screen); sl.setContentsMargins(16,10,16,10); sl.setSpacing(2)
        self.expr_label = QLabel(''); self.expr_label.setAlignment(Qt.AlignRight|Qt.AlignVCenter); self.expr_label.setStyleSheet('font-size:20px;color:#8aa0c2;'); self.expr_label.setMinimumHeight(30)
        self.main_label = QLabel('0'); self.main_label.setAlignment(Qt.AlignRight|Qt.AlignVCenter); self.main_label.setStyleSheet('font-size:46px;color:#f4f7ff;'); self.main_label.setMinimumHeight(64)
        sl.addWidget(self.expr_label); sl.addWidget(self.main_label); layout.addWidget(screen)
        grid = QGridLayout(); grid.setSpacing(8); layout.addLayout(grid)
        for r, row in enumerate(self.KEYS):
            for c, key in enumerate(row):
                b = QPushButton(key); b.setFixedSize(84, 62); b.setFocusPolicy(Qt.NoFocus)
                b.setObjectName('eq' if key == '=' else 'ac' if key in ('AC','⌫') else 'op' if key in ('÷','×','−','+') else 'fn' if r < 3 or key == 'Ans' else '')
                b.clicked.connect(lambda checked=False, k=key: self.press(k)); grid.addWidget(b, r, c)
        self.adjustSize()
    def toggle_mode(self):
        self.degrees = not self.degrees; self.mode.setText('DEG' if self.degrees else 'RAD'); self.preview()
    def press(self, k):
        if k == 'AC': self.expr = ''; self.result = ''; self.just_evaluated = False; self.refresh(); return
        if k == '⌫':
            for token in ('sin(','cos(','tan(','ln(','log(','√('):
                if self.expr.endswith(token): self.expr = self.expr[:-len(token)]; break
            else: self.expr = self.expr[:-1]
            self.just_evaluated = False; self.refresh(); return
        if k == '=':
            if not self.expr: return
            try:
                v = calc_evaluate(self.expr, self.degrees); self.ans = v
                self.result = self.expr; self.expr = calc_format(v).replace('.', '') if ' × 10^' not in calc_format(v) else repr(v).replace('.', ',')
                self.just_evaluated = True
            except ZeroDivisionError: self.result = self.expr; self.expr = ''; self.main_label.setText('Tanımsız'); self.expr_label.setText(self.result+' ='); return
            except Exception: self.result = self.expr; self.expr = ''; self.main_label.setText('Hata'); self.expr_label.setText(self.result+' ='); return
            self.expr_label.setText(self.result+' ='); self.main_label.setText(calc_format(self.ans)); return
        operator = k in ('÷','×','−','+','xʸ','x²','n!','%')
        if self.just_evaluated and not operator: self.expr = ''
        self.just_evaluated = False
        insert = {'sin':'sin(','cos':'cos(','tan':'tan(','ln':'ln(','log':'log(','√':'√(','x²':'²','xʸ':'^','n!':'!','Ans':'Ans'}.get(k, k)
        if k == 'Ans': insert = calc_format(self.ans).replace('.', '') if ' × 10^' not in calc_format(self.ans) else repr(self.ans).replace('.', ',')
        if k == '1/x': self.expr = '1÷(' + (self.expr or '0') + ')'; self.refresh(); return
        if k == '±': self.expr = '−(' + self.expr + ')' if self.expr else '−'; self.refresh(); return
        self.expr += insert; self.refresh()
    def preview(self):
        try: return calc_format(calc_evaluate(self.expr, self.degrees))
        except Exception: return ''
    def refresh(self):
        self.main_label.setText(self.expr or '0')
        p = self.preview() if self.expr else ''
        self.expr_label.setText(('= '+p) if p and p != self.expr else '')
        f = self.main_label.font(); f.setPixelSize(46 if len(self.expr) < 15 else max(22, int(46*15/len(self.expr)))); self.main_label.setFont(f)
    def mousePressEvent(self, e):
        if e.button() == Qt.LeftButton: self.drag_from = e.globalPos()-self.frameGeometry().topLeft()
    def mouseMoveEvent(self, e):
        if self.drag_from is not None: self.move(e.globalPos()-self.drag_from)
    def mouseReleaseEvent(self, e): self.drag_from = None
    def open_calc(self):
        screen = self.main.windowHandle().screen() if self.main.windowHandle() else QApplication.primaryScreen()
        g = screen.availableGeometry(); self.adjustSize()
        if not self.isVisible(): self.move(g.right()-self.width()-40, g.top()+120)
        self.show(); self.raise_(); self.activateWindow()
