class PageScroll(QScrollArea):
    """Sayfanın arkası: konu deseni, tema renginde yumuşak ışık ve sayfanın gölgesi.
    Yalnızca sayfanın çevresi açıldığında çizilir; kalem yazarken çalışmaz."""
    def __init__(self):
        super().__init__(); self.tile = None; self.view = QColor('#091423'); self.accent = QColor('#bb1826')
        for bar in (self.horizontalScrollBar(), self.verticalScrollBar()): bar.valueChanged.connect(lambda _v: self.viewport().update())
    def set_theme(self, view, accent, tile_path):
        self.view = QColor(view); self.accent = QColor(accent)
        self.tile = QPixmap(tile_path) if tile_path and os.path.isfile(tile_path) else None
        self.bg = None; self.viewport().update()
    def background(self, size):
        """Desen + ışık bir kez hazır görüntüye çizilir (kaydırırken yalnızca kopyalanır)."""
        if getattr(self, 'bg', None) is not None and self.bg.size() == size: return self.bg
        from PyQt5.QtGui import QRadialGradient
        bg = QPixmap(size); bg.fill(self.view); p = QPainter(bg); r = QRect(QPoint(0, 0), size)
        if self.tile is not None and not self.tile.isNull(): p.drawTiledPixmap(r, self.tile)
        glow = QRadialGradient(QPointF(r.center()), max(r.width(), r.height())*.62)
        a = QColor(self.accent); a.setAlpha(80); glow.setColorAt(0, a); a2 = QColor(self.accent); a2.setAlpha(26); glow.setColorAt(.5, a2); glow.setColorAt(1, QColor(0, 0, 0, 0))
        p.fillRect(r, glow); p.end(); self.bg = bg; return bg
    def shadow(self, w, h):
        """Sayfa gölgesi: köşe/kenar parçaları bir kez çizilir (dokuz parça), her boyuta uyar."""
        if getattr(self, 'sh', None) is None:
            S = 40; img = QPixmap(3*S, 3*S); img.fill(Qt.transparent); p = QPainter(img); p.setRenderHint(QPainter.Antialiasing); p.setPen(Qt.NoPen)
            g = QRectF(S, S, S, S)
            for k in range(16, 0, -1): p.setBrush(QColor(0, 0, 0, int(4 + (16-k)*1.5))); p.drawRoundedRect(g.adjusted(-k, -k*.5, k, k*1.4), k, k)
            p.end(); self.sh = img
        return self.sh
    def paintEvent(self, e):
        vp = self.viewport(); p = QPainter(vp); er = e.rect()
        bg = self.background(vp.size()); p.drawPixmap(er, bg, er)
        b = self.widget()
        if b is not None and b.isVisible():   # yumuşak gölge: sayfa zeminden yükselmiş gibi
            g = b.geometry(); S = 40; sh = self.shadow(g.width(), g.height())
            x0, y0, x1, y1 = g.left()-S, g.top()-S, g.right()+1, g.bottom()+1
            parts = [(QRect(x0, y0, S, S), QRect(0, 0, S, S)), (QRect(x1, y0, S, S), QRect(2*S, 0, S, S)), (QRect(x0, y1, S, S), QRect(0, 2*S, S, S)), (QRect(x1, y1, S, S), QRect(2*S, 2*S, S, S)),
                     (QRect(g.left(), y0, g.width(), S), QRect(S, 0, S, S)), (QRect(g.left(), y1, g.width(), S), QRect(S, 2*S, S, S)),
                     (QRect(x0, g.top(), S, g.height()), QRect(0, S, S, S)), (QRect(x1, g.top(), S, g.height()), QRect(2*S, S, S, S))]
            for dst, src in parts:
                if dst.intersects(er): p.drawPixmap(dst, sh, src)

def make_theme_tile(key, path):
    """Seamless 480×480 pattern of faint subject motifs (drawn, no image files)."""
    import random
    from PyQt5.QtGui import QFont, QPainterPath, QTransform
    t = THEMES[key]; size = 480
    img = QImage(size, size, QImage.Format_RGB32); img.fill(QColor(t['view']))
    p = QPainter(img); p.setRenderHint(QPainter.Antialiasing); rnd = random.Random(key)
    ink = QColor(t['ink'])
    soft = 1.8 if key == 'default' else 1.0   # konu desenleri soluk: sayfayla yarışmasın
    def col(a): c = QColor(ink); c.setAlpha(min(255, int(a*soft))); return c
    def pen(a, w=2): p.setPen(QPen(col(a), w, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)); p.setBrush(Qt.NoBrush)
    def text(s, x, y, px, a, serif=False, rot=0):
        f = QFont('DejaVu Serif' if serif else 'DejaVu Sans'); f.setPixelSize(px); f.setBold(not serif)
        p.save(); p.translate(x, y); p.rotate(rot); p.setFont(f); p.setPen(col(a)); p.drawText(QRectF(-200, -px, 400, px*2), Qt.AlignCenter, s); p.restore()
    def around(fn):   # draw at offsets so the tile repeats seamlessly
        for dx in (-size, 0, size):
            for dy in (-size, 0, size):
                p.save(); p.translate(dx, dy); fn(); p.restore()
    if key == 'default':
        def f():
            pen(22, 1)
            for i in range(0, size, 24): p.drawLine(i, 0, i, size); p.drawLine(0, i, size, i)
        around(f)
    elif key == 'turkiye':
        def crescent(cx, cy, r, a, rot):
            p.save(); p.translate(cx, cy); p.rotate(rot)
            outer = QPainterPath(); outer.addEllipse(QPointF(0, 0), r, r)
            inner = QPainterPath(); inner.addEllipse(QPointF(r*.25, 0), r*.8, r*.8)
            p.setPen(Qt.NoPen); p.setBrush(col(a)); p.drawPath(outer.subtracted(inner))
            star = QPolygonF([QPointF(r*.95+math.cos(math.radians(-90+i*36))*(r*.38 if i % 2 == 0 else r*.15),
                                      math.sin(math.radians(-90+i*36))*(r*.38 if i % 2 == 0 else r*.15)) for i in range(10)])
            p.drawPolygon(star); p.restore()
        def f():
            crescent(120, 120, 46, 70, -8); crescent(360, 330, 34, 52, 10); crescent(380, 90, 20, 40, 0); crescent(110, 380, 24, 44, -14)
            pen(30, 1.5)
            for k in range(3): p.drawArc(QRectF(-80+k*40, 200+k*14, 640, 240), 20*16, 140*16)
        around(f)
    elif key == 'matematik':
        def f():
            pen(26, 1)
            for i in range(0, size, 40): p.drawLine(i, 0, i, size); p.drawLine(0, i, size, i)
            pen(60, 2.5); path = QPainterPath(QPointF(40, 120))
            for x in range(40, 260, 4): path.lineTo(x, 120-((x-150)/40.0)**2*-6-60)
            p.drawPath(path)
            p.drawPolygon(QPolygonF([QPointF(300, 420), QPointF(440, 420), QPointF(300, 300)]))
            for s, x, y, px, a, r in [('π',380,90,64,70,-8),('∑',90,300,58,60,6),('√x',250,250,40,62,0),('∫',420,230,70,55,10),
                                       ('∞',170,430,44,55,0),('x²+y²=r²',230,40,22,60,0),('Δ',60,200,40,55,-6),('θ',340,190,36,55,4),('f(x)',140,190,26,55,0)]:
                text(s, x, y, px, a, True, r)
        around(f)
    elif key == 'kimya':
        def hexagon(cx, cy, r, a):
            pen(a, 2.5); p.drawPolygon(QPolygonF([QPointF(cx+r*math.cos(math.radians(30+60*i)), cy+r*math.sin(math.radians(30+60*i))) for i in range(6)]))
            p.drawEllipse(QPointF(cx, cy), r*.55, r*.55)
        def f():
            hexagon(110, 110, 52, 70); hexagon(110+90, 110+52, 52, 50); hexagon(380, 360, 40, 55)
            pen(60, 2.5); flask = QPainterPath(QPointF(330, 60)); flask.lineTo(330, 120); flask.lineTo(290, 200); flask.lineTo(410, 200); flask.lineTo(370, 120); flask.lineTo(370, 60)
            p.drawPath(flask); p.drawLine(QPointF(320, 60), QPointF(380, 60)); p.drawLine(QPointF(300, 180), QPointF(400, 180))
            for r in (0, 60, 120):
                p.save(); p.translate(120, 360); p.rotate(r); p.drawEllipse(QPointF(0, 0), 58, 20); p.restore()
            p.setBrush(col(70)); p.drawEllipse(QPointF(120, 360), 7, 7)
            for s, x, y, px, a in [('H₂O',260,300,30,65),('CO₂',420,250,26,55),('NaCl',250,440,26,55),('pH',40,260,30,60)]:
                text(s, x, y, px, a)
        around(f)
    elif key == 'cografya':
        def f():
            pen(40, 1.6)
            for k in range(6): p.drawEllipse(QPointF(130, 330), 30+k*22, 18+k*15)
            for k in range(4): p.drawEllipse(QPointF(380, 120), 20+k*20, 14+k*13)
            pen(28, 1)
            for y in range(40, size, 80):
                path = QPainterPath(QPointF(0, y))
                for x in range(0, size+1, 10): path.lineTo(x, y+math.sin(x/76.4)*8)
                p.drawPath(path)
            cx, cy = 360, 360; p.setPen(Qt.NoPen); p.setBrush(col(60))
            p.drawPolygon(QPolygonF([QPointF(cx+math.cos(math.radians(-90+i*45))*(52 if i % 2 == 0 else 14), cy+math.sin(math.radians(-90+i*45))*(52 if i % 2 == 0 else 14)) for i in range(8)]))
            text('K', cx, cy-72, 24, 80)
            p.setBrush(col(45)); p.drawPolygon(QPolygonF([QPointF(30, 170), QPointF(80, 90), QPointF(130, 170)])); p.drawPolygon(QPolygonF([QPointF(95, 170), QPointF(135, 110), QPointF(180, 170)]))
        around(f)
    elif key == 'fizik':
        def f():
            for r in (0, 60, 120):
                pen(55, 2); p.save(); p.translate(120, 130); p.rotate(r); p.drawEllipse(QPointF(0, 0), 70, 24); p.restore()
            p.setPen(Qt.NoPen); p.setBrush(col(80)); p.drawEllipse(QPointF(120, 130), 9, 9)
            pen(55, 2.5); path = QPainterPath(QPointF(220, 320))
            for x in range(220, 470, 3): path.lineTo(x, 320+math.sin((x-220)/20.0)*26)
            p.drawPath(path)
            pen(45, 2); p.drawEllipse(QPointF(70, 380), 14, 60); p.drawLine(QPointF(0, 380), QPointF(160, 380))
            for s, x, y, px, a, r in [('E = mc²',350,90,34,70,0),('F = m·a',300,200,28,60,-4),('λ',420,420,50,60,0),('Ω',240,430,40,50,0),('ħ',30,250,40,55,0),('v = λ·f',170,270,22,55,0)]:
                text(s, x, y, px, a, True, r)
        around(f)
    elif key == 'biyoloji':
        def f():
            for phase in (0, math.pi):
                pen(70, 3); path = QPainterPath()
                for i, y in enumerate(range(0, size+1, 4)):
                    x = 90+math.sin(y/30.0+phase)*36
                    path.moveTo(x, y) if i == 0 else path.lineTo(x, y)
                p.drawPath(path)
            pen(40, 2)
            for y in range(0, size, 16):
                p.drawLine(QPointF(90+math.sin(y/30.0)*36, y), QPointF(90+math.sin(y/30.0+math.pi)*36, y))
            pen(60, 2.5); leaf = QPainterPath(QPointF(300, 160)); leaf.cubicTo(330, 60, 430, 60, 440, 40); leaf.cubicTo(430, 140, 360, 190, 300, 160)
            p.drawPath(leaf); p.drawLine(QPointF(300, 160), QPointF(420, 60))
            p.drawEllipse(QPointF(330, 350), 80, 60); p.setBrush(col(45)); p.drawEllipse(QPointF(350, 340), 24, 20)
            p.setBrush(Qt.NoBrush); p.drawEllipse(QPointF(290, 370), 16, 8)
            for s, x, y, px, a in [('DNA',200,250,28,60),('ATP',220,440,24,50),('H₂O + CO₂',420,250,18,45)]:
                text(s, x, y, px, a)
        around(f)
    elif key == 'resim':
        paints = ('#e04f3a', '#f2b33d', '#3f7fd9', '#3fae6a', '#b05cc9', '#f2f2f2')
        def blob(cx, cy, r, c, a):
            q = QColor(c); q.setAlpha(a); p.setPen(Qt.NoPen); p.setBrush(q); p.drawEllipse(QPointF(cx, cy), r, r*.86)
        def f():
            # Palet: thumb hole and notch, with paint blobs
            pal = QPainterPath(); pal.addEllipse(QPointF(130, 130), 92, 66)
            hole = QPainterPath(); hole.addEllipse(QPointF(92, 158), 13, 11); notch = QPainterPath(); notch.addEllipse(QPointF(46, 168), 24, 18)
            pen(70, 2.6); p.drawPath(pal.subtracted(hole).subtracted(notch))
            for (x, y), c in zip([(110, 95), (150, 88), (188, 108), (196, 148), (160, 176), (128, 128)], paints): blob(x, y, 12, c, 95)
            # Fırça and its stroke
            p.save(); p.translate(380, 120); p.rotate(-38)
            pen(70, 7); p.drawLine(QPointF(0, -95), QPointF(0, 10))
            pen(70, 2.4); p.drawRect(QRectF(-6, 10, 12, 22))
            tip = QPainterPath(QPointF(-6, 32)); tip.cubicTo(-10, 54, -2, 70, 0, 78); tip.cubicTo(2, 70, 10, 54, 6, 32)
            q = QColor(paints[0]); q.setAlpha(120); p.setBrush(q); p.drawPath(tip); p.restore()
            stroke = QPainterPath(QPointF(250, 250)); stroke.cubicTo(300, 205, 360, 290, 420, 235); stroke.cubicTo(445, 215, 465, 230, 470, 250)
            q = QColor(paints[0]); q.setAlpha(70); p.setPen(QPen(q, 12, Qt.SolidLine, Qt.RoundCap)); p.setBrush(Qt.NoBrush); p.drawPath(stroke)
            # Renk çemberi
            for i, c in enumerate(paints[:5] + ('#f27b3a',)):
                q = QColor(c); q.setAlpha(85); p.setPen(Qt.NoPen); p.setBrush(q)
                p.drawPie(QRectF(320, 315, 110, 110), (90+i*60)*16, 60*16)
            p.setBrush(QColor(t['view'])); p.drawEllipse(QPointF(375, 370), 20, 20)
            # Kurşun kalem
            p.save(); p.translate(70, 400); p.rotate(-30); pen(60, 2.4)
            p.drawPolygon(QPolygonF([QPointF(0, -8), QPointF(120, -8), QPointF(120, 8), QPointF(0, 8)]))
            p.drawPolygon(QPolygonF([QPointF(120, -8), QPointF(146, 0), QPointF(120, 8)])); p.drawLine(QPointF(20, -8), QPointF(20, 8)); p.restore()
            # Çerçeve içinde küçük manzara
            pen(55, 2.4); p.drawRect(QRectF(200, 330, 104, 78)); pen(40, 1.6); p.drawRect(QRectF(208, 338, 88, 62))
            pen(55, 2); p.drawPolyline(QPolygonF([QPointF(210, 396), QPointF(236, 362), QPointF(254, 380), QPointF(272, 354), QPointF(294, 396)]))
            blob(282, 352, 7, paints[1], 110)
            # Boya damlaları
            for (x, y, r), c in zip([(250, 60, 6), (300, 150, 4), (40, 260, 7), (460, 420, 5), (180, 280, 4), (440, 40, 3)], paints*2): blob(x, y, r, c, 80)
        around(f)
    p.end(); img.save(path); return path

# --- Ders zaman çizelgesi (Ümraniye Merkez Anadolu Lisesi, 2026-2027) ---
_LESSONS = [('1. Ders','08:00','08:40'),('2. Ders','08:50','09:30'),('3. Ders','09:40','10:20'),
            ('4. Ders','10:30','11:10'),('5. Ders','11:20','12:00')]
BELL_DAYS = {   # weekday() -> periods; gaps between them are teneffüs
    'normal': [('Derse hazırlık','07:30','08:00')]+_LESSONS+[('Öğle arası','12:00','12:30'),('6. Ders','12:30','13:10'),
               ('7. Ders','13:20','14:00'),('8. Ders','14:10','14:50'),('DYK 1. Ders','15:00','15:40'),('DYK 2. Ders','15:50','16:30')],
    # Cuma (okulun ders zaman çizelgesi): öğle arası 6. dersten sonra 12.50–13.30 (40 dk); 7. ders 13.30–14.10, 8. ders 14.20–15.00; okul 15.00'te biter
    'cuma':   [('Derse hazırlık','07:30','08:00')]+_LESSONS+[('6. Ders','12:10','12:50'),('Öğle arası','12:50','13:30'),
               ('7. Ders','13:30','14:10'),('8. Ders','14:20','15:00'),('DYK 1. Ders','15:00','15:40'),('DYK 2. Ders','15:50','16:30')]}
TR_DAYS = ['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar']
TR_MONTHS = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']

SINAV_SAAT = {}   # zil çizelgesinden farklı saatte yapılan sınavlar (tarih, ders) → (başlangıç, bitiş)
DENEME_DERS = 'Deneme'
_DENEME = {}   # etkin deneme sınavı: {'id', 'tarih', 'a', 'b', 'hedef': [salonlar]} (Öğretmenler odasındaki "Sınav anı" düğmesi)
def exam_span(weekday, name, day=None):
    """Bir dersin (sınavın) başlangıç–bitiş saniyesi; deneme sınavı saat çizelgesinde olmadığı için ayrıca.
    day verilirse o günün özel sınav saati (SINAV_SAAT) önce gelir."""
    if day is not None:
        ov = SINAV_SAAT.get((str(day)[:10], name))
        if ov: return (int(ov[0][:2])*3600 + int(ov[0][3:])*60, int(ov[1][:2])*3600 + int(ov[1][3:])*60)
    if name == DENEME_DERS:
        try:
            import datetime
            if _DENEME and datetime.date.fromisoformat(_DENEME['tarih']).weekday() == weekday: return (int(_DENEME['a']), int(_DENEME['b']))
        except (KeyError, ValueError, TypeError): pass
        return None
    return next(((a, b) for name_, a, b, kind in bell_periods(weekday) if name_ == name), None)
def bell_periods(weekday):
    """[(name, start_s, end_s, kind)] with teneffüs filling the gaps; seconds of day."""
    if weekday >= 5: return []
    sec = lambda t: int(t[:2])*3600+int(t[3:])*60
    out = []
    for name, a, b in BELL_DAYS['cuma' if weekday == 4 else 'normal']:
        a, b = sec(a), sec(b)
        if out and a > out[-1][2]: out.append(('Teneffüs', out[-1][2], a, 'break'))
        kind = 'break' if name == 'Öğle arası' else ('prep' if name == 'Derse hazırlık' else 'lesson')
        out.append((name, a, b, kind))
    return out

def bell_state(now):
    """What the corner clock shows at datetime `now`."""
    t = now.hour*3600+now.minute*60+now.second
    periods = bell_periods(now.weekday())
    st = dict(kind='off', tag='', span='', left=None, frac=0, next='')
    hm = lambda x: '%02d.%02d' % (x//3600, x%3600//60)
    if not periods:
        st.update(tag='HAFTA SONU'); return st
    if t < periods[0][1]:
        st.update(kind='before', tag='GÜNAYDIN', left=periods[0][1]-t, next='Derse hazırlık %s' % hm(periods[0][1])); return st
    if t >= periods[-1][2]:
        st.update(tag='OKUL BİTTİ'); return st
    for i, (name, a, b, kind) in enumerate(periods):
        if a <= t < b:
            nxt = periods[i+1] if i+1 < len(periods) else None
            st.update(kind=kind, tag=name.replace('i','İ').upper(), span='%s – %s' % (hm(a), hm(b)), left=b-t, frac=(t-a)/(b-a),
                      next=('Sonra: %s %s – %s' % (nxt[0], hm(nxt[1]), hm(nxt[2]))) if nxt else 'Sonra: okul bitiyor')
            return st
    return st

