def student_photo(no):
    """Öğrenci fotoğrafı (okul numarasıyla); yoksa None. Kelebek sınav listelerinde kimlik denetimi için."""
    d = _PHOTOS['data']
    if not d or not no or str(no) in FOTO_GIZLI or str(no) in AYRILAN: return None
    pm = _PHOTOS['pix'].get(no)
    if pm is None and no in d:
        import base64
        pm = QPixmap(); pm.loadFromData(base64.b64decode(d[no]), 'JPG'); _PHOTOS['pix'][no] = pm
    return pm
BOARD_PHOTOS = True   # tahtalarda öğrenci fotoğrafları
FOTO_GIZLI = {'101'}   # fotoğrafı hiçbir yerde gösterilmeyecek öğrenciler (okul no); yerine baş harfler
YOKLAMA_BASLA = 5*60   # sn: yoklama sınav başladıktan bu kadar sonra açılır, sınav bitene kadar
YOKLAMA_SURE = 15*60   # sn: sınav başladıktan sonra yoklama bu kadar açık
LOGO_RESMI = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'okul-logo-resmi.png')
