_SUBELER = {}
def exam_course(tarih, ders, sinif, fallback=''):
    """Kelebek sınavında bir şubenin girdiği ders (takvimdeki 'subeler'), yoksa sınıf düzeyinin dersi."""
    if not _SUBELER:
        try:
            with open(EXAM_FILE, encoding='utf-8') as f: d = json.load(f)
            for x in d.get('subeler', []): _SUBELER[(x['tarih'], x['ders'])] = x.get('subeler', {})
            for x in d.get('sinavlar', []): _SUBELER.setdefault(('*', x['tarih'], x['ders']), x.get('siniflar', {}))
        except (OSError, ValueError, KeyError, TypeError, AttributeError): pass
        _SUBELER.setdefault('_', 1)
    c = _SUBELER.get((tarih, ders), {}).get(str(sinif or ''))
    if c: return c
    return _SUBELER.get(('*', tarih, ders), {}).get(class_grade(sinif) or '') or fallback
def tr_title(s_):
    """Kelebekteki BÜYÜK HARFLİ ders adı → 'Din Kültürü ve Ahlak Bilgisi' (Türkçe i/ı ile)."""
    s_ = str(s_ or '').strip()
    if not s_ or any(w != w.upper() for w in s_.split() if w.lower() not in ('ve', 'ile')): return s_
    low = lambda w: w.replace('I', 'ı').replace('İ', 'i').lower()
    out = []
    for j, w in enumerate(s_.split()):
        lw = low(w)
        if j and lw in ('ve', 'ile'): out.append(lw)
        elif len(w) <= 2 and w.endswith('.'): out.append(w)
        else: out.append(w[0] + low(w[1:]))
    return ' '.join(out)
def tr_date(day):
    return '%d %s %d' % (day.day, TR_MONTHS[day.month-1], day.year)
def _salon_key(s_):
    a = str(s_).split('-')[0]
    return (int(a) if a.isdigit() else 99, str(s_))

def draw_photo(p, r, no, name, k):
    pm = student_photo(no)
    p.save(); path = QPainterPath(); path.addRoundedRect(r, 6*k, 6*k); p.setClipPath(path)
    if pm is not None and not pm.isNull():
        sc = max(r.width()/pm.width(), r.height()/pm.height()); w_, h_ = pm.width()*sc, pm.height()*sc
        p.drawPixmap(QRectF(r.center().x() - w_/2, r.center().y() - h_/2, w_, h_), pm, QRectF(pm.rect()))
    else:   # fotoğraf yok: baş harfler
        p.fillRect(r, QColor('#2a3a52')); p.setPen(QColor('#9fb3cc')); f = p.font(); f.setPixelSize(max(9, int(r.height()*.34))); p.setFont(f)
        p.drawText(r, Qt.AlignCenter, ''.join(w[0] for w in name.split()[:2]))
    p.restore()
def kelebek_open(blob):
    """Kelebek oturma planı (şifreli, imzalı): SHA-256 sayaç kipi + HMAC; yalnız standart kitaplık."""
    import hashlib, hmac
    if blob[:3] != b'UK1': raise ValueError('biçim')
    nonce, tag, ct = blob[3:19], blob[19:51], blob[51:]
    if not hmac.compare_digest(tag, hmac.new(KELEBEK_KEY, nonce + ct, hashlib.sha256).digest()): raise ValueError('imza')
    n = len(ct); h0 = hashlib.sha256(KELEBEK_KEY + nonce); ks = bytearray()
    for i in range((n + 31)//32):
        h = h0.copy(); h.update(i.to_bytes(8, 'big')); ks += h.digest()
    ks = bytes(ks[:n])
    return json.loads((int.from_bytes(ct, 'big') ^ int.from_bytes(ks, 'big')).to_bytes(n, 'big').decode('utf-8'))   # K-418: büyük foto dosyasında bayt bayt XOR ekranı donduruyordu
LESSON_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'ders-programi.json')
_LESSON_TABLE = {}
def lesson_now(sinif, now):
    """Panel için: bu sınıfta şu an hangi ders, hangi öğretmen (okulun haftalık ders programından)."""
    if not _LESSON_TABLE:
        try:
            with open(LESSON_FILE, encoding='utf-8') as f: _LESSON_TABLE.update(json.load(f).get('siniflar', {}))
        except (OSError, ValueError, AttributeError): _LESSON_TABLE['_'] = {}
    t = now.hour*3600 + now.minute*60 + now.second; hm = lambda x: '%02d.%02d' % (x//3600, x%3600//60)
    for name, a, b, kind in bell_periods(now.weekday()):
        if a <= t < b:
            if kind != 'lesson': return dict(durum='teneffus' if kind == 'break' else 'ders_disi', saat=name)
            try: n = int(name.split('.')[0])
            except ValueError: return dict(durum='ders_disi', saat=name)   # DYK
            cell = _LESSON_TABLE.get(str(sinif or ''), {}).get('%d-%d' % (now.weekday(), n))
            if not cell: return dict(durum='bos', saat=name, bas=hm(a), bit=hm(b))
            return dict(durum='ders', saat=name, bas=hm(a), bit=hm(b), ders=cell.get('ders', ''), ogretmen=cell.get('ogretmen', []))
    nxt = [p_ for p_ in bell_periods(now.weekday()) if p_[1] > t]
    return dict(durum='teneffus' if nxt and any(p_[2] <= t for p_ in bell_periods(now.weekday())) else 'okul_disi')

def lesson_cell(sinif, weekday, n):
    """Ders programında bir sınıfın o gün o dersteki kaydı: {'ders', 'ogretmen'} ya da None."""
    if not _LESSON_TABLE:
        try:
            with open(LESSON_FILE, encoding='utf-8') as f: _LESSON_TABLE.update(json.load(f).get('siniflar', {}))
        except (OSError, ValueError, AttributeError): _LESSON_TABLE['_'] = {}
    return _LESSON_TABLE.get(str(sinif or ''), {}).get('%d-%d' % (weekday, n))

def class_grade(sinif):
    s = str(sinif or '').strip()
    g = s.split('-')[0].strip()
    return g if g in ('9', '10', '11', '12') else None
GRADE_COLORS = {'9': '#22e8ff', '10': '#3ef08a', '11': '#b06bff', '12': '#ff9a3a'}   # sınıf seviyesi renkleri (sıra kartı şeridi, numara, sınıf)
def grade_color(sinif, fallback='#5cc8ff'):
    return GRADE_COLORS.get(class_grade(sinif) or '', fallback)
TENEFFUS_AHEAD = 7   # gün: bu sınıf düzeyinin bu kadar gün içinde sınavı varsa teneffüste teneffüs modu açılır
def teneffus_info(now, exams, grade, sinif=''):
    """Teneffüs modu verisi: sıradaki ders, bu sınıfın sıradaki sınavı (geri sayım), 5 iş günlük sınav takvimi.
    Sınav yoksa (TENEFFUS_AHEAD gün içinde) None."""
    import datetime
    if not grade: return None
    t = now.hour*3600 + now.minute*60 + now.second; today = now.date(); lst = []
    for d_, l_, g_ in (exams or []):
        if l_ == DENEME_DERS or grade not in g_: continue
        try: day = datetime.date.fromisoformat(d_)
        except (TypeError, ValueError): continue
        if not (0 <= (day - today).days <= 31): continue
        span = exam_span(day.weekday(), l_, day)
        if not span: continue
        crs = tr_title(exam_course(d_, l_, sinif, g_.get(grade, ''))) or g_.get(grade, '')
        lst.append((day, span[0], span[1], l_, crs))
    lst.sort()
    nxt = next((e for e in lst if (e[0], e[1]) > (today, t)), None)
    sinavsiz = nxt is None or (nxt[0] - today).days > TENEFFUS_AHEAD   # K-377: sınav yoksa da teneffüs modu (saat, sıradaki ders)
    per = bell_periods(now.weekday()); cur = next((x for x in per if x[1] <= t < x[2]), None)
    after = next((x for x in per if x[1] >= t and x[3] == 'lesson'), None)
    nowtxt = (cur[0] if cur and cur[0] != 'Teneffüs' else 'Teneffüs') if cur else ''
    if after: nowtxt = (nowtxt + '  ·  ' if nowtxt else '') + 'Sıradaki: %s  %02d.%02d' % (after[0], after[1]//3600, after[1]%3600//60)
    if sinavsiz:
        return dict(saat='%02d.%02d' % (now.hour, now.minute), tarih='%s · %d %s' % (TR_DAYS[now.weekday()], now.day, TR_MONTHS[now.month-1]),
                    simdi=nowtxt, sonraki=None, kalan=None, gunler=[])
    start = datetime.datetime.combine(nxt[0], datetime.time()) + datetime.timedelta(seconds=nxt[1]); left = max(0, int((start - now).total_seconds()))
    days, d = [], today
    while len(days) < 5:
        if d.weekday() < 5:
            label = 'Bugün' if d == today else ('Yarın' if (d - today).days == 1 else TR_DAYS[d.weekday()])
            sub = ('%s %d %s' % (TR_DAYS[d.weekday()], d.day, TR_MONTHS[d.month-1])) if (d - today).days <= 1 else '%d %s' % (d.day, TR_MONTHS[d.month-1])
            items = [(e[4], e[3], '%02d.%02d' % (e[1]//3600, e[1]%3600//60), (e[0], e[2]) <= (today, t)) for e in lst if e[0] == d]
            days.append((label, sub, items))
        d += datetime.timedelta(days=1)
    when = 'Bugün' if nxt[0] == today else ('Yarın' if (nxt[0] - today).days == 1 else '%d %s' % (nxt[0].day, TR_MONTHS[nxt[0].month-1]))
    return dict(saat='%02d.%02d' % (now.hour, now.minute), tarih='%s · %d %s' % (TR_DAYS[now.weekday()], now.day, TR_MONTHS[now.month-1]),
                simdi=nowtxt, sonraki='%s · %s · %s' % (when, nxt[3], nxt[4]), kalan=(left//86400, left%86400//3600, left%3600//60), gunler=days)

