class YerimDialog(QDialog):
    """K-383: 'Yerimi göster' — salonun gerçek oturma düzeni; öğrencinin sırası neon çerçeveyle yanıp söner (web paneldeki 'Planda gör' gibi).
    Dokununca ya da 30 sn sonra kapanır."""
    def __init__(self, main, plan, ders, day, sira):
        super().__init__(main); self.plan = plan; self.ders = ders; self.day = day; self.sira = sira; self.seat_rects = {}; self.absent = set()
        self.setWindowFlags(Qt.Dialog | Qt.FramelessWindowHint); self.setAttribute(Qt.WA_OpaquePaintEvent)
        g = main.geometry(); self.setGeometry(g)
        self.nabiz = None; self.t = QTimer(self); self.t.setInterval(50); self.t.timeout.connect(lambda: self.update(self.nabiz) if self.nabiz is not None else self.update()); self.t.start()
        QTimer.singleShot(30000, self.accept)
    def paintEvent(self, e):
        from PyQt5.QtGui import QPainter, QFont, QPen
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        W, H = self.width(), self.height(); k = min(W/1600, H/900)
        fams = ui_fonts(); fam = fams.get('Poppins-Medium') or 'Sans'; famb = fams.get('Poppins-Bold') or fam
        def font(px, b=False): f = QFont(famb if b else fam); f.setPixelSize(max(10, int(px*k))); f.setWeight(QFont.Bold if b else QFont.Medium); return f
        # K-449: salon (fotoğraflar, yazılar) bir kez çizilip saklanır; saniyede 20 kez baştan çizmek yavaş tahtada ekranı donduruyordu.
        on = getattr(self, '_on', None)
        if on is None or on[0] != (W, H):
            pm = QPixmap(W, H); pm.fill(QColor('#0d1726')); q = QPainter(pm); q.setRenderHint(QPainter.Antialiasing); q.setRenderHint(QPainter.SmoothPixmapTransform)
            try: _draw_seatmap(self, q, W, H - 60*k, k, font, self.plan, '#5cc8ff', '#5cc8ff', '%s  ·  %d %s' % (self.ders, self.day.day, TR_MONTHS[self.day.month-1]))
            except Exception as ex: print('yerim:', ex)
            q.setPen(Qt.NoPen); q.setBrush(QColor(10, 18, 30, 235)); bar_ = QRectF(0, H - 60*k, W, 60*k); q.drawRect(bar_)
            q.setFont(font(26, True)); q.setPen(QColor('#7ff6ff'))
            q.drawText(bar_, Qt.AlignCenter, 'Senin yerin: Salon %s  ·  Sıra %s      (kapatmak için dokun)' % (self.plan['sinif'], self.sira))
            q.end(); on = self._on = ((W, H), pm, dict(self.seat_rects))
            c0 = on[2].get(self.sira)
            if c0 is not None: self.nabiz = c0.adjusted(-48*k, -48*k, 48*k, 48*k).toAlignedRect()   # sonraki çizimler yalnız bu bölge
        p.drawPixmap(e.rect(), on[1], e.rect()); self.seat_rects = on[2]
        c = self.seat_rects.get(self.sira)
        if c is not None:   # neon nabız: parlayan çerçeve büyüyüp küçülür
            a = .5 + .5*math.sin(time.time()*6.0); gl = QColor('#22e8ff')
            p.setPen(Qt.NoPen); p.setBrush(QColor(34, 232, 255, int(40 + 70*a))); p.drawRoundedRect(c, 10*k, 10*k)   # içi de parlar
            for w_, al in ((26, 45), (16, 90), (8, 200)):
                gl.setAlpha(int(al*(.45 + .55*a))); p.setPen(QPen(gl, w_*k)); p.setBrush(Qt.NoBrush)
                p.drawRoundedRect(c.adjusted(-(3 + 4*a)*k, -(3 + 4*a)*k, (3 + 4*a)*k, (3 + 4*a)*k), 12*k, 12*k)
            p.setPen(QPen(QColor('#e9fdff'), 3*k)); p.drawRoundedRect(c.adjusted(-2*k, -2*k, 2*k, 2*k), 11*k, 11*k)
        p.end()
    def mousePressEvent(self, e): self.accept()

class DenemeDialog(QDialog):
    """Öğretmenler odası: seçilen salon tahtaları birkaç dakikalığına sınav anındaki gibi sınav moduna geçer (tanıtım/deneme).
    Öğrenci listeleri en son kelebek planından; yoklama ve mesajlar 'Deneme' adıyla gider, gelmeyenler raporuna/mazerete girmez."""
    def __init__(self, main):
        super().__init__(main); self.main = main; self.setWindowTitle('Sınav anı (deneme)'); self.setMinimumWidth(fit_w(1000))
        self.setStyleSheet('QDialog{background:#0f1c2e;} QLabel{color:white;font-size:20px;background:transparent;}'
                           'QPushButton{background:#1d3150;color:white;border:1px solid #2a4468;border-radius:10px;padding:10px 14px;font-size:19px;font-weight:600;}'
                           'QPushButton:checked{background:#f06d0c;border-color:#ff9a3a;}')
        v = QVBoxLayout(self); v.setSpacing(12); v.setContentsMargins(26, 22, 26, 22)
        main.take_kelebek(); salons = set()
        for pl in (main.kelebek or {}).get('planlar', []):
            if pl.get('ders') != DENEME_DERS: salons |= set(pl.get('salonlar', {}))
        salons = sorted(salons, key=_salon_key)
        if _DENEME:
            now = main.exam_clock(); t = now.hour*3600 + now.minute*60 + now.second; b_ = int(_DENEME.get('b', 0))
            h_ = QLabel('Deneme sınavı sürüyor  ·  %s  ·  %s' % (', '.join(_DENEME.get('hedef', [])), ('%d dk kaldı' % max(0, (b_ - t)//60 + 1)) if t < b_ else 'bitti'))
            h_.setStyleSheet('QLabel{font-size:24px;font-weight:700;color:#ffd9b8;}'); v.addWidget(h_)
            r = QHBoxLayout(); c_ = QPushButton('Kapat'); c_.clicked.connect(self.reject); r.addWidget(c_)
            s_ = QPushButton('Denemeyi bitir'); s_.setStyleSheet('QPushButton{background:#e3343c;color:white;border:none;}'); s_.clicked.connect(self.stop); r.addWidget(s_, 1); v.addLayout(r); return
        t_ = QLabel('Sınav anı (deneme)'); t_.setStyleSheet('QLabel{font-size:27px;font-weight:700;}'); v.addWidget(t_)
        i_ = QLabel('Seçtiğiniz salon tahtaları 1 dakika sonra sınav moduna geçer: oturma planı, yoklama, Kâğıt eksik ve Öğretmenler odası ekranı gerçek sınavdaki gibi çalışır. '
                    'Öğrenci listeleri son kelebek planından gelir. Deneme yoklamaları raporlara ve mazeret listesine girmez. Seçilmeyen sınıflar etkilenmez.')
        i_.setWordWrap(True); i_.setStyleSheet('QLabel{color:#9fb3cc;font-size:17px;}'); v.addWidget(i_)
        if not salons:
            v.addWidget(QLabel('Kelebek planı yok; deneme için en az bir sınav planı gerekir.')); c_ = QPushButton('Kapat'); c_.clicked.connect(self.reject); v.addWidget(c_); return
        g = QGridLayout(); g.setSpacing(8); self.sel = {}
        for i, s_ in enumerate(salons):
            b_ = QPushButton(s_); b_.setCheckable(True); b_.setFocusPolicy(Qt.NoFocus); b_.setMinimumHeight(52); b_.toggled.connect(self.upd); g.addWidget(b_, i // 8, i % 8); self.sel[s_] = b_
        v.addLayout(g)
        r = QHBoxLayout(); r.addWidget(QLabel('Süre')); self.dk = 15; self.dk_btns = {}
        for m in (10, 15, 20, 40):
            b_ = QPushButton('%d dk' % m); b_.setCheckable(True); b_.setFocusPolicy(Qt.NoFocus); b_.setChecked(m == 15); b_.clicked.connect(lambda _=False, x=m: self.pick(x)); r.addWidget(b_); self.dk_btns[m] = b_
        r.addStretch(1); v.addLayout(r)
        self.msg = QLabel(''); self.msg.setStyleSheet('QLabel{color:#ff8a8a;font-size:17px;}'); v.addWidget(self.msg)
        r = QHBoxLayout(); c_ = QPushButton('Vazgeç'); c_.setMinimumHeight(60); c_.clicked.connect(self.reject); r.addWidget(c_)
        self.go = QPushButton('Başlat'); self.go.setMinimumHeight(60); self.go.setEnabled(False); self.go.clicked.connect(self.start); r.addWidget(self.go, 1); v.addLayout(r); self.upd()
    def pick(self, m):
        self.dk = m
        for k_, b_ in self.dk_btns.items(): b_.setChecked(k_ == m)
    def upd(self, *a):
        n = [s_ for s_, b_ in self.sel.items() if b_.isChecked()]
        self.go.setEnabled(bool(n)); self.go.setText(('Başlat  ·  %d salon' % len(n)) if n else 'Salon seçin')
        self.go.setStyleSheet('QPushButton{background:%s;color:white;border:none;border-radius:12px;font-size:21px;font-weight:700;}' % ('#f06d0c' if n else '#2a3040'))
    def start(self):
        n = [s_ for s_, b_ in self.sel.items() if b_.isChecked()]
        if not n: return
        if self.main.deneme_start(n, self.dk): self.accept()
        else: self.msg.setText('Deneme kaydı yazılamadı.')
    def stop(self): self.main.deneme_stop(); self.accept()

class SalonMesajDialog(QDialog):
    """Salon tahtasından Öğretmenler odasına mesaj. Önce 'Kâğıt eksik': salondaki her ders için kaç kâğıt eksik (− / +);
    altta hazır mesajlar (soruda hata, zümre öğretmeni, öğrenci rahatsızlandı) ve serbest yazı."""
    def __init__(self, main, st, plan):
        super().__init__(main); self.main = main; self.st = st; self.plan = plan
        self.setWindowTitle('Öğretmenler odasına mesaj'); self.setMinimumWidth(fit_w(900))
        self.setStyleSheet('QDialog{background:#0f1c2e;} QLabel{color:white;font-size:20px;} QLineEdit{font-size:22px;padding:10px;border-radius:10px;}'
                           'QPushButton{background:#1d3150;color:white;border:1px solid #2a4468;border-radius:10px;padding:12px 16px;font-size:19px;}'
                           'QPushButton:checked{background:#2f6fd6;border-color:#2f6fd6;}')
        v = QVBoxLayout(self); v.setSpacing(10)
        t_ = QLabel('Salon %s  ·  %s' % (plan['sinif'], st['lesson'])); t_.setStyleSheet('QLabel{font-size:24px;font-weight:700;}'); v.addWidget(t_)
        day = st['date'].isoformat(); courses = []
        for r in plan['liste']:   # K-427: ders sınıf seviyesiyle (10. sınıf Coğrafya, 11. sınıf Coğrafya ayrı kâğıt)
            c = tr_title(r.get('ders')) or exam_course(day, st['lesson'], r.get('sinif'), '')
            g_ = class_grade(r.get('sinif'))
            if c: c = ('%s. sınıf %s' % (g_, c)) if g_ else c
            if c and c not in courses: courses.append(c)
        courses.sort(key=lambda c: (int(c.split('.')[0]) if c.split('.')[0].isdigit() else 99, c.split(' ', 2)[-1].startswith('S. '), c))
        h_ = QLabel('Kâğıt eksik  (hangi sınıfın hangi dersinden kaç tane)'); h_.setStyleSheet('QLabel{color:#ffd78a;font-size:21px;font-weight:700;}'); v.addWidget(h_)
        self.counts = {}; grid = QGridLayout(); grid.setHorizontalSpacing(12); grid.setVerticalSpacing(8)
        for i, c in enumerate(courses):
            lab = QLabel(c); mn = QPushButton('−'); pl_ = QPushButton('+'); n_ = QLabel('0')
            n_.setStyleSheet('QLabel{font-size:28px;font-weight:700;min-width:56px;qproperty-alignment:AlignCenter;}')
            for b_ in (mn, pl_): b_.setFocusPolicy(Qt.NoFocus); b_.setFixedWidth(70)
            mn.clicked.connect(lambda c_=False, x=c: self.step(x, -1)); pl_.clicked.connect(lambda c_=False, x=c: self.step(x, 1))
            grid.addWidget(lab, i, 0); grid.addWidget(mn, i, 1); grid.addWidget(n_, i, 2); grid.addWidget(pl_, i, 3); self.counts[c] = [0, n_]
        grid.setColumnStretch(0, 1); v.addLayout(grid)
        h2 = QLabel('Başka bir durum'); h2.setStyleSheet('QLabel{color:#9fb3cc;font-size:19px;font-weight:700;}'); v.addWidget(h2)
        self.q = 1; row = QHBoxLayout()
        self.qb = QPushButton('Soruda hata var:  1. soru'); self.qb.setFocusPolicy(Qt.NoFocus); self.qb.clicked.connect(lambda: self.edit.setText('%d. soruda hata olabilir, zümre öğretmeni gelsin.' % self.q))
        qm = QPushButton('−'); qp = QPushButton('+')
        for b_ in (qm, qp): b_.setFocusPolicy(Qt.NoFocus); b_.setFixedWidth(70)
        qm.clicked.connect(lambda: self.qstep(-1)); qp.clicked.connect(lambda: self.qstep(1))
        row.addWidget(self.qb, 1); row.addWidget(qm); row.addWidget(qp); v.addLayout(row)
        g2 = QGridLayout(); g2.setSpacing(8)
        for i, tx in enumerate(['Zümre öğretmeni salona gelsin.', 'Bir öğrenci rahatsızlandı, idareden biri gelsin.']):
            b_ = QPushButton(tx); b_.setFocusPolicy(Qt.NoFocus); b_.clicked.connect(lambda c_=False, x=tx: self.edit.setText(x)); g2.addWidget(b_, 0, i)
        v.addLayout(g2)
        self.edit = QLineEdit(); self.edit.setPlaceholderText('Mesaj (isteğe bağlı)'); v.addWidget(self.edit)
        attach_touch_keyboard(self, self.edit, v)
        h = QHBoxLayout(); self.msg = QLabel(''); self.msg.setStyleSheet('QLabel{color:#ff8a8a;}'); h.addWidget(self.msg, 1)
        c_ = QPushButton('Vazgeç'); c_.clicked.connect(self.reject); h.addWidget(c_)
        s_ = QPushButton('Gönder'); s_.setStyleSheet('QPushButton{background:#2fbf71;color:#06240f;font-weight:700;}'); s_.clicked.connect(self.send); h.addWidget(s_)
        v.addLayout(h)
    def step(self, c, d):
        e = self.counts[c]; e[0] = max(0, min(60, e[0] + d)); e[1].setText(str(e[0]))
    def qstep(self, d):
        self.q = max(1, min(60, self.q + d)); self.qb.setText('Soruda hata var:  %d. soru' % self.q)
    def send(self):
        kag = {c: e[0] for c, e in self.counts.items() if e[0]}
        parts = []
        if kag: parts.append('Kâğıt eksik: ' + ', '.join('%s %d' % (c, n) for c, n in kag.items()))
        if self.edit.text().strip(): parts.append(self.edit.text().strip())
        if not parts: self.msg.setText('Eksik kâğıt sayısı ya da mesaj girin.'); return
        self.main.salon_message(self.st, self.plan, '  ·  '.join(parts), kag); self.accept()

class DuyuruDialog(QDialog):
    """Karargah: seçilen salonların tahtalarına sınav sırasında duyuru."""
    def __init__(self, main, ex):
        super().__init__(main); self.main = main; self.ex = ex
        self.setWindowTitle('Salonlara duyuru'); self.setMinimumWidth(fit_w(900))
        self.setStyleSheet('QDialog{background:#0f1c2e;} QLabel{color:white;font-size:20px;} QLineEdit{font-size:22px;padding:10px;border-radius:10px;}'
                           'QPushButton{background:#1d3150;color:white;border:1px solid #2a4468;border-radius:10px;padding:10px 16px;font-size:18px;}'
                           'QPushButton:checked{background:#2f6fd6;border-color:#2f6fd6;}')
        v = QVBoxLayout(self); v.setSpacing(12)
        v.addWidget(QLabel('Hazır duyurular'))
        for t_ in DUYURU_HAZIR:
            b = QPushButton(t_); b.setFocusPolicy(Qt.NoFocus); b.clicked.connect(lambda c=False, x=t_: self.edit.setText(x)); v.addWidget(b)
        v.addWidget(QLabel('Duyuru metni'))
        self.edit = QLineEdit(); v.addWidget(self.edit)
        attach_touch_keyboard(self, self.edit, v)
        v.addWidget(QLabel('Hangi salonlar'))
        grid = QGridLayout(); grid.setSpacing(8); self.all = QPushButton('Bütün salonlar'); self.all.setCheckable(True); self.all.setChecked(True)
        grid.addWidget(self.all, 0, 0, 1, 2); self.chips = {}
        for i, s_ in enumerate(sorted(ex[0].get('salonlar', {}), key=_salon_key)):
            b = QPushButton(s_); b.setCheckable(True); b.setFocusPolicy(Qt.NoFocus); b.clicked.connect(lambda c=False: self.all.setChecked(False))
            grid.addWidget(b, 1 + i//7, i % 7); self.chips[s_] = b
        self.all.clicked.connect(lambda c: [b.setChecked(False) for b in self.chips.values()] if c else None)
        v.addLayout(grid)
        h = QHBoxLayout(); self.msg = QLabel(''); h.addWidget(self.msg, 1)
        c_ = QPushButton('Vazgeç'); c_.clicked.connect(self.reject); h.addWidget(c_)
        s_ = QPushButton('Gönder'); s_.setStyleSheet('QPushButton{background:#2fbf71;color:#06240f;font-weight:700;}'); s_.clicked.connect(self.send); h.addWidget(s_)
        v.addLayout(h)
    def send(self):
        t_ = self.edit.text().strip()
        if not t_: self.msg.setText('Duyuru metni boş.'); return
        hedef = ['*'] if self.all.isChecked() else [s_ for s_, b in self.chips.items() if b.isChecked()]
        if not hedef: self.msg.setText('Salon seçilmedi.'); return
        if self.main.send_duyuru(t_, hedef, self.ex): self.accept()
        else: self.msg.setText('Gönderilemedi.')

def yoklama_reports(main, ex, data, folder):
    """Sınav sonu: gelmeyenler PDF'i + bütün sınavların mazeret listesi (PDF ve CSV). [(yerel yol, Drive'daki ad)]"""
    from PyQt5.QtGui import QPdfWriter, QPageSize, QFont
    import datetime, csv
    pl, day, lesson, a, b = ex[:5]; key = Window.yok_key(day, lesson)
    fams = ui_fonts(); fam = fams.get('Poppins-Regular') or 'Sans'; famb = fams.get('Poppins-Bold') or fam
    def F(px, bold=False): f = QFont(famb if bold else fam); f.setPixelSize(px); f.setWeight(QFont.Bold if bold else QFont.Normal); return f
    def esc(s_): return ''.join(c for c in s_ if c not in '/\\:*?"<>|').strip()
    courses = []
    for s_, lst in pl.get('salonlar', {}).items():
        for r in lst:
            c = tr_title(r.get('ders')) or exam_course(day.isoformat(), lesson, r.get('sinif'), '')
            if c and c not in courses: courses.append(c)
    order = ['Kimya', 'Matematik', 'Fizik', 'Biyoloji', 'Tarih']
    courses.sort(key=lambda c: (c.startswith('S. '), c))
    ys = {s_: data.get('%s_%s.json' % (key, s_)) for s_ in pl.get('salonlar', {})}
    absent = []
    for s_, v in ys.items():
        for r in (v or {}).get('gelmedi', []): absent.append(dict(r, salon=s_))
    total = sum(len(v) for v in pl.get('salonlar', {}).values())
    missing = sorted([s_ for s_, v in ys.items() if not v], key=_salon_key)
    unconf = sorted([s_ for s_, v in ys.items() if v and not v.get('onay') and not v.get('gelmedi')], key=_salon_key)
    try: n = int(lesson.split('.')[0])
    except ValueError: n = 0
    def teacher(s_): return pl.get('gozcu', {}).get(s_) or ', '.join((lesson_cell(s_, day.weekday(), n) or {}).get('ogretmen', [])) or '—'
    W, H, M = 1240, 1754, 70
    def new_writer(path):
        w = QPdfWriter(path); w.setPageSize(QPageSize(QPageSize.A4)); w.setResolution(150); w.setTitle(os.path.basename(path))
        from PyQt5.QtCore import QMarginsF
        try: w.setPageMargins(QMarginsF(0, 0, 0, 0))
        except Exception: pass
        return w
    def header(p, sub, right1, right2):
        lg = QPixmap(LOGO_RESMI if os.path.isfile(LOGO_RESMI) else LOGO)
        if not lg.isNull(): p.drawPixmap(QRectF(M, 56, 112, 112), lg, QRectF(lg.rect()))
        p.setPen(QColor('#14223a')); p.setFont(F(34, True)); p.drawText(QRectF(200, 60, 700, 50), Qt.AlignLeft | Qt.AlignVCenter, 'Ümraniye Merkez Anadolu Lisesi')
        p.setFont(F(28)); p.drawText(QRectF(200, 108, 700, 44), Qt.AlignLeft | Qt.AlignVCenter, sub)
        p.setPen(QColor('#444')); p.setFont(F(21)); p.drawText(QRectF(W - M - 500, 64, 500, 34), Qt.AlignRight | Qt.AlignVCenter, right1)
        p.setFont(F(21, True)); p.drawText(QRectF(W - M - 500, 98, 500, 34), Qt.AlignRight | Qt.AlignVCenter, right2)
        p.setPen(QPen(QColor('#14223a'), 3)); p.drawLine(QPointF(M, 192), QPointF(W - M, 192))
    def footer(p, page, txt):
        p.setPen(QColor('#888')); p.setFont(F(16)); p.drawText(QRectF(0, H - 70, W, 30), Qt.AlignCenter, '%s  ·  Sayfa %d' % (txt, page))
    # --- 1) Gelmeyenler ---
    title = '%s - %s' % (tr_date(day), ', '.join(courses) or (pl.get('sinav') or lesson))
    path1 = os.path.join(folder, 'rapor-%s.pdf' % key); name1 = esc(title) + '.pdf'
    w = new_writer(path1); p = QPainter(w); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing)
    sc = w.width()/W; p.scale(sc, sc); page = 1
    header(p, 'Sınava Gelmeyen Öğrenciler', '%s %s' % (tr_date(day), TR_DAYS[day.weekday()]), '%s · %s–%s' % (lesson, '%02d.%02d' % (a//3600, a%3600//60), '%02d.%02d' % (b//3600, b%3600//60)))
    y = 214
    p.setPen(QColor('#14223a')); p.setFont(F(19)); r_ = QRectF(M, y, W - 2*M, 60)
    p.drawText(r_, Qt.AlignLeft | Qt.TextWordWrap, 'Sınav: ' + ', '.join(courses)); y += 64
    boxes = [('Sınava girecek', str(total), '#14223a'), ('Gelen', str(total - len(absent)), '#14223a'), ('Gelmeyen', str(len(absent)), '#c0202e'), ('Yoklama gelmeyen salon', str(len(missing)), '#14223a')]
    bw = (W - 2*M - 3*16)/4; x = M
    for lab, val, col in boxes:
        p.setPen(QPen(QColor('#c9d2de'), 2)); p.setBrush(Qt.NoBrush); p.drawRoundedRect(QRectF(x, y, bw, 80), 10, 10)
        p.setPen(QColor('#666')); p.setFont(F(18)); p.drawText(QRectF(x + 16, y + 8, bw, 26), Qt.AlignLeft | Qt.AlignVCenter, lab)
        p.setPen(QColor(col)); p.setFont(F(30, True)); p.drawText(QRectF(x + 16, y + 34, bw, 40), Qt.AlignLeft | Qt.AlignVCenter, val); x += bw + 16
    y += 112
    by = {}
    for r in absent: by.setdefault(r.get('sinif', ''), []).append(r)
    def need(h):
        nonlocal y, page
        if y + h > H - 100:
            footer(p, page, 'UMAL Atlas · sınav bitiminde hazırlandı'); w.newPage(); page += 1; y = 70
    if not absent:
        p.setPen(QColor('#1f7a46')); p.setFont(F(24, True)); p.drawText(QRectF(M, y, W - 2*M, 50), Qt.AlignLeft | Qt.AlignVCenter, 'Yoklama gönderen salonlarda gelmeyen öğrenci yok.'); y += 70
    for c in sorted(by, key=_salon_key):
        need(56 + 88)
        p.setPen(Qt.NoPen); p.setBrush(QColor('#eef2f7')); p.drawRoundedRect(QRectF(M, y, W - 2*M, 44), 8, 8)
        p.setPen(QColor('#14223a')); p.setFont(F(22, True)); p.drawText(QRectF(M + 16, y, 600, 44), Qt.AlignLeft | Qt.AlignVCenter, '%s sınıfı' % c)
        p.setPen(QColor('#555')); p.setFont(F(20)); p.drawText(QRectF(W - M - 400, y, 384, 44), Qt.AlignRight | Qt.AlignVCenter, '%d öğrenci' % len(by[c])); y += 56
        for r in sorted(by[c], key=lambda r: r.get('ad', '')):
            need(88)
            pm = student_photo(r.get('no'))
            if pm is not None and not pm.isNull(): p.drawPixmap(QRectF(M + 16, y, 58, 75), pm, QRectF(pm.rect()))
            p.setPen(QColor('#111')); p.setFont(F(24, True)); p.drawText(QRectF(M + 90, y + 2, 640, 34), Qt.AlignLeft | Qt.AlignVCenter, r.get('ad', ''))
            p.setPen(QColor('#555')); p.setFont(F(19)); p.drawText(QRectF(M + 90, y + 38, 640, 30), Qt.AlignLeft | Qt.AlignVCenter, 'No: %s  ·  %s' % (r.get('no', ''), r.get('ders_adi') or exam_course(day.isoformat(), lesson, c, '')))
            p.setPen(QColor('#222')); p.setFont(F(21)); p.drawText(QRectF(W - M - 420, y + 2, 404, 34), Qt.AlignRight | Qt.AlignVCenter, 'Salon %s · Sıra %s' % (r['salon'], r.get('sira')))
            y += 88; p.setPen(QPen(QColor('#e3e7ed'), 1)); p.drawLine(QPointF(M + 16, y - 7), QPointF(W - M - 16, y - 7))
        y += 8
    for lab, lst in (('Yoklama göndermeyen salonlar', missing), ('Yoklamayı onaylamayan salonlar (gelmeyen işaretlenmedi)', unconf)):
        if not lst: continue
        txt = ' · '.join('%s (%s)' % (s_, teacher(s_)) for s_ in lst)
        hh = 60 + 28*math.ceil(len(txt)/90); need(hh + 20)
        p.setPen(QPen(QColor('#e0a100'), 2)); p.setBrush(Qt.NoBrush); p.drawRoundedRect(QRectF(M, y + 6, W - 2*M, hh), 8, 8)
        p.setPen(QColor('#8a5a00')); p.setFont(F(20, True)); p.drawText(QRectF(M + 16, y + 14, W - 2*M - 32, 30), Qt.AlignLeft | Qt.AlignVCenter, lab)
        p.setPen(QColor('#333')); p.setFont(F(19)); p.drawText(QRectF(M + 16, y + 46, W - 2*M - 32, hh - 44), Qt.AlignLeft | Qt.TextWordWrap, txt); y += hh + 20
    footer(p, page, 'UMAL Atlas · sınav bitiminde hazırlandı'); p.end()
    # --- 2) Mazeret listesi: Drive'daki bütün sınavların yoklamalarından ---
    rows = []
    for nm, v in data.items():
        if not isinstance(v, dict) or v.get('ders') == DENEME_DERS: continue   # deneme sınavı mazerete girmez
        for r in v.get('gelmedi', []):
            rows.append(dict(r, tarih=v.get('tarih', ''), ders=v.get('ders', ''), salon=v.get('salon', ''), ders_adi=r.get('ders_adi') or exam_course(v.get('tarih', ''), v.get('ders', ''), r.get('sinif'), v.get('sinav', ''))))
    # bu sınavın henüz Drive'a ulaşmamış yerel kopyası yok; Karargah yalnız Drive'dakini bilir
    rows.sort(key=lambda r: (r['tarih'], r['ders'], r['ders_adi'], _salon_key(r.get('sinif', '')), r.get('ad', '')))
    path2 = os.path.join(folder, 'mazeret.pdf'); name2 = 'Mazeret Sınavı Listesi.pdf'
    w = new_writer(path2); p = QPainter(w); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing); p.scale(w.width()/W, w.width()/W); page = 1
    now_ = main.exam_clock()
    header(p, 'Mazeret Sınavı Listesi', '1. Dönem 1. Ortak Yazılılar', 'Güncelleme: %s, %02d.%02d' % (tr_date(now_.date()), now_.hour, now_.minute))
    y = 222
    def need2(h):
        nonlocal y, page
        if y + h > H - 100:
            footer(p, page, 'UMAL Atlas · her sınavdan sonra güncellenir'); w.newPage(); page += 1; y = 70
    p.setPen(QColor('#14223a')); p.setFont(F(26, True)); p.drawText(QRectF(M, y, 600, 40), Qt.AlignLeft | Qt.AlignVCenter, 'Derse göre'); y += 50
    grp = {}
    for r in rows: grp.setdefault((r['ders_adi'], r['tarih'], r['ders']), []).append(r)
    if not rows:
        p.setFont(F(20)); p.setPen(QColor('#555')); p.drawText(QRectF(M, y, W - 2*M, 40), Qt.AlignLeft | Qt.AlignVCenter, 'Henüz gelmeyen öğrenci kaydı yok.'); y += 50
    for (ca, tarih, ders), lst in sorted(grp.items(), key=lambda kv: (kv[0][1], kv[0][2], kv[0][0])):
        need2(52 + 34)
        try: d_ = datetime.date.fromisoformat(tarih); dt = '%d %s' % (d_.day, TR_MONTHS[d_.month-1][:3])
        except ValueError: dt = tarih
        p.setPen(Qt.NoPen); p.setBrush(QColor('#eef2f7')); p.drawRoundedRect(QRectF(M, y, W - 2*M, 44), 8, 8)
        p.setPen(QColor('#14223a')); p.setFont(F(21, True)); p.drawText(QRectF(M + 16, y, W - 2*M - 220, 44), Qt.AlignLeft | Qt.AlignVCenter, '%s  ·  %s · %s' % (ca, dt, ders))
        p.setPen(QColor('#555')); p.setFont(F(19)); p.drawText(QRectF(W - M - 220, y, 204, 44), Qt.AlignRight | Qt.AlignVCenter, '%d öğrenci' % len(lst)); y += 52
        for r in lst:
            need2(34)
            p.setPen(QColor('#333')); p.setFont(F(19, True)); p.drawText(QRectF(M + 20, y, 80, 30), Qt.AlignLeft | Qt.AlignVCenter, r.get('sinif', ''))
            p.setPen(QColor('#111')); p.setFont(F(19)); p.drawText(QRectF(M + 100, y, 700, 30), Qt.AlignLeft | Qt.AlignVCenter, r.get('ad', ''))
            p.setPen(QColor('#555')); p.drawText(QRectF(W - M - 300, y, 280, 30), Qt.AlignRight | Qt.AlignVCenter, 'No: %s' % r.get('no', '')); y += 34
        y += 12
    need2(140); y += 10
    p.setPen(QColor('#14223a')); p.setFont(F(26, True)); p.drawText(QRectF(M, y, 600, 40), Qt.AlignLeft | Qt.AlignVCenter, 'Öğrenciye göre'); y += 50
    per = {}
    for r in rows:
        k_ = (r.get('sinif', ''), r.get('ad', ''), str(r.get('no', '')))
        if r['ders_adi'] not in per.setdefault(k_, []): per[k_].append(r['ders_adi'])
    def thead():
        nonlocal y
        p.setPen(Qt.NoPen); p.setBrush(QColor('#14223a')); p.drawRoundedRect(QRectF(M, y, W - 2*M, 40), 8, 8); p.setPen(QColor('#ffffff')); p.setFont(F(18, True))
        for x_, t_ in ((M + 16, 'Sınıf'), (M + 100, 'Ad Soyad'), (M + 490, 'No'), (M + 610, 'Mazerete gireceği dersler')): p.drawText(QRectF(x_, y, 400, 40), Qt.AlignLeft | Qt.AlignVCenter, t_)
        y += 48
    thead()
    for (c, ad, no), lst in sorted(per.items(), key=lambda kv: (_salon_key(kv[0][0]), kv[0][1])):
        txt = ', '.join(lst); hh = 34*max(1, math.ceil(len(txt)/38))
        if y + hh > H - 100: need2(hh); thead()
        p.setPen(QColor('#333')); p.setFont(F(19, True)); p.drawText(QRectF(M + 16, y, 80, 30), Qt.AlignLeft | Qt.AlignVCenter, c)
        p.setPen(QColor('#111')); p.setFont(F(19)); p.drawText(QRectF(M + 100, y, 380, 30), Qt.AlignLeft | Qt.AlignVCenter, ad)
        p.setPen(QColor('#555')); p.drawText(QRectF(M + 490, y, 110, 30), Qt.AlignLeft | Qt.AlignVCenter, no)
        p.setPen(QColor('#c0202e')); p.setFont(F(19, True)); p.drawText(QRectF(M + 610, y, W - 2*M - 626, hh), Qt.AlignLeft | Qt.AlignTop | Qt.TextWordWrap, txt)
        y += hh; p.setPen(QPen(QColor('#e3e7ed'), 1)); p.drawLine(QPointF(M + 16, y - 3), QPointF(W - M - 16, y - 3))
    footer(p, page, 'UMAL Atlas · her sınavdan sonra güncellenir'); p.end()
    path3 = os.path.join(folder, 'mazeret.csv'); name3 = 'Mazeret Sınavı Listesi.csv'
    with open(path3, 'w', encoding='utf-8-sig', newline='') as f:
        cw = csv.writer(f, delimiter=';'); cw.writerow(['Tarih', 'Ders saati', 'Ders', 'Sınıf', 'Ad Soyad', 'Okul No', 'Salon', 'Sıra'])
        for r in rows: cw.writerow([r['tarih'], r['ders'], r['ders_adi'], r.get('sinif', ''), r.get('ad', ''), r.get('no', ''), r.get('salon', ''), r.get('sira', '')])
    return [(path1, name1), (path2, name2), (path3, name3)]

def _draw_plan_photos(self, p, R, plan, k, font, theme, pad, title_h):
    """Fotoğraflı liste. Salonda: sıra numarasına göre kart ızgarası (fotoğraf, ad, sınıf).
    Sınıfta (sınavdan önce): her satırda fotoğraf, ad, salon, sıra."""
    from PyQt5.QtGui import QFontMetrics, QFont
    lst = plan['liste']; gy = R.y() + title_h + 14*k; gx = R.x() + pad; GW = R.width() - 2*pad; GH = R.bottom() - pad - gy
    def fit(text, f, w):
        f = QFont(f); px = f.pixelSize()
        while px > 9 and QFontMetrics(f).horizontalAdvance(text) > w: px -= 1; f.setPixelSize(px)
        return f
    if plan['tur'] == 'salon':
        seats = {r['sira']: r for r in lst}; n = max(max(seats) if seats else 1, 1)
        cols = 8 if n > 30 else 6 if n > 18 else 5; rows = math.ceil(n/cols); gap = 8*k
        cw = (GW - gap*(cols - 1))/cols; ch = (GH - gap*(rows - 1))/rows
        for i in range(n):
            no = i + 1; st_ = seats.get(no); c, r_ = i % cols, i // cols
            cell = QRectF(gx + c*(cw + gap), gy + r_*(ch + gap), cw, ch)
            p.setPen(Qt.NoPen); p.setBrush(QColor(255, 255, 255, 16 if st_ else 6)); p.drawRoundedRect(cell, 10*k, 10*k)
            ph = cell.height()*.64; pw = min(cell.width() - 12*k, ph*.77); pr = QRectF(cell.center().x() - pw/2, cell.y() + 6*k, pw, ph - 6*k)
            if st_: draw_photo(p, pr, st_.get('no'), st_['ad'], k)
            p.setPen(Qt.NoPen); p.setBrush(QColor(theme)); b = QRectF(cell.x() + 4*k, cell.y() + 4*k, 34*k, 26*k); p.drawRoundedRect(b, 8*k, 8*k)
            p.setFont(font(17, True)); p.setPen(QColor('#0b1422')); p.drawText(b, Qt.AlignCenter, str(no))
            if not st_:
                p.setFont(font(15)); p.setPen(QColor('#5d6f88')); p.drawText(pr, Qt.AlignCenter, 'boş'); continue
            nr = QRectF(cell.x() + 4*k, cell.y() + ph + 2*k, cell.width() - 8*k, (cell.height() - ph)*.55)
            f_ = fit(st_['ad'], font(17, True), nr.width()); p.setPen(QColor('#ffffff'))
            if f_.pixelSize() < 13*k: f_ = font(13, True); p.setFont(f_); p.drawText(nr.adjusted(0, -6*k, 0, 6*k), Qt.AlignCenter | Qt.TextWordWrap, st_['ad'])   # uzun ad: iki satır
            else: p.setFont(f_); p.drawText(nr, Qt.AlignCenter, st_['ad'])
            p.setFont(font(15)); p.setPen(QColor('#9fb3cc')); p.drawText(QRectF(nr.x(), nr.bottom(), nr.width(), cell.bottom() - nr.bottom()), Qt.AlignHCenter | Qt.AlignTop, st_['sinif'])
        return
    n = max(1, len(lst)); cols = 1 if n <= 20 else 2; per = math.ceil(n/cols); gap = 24*k
    gw = (GW - gap*(cols - 1))/cols; head_h = 30*k; rh = (GH - head_h)/per
    for c in range(cols):
        x = gx + c*(gw + gap); sal_w = 84*k; sira_w = 56*k; ph_w = (rh - 4*k)*.77
        p.setFont(font(16, True)); p.setPen(QColor('#8ea3c0'))
        p.drawText(QRectF(x + ph_w + 12*k, gy, gw, head_h), Qt.AlignVCenter | Qt.AlignLeft, 'Ad Soyad')
        p.drawText(QRectF(x + gw - sal_w - sira_w, gy, sal_w, head_h), Qt.AlignVCenter | Qt.AlignHCenter, 'Salon')
        p.drawText(QRectF(x + gw - sira_w, gy, sira_w - 6*k, head_h), Qt.AlignVCenter | Qt.AlignRight, 'Sıra')
        for r_ in range(per):
            idx = c*per + r_
            if idx >= len(lst): continue
            y = gy + head_h + r_*rh; st_ = lst[idx]
            if r_ % 2 == 0: p.setPen(Qt.NoPen); p.setBrush(QColor(255, 255, 255, 12)); p.drawRect(QRectF(x, y, gw, rh))
            draw_photo(p, QRectF(x + 4*k, y + 2*k, ph_w, rh - 4*k), st_.get('no'), st_['ad'], k)
            nr = QRectF(x + ph_w + 12*k, y, gw - ph_w - sal_w - sira_w - 16*k, rh)
            p.setFont(fit(st_['ad'], font(min(24, rh/k*.42)), nr.width())); p.setPen(QColor('#ffffff')); p.drawText(nr, Qt.AlignVCenter | Qt.AlignLeft, st_['ad'])
            p.setFont(font(min(26, rh/k*.46), True)); p.setPen(QColor(theme)); p.drawText(QRectF(x + gw - sal_w - sira_w, y, sal_w, rh), Qt.AlignVCenter | Qt.AlignHCenter, str(st_['salon']))
            p.setPen(QColor('#ffffff')); p.drawText(QRectF(x + gw - sira_w, y, sira_w - 6*k, rh), Qt.AlignVCenter | Qt.AlignRight, str(st_['sira']))
ExamScreen.draw_plan_photos = _draw_plan_photos
SALON_LAYOUT = {'11-H': '11h', '12-I': 'ozel'}   # masa sütunu sayısı (her masada 2 kişi, 5 sıra) ya da özel düzen
def _snake(cols, rows):
    """Genel salon: sütunlar soldan sağa; yılan düzeni (1. sütun önden arkaya, 2. arkadan öne…)."""
    desks = []
    for c in range(cols):
        for r in range(rows):
            rr = r if c % 2 == 0 else rows - 1 - r
            n0 = c*rows*2 + rr*2 + 1
            desks.append((c*2.4, r, 2, [n0, n0 + 1]))
    return desks
def _layout_12i():
    """12-I (tahtadan bakınca aynalı; aşağıdaki sol/sağ planın çizimine göre): sol duvar sütununda 7 sıra, orta ve kapı sütununda 5 sıra, arkada iki tekli sıra.
    Öğretmen masasından başlar: sol sütun önden arkaya 1–10, orta arkadan öne 11–20, kapı sütunu önden arkaya 21–30,
    tekli sıralar 31–32; sol sütunun en arkadaki iki sırası (görünmesi zor köşe) en son, 33–36."""
    d = [(0, r, 2, [r*2 + 1, r*2 + 2]) for r in range(5)]
    d += [(2.4, r, 2, [11 + (4 - r)*2, 12 + (4 - r)*2]) for r in range(5)]
    d += [(4.8, r, 2, [21 + r*2, 22 + r*2]) for r in range(5)]
    d += [(2.4, 5, 1, [31]), (2.4, 6, 1, [32]), (0, 5, 2, [33, 34]), (0, 6, 2, [35, 36])]
    # tahtadan bakınca: solda kapı, sağda öğretmen masası, hemen solunda akıllı tahta, onun solunda beyaz tahta → plan aynada çevrilir
    W_ = max(x + w for x, y, w, _ in d); d = [(round(W_ - x - w, 2), y, w, list(reversed(ns))) for x, y, w, ns in d]
    return dict(desks=d, sol='', sag='DUVAR', on=[('DOLAP · KAPI', 'sol'), ('BEYAZ TAHTA', 'orta'), ('AKILLI TAHTA', 'sagic'), ('Öğretmen masası', 'sag')])
def _layout_11h():
    """11-H (en çok 20 kişi): iki duvar kenarında beşer sıra, her sırada iki kişi; arkada cam.
    Önde solda kapı, sağda öğretmen masası. Öğretmen masasından başlar: sağ sütun önden arkaya 1–10, sol sütun arkadan öne 11–20."""
    d = [(4.4, r, 2, [r*2 + 1, r*2 + 2]) for r in range(5)] + [(0, r, 2, [11 + (4 - r)*2, 12 + (4 - r)*2]) for r in range(5)]
    return dict(desks=d, sol='DUVAR', sag='DUVAR', arka='CAM', on=[('KAPI', 'sol'), ('TAHTA', 'orta'), ('Öğretmen masası', 'sag')])
def seat_layout(plan):
    lay = SALON_LAYOUT.get(plan.get('sinif'), 4)
    if not lay: return None
    if lay == 'ozel': L_ = _layout_12i()
    elif lay == '11h': L_ = _layout_11h()
    else:
        n = max([r['sira'] for r in plan['liste']] or [1]); rows = max(5, math.ceil(n/(lay*2)))
        L_ = dict(desks=_snake(lay, rows), sol='CAM', sag='DUVAR', on=[('Öğretmen masası', 'sol'), ('TAHTA', 'orta'), ('KAPI', 'sag')], wide_aisle=(lay <= 2))
    L_['W'] = max(x + w for x, y, w, _ in L_['desks']); L_['H'] = max(y for x, y, w, _ in L_['desks']) + 1
    L_['seats'] = {n_ for *_, ns in L_['desks'] for n_ in ns}
    return L_
def draw_neon(p, r, s_, f, color, k, glow=1.0):
    """Neon tabela: koyu zemin, parlayan çerçeve ve parlayan yazı (glow: ışıma çarpanı, nefes efekti için)."""
    c = QColor(color); p.save(); p.setBrush(Qt.NoBrush)
    for w_, a in ((14, 22), (9, 40), (5, 70)):
        q = QColor(c); q.setAlpha(int(min(255, a*glow))); p.setPen(QPen(q, w_*k)); p.drawRoundedRect(r, 16*k, 16*k)
    p.setPen(Qt.NoPen); p.setBrush(QColor(8, 14, 26, 235)); p.drawRoundedRect(r, 16*k, 16*k)
    p.setPen(QPen(c, 2.5*k)); p.setBrush(Qt.NoBrush); p.drawRoundedRect(r, 16*k, 16*k)
    path = QPainterPath(); fm = QFontMetrics(f); tw = fm.horizontalAdvance(s_)
    path.addText(QPointF(r.center().x() - tw/2, r.center().y() + (fm.ascent() - fm.descent())/2), f, s_)
    for w_, a in ((12, 30), (7, 60), (3.5, 120)):
        q = QColor(c); q.setAlpha(int(min(255, a*glow))); p.setPen(QPen(q, w_*k, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)); p.drawPath(path)
    core = QColor(c).lighter(160); p.setPen(Qt.NoPen); p.setBrush(core); p.drawPath(path)
    p.restore()
def home_seat_plan(plan):
    """Sınavdan önce kendi sınıfında: öğrenciler okul numarasına göre (küçükten büyüğe) her sırada iki kişi,
    sütun sütun önden arkaya oturtulur; her kartta gideceği salon ve sıra yazar."""
    lst = sorted(plan['liste'], key=lambda r: (int(r['no']) if str(r.get('no', '')).isdigit() else 10**9, r.get('ad', '')))
    probe = dict(sinif=plan['sinif'], liste=[dict(sira=i + 1) for i in range(len(lst))])
    lay = seat_layout(probe)
    if not lay: return None
    order = [n_ for x, y, w, ns in sorted(lay['desks'], key=lambda d: (d[0], d[1])) for n_ in ns]
    if plan['sinif'] in OZEL_SIRA: order = [n_ for n_ in OZEL_SIRA[plan['sinif']] if n_ in lay['seats']] + [n_ for n_ in order if n_ not in OZEL_SIRA[plan['sinif']]]
    out = [dict(sira=order[i], ad=r['ad'], no=r.get('no', ''), sinif=plan['sinif'], ders=r.get('ders', ''), git='%s · Sıra %s' % (r['salon'], r['sira'])) for i, r in enumerate(lst) if i < len(order)]
    return dict(tur='salon', sinif=plan['sinif'], liste=out, ev=True)
OZEL_SIRA = {'12-I': list(range(1, 37)), '11-H': list(range(1, 9)) + list(range(13, 21)) + [9, 10, 11, 12]}   # özel sınıflarda oturtma sırası (öğretmen masasından)

def hata_ozet(tail):
    """Hata kaydının son satırı + uygulamadaki son çağrı yeri (panelde kök nedeni görmek için):
    'IndexError: page 156 not in document · satır 3333 fit_page ← 2901 place_overlays'."""
    import re
    msg = (tail[-1] if tail else '').strip()
    fr = [(m.group(1), m.group(2)) for l in tail for m in [re.search(r'tahta_kalem\.py", line (\d+), in (\w+)', l)] if m]
    if fr: msg += ' · satır ' + ' ← '.join('%s %s' % (n, f) for n, f in reversed(fr[-3:]))
    return msg[:240]
def tr_name(ad):
    """Öğrenci adı ekranda: her kelimenin baş harfi büyük, gerisi küçük (Türkçe I/ı, İ/i doğru): 'SÜMEYYE ÇAĞLAYAN' → 'Sümeyye Çağlayan'."""
    lo = lambda x: x.replace('I', 'ı').replace('İ', 'i').lower()
    up = lambda x: x.replace('i', 'İ').replace('ı', 'I').upper()
    return ' '.join(up(w[:1]) + lo(w[1:]) for w in (ad or '').split())

def seat_courses(plan):
    """Planda (salon ya da sınıf) hangi sınavlar var: Türkçe yazımla, en çok öğrencisi olandan başlayarak."""
    import collections
    c = collections.Counter(tr_title(r.get('ders')) for r in plan.get('liste', []) if r.get('ders'))
    return [x for x, _ in c.most_common() if x]

CARD_COURSE = {'Din Kültürü ve Ahlak Bilgisi': 'Din Kültürü', 'Sağlık Bilgisi ve Trafik': 'Sağlık Bilgisi', 'S. Klasik Ahlak Metinleri': 'S. Klasik Ahlak',
               'S. Türk Dili ve Edebiyatı': 'S. Edebiyat', 'Türk Dili ve Edebiyatı': 'Edebiyat', 'S. Metin Tahlilleri': 'S. Metin Tahlili',
               'S. Temel Matematik': 'S. Temel Mat.', 'S. Peygamberimizin Hayatı': 'S. Peygamber Hayatı', 'S. Türk Kültür ve Medeniyet Tarihi': 'S. Medeniyet Tarihi', 'T.C. İnkılap Tarihi ve Atatürkçülük': 'İnkılap Tarihi', 'S. Türk Kültür ve Medeniyet Tarihi': 'S. Medeniyet Tarihi'}
def course_short(c):
    """Sıra kartında ders adı tek satır: uzun adların kısa biçimi (başlıkta tam adı kalır)."""
    if not c: return c
    c = CARD_COURSE.get(c, c)
    if len(c) > 18 and ' ve ' in c: c = c.split(' ve ')[0]
    return c
def course_wrap(c):
    """Ders adı satır kırılırken 'S.' kendi kelimesinden ayrılmasın."""
    c = course_short(c)
    return c.replace('S. ', 'S.\u00a0') if c else c
def seat_card_parts(hfun, avail, items, gap):
    """Kartın yazı sütunu: ad, ders, sınıf alt alta, dikeyde ortalı. Sığmazsa önce sınıf, sonra ders düşer.
    Döner: [(font, metin, y, yükseklik)] (metin boşsa yükseklik 0)."""
    items = list(items)
    while True:
        hs = [hfun(f, t) if t else 0 for f, t in items]; n = sum(1 for h in hs if h)
        tot = sum(hs) + gap*max(0, n - 1)
        if tot <= avail or n <= 1: break
        for i in (2, 1):
            if items[i][1]: items[i] = (items[i][0], ''); break
    y = max(0, (avail - tot)/2); out = []
    for (f, t), h in zip(items, hs):
        out.append((f, t, y, h if t else 0))
        if t: y += h + gap
    return out
def desk_extend(desks, keep=0.3):
    """Aynı sıradaki komşu masalar arası en dar boşluktan 'keep' kadarı koridor kalır; gerisi masalara eklenir."""
    rows = {}
    for x, y, w, _ in desks: rows.setdefault(y, []).append((x, w))
    gaps = [b[0] - (a[0] + a[1]) for r in rows.values() for a, b in zip(sorted(r), sorted(r)[1:])]
    gaps = [g_ for g_ in gaps if g_ > 0]
    return min(0.4, max(0.0, min(gaps) - keep)) if gaps else 0.0
def seat_fonts(adv, width, names, courses, photos=True):
    """Salonun ortak puntoları (k'siz px): ad için en büyük boy ki en uzun kelime sığsın (alt sınır 14),
    ders için de aynısı (11–15). adv(px, bold, metin) -> genişlik."""
    def best(hi, lo, bold, texts):
        words = {w for t in texts for w in (t or '').split(' ') if w}   # (S.\u00a0Matematik tek kelime sayılır)
        if not words: return hi
        for px in range(hi, lo - 1, -1):
            if max(adv(px, bold, w) for w in words) <= width: return px
        return lo
    def best_line(hi, lo, bold, texts):   # ders adı tek satıra sığsın (en uzun ders adına göre); olmazsa en küçük boy, iki satır
        texts = [t for t in texts if t]
        if not texts: return hi
        for px in range(hi, lo - 1, -1):
            if max(adv(px, bold, t) for t in texts) <= width: return px
        return lo
    return best(22 if photos else 26, 14, False, names), best_line(15, 10, True, courses)
def meta_parts(meta):
    """'4. Ders  ·  6 Kasım  ·  38 öğrenci' → [(parça, sarı_neon_mu)]: öğrenci sayısı sarı neon."""
    return [(m_.strip(), 'öğrenci' in m_) for m_ in (meta or '').split('·') if m_.strip()]
def draw_meta_right(p, r, meta, font, accent, k):
    """Sağa yaslı bilgi satırı; parçalar ' · ' ile, öğrenci sayısı sarı neon ışımalı."""
    from PyQt5.QtGui import QFontMetrics
    parts = meta_parts(meta); sep = '  ·  '
    if not parts: return
    f = font(24)
    while f.pixelSize() > 11 and QFontMetrics(f).horizontalAdvance(sep.join(t for t, _ in parts)) > r.width(): f.setPixelSize(f.pixelSize() - 1)
    fm = QFontMetrics(f); x = r.right(); p.setFont(f)
    for i, (t, neon) in reversed(list(enumerate(parts))):
        w = fm.horizontalAdvance(t); rr = QRectF(x - w, r.y(), w + 2, r.height())
        if neon:
            for dx_, dy_ in ((-1, 0), (1, 0), (0, -1), (0, 1)): p.setPen(QColor(255, 200, 0, 90)); p.drawText(rr.translated(dx_*k*1.5, dy_*k*1.5), Qt.AlignLeft | Qt.AlignVCenter, t)
            p.setPen(QColor('#ffe14d'))
        else: p.setPen(QColor(accent))
        p.drawText(rr, Qt.AlignLeft | Qt.AlignVCenter, t); x -= w
        if i:
            ws = fm.horizontalAdvance(sep); p.setPen(QColor(accent)); p.drawText(QRectF(x - ws, r.y(), ws + 2, r.height()), Qt.AlignLeft | Qt.AlignVCenter, sep); x -= ws
def seat_name_fit(hh, nf, cf, avail, pairs, gap, lo=12):
    """Ad puntosunu (salonun tek puntosu) gerekirse küçült: her kartta ad + ders alt alta sığsın. hh(px, kalın, metin) -> yükseklik."""
    while nf > lo and any(hh(nf, False, ad) + ((hh(cf, True, c) + gap) if c else 0) > avail for ad, c in pairs if ad): nf -= 1
    return nf
def seat_head_zone(self, W, k, hx, hr):
    """Başlık yazısının sağ sınırı: ortada neon arama düğmesi varsa onun solunda biter."""
    b = getattr(self, 'ara_btn', None) or getattr(self, 'b_ara', None)
    if b is None or isinstance(self, SalonBrowser): return hr
    try: bw = b.width()
    except Exception: return hr
    return max(hx + 40*k, min(hr, W/2 - bw/2 - 20*k))
def heart_beat(per=1.0, t=None):
    """Kalp atışı (0..1): saniyenin başında iki kısa vuruş (tık-tık), sonra dinlenme. per: vuruş aralığı (son 5 dk'da .6)."""
    ph = ((time.time() if t is None else t) % per)/per
    return max(math.exp(-((ph - .07)/.035)**2), .6*math.exp(-((ph - .21)/.035)**2))
class HeartOverlay(QWidget):
    """Ağır ekranların (fotoğraflı plan, Karargah) üstünde yalnız saat/sayaç kutusunu saniyede 20 kez çizen küçük katman:
    alttaki ekran saniyede bir çizilmeye devam eder. item: dict(rect, kind, text, font, color, k, bg[, label, lfont])."""
    def __init__(self, parent):
        super().__init__(parent); self.item = None
        self.setAttribute(Qt.WA_OpaquePaintEvent, True); self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.timer = QTimer(self); self.timer.timeout.connect(self.update)
    def set_item(self, it):
        if not it: self.item = None; self.timer.stop(); self.hide(); return
        self.item = it; r = it['rect']; k = it['k']; m = it.get('m', 7*k + r.width()*.03)   # ışıma + büyüme payı (komşu yazıya değmez)
        g = QRectF(r.x() - m, r.y() - m, r.width() + 2*m, r.height() + 2*m).toAlignedRect().intersected(self.parent().rect())
        if g != self.geometry(): self.setGeometry(g)
        if not self.isVisible(): self.show()
        if not self.timer.isActive(): self.timer.start(66)   # K-429: 15 kare/sn
        self.update()
    def paintEvent(self, e):
        it = self.item
        if not it: return
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing)
        p.fillRect(self.rect(), QColor(it.get('bg', '#0d1726'))); p.translate(-self.x(), -self.y())
        v = heart_beat(it.get('per', 1.0)); s_ = 1 + .06*v; r = it['rect']; k = it['k']
        rr = QRectF(r.center().x() - r.width()*s_/2, r.center().y() - r.height()*s_/2, r.width()*s_, r.height()*s_)
        f = QFont(it['font']); f.setPixelSize(max(8, int(it['font'].pixelSize()*s_)))
        if it['kind'] == 'neon': draw_neon(p, rr, it['text'], f, it['color'], k, 1 + 1.3*v)
        elif it['kind'] == 'box':   # dolu kutu (yoklama sayacı): kutu yerinde, parlar; yazı atar
            p.setPen(Qt.NoPen)
            if it.get('strip'): p.setBrush(QColor(it['strip'])); p.drawRoundedRect(r, 12*k, 12*k); p.drawRect(QRectF(r.center().x(), r.y(), r.width()/2, r.height()))   # şeridin devamı
            q = QColor(it['color']); p.setBrush(q.lighter(int(100 + 22*v))); p.drawRoundedRect(r, 12*k, 12*k)
            f2 = QFont(it['font']); f2.setPixelSize(max(8, int(it['font'].pixelSize()*(1 + .08*v))))
            p.setFont(f2); p.setPen(QColor(it.get('fg', '#1a1206'))); p.drawText(r, Qt.AlignCenter, it['text'])
        elif it['kind'] == 'stat':   # Karargah istatistik kutusu: etiket sabit, değer atar
            p.setPen(Qt.NoPen); p.setBrush(QColor('#16243a')); p.drawRoundedRect(r, 12*k, 12*k)
            p.setFont(it['lfont']); p.setPen(QColor('#8fa6c4')); p.drawText(QRectF(r.x() + 16*k, r.y() + 6*k, r.width(), 24*k), Qt.AlignLeft | Qt.AlignVCenter, it['label'])
            vr = QRectF(r.x() + 16*k, r.y() + 30*k, r.width() - 20*k, 38*k); p.save(); p.translate(vr.x(), vr.center().y()); p.scale(s_, s_)
            p.setFont(it['font']); q = QColor(it['color']); p.setPen(q.lighter(int(100 + 30*v))); p.drawText(QRectF(0, -vr.height()/2, vr.width(), vr.height()), Qt.AlignLeft | Qt.AlignVCenter, it['text']); p.restore()
        else:   # düz yazı (sağa yaslı)
            p.save(); p.translate(r.right(), r.center().y()); p.scale(s_, s_)
            p.setFont(it['font']); q = QColor(it['color']); p.setPen(q.lighter(int(100 + 30*v))); p.drawText(QRectF(-r.width(), -r.height()/2, r.width(), r.height()), Qt.AlignRight | Qt.AlignVCenter, it['text']); p.restore()
        p.end()
def hb_sync(w):
    """Ekran çizildikten sonra: kaydedilen saat/sayaç kutularına kalp atışı katmanı koy, gerekmeyenleri gizle."""
    items = getattr(w, 'hb_items', {}) or {}; ov = getattr(w, 'hb_ov', None)
    if ov is None: ov = w.hb_ov = {}
    for key in set(ov) | set(items):
        if key not in ov: ov[key] = HeartOverlay(w); ov[key].lower()   # düğmelerin, duyurunun ve kâğıt alarmının altında kalır
        try: ov[key].set_item(items.get(key))
        except Exception as e: print('kalp:', e); ov[key].hide()
def hb_wrap(cls):
    inner = cls.paintEvent
    def paintEvent(self, e):
        self.hb_items = {}
        inner(self, e)
        hb_sync(self)
    cls.paintEvent = paintEvent
def draw_teneffus(p, W, H, k, font, tn):
    """Teneffüs modu ekranı (Atlas renkleri): büyük neon saat, tarih, şimdi/sıradaki ders, sıradaki sınava geri sayım, 5 iş günü takvim."""
    from PyQt5.QtGui import QFontMetrics
    def text(r, s_, f, c, al=Qt.AlignLeft | Qt.AlignVCenter): p.setFont(f); p.setPen(QColor(c)); p.drawText(r, al, s_)
    v_ = heart_beat(); fC = font(170, True); fC.setPixelSize(int(fC.pixelSize()*(1 + .05*v_))); r = QRectF(60*k, 30*k, 700*k, 190*k)
    p.setFont(fC)
    for w_, a in ((10, 40), (5, 70)):   # neon ışıma
        q = QColor('#22e8ff'); q.setAlpha(int(min(255, a*(1 + 1.2*v_))))
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)): p.setPen(q); p.drawText(r.translated(dx*w_*k*.4, dy*w_*k*.4), Qt.AlignLeft | Qt.AlignVCenter, tn['saat'])
    text(r, tn['saat'], fC, '#7ff6ff')
    text(QRectF(70*k, 225*k, 700*k, 44*k), tn['tarih'], font(32, True), '#c9d6ea')
    if tn.get('simdi'):
        f_ = font(24, True); w_ = QFontMetrics(f_).horizontalAdvance(tn['simdi']) + 36*k; rr = QRectF(70*k, 282*k, w_, 46*k)
        p.setPen(Qt.NoPen); p.setBrush(QColor('#ffb020')); p.drawRoundedRect(rr, 12*k, 12*k); text(rr, tn['simdi'], f_, '#1a1206', Qt.AlignCenter)
    if tn.get('kalan') is None:   # K-377: sınav yokken: Atlas'ı kullanma ipucu
        cd = QRectF(W - 60*k - 640*k, 92*k, 640*k, 250*k)
        for w_, a in ((16, 25), (8, 50)):
            q = QColor('#22e8ff'); q.setAlpha(a); p.setPen(QPen(q, w_*k)); p.setBrush(Qt.NoBrush); p.drawRoundedRect(cd, 24*k, 24*k)
        p.setPen(QPen(QColor('#22e8ff'), 3*k)); p.setBrush(QColor(6, 24, 40, 210)); p.drawRoundedRect(cd, 24*k, 24*k)
        text(QRectF(cd.x() + 34*k, cd.y() + 24*k, cd.width() - 68*k, 44*k), 'Teneffüs', font(34, True), '#7ff6ff')
        text(QRectF(cd.x() + 34*k, cd.y() + 80*k, cd.width() - 68*k, 120*k), 'Oyunlar, Günün soruları ve Atlas için\nsağ alttaki "Gizle"ye dokunun.', font(26, True), '#ffffff', Qt.AlignLeft | Qt.AlignTop)
        return
    cd = QRectF(W - 60*k - 600*k, 92*k, 600*k, 250*k)   # üst ortadaki arama düğmesinin altında
    for w_, a in ((16, 25), (8, 50)):
        q = QColor('#ffe14d'); q.setAlpha(a); p.setPen(QPen(q, w_*k)); p.setBrush(Qt.NoBrush); p.drawRoundedRect(cd, 24*k, 24*k)
    p.setPen(QPen(QColor('#ffe14d'), 3*k)); p.setBrush(QColor(30, 24, 5, 200)); p.drawRoundedRect(cd, 24*k, 24*k)
    text(QRectF(cd.x() + 30*k, cd.y() + 16*k, cd.width() - 60*k, 30*k), 'Bu sınıfın sıradaki sınavı', font(20, True), '#ffe9a0')
    fs = font(28, True)
    while fs.pixelSize() > 12 and QFontMetrics(fs).horizontalAdvance(tn['sonraki']) > cd.width() - 60*k: fs.setPixelSize(fs.pixelSize() - 1)
    text(QRectF(cd.x() + 30*k, cd.y() + 48*k, cd.width() - 60*k, 40*k), tn['sonraki'], fs, '#ffffff')
    bw = (cd.width() - 60*k - 2*14*k)/3
    for i, (v, lab) in enumerate(zip(tn['kalan'], ('gün', 'saat', 'dakika'))):
        b = QRectF(cd.x() + 30*k + i*(bw + 14*k), cd.y() + 100*k, bw, 140*k); p.setPen(Qt.NoPen); p.setBrush(QColor(255, 225, 77, 26)); p.drawRoundedRect(b, 16*k, 16*k)
        fv = font(72, True); fv.setPixelSize(int(fv.pixelSize()*(1 + .06*v_)))
        text(QRectF(b.x(), b.y() + 6*k, b.width(), 92*k), str(v), fv, QColor('#ffe14d').lighter(int(100 + 25*v_)).name(), Qt.AlignCenter); text(QRectF(b.x(), b.y() + 96*k, b.width(), 34*k), lab, font(19), '#ffe9a0', Qt.AlignCenter)
    days = tn['gunler']; n = max(1, len(days)); gap = 20*k; x0 = 60*k; top = 370*k; bot = H - 110*k
    cw = (W - 2*x0 - (n - 1)*gap)/n
    for i, (lab, sub, items) in enumerate(days):
        r_ = QRectF(x0 + i*(cw + gap), top, cw, bot - top); today = lab == 'Bugün'
        p.setPen(QPen(QColor('#22e8ff') if today else QColor(255, 255, 255, 40), (3 if today else 1.2)*k)); p.setBrush(QColor(34, 232, 255, 16) if today else QColor(255, 255, 255, 12)); p.drawRoundedRect(r_, 20*k, 20*k)
        text(QRectF(r_.x() + 20*k, r_.y() + 14*k, r_.width() - 40*k, 38*k), lab, font(28, True), '#ffffff')
        text(QRectF(r_.x() + 20*k, r_.y() + 50*k, r_.width() - 40*k, 26*k), sub, font(17), '#9fb3cc')
        y = r_.y() + 92*k
