            p.setBrush(QColor(col_)); p.drawRoundedRect(QRectF(e_.x(), e_.y(), 6*k, e_.height()), 3*k, 3*k)
            fc = font(22, True); cs = QFontMetrics(fc).elidedText(course_short(crs) + ('  · bitti' if done else ''), Qt.ElideRight, int(e_.width() - 30*k))
            text(QRectF(e_.x() + 18*k, e_.y() + 8*k, e_.width() - 26*k, 34*k), cs, fc, '#7f8da3' if done else '#ffffff')
            text(QRectF(e_.x() + 18*k, e_.y() + 42*k, e_.width() - 26*k, 26*k), '%s · %s' % (les, hm_), font(16), '#9fb3cc')
            y += 88*k
