    meta = ''   # ders saati, tarih, öğrenci sayısı: sağa yaslı ayrı bölme (sınav adlarıyla karışmasın)
    if crs and not any(c_.lower() in (head or '').lower() for c_ in crs): head, meta = ' / '.join(c_.replace('S. ', 'S.\u00a0') for c_ in crs[:3]), (head or '')
    hr = W - 36*k
    if plan.get('saat'):   # neon saat: sağ üstte, uzaktan okunur
        fn = font(40, True); tw = QFontMetrics(fn).horizontalAdvance(plan['saat'])
        pill = QRectF(W - 30*k - tw - 44*k, 8*k, tw + 44*k, 58*k); draw_neon(p, pill, plan['saat'], fn, accent, k); hr = pill.x() - 18*k
        if isinstance(getattr(self, 'hb_items', None), dict) and not p.transform().isTranslating():   # kalp atışı (yalnız tam ekran plan)
            self.hb_items['clock'] = dict(rect=QRectF(pill), kind='neon', text=plan['saat'], font=QFont(fn), color=accent, k=k, bg='#0d1726', per=plan.get('hb_per', 1.0))
    hx = pillT.right() + 20*k; hz = seat_head_zone(self, W, k, hx, hr)   # sol bölme: ortadaki 'Nerede sınava gireceğim?' düğmesine binmez
    if meta:
        mz = (W - hz) if hz < hr else hx + (hr - hx)*.55   # sağ bölme: düğmenin sağından (düğme yoksa ortadan) saate kadar
        if hz >= hr: hz = mz - 20*k
