    col = {'Öğretmen masası': ('#3a2f1f', '#ead6b0'), 'KAPI': ('#2a2f45', '#c9d0ff'), 'DOLAP · KAPI': ('#2a2f45', '#c9d0ff')}
    for lab, where in lay['on']:
        r_ = pos['sag2'] if (where == 'sag' and lab == 'Öğretmen masası') else pos[where]; bg, fg = col.get(lab, ('#1f3a2c', '#b9e3c9'))
        if where == 'orta' and lab == 'BEYAZ TAHTA': bg, fg = '#2f3640', '#e6e9ee'
