        cw0 = (dwf(w_) - gap*(len(nums) + 1))/len(nums); ch0 = (rh - 8*k - 2*gap)*(.7 if plan.get('ev') else 1)
        trw0 = min(trw0, cw0 - 5*k - (min((ch0 - 10*k)*.77, cw0*.45) if BOARD_PHOTOS else 0) - 9*k)
