        p.setPen(QPen(QColor(222, 196, 150, 70), 1.5)); p.setBrush(QColor(222, 196, 150, 14)); p.drawRoundedRect(desk, 12*k, 12*k)   # ahşap tonlu tabla
        p.setPen(Qt.NoPen); p.setBrush(QColor('#c9ad7c')); p.drawRoundedRect(QRectF(desk.x() + 4*k, desk.bottom() - 5*k, dw - 8*k, 4*k), 2*k, 2*k)   # tabla ön kenarı
        cw = (dw - gap*(len(nums) + 1))/len(nums)
        for si, no in enumerate(nums):
            st_ = seats.get(no); cell = QRectF(x + gap + si*(cw + gap), y + gap, cw, rh - 8*k - 2*gap)
            p.setPen(Qt.NoPen); p.setBrush(QColor(255, 255, 255, 18 if st_ else 6)); p.drawRoundedRect(cell, 10*k, 10*k)
            gcol = grade_color(st_.get('sinif'), theme) if st_ else theme   # sınıf seviyesi rengi
            if st_:   # solda seviye şeridi (hafif ışımalı)
                q_ = QColor(gcol); q_.setAlpha(70); p.setBrush(q_); p.drawRoundedRect(QRectF(cell.x() - 1*k, cell.y() + 2*k, 7*k, cell.height() - 4*k), 3*k, 3*k)
                p.setBrush(QColor(gcol)); p.drawRoundedRect(QRectF(cell.x(), cell.y() + 3*k, 4*k, cell.height() - 6*k), 2*k, 2*k)
