            'QPushButton:checked{background:#0f3a4a;border:2px solid #22e8ff;color:#7ff6ff;} QLineEdit{font-size:24px;color:#e8eefc;background:#0b1422;border:2px solid #24364f;border-radius:12px;padding:10px 14px;}'
