        self.send.setStyleSheet('QPushButton{background:#2fbf71;color:#06240f;border:none;font-size:28px;padding:12px 48px;}'); self.send.clicked.connect(self.submit); bot.addWidget(self.send); v.addLayout(bot)
        self.sc = sc; self.aktif = None; self.kb = None; self.tus = None
