            'QToolButton#sekme{background:transparent;border:1.5px solid transparent;font-size:13px;} QToolButton#sekme:checked{background:#14365a;border-color:#38bdf8;}'
            'QPushButton#bolum{color:#e8f1fc;background:#132540;border:1.5px solid #1f3658;border-radius:12px;font-size:15px;font-weight:700;text-align:left;padding:6px 12px;}'
            'QPushButton#bolum:checked{border-color:#38bdf8;background:#14365a;}'
            'QPushButton#ic{color:#e8f1fc;background:#0f1d33;border:1.2px solid #1f3658;border-radius:10px;font-size:14px;text-align:left;padding:6px 8px;}'
