        b = QToolButton(); b.setText(kisa or ad); b.setToolTip(ad); b.setAccessibleName(ad); b.setFocusPolicy(Qt.NoFocus)
        b.setText(ad if kisa is None else kisa); b.setToolButtonStyle(Qt.ToolButtonTextUnderIcon); b.setIcon(QIcon(ATLAS_PNG) if ikon == 'Atlas' else tool_icon(ikon)); b.setIconSize(QSize(boy_, boy_))
        b.setFixedHeight(h); b.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        if w: b.setFixedWidth(w)
        b.setCheckable(secilir); b.clicked.connect(lambda checked=False, f=fn: f()); return b   # K-384: clicked'in 'checked' değeri komuta gitmesin (open_anket(False) hatası)
