class AtlasYuzen(QWidget):
    """K-366: tahtanın köşesinde yüzen Atlas (panelde düğme yerine). Dokun: Atlas açılır. Basılı tut ve sürükle: taşınır (yeri saklanır).
    Sınavda, Atlas paneli / klavye / sınav ekranı açıkken ve grafik sekmesinde (orada kendi Atlas'ı var) görünmez.
    Kalemle yazılırken solar ve dokunuşu tahtaya bırakır; "Atlas'a sor" yazısı açılışta birkaç saniye görünür."""
    BOY = 116
    def __init__(self, main):
        super().__init__(main.scroll); self.main = main; self.setFixedSize(self.BOY, self.BOY); self.setAttribute(Qt.WA_TranslucentBackground)
        self.maskot = AtlasMaskot(self); self.maskot.setGeometry(8, 6, self.BOY - 16, self.BOY - 12); self.maskot.setAttribute(Qt.WA_TransparentForMouseEvents)
        self.etiket = QLabel("Atlas'a sor", main.scroll); self.etiket.setAttribute(Qt.WA_TransparentForMouseEvents)
        self.etiket.setStyleSheet('QLabel{background:rgba(8,20,40,235);color:#7ff6ff;border:2px solid #22e8ff;border-radius:16px;padding:6px 16px;font-size:20px;font-weight:800;}')
        self.etiket.adjustSize(); self.etiket.hide()
        self.yer = None   # (sağdan, alttan) uzaklık
        try:
            with open(os.path.join(main.data_dir, 'atlas-maskot.json'), encoding='utf-8') as f: y_ = json.load(f); self.yer = (int(y_['sag']), int(y_['alt']))
        except Exception: pass
        self.bas = None; self.surukle = False; self.solgun = False; self._son_aktif = 0.0
        self.uzun = QTimer(self); self.uzun.setSingleShot(True); self.uzun.setInterval(450); self.uzun.timeout.connect(self._suruklemeye_gec)
        self.yokla = QTimer(self); self.yokla.setInterval(250); self.yokla.timeout.connect(self.durum); self.yokla.start()
        self.etiket_t = QTimer(self); self.etiket_t.setSingleShot(True); self.etiket_t.timeout.connect(self.etiket.hide)
        self._ilk = True; self.hide()
    def gorunmeli(self):
        m = self.main
        if getattr(m, '_sinav_su_an', False): return False
        for ad in ('atlas_panel', 'genis_klavye', 'exam_screen', 'welcome', 'intro'):
            w_ = getattr(m, ad, None)
            if w_ is not None and w_.isVisible() and not (ad == 'intro' and getattr(w_, 'done', True)): return False
        try:
            if ((m.doc.metadata or {}).get('keywords') or '') == 'UMAL-graph': return False
        except Exception: pass
        return getattr(m, 'tool', '') != 'atlas'
    def durum(self):
        g = self.gorunmeli()
        if g != self.isVisible():
            self.setVisible(g)
            if g:
                self.yerlestir(); self.raise_()
                if self._ilk: self._ilk = False; self.etiket_goster()
            else: self.etiket.hide(); self.balon_kapat()
        if not g: return
        aktif = getattr(self.main.board, 'active', None) is not None
        if aktif: self._son_aktif = time.monotonic()
        sol = aktif or time.monotonic() - self._son_aktif < 1.2   # kalemle yazılırken solar, dokunuş tahtaya geçer
        if sol != self.solgun:
            self.solgun = sol; self.setAttribute(Qt.WA_TransparentForMouseEvents, sol)
            fx = self.graphicsEffect()
            if fx is None:
                from PyQt5.QtWidgets import QGraphicsOpacityEffect
                fx = QGraphicsOpacityEffect(self); self.setGraphicsEffect(fx)
            fx.setOpacity(0.25 if sol else 1.0)
            if sol: self.etiket.hide()
    def etiket_goster(self, sn=5000):
        if not self.isVisible(): return
        self.yerlestir(); self.etiket.show(); self.etiket.raise_(); self.etiket_t.start(sn)
    def yerlestir(self):
        vp = self.main.scroll.viewport().geometry(); sag, alt = self.yer or (28, 150)
        x = max(vp.x() + 4, min(vp.right() - self.width() - 4, vp.right() - self.width() - sag))
        y = max(vp.y() + 4, min(vp.bottom() - self.height() - 4, vp.bottom() - self.height() - alt))
        self.move(x, y); self.raise_()
        self.etiket.adjustSize(); ex = x - self.etiket.width() - 10
        if ex < vp.x() + 4: ex = x + self.width() + 10
        self.etiket.move(ex, y + (self.height() - self.etiket.height())//2)
        if self.etiket.isVisible(): self.etiket.raise_()
    def paintEvent(self, e):
        from PyQt5.QtGui import QRadialGradient
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); r = QRectF(4, 4, self.width() - 8, self.height() - 8)
        for kal, op in ((10, 0.10), (5, 0.18)):
            c = QColor('#22e8ff'); c.setAlphaF(op); p.setPen(QPen(c, kal)); p.setBrush(Qt.NoBrush); p.drawEllipse(r)
        g = QRadialGradient(r.center(), r.width()/2); g.setColorAt(0, QColor('#173a66')); g.setColorAt(1, QColor('#0a1a30'))
        p.setBrush(g); p.setPen(QPen(QColor('#22e8ff'), 2.5)); p.drawEllipse(r); p.end()
    def mousePressEvent(self, e):
        self.bas = (e.globalPos(), self.pos()); self.surukle = False; self.uzun.start(); self.maskot.ifade('dinleme')
    def _suruklemeye_gec(self):
        self.surukle = True; self.maskot.ifade('sasirma')
    def mouseMoveEvent(self, e):
        if self.bas is None: return
        d = e.globalPos() - self.bas[0]
        if not self.surukle and (abs(d.x()) > 24 or abs(d.y()) > 24): self.uzun.stop(); self.surukle = True
        if self.surukle:
            self.move(self.bas[1] + d); self.etiket.hide()
    def mouseReleaseEvent(self, e):
        self.uzun.stop(); bas = self.bas; self.bas = None; self.maskot.ifade('bekleme')
        if bas is None: return
        if self.surukle:
            vp = self.main.scroll.viewport().geometry()
            self.yer = (max(0, vp.right() - self.x() - self.width()), max(0, vp.bottom() - self.y() - self.height())); self.yerlestir()
            try:
                with open(os.path.join(self.main.data_dir, 'atlas-maskot.json'), 'w', encoding='utf-8') as f: json.dump({'sag': self.yer[0], 'alt': self.yer[1]}, f)
            except Exception: pass
            self.surukle = False; return
        self.etiket.hide(); self.dokundu()
    # ---- K-367: dokununca ekrandaki yazılara bakar, öneri balonu (kendiliğinden hiçbir şey yapmaz) ----
    def dokundu(self):
        m = self.main
        if getattr(m, '_sinav_su_an', False): m.show_toast("Sınav saatinde Atlas'a sor kapalı."); return
        bal = getattr(self, 'balon', None)
        if bal is not None and bal.isVisible(): self.balon_kapat(); return
        if getattr(self, 'bekleyen', None): return
        r = self.gorunen_yazi(); b = m.board; k = b.scale or 1
        try: bos_tahta = ((m.doc.metadata or {}).get('keywords') or '').startswith('UMAL-board')
        except Exception: bos_tahta = False
        if r is None and bos_tahta: m.atlas_dugme(); return   # boş tahtada yazı yok: Atlas paneli
        # K-368: ekranda görünen her şey (PDF'teki sorular + öğretmenin yazdıkları) Atlas'a gider
        q = b.visibleRegion().boundingRect().adjusted(4, 4, -4, -4) & b.rect()
        if q.width() < 16 or q.height() < 16: m.atlas_dugme(); return
        b._temiz_cek = True
        try: self.pix = b.grab(q)
        finally: b._temiz_cek = False
        self.cerceve_goster(q); self.istek_gonder()
    def gorunen_yazi(self):
        """Ekranda görünen bütün kalem yazılarının kapsadığı alan (sayfa birimi); yazı yoksa None."""
        m = self.main; b = m.board; k = b.scale or 1; v = b.visibleRegion().boundingRect()
        vr = QRectF(v.x()/k, v.y()/k, v.width()/k, v.height()/k); kap = None
        for s_ in m.marks.get(m.page, []):
            if s_.get('tool') in ('whiteout', 'eraser', 'geo', 'compass'): continue
            p_ = s_.get('points') or []
            if not p_: continue
            xs = [q[0] for q in p_]; ys = [q[1] for q in p_]; rr = QRectF(min(xs), min(ys), max(1, max(xs) - min(xs)), max(1, max(ys) - min(ys)))
            if not rr.intersects(vr): continue
            rr = rr.intersected(vr); kap = rr if kap is None else kap.united(rr)
        return kap
    def cerceve_goster(self, q):
        m = self.main; c = getattr(self, 'cerceve', None)
        if c is None:
            c = self.cerceve = QFrame(m.scroll); c.setAttribute(Qt.WA_TransparentForMouseEvents)
            c.setStyleSheet('QFrame{border:3px dashed #22e8ff;border-radius:14px;background:rgba(34,232,255,18);}')
        tl = m.board.mapTo(m.scroll, q.topLeft()); c.setGeometry(tl.x(), tl.y(), q.width(), q.height()); c.show(); c.raise_(); self.raise_()
    def istek_gonder(self):
        m = self.main; klasor = os.path.join(m.data_dir, 'atlas'); os.makedirs(klasor, exist_ok=True)
        kimlik = uuid.uuid4().hex[:10]; giris = os.path.join(klasor, 'istek-%s.json' % kimlik); cikis = os.path.join(klasor, 'cevap-%s.json' % kimlik)
        try: d_ = lesson_now(m.board_info().get('sinif'), m.exam_clock()); ders = (d_.get('ders') or '') if d_.get('durum') == 'ders' else ''
        except Exception: ders = ''
        istek = ("Ekteki görüntü, öğretmen sana dokunduğunda tahtanın ekranda görünen bölümü: basılı sorular / kitap sayfası ve öğretmenin el yazısıyla yazdıkları olabilir. "
                 "İlk satırda ekranda ne olduğunu tek kısa cümleyle söyle (ör. 'Ekranda diziler konusundan 3., 4. ve 5. sorular var.' ya da 'Tahtaya $y = 2x - 3$ yazdınız.'; formüller $...$ içinde). "
                 "İkinci satıra 'SEÇENEK: ' yazıp öğretmene yapabileceğin en uygun 3 ya da 4 işi ' | ' ile ayırarak yaz; her biri en çok 4 sözcük ve emir kipinde olsun. "
                 "Ekranda numaralı sorular varsa seçeneklerde onları numarasıyla an (ör. 3. soruyu çöz | 4. soruyu çöz | 5. soruyu çöz). "
                 "Fonksiyon varsa: Grafiğini çiz | Kesişimini bul; öğretmen bir çözüm yazmışsa: Çözümü kontrol et | Sonraki adımı göster. "
                 "Başka hiçbir şey yazma; şimdi çözme.")
        veri = dict(sinif=m.board_info().get('sinif') or '-', brans=ders_bransi(ders), istek=istek, formul=True)
        try:
            from PyQt5.QtCore import QBuffer, QByteArray, QIODevice
            im = self.pix
            if max(im.width(), im.height()) > 1024: im = im.scaled(1024, 1024, Qt.KeepAspectRatio, Qt.SmoothTransformation)
            ba = QByteArray(); bu = QBuffer(ba); bu.open(QIODevice.WriteOnly); im.save(bu, 'JPG', 82); bu.close(); veri['resim'] = bytes(ba.toBase64()).decode('ascii')
            with open(giris, 'w', encoding='utf-8') as f: json.dump(veri, f, ensure_ascii=False)
        except Exception as e:
            print('atlas yüzen:', e); self.cerceve and self.cerceve.hide(); return
        self.bekleyen = (cikis, time.monotonic()); m.run_havuz('--atlas-sor', giris, cikis); self.maskot.ifade('dusunme')
        self.balon_goster('Bakıyorum…', [])
        t = getattr(self, 'bek', None)
        if t is None: t = self.bek = QTimer(self); t.setInterval(400); t.timeout.connect(self.bekle)
        t.start()
    def bekle(self):
        if not getattr(self, 'bekleyen', None): self.bek.stop(); return
        cikis, t0 = self.bekleyen
        if os.path.exists(cikis):
            try:
                with open(cikis, encoding='utf-8') as f: d = json.load(f)
            except (OSError, ValueError): return
            self.bek.stop(); self.bekleyen = None
            for yol in (cikis, cikis.replace('cevap-', 'istek-')):
                try: os.remove(yol)
                except OSError: pass
            if not d.get('cevap'): self.balon_goster(d.get('hata') or 'Atlas şu an bakamadı.', ['Başka bir şey sor…']); self.maskot.ifade('sasirma'); return
            ozet, sec = [], []
            for satir in yabanci_yazi_temizle(d['cevap']).split('\n'):
                t_ = satir.strip().strip('*').strip()
                if t_.upper().startswith(('SEÇENEK', 'SECENEK')): sec = [x.strip(' .') for x in t_.split(':', 1)[-1].split('|') if x.strip(' .')]
                elif t_: ozet.append(t_)
            self.grafik = [f for f in (d.get('grafik') or [])[:2] if isinstance(f, str) and graph_compile(f)[0]]
            import re as _re
            oz = latex_duz(' '.join(ozet)); c_ = _re.search(r'^(.{20,170}?[.!?])(\s|$)', oz)   # yapay zekâ çözmeye başlarsa yalnız ilk cümle
            oz = c_.group(1) if c_ else (oz[:170] + '…' if len(oz) > 170 else oz)
            sec = [latex_duz(x) for x in sec if 2 <= len(x) <= 34 and len(x.split()) <= 5][:4]
            if not sec: sec = ['Soruyu çöz', 'Adım adım anlat', 'Çözümü kontrol et'] + (['Grafiğini çiz'] if self.grafik else [])
            self.balon_goster(oz or 'Ne yapayım?', sec + ['Başka bir şey sor…']); self.maskot.ifade('konusma')
            QTimer.singleShot(2500, lambda: self.maskot.ifade('bekleme'))
            return
        if time.monotonic() - t0 > 80:
            self.bek.stop(); self.bekleyen = None; self.balon_goster('Cevap gelmedi. İnterneti kontrol edip yeniden dokunun.', []); self.maskot.ifade('sasirma')
    def balon_goster(self, metin, secenekler):
        m = self.main; bal = getattr(self, 'balon', None); self.etiket.hide()
        if bal is None:
            bal = self.balon = QFrame(m.scroll); bal.setObjectName('atlasBalon')
            bal.setStyleSheet('#atlasBalon{background:rgba(11,26,48,245);border:2px solid #22e8ff;border-radius:18px;} QLabel{color:#eef6ff;font-size:20px;}'
                              'QPushButton{color:#7ff6ff;background:#0a1628;border:1.5px solid #22e8ff;border-radius:14px;padding:8px 14px;font-size:18px;font-weight:700;}'
                              'QPushButton#ilk{background:#22e8ff;color:#04202a;} QPushButton#kapa{border-color:#2a4468;color:#9fb3cc;padding:6px 12px;}')
            v = QVBoxLayout(bal); v.setContentsMargins(16, 12, 16, 14); v.setSpacing(10)
            ust = QHBoxLayout(); bal.yazi = QLabel(); bal.yazi.setWordWrap(True); ust.addWidget(bal.yazi, 1)
            kp = QPushButton('✕'); kp.setObjectName('kapa'); kp.setFocusPolicy(Qt.NoFocus); kp.clicked.connect(self.balon_kapat); ust.addWidget(kp, 0, Qt.AlignTop); v.addLayout(ust)
            bal.izgara = QGridLayout(); bal.izgara.setSpacing(8); v.addLayout(bal.izgara); bal.dug = []
            bal.zaman = QTimer(bal); bal.zaman.setSingleShot(True); bal.zaman.timeout.connect(self.balon_kapat)
        for b_ in bal.dug: bal.izgara.removeWidget(b_); b_.hide(); b_.setParent(None); b_.deleteLater()
        bal.dug = []
        bal.yazi.setText('<b style="color:#7ff6ff">Atlas:</b> ' + metin.replace('&', '&amp;').replace('<', '&lt;'))
        for i, t_ in enumerate(secenekler):
            b_ = QPushButton(t_); b_.setFocusPolicy(Qt.NoFocus)
            if i == 0 and t_ != 'Başka bir şey sor…': b_.setObjectName('ilk')
            b_.setMinimumHeight(48); b_.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            b_.clicked.connect(lambda c=False, t__=t_: self.secildi(t__)); bal.izgara.addWidget(b_, i//2, i % 2); bal.dug.append(b_)
        vp = m.scroll.viewport().geometry(); W_ = min(640, vp.width() - 40); bal.setFixedWidth(W_)
        sat_ = (len(secenekler) + 1)//2; yh = max(30, bal.yazi.heightForWidth(W_ - 32 - 70) + 14); bal.setFixedHeight(12 + max(yh, 40) + (10 + sat_*48 + (sat_ - 1)*8 if sat_ else 0) + 14)
        x = max(vp.x() + 8, self.x() - bal.width() - 14); y = max(vp.y() + 8, min(self.y() + self.height() - bal.height(), vp.bottom() - bal.height() - 8))
        bal.move(x, y); bal.show(); bal.raise_(); self.raise_()
        if secenekler: bal.zaman.start(30000)   # dokunulmazsa kendiliğinden kapanır
    def balon_kapat(self):
        for ad in ('balon', 'cerceve'):
            w_ = getattr(self, ad, None)
            if w_ is not None: w_.hide()
    def secildi(self, t):
        m = self.main; pix = getattr(self, 'pix', None); self.balon_kapat()
        if t != 'Başka bir şey sor…' and 'rafi' in t and self.grafik:   # grafik: Atlas'ın okuduğu fonksiyonlar Grafik çizicide (soru harcamaz)
            if getattr(m, 'atlas_panel', None) is None: m.atlas_panel = AtlasPanel(m)
            m.atlas_panel.grafik = list(self.grafik); m.atlas_panel.grafik_ciz(); return
        m.atlas_sor_ac(pix); pn = m.atlas_panel
        if t != 'Başka bir şey sor…': QTimer.singleShot(0, lambda: pn.sor(t))

def latex_duz(t):
    """Balon için LaTeX'i okunur düz yazıya çevirir ($x^{2}$ → x², \\frac{a}{b} → a/b)."""
    import re
    t = t.replace('$', '')
    def _sapka(m_):   # \widehat{DCB} → DĈB (şapka ortadaki harfte), \hat{x} → x̂
        a = m_.group(2); i = len(a)//2 if len(a) == 3 else len(a) - 1
        return a[:i+1] + '\u0302' + a[i+1:] if a else ''
    t = re.sub(r'\\(widehat|hat)\s*\{([^{}]*)\}', _sapka, t)
    t = re.sub(r'\\(overline|bar)\s*\{([^{}]*)\}', lambda m_: ''.join(ch + '\u0305' for ch in m_.group(2)), t)
    for _ in range(3): t = re.sub(r'\\frac\{([^{}]*)\}\{([^{}]*)\}', r'(\1)/(\2)', t)
    ALT = str.maketrans('0123456789+-=()aehijklmnoprstuvx', '₀₁₂₃₄₅₆₇₈₉₊₋₌₍₎ₐₑₕᵢⱼₖₗₘₙₒₚᵣₛₜᵤᵥₓ'); UST = str.maketrans('0123456789+-=()n', '⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻⁼⁽⁾ⁿ')
    t = re.sub(r'_\{([^{}]*)\}', lambda m_: m_.group(1).replace(' ', '').translate(ALT), t)   # a_{n+1} → aₙ₊₁
    t = re.sub(r'_([0-9]+|[A-Za-z])', lambda m_: m_.group(1).translate(ALT), t)                     # a_n → aₙ
    t = re.sub(r'\^\{([^{}]*)\}', lambda m_: m_.group(1).replace(' ', '').translate(UST), t)
    t = re.sub(r'\^([0-9n])', lambda m_: m_.group(1).translate(UST), t)
    for a_, b_ in (('\\cdot', '·'), ('\\times', '×'), ('\\sqrt', '√'), ('\\pi', 'π'), ('\\le', '≤'), ('\\ge', '≥'), ('\\neq', '≠'), ('\\left', ''), ('\\right', ''), ('\\,', ' '), ('\\', '')):
        t = t.replace(a_, b_)
    t = re.sub(r'\(([A-Za-z0-9]+)\)/\(([A-Za-z0-9]+)\)', r'\1/\2', t)
    return atlas_guzel(t.replace('{', '').replace('}', ''))

class AtlasMaskot(QWidget):
    """Maskot: gövde tek resim (yeniden çizilmez); yalnız gözler QPainter ile canlanır.
    İfadeler: bekleme, dinleme, dusunme, konusma, mutluluk, sasirma (+ kendiliğinden göz kırpma)."""
    IFADE = {'bekleme': (15, 20, 0, 0, 0), 'dinleme': (17.5, 23.5, 0, 1, 0), 'dusunme': (13, 17, 12, -11, 0),
             'konusma': (15, 19, 0, 0, 0), 'mutluluk': (15, 20, 0, -2, 1), 'sasirma': (19, 19, 0, -3, 0)}
    def __init__(self, parent=None):
        super().__init__(parent); self.setAttribute(Qt.WA_TranslucentBackground)
        self.govde = QPixmap(ATLAS_PNG); self._olcekli = None
        self.ad = 'bekleme'; self.su = list(self.IFADE['bekleme']); self.t0 = time.monotonic()
        self.kirp_t = -9; self.sonraki = 3.0
        self.zaman = QTimer(self); self.zaman.setInterval(40); self.zaman.timeout.connect(self.tik)
    def ifade(self, ad):
        if ad in self.IFADE: self.ad = ad
    def showEvent(self, e): self.zaman.start(); super().showEvent(e)
    def hideEvent(self, e): self.zaman.stop(); super().hideEvent(e)
    def tik(self):
        h = self.IFADE[self.ad]; self.su = [a + (b - a)*0.18 for a, b in zip(self.su, h)]; self.update()
    def paintEvent(self, e):
        if self.govde.isNull(): return
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.SmoothPixmapTransform)
        t = time.monotonic() - self.t0
        k = min(self.width()/768, self.height()/780)
        w, h = int(768*k), int(780*k)
        if self._olcekli is None or self._olcekli.width() != w: self._olcekli = self.govde.scaled(w, h, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        ox = (self.width() - w)/2; oy = (self.height() - h)/2 + math.sin(t*1.6)*3*k*4
        p.drawPixmap(int(ox), int(oy), self._olcekli)
        rx, ry, dx, dy, yay = self.su
        kap = 1.0
        if self.ad in ('bekleme', 'dinleme', 'konusma'):
            if t > self.sonraki: self.kirp_t = t; self.sonraki = t + 3 + (hash(int(t)) % 300)/100
            g = t - self.kirp_t
            if g < 0.16: kap = max(0.08, abs(1 - g/0.08))
        if self.ad == 'konusma': ry *= 1 + 0.1*math.sin(t*9); dx += math.sin(t*1.4)*1.5
        if self.ad == 'dusunme': dx += math.sin(t*1.1)*3
        renk = QColor('#7ff0ff')
        for cx, cy in ATLAS_GOZ:
            x = ox + (cx + dx*2)*k; y = oy + (cy + dy*2)*k
            if yay < 0.5:
                for kal, op in ((10, 0.18), (5, 0.3), (0, 1.0)):
                    c = QColor(renk); c.setAlphaF(op); p.setPen(Qt.NoPen); p.setBrush(c)
                    p.drawEllipse(QPointF(x, y), (rx*2 + kal)*k, max(1.5, (ry*2*kap + kal))*k)
            else:
                yol = QPolygonF([QPointF(x + (-40 + 80*i/16)*k, y + (12 - 28*(1 - ((i - 8)/8)**2))*k) for i in range(17)])
                for kal, op in ((14, 0.18), (0, 1.0)):
                    c = QColor(renk); c.setAlphaF(op); p.setPen(QPen(c, (24 + kal)*k, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)); p.setBrush(Qt.NoBrush)
                    p.drawPolyline(yol)
        p.end()

# K-348: Atlas cevabındaki düz yazı matematiği tahtada okunur yapılır (x^2 → x², -> → ⇒, 2*a → 2·a, a - b → a − b).
_UST = str.maketrans('0123456789-+()n', '⁰¹²³⁴⁵⁶⁷⁸⁹⁻⁺⁽⁾ⁿ')
def atlas_guzel(t):
    import re
    t = re.sub(r'\^\((-?\d+|n)\)', lambda m: m.group(1).translate(_UST), t)
    t = re.sub(r'\^(-?\d+|n)', lambda m: m.group(1).translate(_UST), t)
    t = t.replace('->', '⇒').replace('=>', '⇒').replace('>=', '≥').replace('<=', '≤').replace('!=', '≠')
    t = t.replace('sqrt(', '√(')
    t = re.sub(r'(?<=[\w)²³¹⁰-⁹])\s*\*\s*(?=[\w(√])', '·', t)
    t = re.sub(r'(?<=[\w)²³⁰-⁹]) - (?=[\w(√])', ' − ', t)
    t = re.sub(r'(?<=[=(,\s])-(?=[\d(√]|[a-z](?![a-zçğıöşü]))', '−', t)
    t = re.sub(r'(?<=[a-z0-9)])-(?=\d)', '−', t)
    return t

# K-349: Atlas cevaplarını matematik kitabı gibi dizer: $...$ içindeki LaTeX (kesir üst üste, üs yukarıda, kök işareti),
# düz yazı el yazısıyla, satırlar kelime kelime kırılır. Çizim arka uçtan bağımsız: olc(metin, boy) → genişlik;
# sonuç [('t', x, y_taban, metin, boy), ('l', x1, y1, x2, y2, kalınlık)] listesi. Atlas'ta QPainter çizer.
FORMUL_KOMUT = {'int': '∫', 'iint': '∬', 'oint': '∮', 'sum': '∑', 'prod': '∏', 'partial': '∂', 'nabla': '∇', 'forall': '∀', 'exists': '∃',
    'big': '', 'Big': '', 'bigg': '', 'Bigg': '', 'bigl': '', 'bigr': '', 'Bigl': '', 'Bigr': '', 'overline': '', 'bar': '', 'hat': '', 'vec': '', 'cdot': '·', 'times': '×', 'div': '÷', 'pm': '±', 'mp': '∓', 'le': '≤', 'leq': '≤', 'ge': '≥', 'geq': '≥', 'neq': '≠', 'ne': '≠',
    'Rightarrow': '⇒', 'implies': '⇒', 'rightarrow': '→', 'to': '→', 'Leftrightarrow': '⇔', 'iff': '⇔', 'approx': '≈', 'infty': '∞', 'pi': 'π',
    'alpha': 'α', 'beta': 'β', 'gamma': 'γ', 'delta': 'δ', 'Delta': 'Δ', 'theta': 'θ', 'lambda': 'λ', 'mu': 'μ', 'sigma': 'σ', 'Sigma': 'Σ',
    'omega': 'ω', 'Omega': 'Ω', 'phi': 'φ', 'varphi': 'φ', 'epsilon': 'ε', 'varepsilon': 'ε', 'rho': 'ρ', 'tau': 'τ', 'circ': '°', 'degree': '°',
    'in': '∈', 'notin': '∉', 'cup': '∪', 'cap': '∩', 'subset': '⊂', 'emptyset': '∅', 'varnothing': '∅', 'mathbb': '', 'angle': '∠', 'perp': '⊥',
    'parallel': '∥', 'cdots': '⋯', 'ldots': '…', 'dots': '…', '%': '%', '{': '{', '}': '}', ',': ' ', ';': ' ', ':': ' ', '!': '', ' ': ' ',
    'quad': '  ', 'qquad': '    ', 'left': '', 'right': '', 'displaystyle': '', 'limits': '', 'sin': 'sin ', 'cos': 'cos ', 'tan': 'tan ', 'cot': 'cot ',
    'log': 'log', 'ln': 'ln ', 'lim': 'lim', 'max': 'max', 'min': 'min', 'R': 'ℝ', 'N': 'ℕ', 'Z': 'ℤ', 'Q': 'ℚ', 'mid': '|', 'vert': '|', '|': '‖'}
_BAGLAC = set('=<>≤≥≠⇒→⇔≈∈∉⊂')   # iki yanına boşluk
_ISLEM = set('+−±∓×÷·∪∩')

def formul_coz(s):
    """LaTeX alt kümesini ağaca çevirir: ('m', metin) | ('kesir', a, b) | ('kok', a) | ('us', taban, us) | ('alt', taban, alt) | ('g', [..])."""
    i = 0; n = len(s)
    def grup():
        nonlocal i
        oge = []
        while i < n:
            c = s[i]
            if c == '}': i += 1; return oge
            if c == '{': i += 1; oge.append(('g', grup())); continue
            if c in '^_':
                i += 1; arg = tek()
                taban = oge.pop() if oge else ('m', '')
                if taban[0] == 'm' and len(taban[1]) > 1 and c == '^':   # "x2^3" gibi: üs yalnız son karaktere
                    oge.append(('m', taban[1][:-1])); taban = ('m', taban[1][-1])
                oge.append(('us' if c == '^' else 'alt', taban, arg)); continue
            if c == '\\':
                i += 1; j = i
                if i < n and not s[i].isalpha(): i += 1
                else:
                    while i < n and s[i].isalpha(): i += 1
                k = s[j:i]
                if k in ('frac', 'dfrac', 'tfrac'): a = tek(); b = tek(); oge.append(('kesir', a, b)); continue
                if k == 'sqrt':
                    if i < n and s[i] == '[':   # \sqrt[3]{x}
                        e = s.find(']', i); kok_derece = s[i+1:e] if e > 0 else ''; i = e + 1 if e > 0 else i
                    else: kok_derece = ''
                    oge.append(('kok', tek(), kok_derece)); continue
                if k in ('text', 'mathrm', 'textbf', 'mathbf', 'operatorname', 'mbox'): oge.append(('yazi', metin_al())); continue
                if k in ('hat', 'widehat'): oge.append(('sapka', tek())); continue          # m(DĈB): açı şapkası
                if k in ('overline', 'bar'): oge.append(('ustcizgi', tek())); continue
                if k in ('vec', 'overrightarrow'): oge.append(('vektor', tek())); continue
                if k == 'mathbb': a = metin_al(); oge.append(('m', ''.join(FORMUL_KOMUT.get(ch, ch) for ch in a))); continue
                oge.append(('m', FORMUL_KOMUT.get(k, k))); continue
            if c == ' ': i += 1; continue
            j = i
            while i < n and s[i] not in '{}^_\\ ': i += 1
            oge.append(('m', s[j:i].replace('-', '−').replace('*', '·')))
        return oge
    def tek():
        nonlocal i
        while i < n and s[i] == ' ': i += 1
        if i >= n: return ('m', '')
        if s[i] == '{': i += 1; return ('g', grup())
        if s[i] == '\\':
            j = i; i += 1
            while i < n and s[i].isalpha(): i += 1
            k = s[j+1:i]; return ('m', FORMUL_KOMUT.get(k, k))
        i += 1; return ('m', s[i-1].replace('-', '−'))
    def metin_al():
        nonlocal i
        while i < n and s[i] == ' ': i += 1
        if i < n and s[i] == '{':
            d = 1; j = i + 1; i += 1
            while i < n and d:
                d += {'{': 1, '}': -1}.get(s[i], 0); i += 1
            return s[j:i-1]
        return tek()[1]
    return ('g', grup())

class _Kutu:
    __slots__ = ('w', 'a', 'd', 'op')
    def __init__(self, w=0.0, a=0.0, d=0.0, op=None): self.w, self.a, self.d, self.op = w, a, d, op or []
    def ekle(self, k, x, y):
        for o in k.op:
            if o[0] == 't': self.op.append(('t', o[1] + x, o[2] + y, o[3], o[4]))
            else: self.op.append(('l', o[1] + x, o[2] + y, o[3] + x, o[4] + y, o[5]))

def formul_diz(agac, boy, olc):
    """Ağacı kutuya dizer (taban çizgisi y=0, yukarısı eksi)."""
    son = ['']   # son yazılan işaret: tekli eksi / artı (= −b, (−4)) boşluksuz yazılır
    def metin(t, s):
        k = _Kutu(); x = 0.0
        for ch_grup in _parcala(t):
            pay = 0.0
            if ch_grup in _BAGLAC: pay = 0.28*s
            elif ch_grup in _ISLEM and not (ch_grup in '−+±' and (son[0] == '' or son[0] in _BAGLAC or son[0] in '(,[')): pay = 0.18*s
            x += pay
            if ch_grup.strip(): k.op.append(('t', x, 0.0, ch_grup, s)); son[0] = ch_grup.strip()[-1]
            x += olc(ch_grup, s) + pay
            if ch_grup.endswith((',', ';')): x += 0.22*s   # (0, 3)
        k.w = x; k.a = 0.74*s; k.d = 0.24*s; return k
    def us_kur(t, ust, s, tur):
        es = max(13.0, s*0.64); sk = son[0]; son[0] = ''; u = diz(ust, es); son[0] = sk; k = _Kutu(); k.ekle(t, 0, 0)
        if tur == 'us':
            yuk = max(0.42*s, t.a - 0.45*es) if t.a > 0.8*s else 0.42*s   # kesir / büyük parantez üstünde daha yukarı
            k.ekle(u, t.w + 0.04*s, -yuk); k.a = max(t.a, yuk + u.a); k.d = t.d
        else:
            k.ekle(u, t.w + 0.02*s, 0.22*s); k.a = t.a; k.d = max(t.d, 0.22*s + u.d)
        k.w = t.w + 0.06*s + u.w; return k
    def parantez_kutu(ch, A, D, s):
        ps = (A + D)*1.02; orta = (D - A)/2; y = orta + 0.26*ps   # yazı ortası taban çizgisinin ~0.26 boy üstünde
        k = _Kutu(olc(ch, ps), A + 0.04*s, D + 0.04*s); k.op.append(('t', 0.0, y, ch, ps)); return k
    def buyuk_kur(op, alt_, ust_, s):
        # K-361: ∫ ∑ ∏ büyük; ∫ sınırları sağ üst / sağ alt, ∑ ∏ lim sınırları üstte / altta (matematik kitabı gibi)
        es = max(13.0, s*0.64); sk = son[0]; son[0] = ''
        u = diz(ust_, es) if ust_ is not None else None; a_ = diz(alt_, es) if alt_ is not None else None; son[0] = 'x'
        if op == 'lim':
            ps = s; y = 0.0; ow = olc(op, ps); top = -0.74*s; bot = 0.24*s
        else:
            ps = s*(1.9 if op in '∫∬∮' else 1.75); y = -0.30*s + 0.26*ps; ow = olc(op, ps); top = y - 0.74*ps; bot = y + 0.24*ps
        k = _Kutu()
        if op in '∫∬∮':
            k.op.append(('t', 0.0, y, op, ps)); w = ow
            if u is not None: k.ekle(u, ow + 0.02*s, top + u.a); w = max(w, ow + 0.02*s + u.w)
            if a_ is not None: k.ekle(a_, ow - 0.18*s, bot - a_.d); w = max(w, ow - 0.18*s + a_.w)
            k.a = -top; k.d = bot; k.w = w + 0.16*s; return k
        W = max(ow, u.w if u is not None else 0, a_.w if a_ is not None else 0)
        k.op.append(('t', (W - ow)/2, y, op, ps)); k.a = -top; k.d = bot
        if u is not None: yb = top - 0.10*s - u.d; k.ekle(u, (W - u.w)/2, yb); k.a = -yb + u.a
        if a_ is not None: yb = bot + 0.10*s + a_.a; k.ekle(a_, (W - a_.w)/2, yb); k.d = yb + a_.d
        k.w = W + 0.16*s; return k
    def buyuk_mu(d):
        if d[0] == 'm' and d[1] in ('∫', '∬', '∮', '∑', '∏', 'lim'): return [d[1], None, None]
        if d[0] in ('us', 'alt'):
            r = buyuk_mu(d[1]); i_ = 1 if d[0] == 'alt' else 2
            if r and r[i_] is None: r[i_] = d[2]; return r
        return None
    def diz(d, s):
        tur = d[0]
        if tur in ('m', 'us', 'alt'):
            r = buyuk_mu(d)
            if r: return buyuk_kur(r[0], r[1], r[2], s)
        if tur == 'm': return metin(d[1], s)
        if tur == 'yazi':
            k = _Kutu(olc(d[1], s), 0.74*s, 0.24*s); k.op.append(('t', 0.0, 0.0, d[1], s)); return k
        if tur == 'g':
            kutular = [diz(e, s) for e in d[1]]
            # kesir gibi uzun ifadeleri saran parantezler büyür (matematik kitabındaki gibi)
            ici = [c for e, c in zip(d[1], kutular) if not _parantez(e)]
            A = max([c.a for c in ici] or [0.74*s]); D = max([c.d for c in ici] or [0.24*s])
            if A + D > 1.3*s:
                for j, e in enumerate(d[1]):
                    if _parantez(e) == 'm': kutular[j] = parantez_kutu(e[1], A, D, s)
                    elif _parantez(e) == 'us': kutular[j] = us_kur(parantez_kutu(e[1][1], A, D, s), e[2], s, 'us')
            k = _Kutu(); x = 0.0
            for c in kutular: k.ekle(c, x, 0.0); x += c.w; k.a = max(k.a, c.a); k.d = max(k.d, c.d)
            k.w = x
            if not d[1]: k.a, k.d = 0.74*s, 0.24*s
            return k
        if tur in ('us', 'alt'):
            return us_kur(diz(d[1], s), d[2], s, tur)
        if tur == 'kesir':
            es = max(15.0, s*0.9)
            son[0] = ''; a = diz(d[1], es); son[0] = ''; b = diz(d[2], es); son[0] = 'x'; eks = -0.30*s; bos = 0.14*s; kal = max(1.6, s*0.06)
            gen = max(a.w, b.w) + 0.24*s; k = _Kutu(gen + 0.24*s)
            ya = eks - bos - a.d; yb = eks + bos + b.a
            k.ekle(a, 0.12*s + (gen - a.w)/2, ya); k.ekle(b, 0.12*s + (gen - b.w)/2, yb)
            k.op.append(('l', 0.12*s, eks, 0.12*s + gen, eks, kal))
            k.a = -ya + a.a; k.d = yb + b.d; return k
        if tur in ('sapka', 'ustcizgi', 'vektor'):   # yazının üstüne şapka / çizgi / ok
            g = diz(d[1], s); kal = max(1.4, s*0.055); k = _Kutu(); k.ekle(g, 0, 0); k.w = g.w; k.d = g.d
            y0 = -g.a - 0.06*s; x0, x1 = 0.06*s, g.w - 0.06*s
            if tur == 'sapka':
                yt = y0 - 0.22*s; k.op += [('l', x0, y0, g.w/2, yt, kal), ('l', g.w/2, yt, x1, y0, kal)]; k.a = -yt + kal
            else:
                yt = y0 - 0.08*s; k.op.append(('l', x0, yt, x1, yt, kal))
                if tur == 'vektor': k.op += [('l', x1 - 0.16*s, yt - 0.1*s, x1, yt, kal), ('l', x1 - 0.16*s, yt + 0.1*s, x1, yt, kal)]
                k.a = -yt + 0.12*s
            return k
        if tur == 'kok':
            son[0] = ''; g = diz(d[1], s); son[0] = 'x'; kal = max(1.6, s*0.06); ust = g.a + 0.14*s; alt = g.d
            sol = 0.62*s; k = _Kutu()
            if d[2]:
                dr = diz(('m', d[2]), max(12.0, s*0.5)); k.ekle(dr, 0.02*s, -0.42*s)
            pts = [(0.04*s, -0.30*s), (0.18*s, -0.38*s), (0.36*s, alt), (0.56*s, -ust), (sol + g.w + 0.08*s, -ust)]
            for (x1, y1), (x2, y2) in zip(pts, pts[1:]): k.op.append(('l', x1, y1, x2, y2, kal))
            k.ekle(g, sol, 0); k.w = sol + g.w + 0.14*s; k.a = ust + kal; k.d = max(g.d, alt + kal); return k
        return _Kutu()
    return diz(agac, boy)

def _parantez(e):
    if e[0] == 'm' and e[1] in ('(', ')', '[', ']', '|'): return 'm'
    if e[0] == 'us' and e[1][0] == 'm' and e[1][1] in (')', ']', '|'): return 'us'
    return ''

def _parcala(t):
    """Metni bağlaç / işlem işaretleri ve geri kalan parçalar olarak böler."""
    out = []; tam = ''
    for ch in t:
        if ch in _BAGLAC or ch in _ISLEM or ch in ',;':
            if tam: out.append(tam); tam = ''
            out.append(ch)
        else: tam += ch
    if tam: out.append(tam)
    return out

def cevap_diz(cevap, genislik, boy, olc, duzelt=lambda t: t, stil=None):
    """Bütün cevabı dizer: paragraflar, kelime kelime satır kırma, $...$ formülleri kutu olarak.
    stil (isteğe bağlı): baslik / madde / cevap renkleri, satir / paragraf aralık çarpanları.
    Döner: (yükseklik, op listesi) — ('t', x, y, metin, boy, renk|None), ('l', ...), ('k', x0, y0, x1, y1, renk) çerçeve."""
    import re
    st = dict(baslik=None, madde=None, cevap=None, satir=1.0, paragraf=1.0, par_ara=0.0); st.update(stil or {})
    op = []; y = 0.0; ara = boy*0.42*st['satir']
    bosluk = olc(' ', boy)
    for par in cevap.replace('**', '').replace('$$', '$').split('\n'):
        duz = par.strip()
        if not duz: y += boy*0.55*st['paragraf']; continue
        cevap_mi = bool(re.match(r'^(Cevap|Sonuç)\s*:', duz)) and st['cevap'] is not None
        baslik_mi = duz.endswith(':') and len(duz) < 80 and st['baslik'] is not None
        if op: y += boy*st['par_ara']   # dolu paragraflar arası (madde madde ferah)
        if baslik_mi and op: y += boy*0.35*st['paragraf']
        if cevap_mi: y += boy*0.3*st['paragraf']
        ic = boy*0.55 if cevap_mi else 0.0   # cevap kutusunun iç boşluğu
        gen = genislik - 2*ic
        ogeler = []   # (kutu, öncesinde boşluk var mı)
        if '\\' in par:   # $ dışında kalan \widehat{DCB}, \overline{AB}, \vec{u} → formül
            _pp = par.split('$')
            for _i in range(0, len(_pp), 2):
                _pp[_i] = re.sub(r'\\(widehat|hat|overline|bar|vec|overrightarrow)\s*\{([^{}]*)\}', lambda m_: '$\\' + m_.group(1) + '{' + m_.group(2) + '}$', _pp[_i])
            par = '$'.join(_pp)
        parca = par.split('$'); ilk_kelime = True
        for i, p in enumerate(parca):
            if i % 2 == 1 and i < len(parca) - 1:   # formül
                kt = formul_diz(formul_coz(p), boy, olc)
                if kt.w > gen:   # sığmazsa küçült
                    kt = formul_diz(formul_coz(p), max(14.0, boy*gen/kt.w*0.98), olc)
                ogeler.append((kt, True)); ilk_kelime = False
            else:
                if i % 2 == 1: p = '$' + p
                p = duzelt(p)
                ilk = True
                for kel in p.split(' '):
                    if not kel: ilk = False; continue
                    renk = None
                    if baslik_mi: renk = st['baslik']
                    elif ilk_kelime and kel in ('•', '-', '·') and st['madde']: renk = st['madde']; kel = '•'
                    elif ilk_kelime and re.match(r'^\d+[.)]$', kel) and st['baslik']: renk = st['baslik']
                    elif ilk_kelime and cevap_mi: renk = st['cevap']
                    k = _Kutu(olc(kel, boy), 0.74*boy, 0.24*boy); k.op.append(('t', 0.0, 0.0, kel, boy, renk))
                    ogeler.append((k, not ilk or p.startswith(' '))); ilk = False; ilk_kelime = False
        girinti = 0.0
        if duz[:1] in '•-·' or re.match(r'^\d+[.)]\s', duz): girinti = olc(duz.split(' ')[0] + ' ', boy)
        y0 = y; satir = []; x = 0.0
        def bitir(satir):
            nonlocal y
            if not satir: return
            a = max(k.a for _, k in satir); d = max(k.d for _, k in satir)
            yb = y + a
            for xx, k in satir:
                for o in k.op:
                    if o[0] == 't': op.append(('t', o[1] + xx + ic, o[2] + yb, o[3], o[4], o[5] if len(o) > 5 else None))
                    else: op.append(('l', o[1] + xx + ic, o[2] + yb, o[3] + xx + ic, o[4] + yb, o[5]))
            y = yb + d + ara*0.5
        if cevap_mi: y += ic*0.6
        for k, bsl in ogeler:
            once = bosluk if (satir and bsl) else 0.0
            if satir and x + once + k.w > gen:
                bitir(satir); satir = []; x = girinti; once = 0.0
            satir.append((x + once, k)); x += once + k.w
        bitir(satir)
        if cevap_mi:
            y += ic*0.4; op.append(('k', 0.0, y0, genislik, y, st['cevap'])); y += boy*0.3
    return y, op

# K-350: "Tahtaya yaz": Atlas'ın cevabı tek çizgili el yazısı fontuyla (Relief SingleLine, OFL) gerçek kalem çizgilerine çevrilir;
# tahtada silinir, taşınır, Geri al ile kalkar, PDF'e aynen geçer.
_TEK_CIZGI = {}
def tek_cizgi_font(yol):
    """SVG fonttan karakter → (ilerleme, [çoklu çizgi]) (font birimi, y yukarı)."""
    if _TEK_CIZGI.get('_yol') == yol: return _TEK_CIZGI
    import re, html
    _TEK_CIZGI.clear(); _TEK_CIZGI['_yol'] = yol
    try: s = open(yol, encoding='utf-8').read()
    except OSError: return _TEK_CIZGI
    v = re.search(r'<font\b[^>]*horiz-adv-x="([^"]*)"', s); varsayilan = float(v.group(1)) if v else 500.0
    for g in re.finditer(r'<glyph\b([^>]*)/?>', s):
        a = g.group(1); u = re.search(r'unicode="([^"]*)"', a); d = re.search(r'\sd="([^"]*)"', a); w = re.search(r'horiz-adv-x="([^"]*)"', a)
        if not u: continue
        ch = html.unescape(u.group(1))
        if len(ch) != 1: continue
        _TEK_CIZGI[ch] = (float(w.group(1)) if w else varsayilan, _yol_coz(d.group(1)) if d else [])
    # fontta olmayan: ⇒ (iki çizgi + ok başı)
    _TEK_CIZGI['⇒'] = (760.0, [[(90, 330), (560, 330)], [(90, 170), (560, 170)], [(470, 470), (670, 250), (470, 30)]])
    # K-361: fontta olmayan matematik işaretleri ve Yunan harfleri (elle çizgi; büyük harf 680, küçük 470 birim)
    def yay(cx, cy, rx, ry, a0=0, a1=360, n=28):
        return [(cx + rx*math.cos(math.radians(a0 + (a1 - a0)*i/n)), cy + ry*math.sin(math.radians(a0 + (a1 - a0)*i/n))) for i in range(n + 1)]
    E = {
        'α': (540, [[(470, 470), (380, 200), (300, 40), (200, 0), (90, 60), (60, 235), (110, 420), (220, 470), (330, 400), (400, 200), (470, 0)]]),
        'β': (480, [[(110, -200), (110, 560), (170, 680), (280, 700), (360, 640), (370, 520), (280, 420), (200, 410)], [(200, 410), (330, 380), (410, 280), (400, 110), (300, 10), (200, 0), (110, 60)]]),
        'γ': (460, [[(40, 470), (140, 470), (240, 200), (260, -50), (230, -200), (200, -50), (250, 200), (420, 470)]]),
        'θ': (500, [yay(250, 340, 190, 340), [(60, 340), (440, 340)]]),
        'λ': (500, [[(80, 680), (160, 680), (450, 0)], [(270, 400), (60, 0)]]),
        'μ': (540, [[(90, -200), (90, 470)], [(90, 150), (150, 30), (260, 0), (360, 60), (410, 200), (410, 470)], [(410, 200), (420, 40), (480, 0)]]),
        'σ': (520, [[(480, 470), (220, 470)], yay(220, 235, 170, 235, 90, 450)]),
        'φ': (520, [yay(260, 235, 190, 235), [(260, 700), (260, -220)]]),
        'ε': (470, [[(400, 430), (300, 470), (160, 450), (110, 360), (170, 260), (300, 240)], [(300, 240), (150, 220), (80, 120), (140, 20), (280, 0), (410, 50)]]),
        'ρ': (460, [[(100, -220), (100, 235)], yay(250, 235, 160, 235, 180, 540)]),
        'τ': (480, [[(40, 470), (460, 470)], [(250, 470), (250, 60), (300, 0), (380, 20)]]),
        'ω': (590, [[(120, 470), (60, 250), (110, 40), (200, 0), (270, 80), (290, 250)], [(290, 250), (310, 80), (380, 0), (470, 40), (520, 250), (460, 470)]]),
        'Ω': (640, [[(80, 0), (240, 0), (240, 90), (130, 230), (90, 400), (160, 600), (320, 690), (480, 600), (550, 400), (510, 230), (400, 90), (400, 0), (560, 0)]]),
        '∈': (600, [[(520, 560), (330, 560), (170, 500), (100, 340), (170, 180), (330, 120), (520, 120)], [(100, 340), (470, 340)]]),
        '∉': (600, [[(520, 560), (330, 560), (170, 500), (100, 340), (170, 180), (330, 120), (520, 120)], [(100, 340), (470, 340)], [(220, 0), (420, 680)]]),
        '⊂': (600, [[(520, 560), (330, 560), (170, 500), (100, 340), (170, 180), (330, 120), (520, 120)]]),
        '∪': (620, [[(100, 560), (100, 260), (170, 140), (310, 100), (450, 140), (520, 260), (520, 560)]]),
        '∅': (600, [yay(300, 340, 210, 290), [(120, 0), (480, 680)]]),
        '⇔': (780, [[(220, 330), (560, 330)], [(220, 170), (560, 170)], [(470, 470), (670, 250), (470, 30)], [(310, 470), (110, 250), (310, 30)]]),
        '∀': (600, [[(60, 680), (300, 0), (540, 680)], [(150, 420), (450, 420)]]),
        '∃': (580, [[(80, 680), (480, 680), (480, 0), (80, 0)], [(160, 340), (480, 340)]]),
        '∇': (600, [[(60, 680), (540, 680), (300, 0), (60, 680)]]),
        '∠': (620, [[(520, 520), (80, 40), (560, 40)]]),
        '∓': (560, [[(80, 560), (480, 560)], [(280, 460), (280, 60)], [(80, 260), (480, 260)]]),
        '‖': (450, [[(150, 700), (150, -150)], [(300, 700), (300, -150)]]),
        '⋯': (620, [yay(110, 250, 22, 22, n=10), yay(310, 250, 22, 22, n=10), yay(510, 250, 22, 22, n=10)]),
    }
    for ch, (adv, polys) in E.items():
        if ch not in _TEK_CIZGI or ch == 'ω': _TEK_CIZGI[ch] = (float(adv), [[(float(x), float(y)) for x, y in p_] for p_ in polys])
    if '∑' in _TEK_CIZGI and 'Σ' not in _TEK_CIZGI: _TEK_CIZGI['Σ'] = _TEK_CIZGI['∑']
    if '∫' in _TEK_CIZGI:
        adv_, pl_ = _TEK_CIZGI['∫']
        if '∬' not in _TEK_CIZGI: _TEK_CIZGI['∬'] = (adv_*1.6, pl_ + [[(x + adv_*0.6, y) for x, y in p_] for p_ in pl_])
        if '∮' not in _TEK_CIZGI:
            xs_ = [x for p_ in pl_ for x, _ in p_]; ys_ = [y for p_ in pl_ for _, y in p_]
            _TEK_CIZGI['∮'] = (adv_, pl_ + [yay((min(xs_) + max(xs_))/2, (min(ys_) + max(ys_))/2, adv_*0.32, adv_*0.32)])
    for ch, harf in (('ℝ', 'R'), ('ℕ', 'N'), ('ℤ', 'Z'), ('ℚ', 'Q')):   # tahta harfi: harfe ikinci dikey çizgi
        if ch not in _TEK_CIZGI and harf in _TEK_CIZGI:
            adv_, pl_ = _TEK_CIZGI[harf]; xs_ = [x for p_ in pl_ for x, _ in p_]; x_ = min(xs_) + 70 if xs_ else 150
            _TEK_CIZGI[ch] = (adv_, pl_ + [[(x_, 20), (x_, 660)]])
    # fontta olmayan öteki işaretler (Δ…): Hershey çizgi yazısından (büyük harf 21 birim, taban y=9) ölçeklenir
    hs = globals().get('HERSHEY') or {}
    k = 680/21.0
    for ch, (adv, polys) in hs.items():
        if ch not in _TEK_CIZGI and len(ch) == 1:
            _TEK_CIZGI[ch] = (adv*k, [[(gx*k, (9 - gy)*k) for gx, gy in poly] for poly in polys])
    return _TEK_CIZGI

def _yol_coz(d):
    import re
    t = re.findall(r'[MmLlHhVvCcSsQqTtZz]|-?\d*\.?\d+(?:[eE][-+]?\d+)?', d)
    out = []; cur = []; x = y = 0.0; sx = sy = 0.0; komut = None; i = 0; onc = None
    def sayi():
        nonlocal i
        v = float(t[i]); i += 1; return v
    def kubik(p0, p1, p2, p3, n=10):
        return [((1-u)**3*p0[0] + 3*(1-u)**2*u*p1[0] + 3*(1-u)*u*u*p2[0] + u**3*p3[0], (1-u)**3*p0[1] + 3*(1-u)**2*u*p1[1] + 3*(1-u)*u*u*p2[1] + u**3*p3[1]) for u in (k/n for k in range(1, n+1))]
    while i < len(t):
        if t[i].isalpha(): komut = t[i]; i += 1
        rel = komut.islower(); c = komut.upper()
        if c == 'Z':
            if cur: cur.append((sx, sy))
            x, y = sx, sy; continue
        bx, by = (x, y) if rel else (0.0, 0.0)
        if c == 'M':
            if len(cur) > 1: out.append(cur)
            x, y = bx + sayi(), by + sayi(); sx, sy = x, y; cur = [(x, y)]; komut = 'l' if rel else 'L'; onc = None; continue
        if c == 'L': x, y = bx + sayi(), by + sayi(); cur.append((x, y)); onc = None
        elif c == 'H': x = bx + sayi(); cur.append((x, y)); onc = None
        elif c == 'V': y = (y if rel else 0.0) + sayi(); cur.append((x, y)); onc = None
        elif c == 'C':
            p1 = (bx + sayi(), by + sayi()); p2 = (bx + sayi(), by + sayi()); p3 = (bx + sayi(), by + sayi())
            cur += kubik((x, y), p1, p2, p3); onc = p2; x, y = p3
        elif c == 'S':
            p1 = (2*x - onc[0], 2*y - onc[1]) if onc else (x, y); p2 = (bx + sayi(), by + sayi()); p3 = (bx + sayi(), by + sayi())
            cur += kubik((x, y), p1, p2, p3); onc = p2; x, y = p3
        elif c == 'Q':
            q = (bx + sayi(), by + sayi()); p3 = (bx + sayi(), by + sayi())
            cur += kubik((x, y), (x + 2/3*(q[0]-x), y + 2/3*(q[1]-y)), (p3[0] + 2/3*(q[0]-p3[0]), p3[1] + 2/3*(q[1]-p3[1])), p3); onc = None; x, y = p3
        elif c == 'T':
            p3 = (bx + sayi(), by + sayi()); cur.append(p3); x, y = p3; onc = None
        else: i += 1
    if len(cur) > 1: out.append(cur)
    return out

def tek_cizgi_olcer(yol):
    f = tek_cizgi_font(yol)
    def olc(t, boy): return sum(f.get(ch, f.get('?', (500.0, [])))[0] for ch in t)*boy/1000.0
    return olc

def murekkep_cizgileri(cevap, genislik, boy, renk, kalinlik, yol, duzelt=lambda t: t):
    """Cevabı kalem çizgilerine çevirir: [{'tool': 'pen', 'color', 'width', 'points'}], sol üst (0, 0)."""
    f = tek_cizgi_font(yol); olc = tek_cizgi_olcer(yol)
    h, op = cevap_diz(cevap, genislik, boy, olc, duzelt, dict(satir=2.3, paragraf=1.5, par_ara=0.45))   # tahtada ferah: satırlar iç içe girmesin
    out = []
    for o in op:
        if o[0] == 't':
            x = o[1]; k = o[4]/1000.0
            for ch in o[3]:
                adv, cizgiler = f.get(ch, f.get('?', (500.0, [])))
                for c in cizgiler:
                    out.append(dict(tool='pen', color=renk, width=kalinlik*(o[4]/boy)**0.5, points=[[round(x + gx*k, 2), round(o[2] - gy*k, 2)] for gx, gy in c]))
                x += adv*k
        elif o[0] == 'l':
            out.append(dict(tool='pen', color=renk, width=kalinlik, points=[[o[1], o[2]], [o[3], o[4]]]))
    return out, h

_ATLAS_FONT = {}
def _atlas_font(boy, yedek=False):
    from PyQt5.QtGui import QFont
    k = (yedek, int(round(boy)))
    if k not in _ATLAS_FONT:
        f = QFont('DejaVu Sans' if yedek else (ui_fonts().get('PatrickHand-Regular') or 'DejaVu Sans')); f.setPixelSize(max(8, k[1])); _ATLAS_FONT[k] = f
    return _ATLAS_FONT[k]
def _atlas_kos(t, boy):
    """Metni (parça, font) kümelerine böler: el yazısı fontunda olmayan işaretler (⇒, ∞…) DejaVu Sans ile."""
    from PyQt5.QtGui import QFontMetricsF
    ana = _atlas_font(boy); fm = QFontMetricsF(ana); out = []
    for ch in t:
        f = ana if fm.inFontUcs4(ord(ch)) else _atlas_font(boy, True)
        if out and out[-1][1] is f: out[-1][0] += ch
        else: out.append([ch, f])
    return out
def _atlas_olc(t, boy):
    from PyQt5.QtGui import QFontMetricsF
    return sum(QFontMetricsF(f).width(c) for c, f in _atlas_kos(t, boy))
ATLAS_STIL = dict(baslik='#7ff6ff', madde='#22e8ff', cevap='#3ef08a', satir=1.15, paragraf=1.1)
ATLAS_STIL_TAM = dict(ATLAS_STIL, satir=1.6, paragraf=1.7, par_ara=0.3)   # tam ekran: kitap gibi ferah
def atlas_cevap_resmi(cevap, genislik, boy=27, renk='#eef6ff', formul=True, stil=None):
    """K-349: cevabı matematik kitabı düzeninde (kesir üst üste, üs yukarıda, kök işareti) el yazısıyla çizer; saydam QImage.
    K-350: başlıklar camgöbeği, madde işaretleri, "Cevap:" yeşil çerçevede."""
    metin = cevap if formul else cevap.replace('$', '＄')
    h, op = cevap_diz(metin, genislik - 12, boy, _atlas_olc, atlas_guzel, stil)
    im = QImage(int(genislik) + 2, max(1, int(h + boy*0.4)), QImage.Format_ARGB32_Premultiplied); im.fill(Qt.transparent)
    p = QPainter(im); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing)
    c = QColor(renk); p.translate(6, 0)
    for o in op:
        if o[0] == 't':
            x = o[1]; p.setPen(QColor(o[5]) if len(o) > 5 and o[5] else c)
            for parca, f in _atlas_kos(o[3], o[4]):
                p.setFont(f); p.drawText(QPointF(x, o[2]), parca); x += _atlas_olc(parca, o[4])
        elif o[0] == 'k':
            kc = QColor(o[5]); dolgu = QColor(kc); dolgu.setAlpha(28)
            p.setPen(QPen(kc, max(2.0, boy*0.08))); p.setBrush(dolgu); p.drawRoundedRect(QRectF(o[1] - 4, o[2], o[3] - o[1] + 8, o[4] - o[2]), boy*0.5, boy*0.5); p.setBrush(Qt.NoBrush)
        else:
            p.setPen(QPen(c, o[5], Qt.SolidLine, Qt.RoundCap)); p.drawLine(QPointF(o[1], o[2]), QPointF(o[3], o[4]))
    p.end(); return im

class AtlasCevap(QFrame):
    """Cevap kutusu: QTextBrowser yerine; formüller çizilir, parmakla kaydırılır. setPlainText ile aynı kullanım.
    Tam ekranda yazı büyür, satır araları açılır, metin ortada kitap sayfası genişliğinde durur."""
    def __init__(self, parent=None):
        super().__init__(parent)
        from PyQt5.QtWidgets import QScrollArea, QScroller
        self.setObjectName('atlasCevap'); self.setStyleSheet('#atlasCevap{background:#0a1628;border:1px solid #2a4468;border-radius:14px;}')
        v = QVBoxLayout(self); v.setContentsMargins(12, 10, 6, 10)
        self.alan = QScrollArea(); self.alan.setWidgetResizable(False); self.alan.setFrameShape(QFrame.NoFrame)
        self.alan.setStyleSheet('QScrollArea{background:transparent;} QScrollArea > QWidget > QWidget{background:transparent;}'
                                'QScrollBar:vertical{background:transparent;width:10px;margin:4px 0;} QScrollBar::handle:vertical{background:#2a6f8a;border-radius:5px;min-height:40px;}'
                                'QScrollBar::add-line:vertical,QScrollBar::sub-line:vertical{height:0;} QScrollBar::add-page:vertical,QScrollBar::sub-page:vertical{background:none;}')
        self.alan.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.resim = QLabel(); self.resim.setStyleSheet('background:transparent;'); self.alan.setWidget(self.resim); v.addWidget(self.alan)
        QScroller.grabGesture(self.alan.viewport(), QScroller.LeftMouseButtonGesture)
        self.metin = ''; self.formul = False; self._gen = 0; self.tam = False
    def tam_ekran(self, tam):
        self.tam = tam; self.setStyleSheet('#atlasCevap{background:%s;border:1px solid #2a4468;border-radius:22px;}' % ('#0b1a30' if tam else '#0a1628'))
        self.layout().setContentsMargins(*((40, 30, 20, 30) if tam else (12, 10, 6, 10))); QTimer.singleShot(0, self._ciz)
    def setPlainText(self, t, formul=False):
        self.metin = t or ''; self.formul = formul; self._ciz(); self.alan.verticalScrollBar().setValue(0)
    def toPlainText(self): return self.metin
    def _ciz(self):
        g = max(200, self.alan.width() - 22); self._gen = g   # kaydırma çubuğu çıksa da kesilmesin
        if self.tam:
            sayfa = min(g, 1250)   # kitap sayfası genişliği; ortada
            im = atlas_cevap_resmi(self.metin, sayfa, 38, '#eef6ff', self.formul, ATLAS_STIL_TAM)
            self.resim.setPixmap(QPixmap.fromImage(im)); self.resim.setFixedSize(g, im.height()); self.resim.setAlignment(Qt.AlignHCenter | Qt.AlignTop)
        else:
            im = atlas_cevap_resmi(self.metin, g, 27, '#eef6ff', self.formul, ATLAS_STIL)
            self.resim.setPixmap(QPixmap.fromImage(im)); self.resim.setFixedSize(im.width(), im.height()); self.resim.setAlignment(Qt.AlignLeft | Qt.AlignTop)
    def resizeEvent(self, e):
        super().resizeEvent(e)
        if abs(self.alan.width() - 22 - self._gen) > 4: QTimer.singleShot(0, self._ciz)

class KaraTahtaCerceve(QWidget):
    """K-351: kara tahtanın ince ahşap çerçevesi, tebeşir oluğu ve silgisi (yalnız süs; dokunuşları alttaki tahtaya geçirir)."""
    def __init__(self, parent, tur):
        super().__init__(parent); self.tur = tur
        self.setAttribute(Qt.WA_TransparentForMouseEvents); self.setAttribute(Qt.WA_TranslucentBackground, tur == 'silgi'); self.hide()
    def paintEvent(self, e):
        from PyQt5.QtGui import QLinearGradient
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); w, h = self.width(), self.height()
        def ahsap(x1, y1, x2, y2, renkler):
            g = QLinearGradient(x1, y1, x2, y2)
            for t_, c_ in renkler: g.setColorAt(t_, QColor(c_))
            return g
        if self.tur in ('ust', 'alt'):
            p.fillRect(self.rect(), ahsap(0, 0, 0, h, ((0, '#b07a43'), (.5, '#8d5a2b'), (1, '#6b4220'))))
            if self.tur == 'alt':
                p.fillRect(0, 0, w, 2, QColor(0, 0, 0, 90))
                p.setPen(QPen(QColor(74, 44, 18, 90), 1))
                for y_ in (h*.45, h*.75):
                    path = QPainterPath(QPointF(0, y_))
                    for i in range(1, 9): path.quadTo(QPointF(w*(i - .5)/8, y_ + (1.2 if i % 2 else -1.2)), QPointF(w*i/8, y_))
                    p.drawPath(path)
                x0 = w*.2; p.setPen(Qt.NoPen)   # tebeşirler
                p.setBrush(QColor('#f4f4ee')); p.drawRoundedRect(QRectF(x0, 3, 64, 9), 4, 4)
                p.setBrush(QColor('#ffd36e')); p.drawRoundedRect(QRectF(x0 + 76, 4, 40, 8), 4, 4)
        elif self.tur in ('sol', 'sag'):
            p.fillRect(self.rect(), ahsap(0, 0, w, 0, ((0, '#6b4220'), (.5, '#9a6533'), (1, '#6b4220'))))
        else:   # silgi: ahşap sırt, gri keçe, gölge, keçede tebeşir tozu
            p.setPen(Qt.NoPen); p.setBrush(QColor(0, 0, 0, 80)); p.drawEllipse(QRectF(8, h - 8, w - 16, 8))
            p.setBrush(QColor('#6b6f75')); p.drawRoundedRect(QRectF(10, 20, w - 20, 15), 4, 4)
            p.setBrush(QColor('#4f5257')); p.drawRoundedRect(QRectF(10, 30, w - 20, 5), 3, 3)
            p.setBrush(ahsap(0, 0, 0, 22, ((0, '#d09a5c'), (1, '#9c6431')))); p.setPen(QPen(QColor(59, 34, 13, 120), 1)); p.drawRoundedRect(QRectF(14, 1, w - 28, 22), 8, 8)
            p.setPen(QPen(QColor(90, 52, 21, 90), 1.4)); p.drawLine(QPointF(24, 8), QPointF(w - 30, 9)); p.drawLine(QPointF(22, 15), QPointF(w - 26, 16))
            p.setPen(Qt.NoPen); p.setBrush(QColor(255, 255, 255, 90)); p.drawEllipse(QRectF(40, 31, 36, 5))
        p.end()

def mikrofon_komutu(cikis):
    """K-354: tahtada mikrofon varsa ses kaydı komutu (pw-record / parecord / arecord), yoksa None."""
    import shutil, subprocess
    try:
        if shutil.which('pactl'):
            o = subprocess.run(['pactl', 'list', 'short', 'sources'], capture_output=True, text=True, timeout=3).stdout
            if any(l.strip() and '.monitor' not in l for l in o.splitlines()):
                if shutil.which('pw-record'): return ['pw-record', '--rate', '16000', '--channels', '1', cikis]
                if shutil.which('parecord'): return ['parecord', '--rate=16000', '--channels=1', '--format=s16le', '--file-format=wav', cikis]
        if shutil.which('arecord'):
            o = subprocess.run(['arecord', '-l'], capture_output=True, text=True, timeout=3).stdout
            if 'card' in o.lower(): return ['arecord', '-q', '-f', 'S16_LE', '-r', '16000', '-c', '1', '-d', '30', cikis]
    except Exception: pass
    return None

def mikrofon_ikonu(renk='#7ff6ff', boy=30):
    pm = QPixmap(boy, boy); pm.fill(Qt.transparent); p = QPainter(pm); p.setRenderHint(QPainter.Antialiasing)
    p.setPen(QPen(QColor(renk), boy*0.09, Qt.SolidLine, Qt.RoundCap)); p.setBrush(QColor(renk))
    p.drawRoundedRect(QRectF(boy*.37, boy*.1, boy*.26, boy*.48), boy*.13, boy*.13); p.setBrush(Qt.NoBrush)
    p.drawArc(QRectF(boy*.24, boy*.28, boy*.52, boy*.42), 180*16, 180*16); p.drawLine(QPointF(boy*.5, boy*.7), QPointF(boy*.5, boy*.86)); p.drawLine(QPointF(boy*.36, boy*.87), QPointF(boy*.64, boy*.87))
    p.end(); return QIcon(pm)

def yabanci_yazi_temizle(t):
    """K-362: yapay zekâ bazen araya başka alfabeden sözcük katar (Çince, Hintçe, Kiril…); tahtada ??? çıkmasın diye atılır."""
    import re
    t = re.sub(r'[\u0370-\u03FF]+', lambda m_: m_.group(0), t)   # Yunan harfleri matematikte kalır
    t = re.sub(r'[\u0400-\u052F\u0590-\u08FF\u0900-\u0DFF\u0E00-\u0FFF\u1100-\u11FF\u3040-\u30FF\u3400-\u4DBF\u4E00-\u9FFF\uAC00-\uD7AF\uF900-\uFAFF]+', '', t)
    return re.sub(r'[ \t]{2,}', ' ', t).replace(' :', ':').replace(' ,', ',')

