        self.setStyleSheet('QDialog{background:#0f1c2e;} QLabel{color:white;} QPushButton{font-size:24px;font-weight:700;color:white;background:#13233a;border:2px solid #2a4468;border-radius:18px;padding:14px 20px;text-align:left;} QPushButton:pressed{background:#1d3150;} QPushButton:disabled{color:#6f819c;border-color:#1d2c44;}')
        v = QVBoxLayout(self); v.setContentsMargins(30, 24, 30, 24); v.setSpacing(16)
