class AnketSonucDialog(QDialog):
    """Öğretmenler odası: açık anketlerin katılımı ve 'Raporu Drive'a gönder'."""
    def __init__(self, main):
        super().__init__(main); self.main = main; self.setWindowTitle('Anketler')
        self.setStyleSheet('QDialog{background:#0f1c2e;} QLabel{color:white;font-size:20px;} QPushButton{font-size:20px;font-weight:700;color:white;background:#1d3150;border:1px solid #2a4468;border-radius:12px;padding:12px 22px;}')
        v = QVBoxLayout(self); v.setContentsMargins(30, 24, 30, 24); v.setSpacing(12)
        defs = [a for a in main.anket_defs() if str(a.get('bitis') or '9999') >= (datetime_today() - 30)]
        if not defs: v.addWidget(QLabel('Henüz anket yok.'))
        self.info = QLabel(''); self.info.setStyleSheet('color:#ffe14d;font-size:19px;')
        for a in defs:
            row = QHBoxLayout(); n = sum(1 for s_ in a.get('siniflar', {}) for r in anket_roster(a, s_) if r[2])
            row.addWidget(QLabel('<b>%s</b><br><span style="color:#9fb3cc;font-size:17px">%d sınıf · %d öğrenci · %s – %s</span>' % (a.get('ad', '').replace('<', ''), len(a.get('siniflar', {})), n, a.get('baslangic', ''), a.get('bitis', ''))), 1)
            b = QPushButton('Raporu Drive\'a gönder'); b.clicked.connect(lambda c=False, a_=a: self.report(a_)); row.addWidget(b); v.addLayout(row)
        v.addWidget(self.info); cl = QPushButton('Kapat'); cl.clicked.connect(self.accept); v.addWidget(cl)
        self.resize(900, 200 + 90*len(defs))
    def report(self, a):
        out = os.path.join(self.main.data_dir, 'anket-%s-tum.json' % a['id'])
        try: t0 = os.path.getmtime(out)
        except OSError: t0 = 0
        self.main.run_havuz('--yoklama-oku', 'anket_%s_' % a['id'], out); self.info.setText('Cevaplar Drive\'dan alınıyor…'); self.tries = 0
        def wait():
            self.tries += 1
            try: m = os.path.getmtime(out)
            except OSError: m = 0
            if m > t0 or self.tries > 60:
                try:
                    with open(out, encoding='utf-8') as f: raw = json.load(f)
                except (OSError, ValueError): raw = {}
                files = {(v_ or {}).get('salon'): v_ for v_ in raw.values() if isinstance(v_, dict)}
                try:
                    res = anket_report(a, files, os.path.join(self.main.data_dir, 'anket-rapor'), UI_FONT_DIR)
                    for path, name in res: self.main.run_havuz('--yukle', path, name)
                    sm = anket_summary(a, files); tk = sum(x['katilan'] for x in sm['siniflar'].values()); tb = sum(x['beklenen'] for x in sm['siniflar'].values())
                    self.info.setText('Rapor Drive\'daki "Sınav Yoklamaları" klasörüne gönderildi · katılım %d / %d' % (tk, tb))
                except Exception as e: self.info.setText('Rapor hazırlanamadı: %s' % e)
                return
            QTimer.singleShot(1000, wait)
        QTimer.singleShot(1000, wait)
class AnketCanli(QWidget):
    """Öğretmenler odası: anketin canlı katılım ekranı. Cevap verenler geldikçe ekrana düşer, bekleyenler sağda sınıf sınıf;
    'Anketi kapat / aç' bütün sınıf tahtalarına (1–2 dk içinde), 'Raporu Drive'a gönder'."""
    OKU_SN = 15
    def __init__(self, main):
        super().__init__(main); self.main = main; self.a = None; self.defs = []; self.files = {}; self.geldi = {}; self.first = True
        self.sec = None; self.hits = {}; self.toast = ''; self.out_m = 0; self.wait_report = None
        st_ = 'QPushButton{background:#1d3150;color:white;border:2px solid %s;border-radius:14px;padding:0 28px;font-size:22px;font-weight:700;}QPushButton:pressed{background:#2a4468;}'
        self.toggle_b = QPushButton('', self); self.rapor_b = QPushButton("Raporu Drive'a gönder", self); self.next_b = QPushButton('Diğer anket', self); self.close_b = QPushButton('Kapat', self)
        for b, c in ((self.toggle_b, '#ff3b4e'), (self.rapor_b, '#22e8ff'), (self.next_b, '#2a4468'), (self.close_b, '#2a4468')):
            b.setFocusPolicy(Qt.NoFocus); b.setMinimumHeight(58); b.setStyleSheet(st_ % c)
        self.toggle_b.clicked.connect(self.toggle); self.rapor_b.clicked.connect(self.report); self.next_b.clicked.connect(self.other); self.close_b.clicked.connect(self.close_)
        self.poll = QTimer(self); self.poll.timeout.connect(self.fetch)
        self.tick_t = QTimer(self); self.tick_t.setInterval(40); self.tick_t.timeout.connect(self.tick)
        self.load_t = QTimer(self); self.load_t.setInterval(1000); self.load_t.timeout.connect(self.load)
    def out_path(self): return os.path.join(self.main.data_dir, 'anket-%s-tum.json' % self.a['id'])
    def open_(self, a, defs):
        if self.a is None or self.a['id'] != a['id']: self.files = {}; self.geldi = {}; self.first = True; self.sec = None; self.out_m = 0
        self.a = a; self.defs = defs; self.toast = ''
        self.fit(self.main.rect()); self.show(); self.raise_(); self.load(); self.fetch()
        self.poll.start(self.OKU_SN*1000); self.load_t.start(); self.tick_t.start()
    def close_(self): self.poll.stop(); self.load_t.stop(); self.tick_t.stop(); self.hide()
    def other(self):
        if len(self.defs) < 2: return
        i = next((j for j, d in enumerate(self.defs) if d['id'] == self.a['id']), 0); self.open_(self.defs[(i + 1) % len(self.defs)], self.defs)
    def fit(self, rect): self.setGeometry(rect); self.layout_btns(); self.update()
    def resizeEvent(self, e): self.layout_btns()
    def layout_btns(self):
        W, H = self.width(), self.height(); m = int(64*min(1.0, H/1080.0)) if H else 64
        self.close_b.adjustSize(); self.close_b.move(W - self.close_b.width() - m, H - self.close_b.height() - m)
        self.next_b.adjustSize(); self.next_b.move(self.close_b.x() - self.next_b.width() - 14, self.close_b.y()); self.next_b.setVisible(len(self.defs) > 1)
        self.toggle_b.setText('Anketi aç' if self.a is not None and not self.acik() else 'Anketi kapat')
        self.toggle_b.setStyleSheet(self.toggle_b.styleSheet().replace('#2fbf71', '#ff3b4e') if self.acik() else self.toggle_b.styleSheet().replace('#ff3b4e', '#2fbf71'))
        self.toggle_b.adjustSize(); self.toggle_b.move(m, self.close_b.y())
        self.rapor_b.adjustSize(); self.rapor_b.move(self.toggle_b.x() + self.toggle_b.width() + 14, self.close_b.y())
    def acik(self):
        if self.a is None: return False
        return anket_durum_acik(self.a, self.main.anket_kontrol().get(self.a['id']), datetime_today())
    # veri
    def fetch(self):
        if self.a is None: return
        self.main.run_havuz('--yoklama-oku', 'anket_%s_' % self.a['id'], self.out_path())
        self.main.run_havuz('--yoklama-oku', 'anketdurum_', os.path.join(self.main.data_dir, 'anketdurum-gelen.json'))
    def load(self):
        if self.a is None: return
        m = arka_dosya().surum(self.out_path()) + 1   # K-434: diske gitmeden (yoksa 0)
        if m and m != self.out_m:
            self.out_m = m
            raw = arka_dosya().json(self.out_path(), {})
            if not isinstance(raw, dict): raw = {}
            self.files = {(v_ or {}).get('salon'): v_ for v_ in raw.values() if isinstance(v_, dict)}
        cevl, bek, say = anket_canli_veri(self.a, self.files); now = time.monotonic()
        for d in cevl:   # yeni gelen (ya da cevabını değiştiren) yukarıdan düşer; açılıştaki liste düşmez
            key = (d['sinif'], d['no'])
            if self.geldi.get(key, (None,))[0] != d['zaman']: self.geldi[key] = (d['zaman'], -1e9 if self.first else now)
            d['geldi'] = self.geldi[key][1]
        if self.first and self.files: self.first = False
        elif self.first and m: self.first = False
        self.data = (cevl, bek, say)
        if self.sec not in say: self.sec = max(say, key=lambda s_: len(bek.get(s_, []))) if say else None
        self.layout_btns(); self.update()
    def tick(self):
        cevl = getattr(self, 'data', ([], {}, {}))[0]; now = time.monotonic()
        if any(now - d.get('geldi', -1e9) < ANKET_YENI_SURE + 0.2 for d in cevl[:60]): self.update()
    # eylemler
    def mousePressEvent(self, e):
        pos = QPointF(e.pos())
        for r, s_ in self.hits.get('sinif', []):
            if r.contains(pos): self.sec = s_; self.update(); return
    def toggle(self):
        if self.a is None: return
        kapat = self.acik(); soru = ('“%s” bütün sınıf tahtalarında kapatılsın mı?' if kapat else '“%s” sınıf tahtalarında yeniden açılsın mı? (bugün için)') % self.a.get('ad', 'Anket')
        if QMessageBox.question(self, 'Anket', soru) != QMessageBox.Yes: return
        if self.main.anket_kontrol_yaz(self.a, 'kapali' if kapat else 'acik'):
            self.toast = ('Anket kapatıldı: 1–2 dakika içinde bütün tahtalarda kapanır.' if kapat else 'Anket açıldı: 1–2 dakika içinde sınıf tahtalarında görünür.')
        else: self.toast = 'Kaydedilemedi.'
        self.layout_btns(); self.update()
    def report(self):
        if self.a is None: return
        try:
            res = anket_report(self.a, self.files, os.path.join(self.main.data_dir, 'anket-rapor'), UI_FONT_DIR)
            for path, name in res: self.main.run_havuz('--yukle', path, name)
            cevl, bek, say = self.data; self.toast = 'Rapor Drive\'daki "Sınav Yoklamaları" klasörüne gönderildi · katılım %d / %d' % (sum(x[0] for x in say.values()), sum(x[1] for x in say.values()))
        except Exception as e: self.toast = 'Rapor hazırlanamadı: %s' % e
        self.update()
    def paintEvent(self, e):
        from PyQt5.QtGui import QFont
        fams = ui_fonts(); fam = fams.get('Poppins-Medium') or 'Sans'; famb = fams.get('Poppins-Bold') or fam
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing)
        W, H = self.width(), self.height(); k = min(W/1600, H/900)
        def font(px, b=False): f = QFont(famb if b else fam); f.setPixelSize(max(10, int(px*k))); return f
        p.fillRect(self.rect(), QColor('#0d1726'))
        if self.a is not None:
            cevl, bek, say = getattr(self, 'data', ([], {}, {}))
            self.hits = draw_anket_canli(p, W, H, k, font, self.a, cevl, bek, say, self.sec, self.acik(), time.monotonic(), self.close_b.y(), self.toast)
        p.end()

ANKET_YENI_SURE = 10.0   # yeni gelen cevap bu kadar saniye neon çerçeveli durur
def anket_canli_veri(a, files):
    """Öğretmenler odası canlı ekranı: (cevaplayanlar [dict(no, ad, sinif, cevap, zaman)] en yeni önce,
    bekleyenler {sınıf: [(no, ad)]}, sayılar {sınıf: (katılan, beklenen)})."""
    cev_l, bek, say = [], {}, {}
    for s_ in sorted((a.get('siniflar') or {}), key=lambda x: (class_grade(x) or 0, x)):
        exp = [r for r in anket_roster(a, s_) if r[2]]; cev = ((files or {}).get(s_) or {}).get('cevaplar', {}) or {}
        for no, ad, ok in exp:
            c = cev.get(no)
            if c: v = (c.get('c') or [None])[0]; cev_l.append(dict(no=no, ad=ad, sinif=s_, cevap=(', '.join(v) if isinstance(v, list) else (v or '')), zaman=float(c.get('zaman') or 0)))
        bek[s_] = [(no, ad) for no, ad, ok in exp if no not in cev]; say[s_] = (len(exp) - len(bek[s_]), len(exp))
    cev_l.sort(key=lambda d: -d['zaman'])
    return cev_l, bek, say
def anket_durum_acik(a, kontrol, today_iso):
    """Anket bu tahtada açık mı: Öğretmenler odasının 'Anketi aç / kapat' kaydı (anketdurum) tarih aralığından önce gelir.
    Kapatma kalıcıdır (yeniden açılana kadar); 'aç' yalnız verildiği gün geçerli."""
    k = kontrol if isinstance(kontrol, dict) else {}
    if k.get('durum') == 'kapali': return False
    if k.get('durum') == 'acik' and k.get('gun') == today_iso: return True
    return str(a.get('baslangic') or '0000') <= today_iso <= str(a.get('bitis') or '9999')
def draw_anket_canli(p, W, H, k, font, a, cevl, bek, say, sec, acik, now, bottom, toast=''):
    """Canlı katılım ekranı: solda cevap verenler (yeni gelen yukarıdan düşer), sağda sınıf sınıf bekleyenler.
    Döner: {'sinif': [(QRectF, sınıf)]} dokunma alanları."""
    def text(r, s_, f, c, al=Qt.AlignCenter): p.setFont(f); p.setPen(QColor(c)); p.drawText(r, al, s_)
    def elide(s_, f, w): return QFontMetrics(f).elidedText(s_, Qt.ElideRight, int(w))
    hits = {'sinif': []}
    fT = font(34, True); lbl = 'ANKET'; tw = QFontMetrics(fT).horizontalAdvance(lbl); pill = QRectF(30*k, 20*k, tw + 48*k, 58*k)
    draw_neon(p, pill, lbl, fT, '#22e8ff', k)
    fS = font(26, True); st_ = 'AÇIK' if acik else 'KAPALI'; sw = QFontMetrics(fS).horizontalAdvance(st_) + 56*k
    spill = QRectF(W - 30*k - sw, 22*k, sw, 54*k); draw_neon(p, spill, st_, fS, '#2fbf71' if acik else '#ff3b4e', k)
    fA = font(28, True); tx = pill.right() + 24*k
    text(QRectF(tx, 16*k, spill.left() - tx - 24*k, 40*k), elide(a.get('ad', ''), fA, spill.left() - tx - 24*k), fA, '#ffffff', Qt.AlignLeft | Qt.AlignVCenter)
    tk_ = sum(x[0] for x in say.values()); tb_ = sum(x[1] for x in say.values())
    dag = {}
    for d in cevl: dag[d['cevap']] = dag.get(d['cevap'], 0) + 1
    ops = list((a.get('sorular') or [{}])[0].get('secenekler') or [])
    parts = ['Cevap veren %d / %d' % (tk_, tb_)] + ['%s %d' % (o, dag.get(o, 0)) for o in ops]
    text(QRectF(tx, 56*k, spill.left() - tx - 24*k, 32*k), '   ·   '.join(parts), font(20, True), '#ffe14d', Qt.AlignLeft | Qt.AlignVCenter)
    # sağ: bekleyenler
    side = QRectF(W - 540*k, 104*k, 510*k, bottom - 164*k)   # altta bilgi satırına yer
    p.setPen(Qt.NoPen); p.setBrush(QColor(255, 255, 255, 10)); p.drawRoundedRect(side, 18*k, 18*k)
    nb = sum(len(v) for v in bek.values())
    text(QRectF(side.x() + 22*k, side.y() + 12*k, side.width() - 44*k, 40*k), 'Cevap bekleyenler · %d' % nb, font(22, True), '#7ff6ff', Qt.AlignLeft | Qt.AlignVCenter)
    y = side.y() + 60*k; fC = font(20, True); fN = font(17)
    nc = 3; gw = (side.width() - 28*k - (nc - 1)*8*k)/nc; gh = 64*k   # sınıflar: 3 sütunlu kutucuklar (adlara yer kalsın)
    for i, s_ in enumerate(say):
        r = QRectF(side.x() + 14*k + (i % nc)*(gw + 8*k), y + (i // nc)*(gh + 8*k), gw, gh); kat, bek_n = say[s_]
        if s_ == sec: p.setPen(QPen(QColor('#22e8ff'), 2.5*k)); p.setBrush(QColor(34, 232, 255, 26))
        else: p.setPen(Qt.NoPen); p.setBrush(QColor(255, 255, 255, 12))
        p.drawRoundedRect(r, 10*k, 10*k); kal = bek_n - kat
        text(QRectF(r.x() + 12*k, r.y() + 6*k, r.width() - 24*k, 32*k), s_, fC, '#ffffff', Qt.AlignLeft | Qt.AlignVCenter)
        text(QRectF(r.x() + 12*k, r.y() + 6*k, r.width() - 24*k, 32*k), ('%d kaldı' % kal) if kal else 'tamam', font(16, True), '#ffe14d' if kal else '#2fbf71', Qt.AlignRight | Qt.AlignVCenter)
        bar = QRectF(r.x() + 12*k, r.bottom() - 18*k, r.width() - 24*k, 8*k)
        p.setPen(Qt.NoPen); p.setBrush(QColor('#1d3150')); p.drawRoundedRect(bar, 4*k, 4*k)
        if bek_n and kat: p.setBrush(QColor('#2fbf71')); p.drawRoundedRect(QRectF(bar.x(), bar.y(), max(bar.height(), bar.width()*kat/bek_n), bar.height()), 4*k, 4*k)
        hits['sinif'].append((r, s_))
    y += ((len(say) + nc - 1)//nc)*(gh + 8*k)
    if sec in bek:
        y += 10*k; lst = bek[sec]
        text(QRectF(side.x() + 22*k, y, side.width() - 44*k, 32*k), ('%s · bekleyenler' % sec) if lst else ('%s · herkes cevap verdi' % sec), font(19, True), '#9fb3cc', Qt.AlignLeft | Qt.AlignVCenter)
        y += 38*k; colw = (side.width() - 44*k)/2; lh = 29*k; rows = max(1, int((side.bottom() - 14*k - y)//lh))
        cap = rows*2; show = lst if len(lst) <= cap else lst[:cap - 1]
        for i, (no, ad) in enumerate(show):
            cx = side.x() + 22*k + (i // rows)*colw; cy = y + (i % rows)*lh
            text(QRectF(cx, cy, colw - 10*k, lh), elide(ad, fN, colw - 10*k), fN, '#dbe6f5', Qt.AlignLeft | Qt.AlignVCenter)
        if len(show) < len(lst):
            i = len(show); cx = side.x() + 22*k + (i // rows)*colw; cy = y + (i % rows)*lh
            text(QRectF(cx, cy, colw - 10*k, lh), '+%d öğrenci daha' % (len(lst) - len(show)), font(16, True), '#ffe14d', Qt.AlignLeft | Qt.AlignVCenter)
    # sol: cevap verenler (en yeni sol üstte)
    area = QRectF(30*k, 104*k, side.left() - 54*k, bottom - 164*k)
    text(QRectF(area.x() + 4*k, area.y(), area.width(), 40*k), 'Cevap verenler · en yeni başta', font(22, True), '#7ff6ff', Qt.AlignLeft | Qt.AlignVCenter)
    gy = area.y() + 52*k; cw_min = 238*k; cols = max(1, int(area.width()//cw_min)); cw = area.width()/cols; ch = 104*k
    rows = max(1, int((area.bottom() - gy)//ch)); cap = rows*cols
    show = cevl if len(cevl) <= cap else cevl[:cap - 1]
    if not cevl: text(QRectF(area.x(), gy, area.width(), 200*k), 'Henüz cevap gelmedi.\nÖğrenciler sınıf tahtasından cevap verdikçe burada belirir.', font(24, True), '#6f819c')
    fName = font(17, True); fCls = font(15, True)
    for i, d in enumerate(show):
        cx = area.x() + (i % cols)*cw; cy = gy + (i // cols)*ch
        age = now - d.get('geldi', -1e9); t = min(1.0, max(0.0, age/0.6))
        dy = -(1 - t)**2*70*k   # yukarıdan düşer
        r = QRectF(cx + 4*k, cy + 4*k + dy, cw - 8*k, ch - 10*k)
        p.save(); p.setOpacity(0.25 + 0.75*t)
        yeni = age < ANKET_YENI_SURE
        if yeni:
            for w_, al in ((12, 26), (6, 70)):
                q = QColor('#22e8ff'); q.setAlpha(al); p.setPen(QPen(q, w_*k)); p.setBrush(Qt.NoBrush); p.drawRoundedRect(r, 12*k, 12*k)
        p.setPen(QPen(QColor('#22e8ff' if yeni else '#2a4468'), (2.5 if yeni else 1.2)*k)); p.setBrush(QColor('#13233a')); p.drawRoundedRect(r, 12*k, 12*k)
        ph = QRectF(r.x() + 8*k, r.y() + 8*k, (r.height() - 16*k)*0.78, r.height() - 16*k); draw_photo(p, ph, d['no'], d['ad'], k)
        tx_ = ph.right() + 10*k; tw_ = r.right() - tx_ - 8*k
        text(QRectF(tx_, r.y() + 8*k, tw_, 26*k), elide(d['ad'], fName, tw_), fName, '#ffffff', Qt.AlignLeft | Qt.AlignVCenter)
        text(QRectF(tx_, r.y() + 34*k, tw_, 22*k), d['sinif'], fCls, '#9fb3cc', Qt.AlignLeft | Qt.AlignVCenter)
        cv = d.get('cevap') or '—'; fc = font(16, True); cw_ = min(tw_, QFontMetrics(fc).horizontalAdvance(cv) + 26*k)
        chip = QRectF(tx_, r.bottom() - 36*k, cw_, 28*k)
        col = '#2fbf71' if cv == (ops[0] if ops else None) else ('#ff6b6b' if (len(ops) > 1 and cv == ops[1]) else '#7ff6ff')
        q = QColor(col); q.setAlpha(40); p.setPen(QPen(QColor(col), 1.5*k)); p.setBrush(q); p.drawRoundedRect(chip, 14*k, 14*k)
        text(chip, elide(cv, fc, cw_ - 16*k), fc, col)
        p.restore()
    if len(show) < len(cevl):
        i = len(show); cx = area.x() + (i % cols)*cw; cy = gy + (i // cols)*ch
        text(QRectF(cx, cy, cw, ch), '+%d cevap daha\n(rapor hepsini içerir)' % (len(cevl) - len(show)), font(17, True), '#ffe14d')
    if toast: text(QRectF(0, bottom - 50*k, W, 38*k), toast, font(21, True), '#7ff6ff')
    return hits

def datetime_today():
    import datetime
    class _D(str):
        def __sub__(self, days): return (datetime.date.fromisoformat(self) - datetime.timedelta(days=days)).isoformat()
    return _D(datetime.date.today().isoformat())

class Curtain(QWidget):
    """Perde: covers the solution; drag the handle to reveal it step by step.
    Screen-only (never saved). Below the line by default; ⇅ flips it to cover the top."""
    GRIP = 46
    def __init__(self, main):
        super().__init__(main.scroll); self.main = main; self.ratio = .45; self.top_side = False
        self.drag = None; self.vp = QRect(); self.setCursor(Qt.SizeVerCursor)
    def fit(self, vp):
        self.vp = QRect(vp); line = int(vp.height()*self.ratio)
        if self.top_side: self.setGeometry(vp.x(), vp.y(), vp.width(), max(self.GRIP, line))
        else: self.setGeometry(vp.x(), vp.y()+min(line, vp.height()-self.GRIP), vp.width(), max(self.GRIP, vp.height()-line))
    def strip(self):   # the handle strip faces the open part
        return QRectF(0, self.height()-self.GRIP, self.width(), self.GRIP) if self.top_side else QRectF(0, 0, self.width(), self.GRIP)
    def buttons(self):
        s = self.strip(); y = s.center().y()
        return QRectF(self.width()-58, y-19, 38, 38), QRectF(self.width()-106, y-19, 38, 38)   # ×, ⇅
    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        p.fillRect(self.rect(), QColor(11, 22, 38))   # opaque: nothing of the answer shows through
        p.setPen(QPen(QColor(255, 255, 255, 14), 1))
        for y in range(0, self.height(), 18): p.drawLine(0, y, self.width(), y)   # cloth folds
        s = self.strip(); p.fillRect(s, QColor('#1d3150'))
        edge = s.top() if not self.top_side else s.bottom()-1
        p.setPen(QPen(QColor('#ffc526'), 3)); p.drawLine(QPointF(0, edge), QPointF(self.width(), edge))
        grip = QRectF(s.center().x()-90, s.center().y()-15, 180, 30)
        p.setPen(Qt.NoPen); p.setBrush(QColor('#ffc526')); p.drawRoundedRect(grip, 15, 15)
        p.setPen(QColor('#122034')); p.setFont(BellClock.font(15, True))
        p.drawText(grip, Qt.AlignCenter, ('▲ Perdeyi çek' if self.top_side else '▼ Perdeyi çek'))
        x, flip = self.buttons()
        for r, t in ((x, '×'), (flip, '⇅')):
            p.setPen(Qt.NoPen); p.setBrush(QColor('#30496d')); p.drawEllipse(r)
            p.setPen(Qt.white); p.setFont(BellClock.font(22, True)); p.drawText(r, Qt.AlignCenter, t)
        p.end()
    def mousePressEvent(self, e):
        x, flip = self.buttons(); pos = QPointF(e.pos())
        if x.adjusted(-6, -6, 6, 6).contains(pos): self.main.toggle_curtain(False); return
        if flip.adjusted(-6, -6, 6, 6).contains(pos):
            self.top_side = not self.top_side; self.ratio = 1-self.ratio; self.fit(self.vp); self.update(); return
        self.drag = e.globalPos().y()
    def mouseMoveEvent(self, e):
        if self.drag is None or not self.vp.height(): return
        dy = e.globalPos().y()-self.drag; self.drag = e.globalPos().y()
        self.ratio = max(.0, min(1.0, self.ratio + dy/self.vp.height())); self.fit(self.vp); self.update()
    def mouseReleaseEvent(self, e):
        self.drag = None
        if (not self.top_side and self.ratio >= .97) or (self.top_side and self.ratio <= .03): self.main.toggle_curtain(False)   # pulled all the way: gone

class Spotlight(QWidget):
    """Spot ışığı: the board darkens; the framed part stays lit. The lit part is
    left out of this widget's mask, so the pen keeps writing there."""
    def __init__(self, main):
        super().__init__(main.scroll); self.main = main; self.hole = None; self.round = False
        self.mode = None; self.start = None; self.corner = None
    def fit(self, vp):
        self.setGeometry(vp); self.remask()
    def remask(self):
        if self.hole is None or self.hole.width() < 4: self.clearMask(); return
        h = self.hole.toAlignedRect().adjusted(2, 2, -2, -2)
        self.setMask(QRegion(self.rect()).subtracted(QRegion(h, QRegion.Ellipse if self.round else QRegion.Rectangle)))
    def corners(self):
        h = self.hole; return [h.topLeft(), h.topRight(), h.bottomLeft(), h.bottomRight()]
    def controls(self):
        h = self.hole; y = h.top()-46 if h.top() > 56 else h.bottom()+8
        return QRectF(h.center().x()-55, y, 110, 38), QRectF(h.right()-38, y, 38, 38), QRectF(h.right()-84, y, 38, 38)   # taşı, ×, şekil
    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        p.fillRect(self.rect(), QColor(3, 8, 18, 205))
        if self.hole is None:
            p.setPen(Qt.white); p.setFont(BellClock.font(22, True))
            p.drawText(self.rect(), Qt.AlignCenter, 'Aydınlık kalacak yeri kalemle çerçeveleyin'); return
        h = self.hole
        p.setBrush(Qt.NoBrush); p.setPen(QPen(QColor(255, 225, 77, 200), 4))
        (p.drawEllipse if self.round else p.drawRect)(h.adjusted(-2, -2, 2, 2))
        if self.mode == 'draw': return
        p.setPen(Qt.NoPen); p.setBrush(QColor('#ffe14d'))
        for c in self.corners(): p.drawEllipse(c, 12, 12)
        move, x, shape = self.controls()
        p.setBrush(QColor('#ffe14d')); p.drawRoundedRect(move, 19, 19)
        p.setPen(QColor('#122034')); p.setFont(BellClock.font(16, True)); p.drawText(move, Qt.AlignCenter, '✥ Taşı')
        for r, t in ((x, '×'), (shape, '▢' if self.round else '◯')):
            p.setPen(Qt.NoPen); p.setBrush(QColor('#30496d')); p.drawEllipse(r)
            p.setPen(Qt.white); p.setFont(BellClock.font(20, True)); p.drawText(r, Qt.AlignCenter, t)
        p.end()
    def mousePressEvent(self, e):
        pos = QPointF(e.pos()); self.start = pos; self.corner = None
        if self.hole is not None:
            move, x, shape = self.controls()
            if x.adjusted(-6, -6, 6, 6).contains(pos): self.main.toggle_spot(False); return
            if shape.adjusted(-6, -6, 6, 6).contains(pos): self.round = not self.round; self.remask(); self.update(); return
            if move.adjusted(-6, -6, 6, 6).contains(pos): self.mode = 'move'; return
            for i, c in enumerate(self.corners()):
                if math.hypot(pos.x()-c.x(), pos.y()-c.y()) <= 30: self.mode = 'resize'; self.corner = i; return
        self.mode = 'draw'; self.hole = QRectF(pos, pos); self.remask(); self.update()   # frame a new lit part
    def mouseMoveEvent(self, e):
        pos = QPointF(e.pos())
        if self.mode == 'draw': self.hole = QRectF(self.start, pos).normalized(); self.remask()
        elif self.mode == 'move': d = pos-self.start; self.start = pos; self.hole.translate(d); self.remask()
        elif self.mode == 'resize':
            h = self.hole
            if self.corner in (0, 2): h.setLeft(min(pos.x(), h.right()-60))
            else: h.setRight(max(pos.x(), h.left()+60))
            if self.corner in (0, 1): h.setTop(min(pos.y(), h.bottom()-40))
            else: h.setBottom(max(pos.y(), h.top()+40))
            self.remask()
        else: return
        self.update()
    def mouseReleaseEvent(self, e):
        if self.mode == 'draw' and (self.hole.width() < 40 or self.hole.height() < 30): self.hole = None
        self.mode = None; self.remask(); self.update()

class PanelClock(QWidget):
    """Sol paneldeki saat. K-452: web panelindeki saatin aynısı — analog kadran (serif rakamlar, ince iç halka, yaprak akrep/yelkovan,
    ortada silik okul logosu, turuncu saniye), altında dijital saat ve tarih. Yer dar ise (eski küçük panel) yalnız dijital saat ve tarih.
    Kadran (logo, çizgiler, rakamlar) bir kez çizilip saklanır; her saniye yalnız ibreler ve yazı."""
    def __init__(self, parent=None):
        super().__init__(parent); self.setMinimumHeight(110); self.now = None; self._kadran = None; self._isik = None; self._logo_r = None; self._son_sn = None
        self.timer = QTimer(self); self.timer.timeout.connect(self.tik); self.timer.start(50)
    ISIK_DONGU, ISIK_BAS = 6.0, .55   # K-455: web panelindeki gibi logonun üstünden 6 sn'de bir geçen ışık (döngünün son %45'i)
    def tik(self):
        """Saniye değişince bütün saat; ışık geçerken yalnız logo bölgesi (yazarken ışık beklemede: kalem akıcılığı)."""
        import datetime
        sn = (self.now or datetime.datetime.now()).second
        if sn != self._son_sn: self._son_sn = sn; self.update(); return
        f = (time.time() % self.ISIK_DONGU)/self.ISIK_DONGU
        if f >= self.ISIK_BAS - .02 and self._logo_r is not None and self.isVisible():
            try:
                b_ = getattr(self.window(), 'board', None)
                if b_ is not None and getattr(b_, 'active', None) is not None: return
            except Exception: pass
            self.update(self._logo_r)
    def isik_logo(self, D):
        """Logonun parlak kopyası (açık yerleri parlar): ışık bandı yalnız logonun üstünde görünür. Bir kez hazırlanır."""
        k_ = self._isik
        if k_ is not None and k_[0] == D: return k_[1]
        from PyQt5.QtGui import QImage
        n = max(8, int(D*.6)); pm = None
        try:
            lg = QPixmap(LOGO_RESMI) if os.path.isfile(LOGO_RESMI) else QPixmap()
            if not lg.isNull():
                im = lg.toImage().scaled(n, n, Qt.IgnoreAspectRatio, Qt.SmoothTransformation).convertToFormat(QImage.Format_ARGB32)
                g = im.convertToFormat(QImage.Format_Grayscale8)
                t_ = QImage(n, n, QImage.Format_ARGB32); t_.fill(QColor('#e6fdff')); t_.setAlphaChannel(g)
                q = QPainter(t_); q.setCompositionMode(QPainter.CompositionMode_DestinationIn); q.drawImage(0, 0, im); q.end()   # logonun dışı saydam kalsın
                pm = QPixmap.fromImage(t_)
        except Exception as x: print('saat ışığı:', x)
        self._isik = (D, pm); return pm
    def kadran(self, D):
        k_ = self._kadran
        if k_ is not None and k_[0] == D: return k_[1]
        from PyQt5.QtGui import QFont
        dpr = self.devicePixelRatioF() if hasattr(self, 'devicePixelRatioF') else 1.0
        pm = QPixmap(int(D*dpr), int(D*dpr)); pm.setDevicePixelRatio(dpr); pm.fill(Qt.transparent)
        p = QPainter(pm); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.SmoothPixmapTransform); u = D/100.0; p.scale(u, u)
        for w_, a in ((5.0, 26), (3.2, 50)):   # camgöbeği ışıma
            q = QColor('#22e8ff'); q.setAlpha(a); p.setPen(QPen(q, w_)); p.setBrush(Qt.NoBrush); p.drawEllipse(QPointF(50, 50), 46.2, 46.2)
        p.setPen(QPen(QColor('#22e8ff'), 1.6)); p.setBrush(QColor(13, 23, 38, 235)); p.drawEllipse(QPointF(50, 50), 46.2, 46.2)
        try:
            lg = QPixmap(LOGO_RESMI) if os.path.isfile(LOGO_RESMI) else QPixmap()
            if not lg.isNull(): p.setOpacity(.24); p.drawPixmap(QRectF(20, 20, 60, 60), lg, QRectF(lg.rect())); p.setOpacity(1)
        except Exception: pass
        for i in range(60):   # dakika çizgileri
            p.save(); p.translate(50, 50); p.rotate(i*6)
            if i % 5 == 0: p.setPen(QPen(QColor('#7ff6ff'), 1.4, Qt.SolidLine, Qt.RoundCap)); p.drawLine(QPointF(0, -45), QPointF(0, -39.8))
            else: p.setPen(QPen(QColor('#3a5a86'), 1)); p.drawLine(QPointF(0, -43), QPointF(0, -40.5))
            p.restore()
        p.setPen(QPen(QColor(127, 246, 255, 72), .5)); p.setBrush(Qt.NoBrush); p.drawEllipse(QPointF(50, 50), 37.6, 37.6)   # ince iç halka
        f = QFont('Liberation Serif'); f.setStyleHint(QFont.Serif); f.setPixelSize(max(8, int(round(7.4*u)))); f.setWeight(QFont.DemiBold)
        p.resetTransform(); p.scale(1, 1); p.setFont(f)   # rakamlar ekran pikselinde (keskin)
        for n in range(1, 13):
            a = math.radians(n*30); x = (50 + 31.6*math.sin(a))*u; y = (50 - 31.6*math.cos(a))*u; r_ = QRectF(x - 12*u, y - 6*u, 24*u, 12*u)
            p.setPen(QColor(13, 23, 38, 215))
            for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)): p.drawText(r_.translated(dx, dy), Qt.AlignCenter, str(n))
            p.setPen(QColor('#d9fbff')); p.drawText(r_, Qt.AlignCenter, str(n))
        p.end(); self._kadran = (D, pm); return pm
    def paintEvent(self, e):
        import datetime
        now = self.now or datetime.datetime.now(); p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        r = self.rect(); W, H = r.width(), r.height()
        p.setPen(QPen(QColor('#364a63'), 1)); p.drawLine(QPointF(12, 2), QPointF(W - 12, 2))
        tarih = '%d %s %d' % (now.day, TR_MONTHS[now.month-1], now.year); gun = TR_DAYS[now.weekday()]
        D = int(min(W - 28, H - 128, 210))
        if D < 120:   # dar yer: yalnız dijital saat ve tarih (eski görünüm)
            cy = H/2; tr_ = QRectF(0, cy-60, W, 64); hm = now.strftime('%H:%M'); p.setFont(BellClock.font(52, True))
            for w_, a in ((4, 45), (2, 90)):
                q = QColor('#22e8ff'); q.setAlpha(a); p.setPen(q)
                for dx, dy in ((-w_, 0), (w_, 0), (0, -w_), (0, w_)): p.drawText(tr_.translated(dx, dy), Qt.AlignCenter, hm)
            p.setPen(QColor('#7ff6ff')); p.drawText(tr_, Qt.AlignCenter, hm)
            p.setPen(QColor('#a9b9cf')); p.setFont(BellClock.font(16))
            p.drawText(QRectF(0, cy+6, W, 22), Qt.AlignCenter, tarih); p.drawText(QRectF(0, cy+28, W, 22), Qt.AlignCenter, gun)
            p.end(); return
        x0 = (W - D)/2.0; y0 = 12.0; p.drawPixmap(QPointF(x0, y0), self.kadran(D))
        u = D/100.0; h_, m_, s_ = now.hour, now.minute, now.second
        self._logo_r = QRectF(x0 + 19*u, y0 + 19*u, 62*u, 62*u).toAlignedRect()
        f_ = (time.time() % self.ISIK_DONGU)/self.ISIK_DONGU; il = self.isik_logo(D)
        if f_ >= self.ISIK_BAS and il is not None and not il.isNull():   # ışık bandı soldan sağa geçer (eğik, kenarları yumuşak)
            from PyQt5.QtGui import QPainterPath as _PP
            g_ = (f_ - self.ISIK_BAS)/(1 - self.ISIK_BAS); bx = -10 + 105*g_
            p.save(); p.translate(x0, y0); p.scale(u, u)
            daire = _PP(); daire.addEllipse(QPointF(50, 50), 30, 30)
            for gen, op in ((22, .16), (14, .2), (7, .28)):   # dış kenardan içe: yumuşak geçiş (toplam ~.65)
                bant = _PP(); sk = math.tan(math.radians(18))
                cx = bx + 11; y1, y2 = 10.0, 90.0
                bant.moveTo(cx - gen/2 - sk*(y1 - 50)*-1, y1); bant.lineTo(cx + gen/2 - sk*(y1 - 50)*-1, y1)
                bant.lineTo(cx + gen/2 - sk*(y2 - 50)*-1, y2); bant.lineTo(cx - gen/2 - sk*(y2 - 50)*-1, y2); bant.closeSubpath()
                p.save(); p.setClipPath(daire.intersected(bant)); p.setOpacity(op); p.drawPixmap(QRectF(20, 20, 60, 60), il, QRectF(il.rect())); p.restore()
            p.restore()
        from PyQt5.QtGui import QPolygonF as _Pg
        def ibre(aci, pts, renk, kenar):
            p.save(); p.translate(x0 + 50*u, y0 + 50*u); p.rotate(aci); p.scale(u, u)
            q = QColor('#22e8ff'); q.setAlpha(70); p.setPen(QPen(q, 1.6)); p.setBrush(Qt.NoBrush); p.drawPolygon(_Pg([QPointF(a, b) for a, b in pts]))   # hafif ışıma
            p.setPen(QPen(QColor('#0d1726'), kenar)); p.setBrush(QColor(renk)); p.drawPolygon(_Pg([QPointF(a, b) for a, b in pts])); p.restore()
        ibre((h_ % 12)*30 + m_*.5, ((0, 6), (-2.5, 0), (0, -23), (2.5, 0)), '#ffffff', .5)      # akrep (yaprak)
        ibre(m_*6 + s_*.1, ((0, 7), (-1.9, 0), (0, -36), (1.9, 0)), '#dffbff', .45)             # yelkovan
        p.save(); p.translate(x0 + 50*u, y0 + 50*u); p.rotate(s_*6); p.scale(u, u)                   # saniye: turuncu
        q = QColor('#ff9a3a'); q.setAlpha(80); p.setPen(QPen(q, 3.0, Qt.SolidLine, Qt.RoundCap)); p.drawLine(QPointF(0, 8), QPointF(0, -40))
        p.setPen(QPen(QColor('#ff9a3a'), 1.3, Qt.SolidLine, Qt.RoundCap)); p.drawLine(QPointF(0, 8), QPointF(0, -40))
        p.setPen(Qt.NoPen); p.setBrush(QColor('#ff9a3a')); p.drawEllipse(QPointF(0, -40), 2.2, 2.2); p.restore()
        p.setPen(QPen(QColor('#0d1726'), 1*u)); p.setBrush(QColor('#ff9a3a')); p.drawEllipse(QPointF(x0 + 50*u, y0 + 50*u), 3.2*u, 3.2*u)
        # dijital saat (saniye küçük, turuncu) ve tarih
        ty = y0 + D + 6; hm = now.strftime('%H.%M'); sn = '%02d' % s_
        fb = BellClock.font(40, True); fs = BellClock.font(20, True)
        from PyQt5.QtGui import QFontMetrics as _FM
        wb = _FM(fb).horizontalAdvance(hm); ws = _FM(fs).horizontalAdvance('00'); bx = (W - wb - 6 - ws)/2.0
        tr_ = QRectF(bx, ty, wb, 50); p.setFont(fb)
        for w_, a in ((3, 45), (1.5, 90)):
            q = QColor('#22e8ff'); q.setAlpha(a); p.setPen(q)
            for dx, dy in ((-w_, 0), (w_, 0), (0, -w_), (0, w_)): p.drawText(tr_.translated(dx, dy), Qt.AlignCenter, hm)
        p.setPen(QColor('#e9fdff')); p.drawText(tr_, Qt.AlignCenter, hm)
        p.setFont(fs); p.setPen(QColor('#ffd2a1')); p.drawText(QRectF(bx + wb + 6, ty + 14, ws + 2, 30), Qt.AlignLeft | Qt.AlignVCenter, sn)
        p.setFont(BellClock.font(16)); p.setPen(QColor('#a9b9cf')); p.drawText(QRectF(0, ty + 52, W, 22), Qt.AlignCenter, tarih)
        p.setFont(BellClock.font(16, True)); p.setPen(QColor('#7ff6ff')); p.drawText(QRectF(0, ty + 74, W, 22), Qt.AlignCenter, gun)
        p.end()

# ---- Ağdaki yazıcıları bulma (yalnızca yönetim panelinden "Yazıcıları bul" komutuyla) ----
PRINTER_PORTS = (9100, 631, 515)   # ham baskı (JetDirect), IPP, LPD
def _snmp_get_sysdescr(ip, timeout=.8):
    """SNMP v1 'public' ile sysDescr (1.3.6.1.2.1.1.1.0): yazıcılar marka/modelini burada söyler."""
    import socket
    oid = bytes([0x06, 0x08, 0x2b, 6, 1, 2, 1, 1, 1, 0])
    vb = bytes([0x30, len(oid) + 2]) + oid + b'\x05\x00'; vbl = bytes([0x30, len(vb)]) + vb
    pdu_body = b'\x02\x01\x01' + b'\x02\x01\x00' + b'\x02\x01\x00' + vbl
    pdu = bytes([0xa0, len(pdu_body)]) + pdu_body
    msg_body = b'\x02\x01\x00' + b'\x04\x06public' + pdu
    msg = bytes([0x30, len(msg_body)]) + msg_body
    sk = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); sk.settimeout(timeout)
    try:
        sk.sendto(msg, (ip, 161)); data, _ = sk.recvfrom(2048)
    except OSError: return ''
    finally: sk.close()
    i = data.rfind(b'\x04')   # son OCTET STRING = değer
    while i > 0:
        n = data[i+1]
        if n < 0x80 and i + 2 + n == len(data): return data[i+2:i+2+n].decode('utf-8', 'replace').strip()
        if n == 0x81 and i + 3 + data[i+2] == len(data): return data[i+3:i+3+data[i+2]].decode('utf-8', 'replace').strip()
        i = data.rfind(b'\x04', 0, i)
    return ''
def _http_title(ip, port=80, timeout=1.5):
    import urllib.request, re as re_
    try:
        with urllib.request.urlopen('http://%s:%d/' % (ip, port), timeout=timeout) as r: body = r.read(20000).decode('utf-8', 'replace')
    except Exception: return ''
    m = re_.search(r'<title[^>]*>(.*?)</title>', body, re_.I | re_.S)
    return ' '.join(m.group(1).split())[:120] if m else ''
def scan_printers(hosts=None):
    """Bu tahtanın bulunduğu ağı (/24) yazıcı bağlantı noktaları için kısaca yoklar; model bilgisini toplar."""
    import socket, concurrent.futures as cf, subprocess
    try:
        u = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); u.connect(('8.8.8.8', 80)); my = u.getsockname()[0]; u.close()   # paket gönderilmez
    except OSError: my = ''
    if hosts is None:
        if not my: return dict(zaman=time.time(), hata='Ağ adresi bulunamadı', bulunan=[])
        pre = my.rsplit('.', 1)[0]; hosts = ['%s.%d' % (pre, i) for i in range(1, 255) if '%s.%d' % (pre, i) != my]
    def probe(h):
        open_ = []
        for port in PRINTER_PORTS + (80,):
            sk = socket.socket(); sk.settimeout(.35)
            try:
                if sk.connect_ex((h, port)) == 0: open_.append(port)
            except OSError: pass
            finally: sk.close()
        return h, open_
    found = []
    with cf.ThreadPoolExecutor(64) as ex:
        for h, ports in ex.map(probe, hosts):
            if any(p_ in ports for p_ in PRINTER_PORTS): found.append(dict(ip=h, portlar=ports))
    for f in found:
        f['model'] = _snmp_get_sysdescr(f['ip'])[:160]
        if 80 in f['portlar']: f['web'] = _http_title(f['ip'])
    cups = []
    try:
        out = subprocess.run(['lpstat', '-v'], capture_output=True, text=True, timeout=5).stdout
        cups = [l.strip() for l in out.splitlines() if l.strip()][:20]
    except Exception: pass
    return dict(zaman=time.time(), ag=(my.rsplit('.', 1)[0] + '.0/24') if my else '', bu_tahta=my, bulunan=found, cups=cups)

class LiveMeter:
    """Derste gerçek kullanımda kalem akıcılığı: gün boyu tutulur, durum bildirimiyle sunucuya gider.
    Takılma: bir nokta 60 ms'den uzun sırada bekledi / işlendi ya da çizgiyi bitirmek 100 ms'yi geçti."""
    KEEP = 3000
    def __init__(self, main):
        import collections
        self.main = main; self.path = os.path.join(main.data_dir, 'kalem-canli.json')
        self.proc = collections.deque(maxlen=self.KEEP); self.lag = collections.deque(maxlen=self.KEEP); self.fin = collections.deque(maxlen=self.KEEP)
        self.day = time.strftime('%Y-%m-%d'); self.strokes = 0; self.points = 0; self.stalls = 0; self.worst = []; self.base = None; self.last_t = 0
        try:
            with open(self.path, encoding='utf-8') as f: d = json.load(f)
            if d.get('gun') == self.day:
                self.strokes, self.points, self.stalls = d.get('cizgi', 0), d.get('nokta', 0), d.get('takilma', 0); self.worst = d.get('en_kotu', [])[:5]
                self.proc.extend(d.get('_isleme', [])); self.lag.extend(d.get('_bekleme', [])); self.fin.extend(d.get('_bitis', []))
        except (OSError, ValueError, AttributeError): pass
    def roll(self):
        today = time.strftime('%Y-%m-%d')
        if today != self.day:
            self.day = today; self.strokes = self.points = self.stalls = 0; self.worst = []
            self.proc.clear(); self.lag.clear(); self.fin.clear()
    def context(self, b):
        o = self.main
        return dict(saat=time.strftime('%H:%M'), cozum=bool(o.in_solution()) if hasattr(o, 'in_solution') else False,
                    cizgi_sayfada=len(o.marks.get(o.page, [])), yakinlik=round(getattr(o, 'zoom', 1), 2))
    def note(self, kind, ms, b):
        self.stalls += 1
        self.worst.append(dict(self.context(b), tur=kind, ms=round(ms)))
        self.worst = sorted(self.worst, key=lambda x: -x['ms'])[:5]
    def point(self, ms, ts, b):
        self.roll(); now = time.monotonic()
        if now - self.last_t > .2: self.base = None   # yeni çizgi
        self.last_t = now; self.points += 1; self.proc.append(round(ms, 2))
        if ms > 60: self.note('isleme', ms, b)
        if ts:
            d = now*1000 - ts
            if self.base is None or d < self.base: self.base = d
            lag = d - self.base; self.lag.append(round(lag, 1))
            if lag > 60: self.note('bekleme', lag, b)
    def stroke_end(self, ms, b):
        self.roll(); self.strokes += 1; self.fin.append(round(ms, 1)); self.base = None
        if ms > 100: self.note('bitis', ms, b)
    @staticmethod
    def pct(v, q):
        v = sorted(v); return v[min(len(v)-1, int(len(v)*q))] if v else 0
    def summary(self):
        self.roll()
        return dict(gun=self.day, cizgi=self.strokes, nokta=self.points, takilma=self.stalls,
                    isleme_95=self.pct(self.proc, .95), isleme_max=max(self.proc) if self.proc else 0,
                    bekleme_95=self.pct(self.lag, .95), bekleme_max=max(self.lag) if self.lag else 0,
                    bitis_95=self.pct(self.fin, .95), bitis_max=max(self.fin) if self.fin else 0, en_kotu=self.worst, surum=installed_version())
    def save(self):
        d = self.summary(); d.update(_isleme=list(self.proc)[-500:], _bekleme=list(self.lag)[-500:], _bitis=list(self.fin)[-500:])
        try:
            with open(self.path, 'w', encoding='utf-8') as f: json.dump(d, f, ensure_ascii=False)
        except OSError: pass

class PenMeter:
    """Kalem ölçümü: 10 saniye yazılır; tahtanın nokta sıklığı, işleme ve çizim süresi,
    sırada bekleme ölçülür, sonuç ekranda gösterilir (Terminal gerekmez)."""
    SECONDS = 10
    def __init__(self, main):
        self.main = main; self.b = main.board; self.events = []; self.paints = []; self.kinds = {}; self.t0 = None
    def start(self):
        m = self.main; m.new_board()
        m.set_tool('pen'); b = self.b
        self.orig = (b.event, b.paintEvent)
        def event(e):
            t = e.type()
            if t in (QEvent.TouchUpdate, QEvent.MouseMove, QEvent.TabletMove):
                st = time.perf_counter(); r = self.orig[0](e); dur = (time.perf_counter() - st)*1000
                if self.t0 is None: self.t0 = time.monotonic()
                try: ts = e.timestamp()
                except Exception: ts = 0
                self.events.append((time.monotonic(), ts, dur, b.active is not None))
                k = {QEvent.TouchUpdate: 'dokunma', QEvent.MouseMove: 'fare', QEvent.TabletMove: 'kalem'}[t]; self.kinds[k] = self.kinds.get(k, 0) + 1
                return r
            return self.orig[0](e)
        def paint(e):
            st = time.perf_counter(); self.orig[1](e); self.paints.append((time.perf_counter() - st)*1000)
        b.event = event; b.paintEvent = paint
        self.banner = QLabel(m.scroll); self.banner.setAlignment(Qt.AlignCenter)
        self.banner.setStyleSheet('background:rgba(14,28,50,230);color:white;border:2px solid #3d8bff;border-radius:16px;padding:14px 26px;font-size:22px;')
        self.timer = QTimer(); self.timer.timeout.connect(self.tick); self.timer.start(200); self.tick()
    def tick(self):
        left = self.SECONDS if self.t0 is None else max(0, self.SECONDS - (time.monotonic() - self.t0))
        self.banner.setText('Kalem ölçümü · ' + ('normal hızda yazmaya başlayın' if self.t0 is None else 'yazmaya devam edin · %d sn' % math.ceil(left)))
        self.banner.adjustSize(); vp = self.main.scroll.viewport().geometry()
        self.banner.move(vp.x() + (vp.width() - self.banner.width())//2, vp.y() + 16); self.banner.show(); self.banner.raise_()
        if self.t0 is not None and left <= 0: self.stop()
    def stop(self):
        self.timer.stop(); self.banner.hide(); b = self.b
        del b.event; del b.paintEvent   # özgün yöntemlere dön
        self.main.pen_meter = None; self.show(self.result())
    @staticmethod
    def pct(v, q):
        if not v: return 0.0
        v = sorted(v); return v[min(len(v)-1, int(len(v)*q))]
    def result(self):
        ev = [e for e in self.events if e[3]]   # yalnızca yazarken
        gaps = [(b_[1]-a_[1]) for a_, b_ in zip(ev, ev[1:]) if 0 < b_[1]-a_[1] < 200]
        hz = 1000/self.pct(gaps, .5) if gaps else 0
        lag = []   # sırada bekleme: her çizginin içinde, en hızlı işlenen noktaya göre gecikme
        if ev and ev[0][1]:
            stroke = [ev[0]]
            for prev, cur in list(zip(ev, ev[1:])) + [(ev[-1], None)]:
                if cur is None or cur[0] - prev[0] > .2:
                    base = [e[0]*1000 - e[1] for e in stroke]; lo = min(base); lag += [x - lo for x in base]
                    stroke = [cur] if cur is not None else []
                else: stroke.append(cur)
        proc = [e[2] for e in ev]
        r = dict(nokta=len(ev), hz=round(hz), isleme_ort=round(sum(proc)/len(proc), 2) if proc else 0, isleme_95=round(self.pct(proc, .95), 2),
                 cizim_ort=round(sum(self.paints)/len(self.paints), 2) if self.paints else 0, cizim_95=round(self.pct(self.paints, .95), 2),
                 bekleme_95=round(self.pct(lag, .95), 1), bekleme_max=round(max(lag), 1) if lag else 0, giris=self.kinds, surum=installed_version())
        try:
            with open(os.path.join(self.main.data_dir, 'kalem-olcum.json'), 'w', encoding='utf-8') as f: json.dump(r, f, ensure_ascii=False)
        except OSError: pass
        return r
    def show(self, r):
        if r['nokta'] < 20: verdict = 'Yeterli yazı alınamadı. Ölçümü yeniden başlatıp 10 saniye boyunca sürekli yazın.'
        elif r['isleme_95'] > 8 or r['cizim_95'] > 16: verdict = 'Uygulama yavaş kalıyor: işleme ya da çizim süresi uzun. Kodda iyileştirilecek yer var.'
        elif r['bekleme_95'] > 25: verdict = 'Noktalar sırada bekliyor: tahta meşgul. Kodda iyileştirilecek yer var.'
        elif r['hz'] and r['hz'] < 80: verdict = 'Uygulama tarafı hızlı. Dokunmatik panel saniyede %d nokta gönderiyor; bu panelin kendi sınırı.' % r['hz']
        else: verdict = 'Uygulama tarafı hızlı. Kalan küçük gecikme dokunmatik panel ve ekrandan geliyor.'
        giris = ', '.join('%s %d' % kv for kv in r['giris'].items()) or '-'
        rows = [('Tahtanın gönderdiği nokta', '%d / saniye' % r['hz']), ('Noktayı işleme (ort / %95)', '%.2f / %.2f ms' % (r['isleme_ort'], r['isleme_95'])),
                ('Ekrana çizme (ort / %95)', '%.2f / %.2f ms' % (r['cizim_ort'], r['cizim_95'])), ('Sırada bekleme (%95 / en çok)', '%.1f / %.1f ms' % (r['bekleme_95'], r['bekleme_max'])),
                ('Ölçülen nokta', str(r['nokta'])), ('Giriş türü', giris), ('Uç tahmini', 'açık (normal ve Akıcı kalem)' if Board.PRED_ON else 'kapalı'), ('Sürüm', r['surum'])]
        d = QDialog(self.main); d.setWindowTitle('Kalem ölçümü'); lay = QVBoxLayout(d); lay.setContentsMargins(26, 22, 26, 22); lay.setSpacing(12)
        t = QLabel('Kalem ölçümü sonucu'); t.setStyleSheet('font-size:24px;font-weight:600;'); lay.addWidget(t)
        g = QGridLayout(); g.setHorizontalSpacing(30); g.setVerticalSpacing(10); lay.addLayout(g)
        for i, (a, v) in enumerate(rows):
            la = QLabel(a); la.setStyleSheet('font-size:19px;color:#a9b9cf;'); lv = QLabel(v); lv.setStyleSheet('font-size:21px;font-weight:600;')
            g.addWidget(la, i, 0); g.addWidget(lv, i, 1)
        v = QLabel(verdict); v.setWordWrap(True); v.setStyleSheet('font-size:18px;padding:12px;border-radius:12px;background:rgba(61,139,255,0.18);'); lay.addWidget(v)
        n = QLabel('Bu ekranın fotoğrafını gönderebilirsiniz.'); n.setStyleSheet('color:#a9b9cf;font-size:15px;'); lay.addWidget(n)
        ok = QPushButton('Kapat'); ok.setObjectName('primary'); ok.setMinimumHeight(48); ok.clicked.connect(d.accept); lay.addWidget(ok)
        d.resize(720, 560); d.exec_()


