# Ölçülü üçgen: kenar/açıdan üçgeni hesaplar; tahtaya normal çizgilerle konur.
TRI_MODES = [('sss', '3 kenar', ('|AB|', '|BC|', '|CA|')), ('sas', '2 kenar + aradaki açı', ('|AB|', '|AC|', 'A açısı')),
             ('asa', '1 kenar + 2 açı', ('|AB|', 'A açısı', 'B açısı')), ('aaa', 'Yalnız açılar', ('A açısı', 'B açısı'))]

def triangle_solve(mode, vals):
    """Döner: (a=|BC|, b=|CA|, c=|AB|, A, B, C derece) ya da hata metni."""
    d = math.degrees; r_ = math.radians
    try:
        if mode == 'sss':
            c, a, b = vals
            if min(a, b, c) <= 0: return 'Kenarlar sıfırdan büyük olmalı.'
            for x, y, z in ((a, b, c), (b, c, a), (c, a, b)):
                if x + y <= z: return 'Bu kenarlarla üçgen olmaz (%s + %s ≤ %s).' % (fmt_num(x), fmt_num(y), fmt_num(z))
            A = d(math.acos((b*b + c*c - a*a)/(2*b*c))); B = d(math.acos((a*a + c*c - b*b)/(2*a*c)))
        elif mode == 'sas':
            c, b, A = vals
            if min(b, c) <= 0: return 'Kenarlar sıfırdan büyük olmalı.'
            if not 0 < A < 180: return 'Açı 0° ile 180° arasında olmalı.'
            a = math.sqrt(b*b + c*c - 2*b*c*math.cos(r_(A))); B = d(math.acos(max(-1, min(1, (a*a + c*c - b*b)/(2*a*c)))))
        elif mode == 'asa':
            c, A, B = vals
            if c <= 0: return 'Kenar sıfırdan büyük olmalı.'
            if A <= 0 or B <= 0 or A + B >= 180: return 'Açıların toplamı 180°\'den küçük olmalı.'
            C = 180 - A - B; a = c*math.sin(r_(A))/math.sin(r_(C)); b = c*math.sin(r_(B))/math.sin(r_(C))
        else:
            A, B = vals
            if A <= 0 or B <= 0 or A + B >= 180: return 'Açıların toplamı 180° olmalı (iki açının toplamı 180°\'den küçük).'
            C = 180 - A - B; c = 6.0; a = c*math.sin(r_(A))/math.sin(r_(C)); b = c*math.sin(r_(B))/math.sin(r_(C))
        C = 180 - A - B
        return (a, b, c, A, B, C)
    except (ValueError, ZeroDivisionError):
        return 'Bu değerlerle üçgen çizilemiyor.'

def label_half(text, h):
    """text_strokes yazısının yarı genişlik/yükseklik kutusu."""
    xs = [q[0] for m in text_strokes(text, 0, 0, h, '#000', 1) for q in m['points']]
    ys = [q[1] for m in text_strokes(text, 0, 0, h, '#000', 1) for q in m['points']]
    if not xs: return h*.3, h*.5
    return max(abs(min(xs)), abs(max(xs))), max(abs(min(ys)), abs(max(ys)))

def triangle_marks(sol, mode, opts, size, color, width):
    """Üçgeni (ağırlık merkezi 0,0) çizgi listesi olarak üretir; size: en uzun kenar (sayfa birimi)."""
    a, b, c, A, B, C = sol; k = size/max(a, b, c)
    P = {'A': (0.0, 0.0), 'B': (c*k, 0.0), 'C': (b*k*math.cos(math.radians(A)), -b*k*math.sin(math.radians(A)))}
    gx = sum(v[0] for v in P.values())/3; gy = sum(v[1] for v in P.values())/3
    P = {n: (x - gx, y - gy) for n, (x, y) in P.items()}
    h = max(9.0, size*.075); blue, red, grey = '#0057ff', '#e8132b', '#64748b'
    out = [dict(tool='pen', color=color, width=width, points=[list(P['A']), list(P['B']), list(P['C']), list(P['A'])])]
    def unit(x, y): n = math.hypot(x, y) or 1; return x/n, y/n
    edges = [(P['A'], P['B']), (P['B'], P['C']), (P['C'], P['A'])]; boxes = []
    Ax, Ay = P['A']; Bx, By = P['B']; Cx, Cy = P['C']
    if opts.get('height'):   # yardımcı çizgiler de etiketlerin kaçınacağı yerler
        t_ = ((Cx - Ax)*(Bx - Ax) + (Cy - Ay)*(By - Ay))/((Bx - Ax)**2 + (By - Ay)**2); edges.append(((Cx, Cy), (Ax + t_*(Bx - Ax), Ay + t_*(By - Ay))))
    if opts.get('bisector'): t_ = c/(b + c); edges.append(((Ax, Ay), (Bx + (Cx - Bx)*t_, By + (Cy - By)*t_)))
    if opts.get('median'): edges.append(((Ax, Ay), ((Bx + Cx)/2, (By + Cy)/2)))
    def seg_hits(box, p0, p1):   # doğru parçası kutuya giriyor mu (Liang–Barsky)
        x0, y0, x1, y1 = box; t0, t1 = 0.0, 1.0; dx, dy = p1[0] - p0[0], p1[1] - p0[1]
        for pp, qq in ((-dx, p0[0] - x0), (dx, x1 - p0[0]), (-dy, p0[1] - y0), (dy, y1 - p0[1])):
            if pp == 0:
                if qq < 0: return False
            else:
                r_ = qq/pp
                if pp < 0: t0 = max(t0, r_)
                else: t1 = min(t1, r_)
                if t0 > t1: return False
        return True
    def free(box):
        g = h*.18; bb = (box[0] - g, box[1] - g, box[2] + g, box[3] + g)
        if any(seg_hits(bb, p0, p1) for p0, p1 in edges): return False
        return not any(bb[0] < q[2] and q[0] < bb[2] and bb[1] < q[3] and q[1] < bb[3] for q in boxes)
    def place(txt, hs, col, wid, tries):
        """tries: [(px, py, ux, uy, t0, t1)] sırayla denenir; çizgiye/etikete değmeyen ilk yer."""
        hw, hh = label_half(txt, hs); last = None
        for px, py, ux, uy, t0, t1 in tries:
            t = t0
            while t <= t1:
                cx, cy = px + ux*t, py + uy*t; box = (cx - hw, cy - hh, cx + hw, cy + hh)
                if free(box):
                    boxes.append(box); return text_strokes(txt, cx, cy, hs, col, wid)
                last = last or (cx, cy, box); t += h*.2
        cx, cy, box = last; boxes.append(box); return text_strokes(txt, cx, cy, hs, col, wid)
    angs = {'A': A, 'B': B, 'C': C}; bis = {}
    for n_ in 'ABC':
        others = [m for m in 'ABC' if m != n_]; vx, vy = P[n_]
        d1 = unit(P[others[0]][0] - vx, P[others[0]][1] - vy); d2 = unit(P[others[1]][0] - vx, P[others[1]][1] - vy)
        bis[n_] = (d1, d2, unit(d1[0] + d2[0], d1[1] + d2[1]))
    if opts.get('names', True):
        for n_ in 'ABC':   # köşe adı: açının tam dışına
            bx, by = bis[n_][2]; out += place(n_, h, color, max(1.2, width*.7), [(P[n_][0], P[n_][1], -bx, -by, h*.7, h*4)])
    given_s = {'sss': ('c', 'a', 'b'), 'sas': ('c', 'b'), 'asa': ('c',), 'aaa': ()}[mode]
    given_a = {'sss': (), 'sas': ('A',), 'asa': ('A', 'B'), 'aaa': ('A', 'B')}[mode]
    sides = {'c': ('A', 'B', c), 'a': ('B', 'C', a), 'b': ('C', 'A', b)}
    rr = size*.09; jobs = []
    for n_, val in angs.items():
        show = n_ in given_a and opts.get('angles', True); calc = n_ not in given_a and opts.get('calc', False)
        right = abs(val - 90) < 1e-6
        if not (show or calc or right): continue
        d1, d2, (bx, by) = bis[n_]; vx, vy = P[n_]; col = red if show else grey
        if right:   # dik açı: küçük kare
            q = rr*.6; out.append(dict(tool='pen', color=red, width=max(1.2, width*.7), points=[[vx + d1[0]*q, vy + d1[1]*q], [vx + (d1[0] + d2[0])*q, vy + (d1[1] + d2[1])*q], [vx + d2[0]*q, vy + d2[1]*q]]))
        else:
            a0 = math.atan2(d1[1], d1[0]); a1 = math.atan2(d2[1], d2[0]); da = (a1 - a0 + math.pi) % (2*math.pi) - math.pi
            out.append(dict(tool='pen', color=col, width=max(1.2, width*.7), points=[[vx + rr*math.cos(a0 + da*i/16), vy + rr*math.sin(a0 + da*i/16)] for i in range(17)]))
        if show or calc:
            txt = ('≈ ' if calc and not show else '') + fmt_num(val, 1) + '°'
            # önce açının içinde (yayın ötesinde), sığmazsa köşenin dışında
            o1, o2 = (P[m] for m in 'ABC' if m != n_)   # karşı kenara kadar olan iç mesafe
            ex_, ey_ = o2[0] - o1[0], o2[1] - o1[1]; den = bx*ey_ - by*ex_
            reach = ((o1[0] - vx)*ey_ - (o1[1] - vy)*ex_)/den if abs(den) > 1e-9 else size
            tries = [(vx, vy, bx, by, rr*1.1, min(size*.45, reach*.85))] if val >= 30 else []   # çok dar açı: doğrudan dışarı
            tries.append((vx, vy, -bx, -by, h*.8, h*6))
            jobs.append((0 if show else 1, txt, h*(.75 if show else .64), col, max(1.1, width*.55), tries))
    for key, (u, v, val) in sides.items():
        show = key in given_s and mode != 'aaa' and opts.get('sides', True)
        calc = key not in given_s and mode != 'aaa' and opts.get('calc', False)
        if not (show or calc): continue
        mx, my = (P[u][0] + P[v][0])/2, (P[u][1] + P[v][1])/2
        ex, ey = unit(P[v][0] - P[u][0], P[v][1] - P[u][1]); nx, ny = -ey, ex
        if nx*mx + ny*my < 0: nx, ny = -nx, -ny   # kenarın dış normali
        L = math.hypot(P[v][0] - P[u][0], P[v][1] - P[u][1])
        tries = [(mx + ex*o, my + ey*o, nx, ny, h*.3, h*3) for o in (0, L*.15, -L*.15, L*.28, -L*.28)]
        jobs.append((0 if show else 1, ('≈ ' if calc else '') + fmt_num(val), h*(.9 if show else .78), blue if show else grey, max(1.2, width*.6), tries))
    for _, txt, hs, col, wid, tries in sorted(jobs, key=lambda j: j[0]):   # verilenler önce yerini alır
        out += place(txt, hs, col, wid, tries)
    Ax, Ay = P['A']; Bx, By = P['B']; Cx, Cy = P['C']
    if opts.get('height'):   # C'den AB'ye yükseklik (kesikli), ayağında dik açı
        t = ((Cx - Ax)*(Bx - Ax) + (Cy - Ay)*(By - Ay))/((Bx - Ax)**2 + (By - Ay)**2); Hx, Hy = Ax + t*(Bx - Ax), Ay + t*(By - Ay)
        out.append(dict(tool='pen', color=grey, width=max(1.2, width*.7), dash=True, points=[[Cx, Cy], [Hx, Hy]]))
        if not 0 <= t <= 1: out.append(dict(tool='pen', color=grey, width=max(1.0, width*.5), dash=True, points=[[Ax, Ay] if t < 0 else [Bx, By], [Hx, Hy]]))
        q = size*.04; out.append(dict(tool='pen', color=grey, width=max(1.0, width*.5), points=[[Hx + q, Hy], [Hx + q, Hy - q], [Hx, Hy - q]]))
    if opts.get('bisector'):   # A'dan açıortay
        t = c/(b + c); Dx, Dy = Bx + (Cx - Bx)*t, By + (Cy - By)*t
        out.append(dict(tool='pen', color='#16a34a', width=max(1.2, width*.7), dash=True, points=[[Ax, Ay], [Dx, Dy]]))
    if opts.get('median'):   # A'dan kenarortay
        out.append(dict(tool='pen', color='#d946ef', width=max(1.2, width*.7), dash=True, points=[[Ax, Ay], [(Bx + Cx)/2, (By + Cy)/2]]))
    return out

class NumPad(QWidget):
    """Sayı tuş takımı (ölçü girişleri için): rakamlar, virgül, sil."""
    def __init__(self, parent, on_key):
        super().__init__(parent); g = QGridLayout(self); g.setSpacing(6); g.setContentsMargins(0, 0, 0, 0)
        for i, k in enumerate(['7', '8', '9', '⌫', '4', '5', '6', 'Temizle', '1', '2', '3', ',', '0', '00', '.', '°']):
            if k in ('.', '°'): continue
            b = QPushButton(k); b.setFocusPolicy(Qt.NoFocus); b.setMinimumHeight(52); b.setStyleSheet('font-size:21px;')
            b.clicked.connect(lambda checked=False, k_=k: on_key(k_)); g.addWidget(b, i//4, i % 4)

# ---- Canlı koordinat düzlemi: noktalar, doğrular, sonuçlar (kesir + ondalık) ----
from fractions import Fraction as _Fr
from PyQt5.QtGui import QFont, QFontMetricsF, QPainterPath
from PyQt5.QtWidgets import QFrame
from html import escape as html_escape
GEO_U = 24   # make_template('koordinat') birimi
GEO_COL = {'line': '#16a34a', 'par': '#0d9488', 'perp': '#ea580c', 'dist': '#0057ff', 'slope': '#c026d3', 'mid': '#b45309', 'cut': '#7c3aed'}
GEO_LINES = ('line', 'par', 'perp')
GEO_LETTERS = 'ABCDEFGHLNPRSTUVYZ'
def gq(v): return _Fr(str(v)).limit_denominator(100000)
def _minus(t): return t.replace('-', '−')
def gexact(q):   # sonlu ondalık mı (paydada yalnız 2 ve 5)
    d = q.denominator
    for f in (2, 5):
        while d % f == 0: d //= f
    return d == 1
def gdec(q, nd=2):
    t = ('%.*f' % (nd, float(q))).rstrip('0').rstrip('.')
    return _minus(t.replace('.', ',')) if t not in ('-0', '') else '0'
def gnum(q):   # koordinat yazımı: tam, sonlu ondalık ya da kesir
    if q.denominator == 1: return _minus(str(q.numerator))
    if gexact(q) and q.denominator <= 1000: return gdec(q, 4)
    return gfrac(q)
def gfrac(q): return _minus(str(q.numerator)) if q.denominator == 1 else _minus('%d/%d' % (q.numerator, q.denominator))
def gboth(q):   # 4/5 = 0,8  ·  1/3 ≈ 0,33  ·  2
    if q.denominator == 1: return gfrac(q)
    return gfrac(q) + (' = ' if gexact(q) and q.denominator <= 100 else ' ≈ ') + gdec(q)
def gpt(x, y):
    sep = ', ' if x.denominator == 1 and y.denominator == 1 else ' ; '
    return '(' + gnum(x) + sep + gnum(y) + ')'
def gpt_both(x, y):
    t = gpt(x, y)
    if all(q.denominator == 1 or (gexact(q) and q.denominator <= 1000) for q in (x, y)): return t
    return t + ' ≈ (' + gdec(x) + ' ; ' + gdec(y) + ')'
def _isqrt_q(q):
    import math as _m
    a, b = _m.isqrt(q.numerator), _m.isqrt(q.denominator)
    return _Fr(a, b) if a*a == q.numerator and b*b == q.denominator else None
def gdist(d2):
    import math as _m
    r = _isqrt_q(d2)
    if r is not None: return gnum(r)
    approx = ' ≈ ' + gdec(_Fr(_m.sqrt(d2)))
    if d2.denominator == 1:
        n = d2.numerator; k = 1; i = 2
        while i*i <= n:
            while n % (i*i) == 0: n //= i*i; k *= i
            i += 1
        return ('' if k == 1 else str(k)) + '√' + str(n) + approx
    return approx.strip()
def geq(L, dec=False):
    A, B, C = L; f = gdec if dec else gfrac
    if B == 0: return 'x = ' + f(C/A)
    m, c = -A/B, C/B; t = 'y = '
    if m != 0: t += ('' if m == 1 else '−' if m == -1 else f(m)) + 'x'
    if m == 0: t += f(c)
    elif c != 0: t += (' − ' if c < 0 else ' + ') + f(abs(c))
    return t
def geq_both(L):
    A, B, C = L; e = geq(L)
    if B == 0: frac_ = (C/A).denominator != 1
    else: frac_ = (A/B).denominator != 1 or (C/B).denominator != 1
    return e + ('   (' + geq(L, True) + ')' if frac_ else '')
def geo_find(marks):
    for m in marks:
        if m.get('tool') == 'geo': return m
    return None
def geo_eval(m):
    """Her nesnenin değeri: doğrular (A, B, C: Ax + By = C), noktalar, adlar."""
    P = [(gq(x), gq(y)) for x, y, _ in m['P']]; lines = {}; names = {}; nd = nm = nk = 0; out = []
    sub = '₀₁₂₃₄₅₆₇₈₉'
    def nm_(base, n): return base + ('' if n == 1 and base in 'MK' else ''.join(sub[int(c)] for c in str(n)))
    for k, o in enumerate(m['O']):
        t = o['t']; v = dict(t=t)
        try:
            if t in ('dist', 'line', 'slope', 'mid'):
                (ax, ay), (bx, by) = P[o['a']], P[o['b']]; v['ab'] = m['P'][o['a']][2] + m['P'][o['b']][2]
                if t == 'line':
                    A, B = by - ay, ax - bx
                    if A == 0 and B == 0: raise ValueError
                    lines[k] = (A, B, A*ax + B*ay)
                elif t == 'mid': nm += 1; v['pt'] = ((ax + bx)/2, (ay + by)/2); v['name'] = nm_('M', nm)
                elif t == 'dist': v['d2'] = (bx - ax)**2 + (by - ay)**2; v['seg'] = ((ax, ay), (bx, by))
                else: v['seg'] = ((ax, ay), (bx, by)); v['m'] = None if bx == ax else (by - ay)/(bx - ax); v['dx'] = bx - ax; v['dy'] = by - ay
            elif t in ('par', 'perp'):
                A, B, _ = lines[o['l']]; rx, ry = P[o['p']]
                if t == 'perp': A, B = -B, A
                lines[k] = (A, B, A*rx + B*ry); v['of'] = names[o['l']]; v['p'] = m['P'][o['p']][2]
                if t == 'perp':
                    A1, B1, C1 = lines[o['l']]; A2, B2, C2 = lines[k]; det = A1*B2 - A2*B1
                    v['foot'] = ((C1*B2 - C2*B1)/det, (A1*C2 - A2*C1)/det); v['dir'] = (-B1, A1)
            elif t == 'cut':
                (A1, B1, C1), (A2, B2, C2) = lines[o['l']], lines[o['m']]; v['of'] = (names[o['l']], names[o['m']])
                det = A1*B2 - A2*B1
                if det == 0: v['pt'] = None; v['same'] = A1*C2 == A2*C1 and B1*C2 == B2*C1
                else: nk += 1; v['pt'] = ((C1*B2 - C2*B1)/det, (A1*C2 - A2*C1)/det); v['name'] = nm_('K', nk)
            if k in lines: nd += 1; names[k] = 'd' + ''.join(sub[int(c)] for c in str(nd)); v['name'] = names[k]; v['L'] = lines[k]
        except (KeyError, IndexError, ZeroDivisionError, ValueError):
            v['bad'] = True
        out.append(v)
    return P, out
def geo_rows(m, vals):
    """Sonuç panosu satırları: (nesne no, renk, başlık, değer)."""
    rows = []
    for k, (o, v) in enumerate(zip(m['O'], vals)):
        if v.get('bad'): continue
        t = o['t']; c = GEO_COL[t]
        if t == 'dist': rows.append((k, c, '|%s| = ' % v['ab'], gdist(v['d2'])))
        elif t == 'slope': rows.append((k, c, 'm(%s) = Δy/Δx = ' % v['ab'], 'tanımsız (dikey doğru)' if v['m'] is None else gboth(v['m'])))
        elif t == 'mid': rows.append((k, c, '%s, %s’nin orta noktası: ' % (v['name'], v['ab']), v['name'] + gpt_both(*v['pt'])))
        elif t == 'line':
            L = v['L']; extra = []
            if L[1] != 0: extra.append(gpt(_Fr(0), L[2]/L[1]))
            if L[0] != 0 and not (L[1] != 0 and L[2] == 0): extra.append(gpt(L[2]/L[0], _Fr(0)))
            rows.append((k, c, '%s (%s): ' % (v['name'], v['ab']), geq_both(L) + ('   · eksenleri keser: ' + ' ve '.join(extra) if extra else '')))
        elif t in ('par', 'perp'):
            rows.append((k, c, '%s %s %s, %s’den: ' % (v['name'], '∥' if t == 'par' else '⊥', v['of'], v['p']), geq_both(v['L'])))
        elif t == 'cut':
            a, b = v['of']
            if v['pt'] is None: rows.append((k, c, '%s ∩ %s: ' % (a, b), 'çakışık (aynı doğru)' if v['same'] else 'kesişmez (paralel)'))
            else: rows.append((k, c, '%s ∩ %s = ' % (a, b), v['name'] + gpt_both(*v['pt'])))
    return rows
def halo_text(p, x, y, text, px, color, bold=False, align='l'):
    """Izgara üstünde okunaklı yazı: beyaz kenarlı."""
    f = QFont(p.font()); f.setPixelSize(max(1, int(px))); f.setBold(bold); fm = QFontMetricsF(f)
    w = fm.horizontalAdvance(text); x0 = x - w/2 if align == 'c' else x - w if align == 'r' else x
    path = QPainterPath(); path.addText(QPointF(x0, y), f, text)
    p.setBrush(Qt.NoBrush); p.setPen(QPen(QColor(255, 255, 255, 235), px*.28, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)); p.drawPath(path)
    p.setPen(Qt.NoPen); p.setBrush(QColor(color)); p.drawPath(path); p.setBrush(Qt.NoBrush)
    return QRectF(x0, y - fm.ascent(), w, fm.height())
def geo_layout(m, vals, W):
    """Panonun satır kutuları (sayfa birimi): [(nesne no, kutu, gizli mi)]."""
    rows = geo_rows(m, vals); f = QFont(); f.setPixelSize(13); fm = QFontMetricsF(f); fb = QFont(f); fb.setBold(True); fmb = QFontMetricsF(fb)
    out = []; y = 12
    for k, c, head, val in rows:
        hid = m['O'][k].get('h'); vtxt = '?' if hid else val
        w = 26 + fm.horizontalAdvance(head) + (34 if hid else fmb.horizontalAdvance(vtxt)) + 12
        out.append((k, QRectF(12, y, min(w, W*.62), 24), hid, c, head, vtxt)); y += 28
    return out
def geo_strokes(m, W, H):
    """PDF'ye: aynı çizim kalem çizgileri olarak (gizli cevaplar gizli kalır)."""
    P, vals = geo_eval(m); cx, cy, U = W/2, H/2, GEO_U; out = []
    X = lambda x: cx + float(x)*U; Y = lambda y: cy - float(y)*U
    def ln(a, b, col, w): out.append(dict(tool='pen', color=col, width=w, points=[list(a), list(b)]))
    for k, (o, v) in enumerate(zip(m['O'], vals)):
        if v.get('bad'): continue
        col = GEO_COL[o['t']]
        if 'L' in v:
            A, B, C = (float(t) for t in v['L'])
            if B == 0: ln((X(C/A), 0), (X(C/A), H), col, 2.2)
            else:
                xa, xb = -cx/U, cx/U; ya, yb = (C - A*xa)/B, (C - A*xb)/B
                pts = []
                for xx, yy in ((xa, ya), (xb, yb)):
                    if abs(yy) > cy/U: yy = math.copysign(cy/U, yy); xx = (C - B*yy)/A if A else xx
                    pts.append((X(xx), Y(yy)))
                ln(pts[0], pts[1], col, 2.2)
        elif o['t'] == 'dist': (ax, ay), (bx, by) = v['seg']; ln((X(ax), Y(ay)), (X(bx), Y(by)), col, 3)
        elif o['t'] == 'slope' and v['m'] is not None:
            (ax, ay), (bx, by) = v['seg']
            for (x0, y0), (x1, y1) in (((X(ax), Y(ay)), (X(bx), Y(ay))), ((X(bx), Y(ay)), (X(bx), Y(by)))):   # kesikli Δx, Δy
                L_ = math.hypot(x1 - x0, y1 - y0); n_ = max(1, int(L_/7))
                for j in range(0, n_, 2): ln((x0 + (x1 - x0)*j/n_, y0 + (y1 - y0)*j/n_), (x0 + (x1 - x0)*(j + 1)/n_, y0 + (y1 - y0)*(j + 1)/n_), col, 1.6)
            if not o.get('h'):
                if v['dx']: out += text_strokes('Δx = ' + gnum(v['dx']), (X(ax) + X(bx))/2, Y(ay) + (12 if by > ay else -8), 8, col, 1.1)
                if v['dy']: out += text_strokes('Δy = ' + gnum(v['dy']), X(bx) + 6, (Y(ay) + Y(by))/2, 8, col, 1.1, 'l')
        elif o['t'] in ('mid', 'cut') and v.get('pt') is not None:
            x, y = v['pt']; out += text_strokes(v['name'] + ('' if o.get('h') else gpt_canvas(x, y)), X(x) + 8, Y(y) + 12, 9, col, 1.2, 'l')
            out.append(dict(tool='pen', color=col, width=8, points=[[X(x), Y(y)]]))
    for i, (x, y) in enumerate(P):
        out.append(dict(tool='pen', color='#e8132b', width=9, points=[[X(x), Y(y)]]))
        out += text_strokes(m['P'][i][2] + gpt(x, y), X(x) + 8, Y(y) - 12, 10, '#111827', 1.3, 'l')
    y0 = 18
    for k, c, head, val in geo_rows(m, vals):
        for part in (head + ('?' if m['O'][k].get('h') else val)).split('   · '):
            out += text_strokes(part, 14, y0, 9, c, 1.1, 'l'); y0 += 16
    return out

def gpt_canvas(x, y):   # tahtadaki kısa yazım: tam/sonlu ondalık, değilse ≈ iki basamak
    if all(q.denominator == 1 or (gexact(q) and q.denominator <= 1000) for q in (x, y)): return gpt(x, y)
    return '≈(' + gdec(x) + ' ; ' + gdec(y) + ')'
def draw_geo(p, m, W, H, sel=()):
    P, vals = geo_eval(m); cx, cy, U = W/2, H/2, GEO_U
    X = lambda x: cx + float(x)*U; Y = lambda y: cy - float(y)*U
    p.save(); p.setClipRect(QRectF(0, 0, W, H)); p.setOpacity(1)
    placed = [QRectF(X(x) - 7, Y(y) - 7, 14, 14) for x, y in P]   # noktaların kendisi de dolu sayılır
    def label(ax, ay, text, px, color, bold=True, offs=None):
        """Yazıyı çevresindeki ilk boş yere koyar (öteki yazılara/noktalara binmez)."""
        f = QFont(p.font()); f.setPixelSize(max(1, int(px))); f.setBold(bold); fm = QFontMetricsF(f); w = fm.horizontalAdvance(text)
        offs = offs or [(9, -9, 'l'), (9, 19, 'l'), (-9, -9, 'r'), (-9, 19, 'l2'), (0, -14, 'c'), (0, 26, 'c'), (14, -24, 'l'), (14, 32, 'l'), (-14, -24, 'r'), (-14, 32, 'r')]
        first = None
        for dx, dy, al in offs:
            x0 = ax + dx - (w if al in ('r', 'l2') else w/2 if al == 'c' else 0); y0 = ay + dy
            box = QRectF(x0 - 2, y0 - fm.ascent() - 1, w + 4, fm.height() + 2)
            if first is None: first = (x0, y0, box)
            if 0 <= box.left() and box.right() <= W and 0 <= box.top() and box.bottom() <= H and not any(box.intersects(q) for q in placed):
                placed.append(box); halo_text(p, x0, y0, text, px, color, bold); return
        placed.append(first[2]); halo_text(p, first[0], first[1], text, px, color, bold)
    def line_seg(L):
        A, B, C = (float(v) for v in L)
        if B == 0: x = C/A; return (QPointF(X(x), 0), QPointF(X(x), H))
        xa, xb = -cx/U - 1, cx/U + 1
        return (QPointF(X(xa), Y((C - A*xa)/B)), QPointF(X(xb), Y((C - A*xb)/B)))
    hidden = lambda k: m['O'][k].get('h')
    names = []
    for k, (o, v) in enumerate(zip(m['O'], vals)):   # doğrular en altta
        if v.get('bad') or 'L' not in v: continue
        col = QColor(GEO_COL[o['t']]); a, b = line_seg(v['L'])
        if ('o', k) in sel: p.setPen(QPen(QColor(47, 124, 246, 70), 10, Qt.SolidLine, Qt.RoundCap)); p.drawLine(a, b)
        p.setPen(QPen(col, 2.4, Qt.SolidLine, Qt.RoundCap)); p.drawLine(a, b)
        names.append((a, b, v['name'], col.name()))
        if o['t'] == 'perp' and v.get('foot'):
            fx, fy = (float(t_) for t_ in v['foot']); A1, B1 = (float(t_) for t_ in v['dir'])
            n1 = math.hypot(A1, B1) or 1; u1 = (A1/n1, -B1/n1); A2, B2, _ = (float(t_) for t_ in v['L']); n2 = math.hypot(A2, B2) or 1; u2 = (-B2/n2, -A2/n2)
            e = 9; o_ = QPointF(X(fx), Y(fy)); a1 = QPointF(u1[0]*e, u1[1]*e); a2 = QPointF(u2[0]*e, u2[1]*e)
            p.setPen(QPen(col, 1.6)); p.drawPolyline(QPolygonF([o_ + a1, o_ + a1 + a2, o_ + a2]))
    for k, (o, v) in enumerate(zip(m['O'], vals)):
        if v.get('bad'): continue
        t = o['t']; col = QColor(GEO_COL[t])
        if t == 'dist':
            (ax, ay), (bx, by) = v['seg']; p.setPen(QPen(col, 3.4, Qt.SolidLine, Qt.RoundCap)); p.drawLine(QPointF(X(ax), Y(ay)), QPointF(X(bx), Y(by)))
        elif t == 'slope' and v['m'] is not None:
            (ax, ay), (bx, by) = v['seg']; pen = QPen(col, 2, Qt.DashLine); pen.setDashPattern([4, 3]); p.setPen(pen)
            p.drawPolyline(QPolygonF([QPointF(X(ax), Y(ay)), QPointF(X(bx), Y(ay)), QPointF(X(bx), Y(by))]))
    # noktalar
    for i, (x, y) in enumerate(P):
        c = QPointF(X(x), Y(y))
        if ('p', i) in sel: p.setPen(QPen(QColor('#2f7cf6'), 2.6)); p.setBrush(QColor(47, 124, 246, 40)); p.drawEllipse(c, 12, 12)
        p.setPen(QPen(Qt.white, 1.6)); p.setBrush(QColor('#e8132b')); p.drawEllipse(c, 5.5, 5.5); p.setBrush(Qt.NoBrush)
    for k, (o, v) in enumerate(zip(m['O'], vals)):   # türetilen noktalar
        if v.get('bad') or o['t'] not in ('mid', 'cut') or v.get('pt') is None: continue
        x, y = v['pt']; col = QColor(GEO_COL[o['t']]); p.setPen(QPen(Qt.white, 1.4)); p.setBrush(col); p.drawEllipse(QPointF(X(x), Y(y)), 5, 5); p.setBrush(Qt.NoBrush)
        placed.append(QRectF(X(x) - 6, Y(y) - 6, 12, 12))
    icpts = []   # doğruların eksenleri kestiği yerler
    for k, (o, v) in enumerate(zip(m['O'], vals)):
        if v.get('bad') or o['t'] != 'line': continue
        A, B, C = v['L']; col = GEO_COL['line']
        for ix, iy in ([(_Fr(0), C/B)] if B != 0 else []) + ([(C/A, _Fr(0))] if A != 0 and C != 0 else []):
            if abs(float(ix)) > cx/U or abs(float(iy)) > cy/U: continue
            p.setPen(QPen(QColor(col), 2)); p.setBrush(Qt.white); p.drawEllipse(QPointF(X(ix), Y(iy)), 4, 4); p.setBrush(Qt.NoBrush)
            placed.append(QRectF(X(ix) - 5, Y(iy) - 5, 10, 10)); icpts.append((ix, iy, col, not hidden(k)))
    # yazılar: önce asıl noktalar, sonra türetilenler, en son eksen kesimleri ve doğru adları
    for i, (x, y) in enumerate(P): label(X(x), Y(y), m['P'][i][2] + gpt(x, y), 15, '#111827')
    for k, (o, v) in enumerate(zip(m['O'], vals)):
        if v.get('bad'): continue
        col = GEO_COL[o['t']]
        if o['t'] in ('mid', 'cut') and v.get('pt') is not None:
            x, y = v['pt']; label(X(x), Y(y), v['name'] + ('' if hidden(k) else gpt_canvas(x, y)), 14, col)
        elif o['t'] == 'slope' and v['m'] is not None:
            (ax, ay), (bx, by) = v['seg']; h = hidden(k)
            if v['dx']: label((X(ax) + X(bx))/2, Y(ay), 'Δx = ' + ('?' if h else gnum(v['dx'])), 13, col, offs=[(0, 17 if by > ay else -8, 'c'), (0, -8 if by > ay else 17, 'c'), (0, 32, 'c')])
            if v['dy']: label(X(bx), (Y(ay) + Y(by))/2 + 5, 'Δy = ' + ('?' if h else gnum(v['dy'])), 13, col, offs=[(8, 0, 'l') if bx > ax else (-8, 0, 'r'), (-8, 0, 'r') if bx > ax else (8, 0, 'l'), (8, 18, 'l')])
    for ix, iy, col, show in icpts:
        if show: label(X(ix), Y(iy), gpt_canvas(ix, iy), 12, col, False)
    for a, b, name, col in names:   # doğru adı: sayfanın içinde, uca yakın boş yer
        d = b - a; n = math.hypot(d.x(), d.y()) or 1; nx, ny = -d.y()/n, d.x()/n
        if ny > 0: nx, ny = -nx, -ny
        for i in range(60):
            q = a + d*(.95 - i*.015)
            if 30 < q.x() < W - 30 and 30 < q.y() < H - 30: break
        label(q.x(), q.y(), name, 15, col, True, [(nx*16, ny*16 + 5, 'c'), (-nx*16, -ny*16 + 5, 'c'), (nx*30, ny*30 + 5, 'c')])
    p.restore()

class GeoPanel(QWidget):
    """Sonuçlar: ekranın sağında, katlanır, başlığından sürüklenir; “?” dokununca açılır."""
    def __init__(self, main):
        super().__init__(main.scroll); self.main = main; self.setObjectName('geopanel'); self.setAttribute(Qt.WA_StyledBackground, True)
        self.setStyleSheet('#geopanel{background:rgba(15,26,46,238);border:1px solid #2b3b5a;border-radius:16px;}'
                           '#geopanel QLabel{color:#dbe5f7;font-size:17px;background:transparent;}'
                           '#geopanel QPushButton{background:#22314d;color:#e8eefc;border:1px solid #33456a;border-radius:10px;font-size:17px;padding:2px 10px;}'
                           '#geopanel QPushButton#soru{background:#fef3c7;color:#92400e;border:1.5px solid #d97706;font-weight:700;min-width:46px;}')
        from PyQt5.QtWidgets import QLayout
        self.box = QVBoxLayout(self); self.box.setContentsMargins(14, 10, 14, 12); self.box.setSpacing(6); self.box.setSizeConstraint(QLayout.SetFixedSize)
        head = QHBoxLayout(); self.title = QLabel('Sonuçlar'); self.title.setStyleSheet('font-size:18px;font-weight:600;color:#ffffff;'); head.addWidget(self.title); head.addStretch(1)
        self.fold = QPushButton('–'); self.fold.setFocusPolicy(Qt.NoFocus); self.fold.setFixedSize(40, 34); self.fold.clicked.connect(self.toggle); head.addWidget(self.fold)
        self.box.addLayout(head); self.body = QWidget(); self.rows = QVBoxLayout(self.body); self.rows.setContentsMargins(0, 0, 0, 0); self.rows.setSpacing(6); self.box.addWidget(self.body)
        self.offset = None; self.drag = None; self.folded = False; self.hide()
    def toggle(self):
        self.folded = not self.folded; self.body.setVisible(not self.folded); self.fold.setText('+' if self.folded else '–'); self.adjustSize(); self.place()
    def fill(self, m):
        old = self.body; self.body = QWidget(); self.rows = QVBoxLayout(self.body); self.rows.setContentsMargins(0, 0, 0, 0); self.rows.setSpacing(6)
        self.box.replaceWidget(old, self.body); old.deleteLater(); self.body.setVisible(not self.folded)
        P, vals = geo_eval(m); rows = geo_rows(m, vals); n = 0
        for k, c, head, val in rows:
            line = QHBoxLayout(); line.setSpacing(8); hid = m['O'][k].get('h')
            dot = QLabel('●'); dot.setStyleSheet('color:%s;font-size:16px;' % c); line.addWidget(dot, 0, Qt.AlignTop)
            if hid:
                h_ = QLabel(head.strip()); line.addWidget(h_); q = QPushButton('?'); q.setObjectName('soru'); q.setFocusPolicy(Qt.NoFocus)
                q.clicked.connect(lambda checked=False, k_=k: self.main.geo_reveal(k_)); line.addWidget(q); line.addStretch(1)
            else:
                v_ = html_escape(val).replace('   · ', '<br>').replace('   (', '&nbsp;&nbsp;(')
                lab = QLabel('%s<b style="color:%s">%s</b>' % (html_escape(head), QColor(c).lighter(135).name(), v_)); lab.setTextFormat(Qt.RichText); line.addWidget(lab, 1)
            self.rows.addLayout(line); n += 1
        self.title.setText('Sonuçlar (%d)' % n if n else 'Sonuçlar'); self.body.adjustSize(); self.adjustSize()
        return n
    def place(self):
        vp = self.main.scroll.viewport().geometry(); self.adjustSize()
        if self.offset is None: x, y = vp.right() - self.width() - 12, vp.y() + 74
        else: x, y = vp.x() + self.offset.x(), vp.y() + self.offset.y()
        x = max(vp.x() + 4, min(x, vp.right() - self.width() - 4)); y = max(vp.y() + 4, min(y, vp.bottom() - min(self.height(), 60)))
        self.move(x, y); self.raise_()
    def resizeEvent(self, e):
        if self.isVisible(): QTimer.singleShot(0, self.place)
    def mousePressEvent(self, e): self.drag = e.globalPos() - self.pos()
    def mouseMoveEvent(self, e):
        if self.drag is not None:
            vp = self.main.scroll.viewport().geometry(); np_ = e.globalPos() - self.drag; self.offset = np_ - vp.topLeft(); self.place()
    def mouseReleaseEvent(self, e): self.drag = None

class GeoBar(QWidget):
    """Koordinat düzlemi araç çubuğu: yalnızca koordinat şablonunda görünür."""
    BTN = [('nokta', 'Nokta koy'), ('gir', 'Koordinat gir'), None, ('dist', 'Mesafe'), ('line', 'Doğru'), ('slope', 'Eğim'), ('mid', 'Orta nokta'),
           ('par', 'Paralel'), ('perp', 'Dik'), ('cut', 'Kesişim'), None, ('gizle', 'Cevabı gizle'), ('sil', 'Sil'), ('temizle', 'Temizle')]
    def __init__(self, main):
        super().__init__(main.scroll); self.main = main; self.setObjectName('geobar'); self.setAttribute(Qt.WA_StyledBackground, True)
        self.setStyleSheet('#geobar{background:rgba(15,26,46,236);border:1px solid #2b3b5a;border-radius:16px;}'
                           '#geobar QPushButton{background:#22314d;color:#e8eefc;border:1px solid #33456a;border-radius:11px;padding:8px 13px;font-size:15px;min-height:26px;}'
                           '#geobar QPushButton:checked{background:#2f7cf6;border-color:#2f7cf6;color:white;}'
                           '#geobar QPushButton[pasif="true"]{color:#6b7c99;background:#1a2640;border-color:#24324d;}'
                           '#geobar QFrame{background:#33456a;}')
        row = QHBoxLayout(self); row.setContentsMargins(8, 7, 8, 7); row.setSpacing(6); self.b = {}
        for it in self.BTN:
            if it is None:
                sep = QFrame(); sep.setFixedSize(1, 30); row.addWidget(sep); continue
            k, t = it; b = QPushButton(t); b.setFocusPolicy(Qt.NoFocus); b.setCheckable(k in ('nokta', 'gizle'))
            b.clicked.connect(lambda checked=False, k_=k: self.main.geo_action(k_)); row.addWidget(b); self.b[k] = b
        self.hide()
    def sync(self):
        o = self.main; sel = getattr(o.board, 'geo_sel', []); np_ = sum(1 for t, _ in sel if t == 'p'); nl = len(sel) - np_
        self.b['nokta'].setChecked(o.tool == 'geo'); self.b['gizle'].setChecked(getattr(o, 'geo_hide', False))
        ok = {'dist': np_ == 2, 'line': np_ == 2, 'slope': np_ == 2, 'mid': np_ == 2, 'par': np_ == 1 and nl == 1, 'perp': np_ == 1 and nl == 1, 'cut': nl == 2, 'sil': bool(sel)}
        for k, v in ok.items():
            b = self.b[k]
            if b.property('pasif') != (not v): b.setProperty('pasif', not v); b.style().unpolish(b); b.style().polish(b)
    def place(self):
        vp = self.main.scroll.viewport().geometry(); self.adjustSize()
        self.move(vp.x() + max(10, (vp.width() - self.width())//2), vp.y() + 10); self.raise_()

class GeoInput(QDialog):
    """Koordinat gir: x ve y, tahtanın kendi tuş takımıyla."""
    def __init__(self, main):
        super().__init__(main); self.main = main; self.setWindowTitle('Koordinat gir'); self.setModal(True)
        from PyQt5.QtWidgets import QLineEdit
        box = QVBoxLayout(self); box.setContentsMargins(22, 18, 22, 18); box.setSpacing(10)
        t = QLabel('Nokta koordinatı'); t.setStyleSheet('font-size:21px;font-weight:600;'); box.addWidget(t)
        row = QHBoxLayout(); row.setSpacing(8); box.addLayout(row); self.fields = []
        for i, name in enumerate(('x', 'y')):
            l = QLabel(('( ' if i == 0 else ' ;  ') + name + ' ='); l.setStyleSheet('font-size:20px;'); row.addWidget(l)
            e = QLineEdit(); e.setMinimumHeight(52); e.setFixedWidth(130); e.setAlignment(Qt.AlignCenter); e.setStyleSheet('font-size:22px;'); e.installEventFilter(self); e.setAttribute(Qt.WA_InputMethodEnabled, False); row.addWidget(e); self.fields.append(e)
        r_ = QLabel(' )'); r_.setStyleSheet('font-size:20px;'); row.addWidget(r_); row.addStretch(1)
        self.cur = self.fields[0]; self.err = QLabel(''); self.err.setStyleSheet('color:#ff8a95;font-size:15px;'); box.addWidget(self.err)
        pad = QHBoxLayout(); box.addLayout(pad); pad.addWidget(NumPad(self, self.key), 1)
        sign = QPushButton('±'); sign.setFocusPolicy(Qt.NoFocus); sign.setMinimumSize(70, 52); sign.setStyleSheet('font-size:24px;'); sign.clicked.connect(lambda: self.key('±')); pad.addWidget(sign, 0, Qt.AlignTop)
        bt = QHBoxLayout(); box.addLayout(bt)
        c = QPushButton('Vazgeç'); c.setMinimumHeight(48); c.clicked.connect(self.reject); bt.addWidget(c)
        ok = QPushButton('Noktayı koy'); ok.setMinimumHeight(48); ok.setObjectName('primary'); ok.clicked.connect(self.put); bt.addWidget(ok)
        self.fields[0].setFocus()
    def eventFilter(self, o, e):
        if e.type() == QEvent.FocusIn and o in self.fields: self.cur = o
        return False
    def key(self, k):
        e = self.cur; t = e.text()
        if k == '⌫': e.setText(t[:-1])
        elif k == 'Temizle': e.setText('')
        elif k == '±': e.setText(t[1:] if t.startswith('−') else '−' + t)
        elif k == ',':
            if ',' not in t: e.setText((t or '0') + ',')
        else: e.setText(t + k)
        e.setFocus()
    def put(self):
        try:
            x, y = (gq(float(f.text().replace('−', '-').replace(',', '.'))) for f in self.fields)
        except ValueError:
            self.err.setText('İki sayıyı da girin (ör. 2,5 ve −3).'); return
        page = self.main.doc[self.main.page].rect
        if abs(float(x)) > page.width/2/GEO_U or abs(float(y)) > page.height/2/GEO_U:
            self.err.setText('Bu nokta düzlemin dışında kalıyor (x: ±%d, y: ±%d).' % (page.width/2/GEO_U, page.height/2/GEO_U)); return
        self.main.board.geo_point(x, y); self.accept()

# ---- Yönetim: tahtanın sınıfı ve durum bildirimi (kişisel veri yok) ----
CLASS_GRADES = ['9', '10', '11', '12']
CLASS_BY_GRADE = {'9': 'ABCD', '10': 'ABCDEFGH', '11': 'ABCDEFGHI', '12': 'ABCDEFGHI'}   # okulun şubeleri (12-J'de tahta yok)
CLASS_SECTIONS = list('ABCDEFGHI')
CLASS_PLACES = ['Öğretmenler odası']   # sınıf dışında tahta olan tek yer
class ClassDialog(QDialog):
    """Bu tahta hangi sınıfta? Bir kez sorulur; Ayarlar'dan değiştirilebilir."""
    def __init__(self, main, current=''):
        super().__init__(main); self.setWindowTitle('Tahtanın sınıfı'); self.setModal(True); self.value = current or ''
        box = QVBoxLayout(self); box.setContentsMargins(24, 20, 24, 20); box.setSpacing(12)
        t = QLabel('Bu tahta hangi sınıfta?'); t.setStyleSheet('font-size:22px;font-weight:600;'); box.addWidget(t)
        n = QLabel('Yalnızca bir kez sorulur. Okul yönetimi tahtayı bu adla görür. Ayarlar’dan değiştirilebilir.'); n.setWordWrap(True); box.addWidget(n)
        self.grade = None; self.section = None; self.buttons = {}
        def row(label, items, kind):
            box.addWidget(QLabel(label)); r = QHBoxLayout(); r.setSpacing(8); box.addLayout(r)
            for it in items:
                b = QPushButton(it); b.setCheckable(True); b.setMinimumSize(64 if kind != 'place' else 120, 54); b.setStyleSheet('font-size:19px;')
                b.clicked.connect(lambda checked=False, v=it, k=kind: self.pick(k, v)); r.addWidget(b); self.buttons[(kind, it)] = b
            r.addStretch(1)
        row('Sınıf', CLASS_GRADES, 'grade'); row('Şube', CLASS_SECTIONS, 'section')
        box.addWidget(QLabel('Sınıf dışında bir yerse'))
        g = QGridLayout(); g.setSpacing(8); box.addLayout(g)
        for i, it in enumerate(CLASS_PLACES):
            b = QPushButton(it); b.setCheckable(True); b.setMinimumHeight(50); b.setStyleSheet('font-size:17px;')
            b.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed); b.setMinimumWidth(200)
            b.clicked.connect(lambda checked=False, v=it: self.pick('place', v)); g.addWidget(b, i//3, i % 3, 1, 3 if len(CLASS_PLACES) == 1 else 1); self.buttons[('place', it)] = b
        for c in range(3): g.setColumnStretch(c, 1)   # eşit genişlik
        box.addSpacing(4); self.shown = QLabel(); self.shown.setStyleSheet('font-size:20px;'); box.addWidget(self.shown)
        bt = QHBoxLayout(); box.addLayout(bt)
        later = QPushButton('Sonra'); later.setMinimumHeight(50); later.clicked.connect(self.reject); bt.addWidget(later)
        self.ok = QPushButton('Kaydet'); self.ok.setObjectName('primary'); self.ok.setMinimumHeight(50); self.ok.clicked.connect(self.accept); bt.addWidget(self.ok)
        if '-' in self.value and self.value.split('-')[0] in CLASS_GRADES:
            self.grade, self.section = self.value.split('-', 1)
        self.refresh()
    def pick(self, kind, v):
        if kind == 'place': self.grade = self.section = None; self.value = v
        else:
            if self.value in CLASS_PLACES: self.value = ''
            if kind == 'grade':
                self.grade = v
                if self.section and self.section not in CLASS_BY_GRADE.get(v, ''): self.section = None   # o seviyede olmayan şube
            else: self.section = v
            self.value = '%s-%s' % (self.grade, self.section) if self.grade and self.section else ''
        self.refresh()
    def refresh(self):
        valid = CLASS_BY_GRADE.get(self.grade, '')
        for (k, it), b in self.buttons.items():
            if k == 'section': b.setVisible(bool(valid) and it in valid)   # yalnız o seviyedeki şubeler
            b.setChecked((k == 'grade' and it == self.grade) or (k == 'section' and it == self.section) or (k == 'place' and it == self.value))
        self.shown.setText('Seçilen: <b>%s</b>' % (self.value or '—')); self.ok.setEnabled(bool(self.value))

class AcilMesaj(QWidget):
    """K-341: tahtayı kaplayan yönetim mesajı. Başlık ve metin kendi alanlarına sığacak boyda yazılır (üst üste binmez)."""
    def __init__(self, main):
        super().__init__(main); self.main = main; self.m = {}; self.mid = None
        self.setAttribute(Qt.WA_StyledBackground, False)
        self.ok = QPushButton('Okudum', self); self.ok.setFocusPolicy(Qt.NoFocus); self.ok.clicked.connect(lambda: self.main.acil_okudum(self.mid))
        self.hide()
    def goster(self, m):
        self.m = dict(m); self.mid = m.get('id'); self.yerlestir(); self.update()
    def resizeEvent(self, e): self.yerlestir()
    def yerlestir(self):
        k = min(self.width()/1600, self.height()/900) or 1
        self.ok.setStyleSheet('QPushButton{background:#281404;color:#ff9a3a;border:2px solid #ff9a3a;border-radius:%dpx;padding:0 %dpx;font-size:%dpx;font-weight:800;}' % (int(16*k), int(48*k), max(16, int(30*k))))
        self.ok.setFixedHeight(max(52, int(76*k))); self.ok.adjustSize()
        self.ok.move((self.width() - self.ok.width())//2, self.height() - self.ok.height() - int(46*k))
    @staticmethod
    def sigdir(p, rect, text, fam, bold, px_max, px_min, flags):
        from PyQt5.QtGui import QFont, QFontMetrics
        px = px_max
        while True:
            f = QFont(fam); f.setPixelSize(int(px)); f.setBold(bold)
            br = QFontMetrics(f).boundingRect(rect.toRect(), flags, text)
            if (br.height() <= rect.height() and br.width() <= rect.width()) or px <= px_min: return f
            px = max(px_min, px * 0.92)
    def paintEvent(self, e):
        from PyQt5.QtGui import QLinearGradient, QRadialGradient
        fams = ui_fonts(); fam = fams.get('Poppins-Medium') or 'Sans'; famb = fams.get('Poppins-Bold') or fam
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing)
        W, H = self.width(), self.height(); k = min(W/1600, H/900) or 1
        ry = self.m.get('resim_yol')
        if ry and os.path.isfile(ry) and not (str(self.m.get('baslik') or '').strip() or str(self.m.get('metin') or '').strip()):
            if getattr(self, '_rp', (None, None))[0] != ry: self._rp = (ry, QPixmap(ry))
            pm = self._rp[1]
            if not pm.isNull():   # K-417: yalnız fotoğraf: tahtanın tamamı, çerçevesiz
                p.fillRect(self.rect(), QColor('#000000'))
                s_ = min(W/pm.width(), H/pm.height()); w_, h_ = pm.width()*s_, pm.height()*s_
                p.setRenderHint(QPainter.SmoothPixmapTransform); p.drawPixmap(QRectF((W - w_)/2, (H - h_)/2, w_, h_), pm, QRectF(pm.rect()))
                p.end(); return
        g = QRadialGradient(W/2, H/2, max(W, H)*0.7); g.setColorAt(0, QColor('#2a1406')); g.setColorAt(1, QColor('#0b0705')); p.fillRect(self.rect(), g)
        p.setPen(QPen(QColor('#ff9a3a'), max(4, 6*k))); p.setBrush(Qt.NoBrush); p.drawRoundedRect(QRectF(6*k, 6*k, W - 12*k, H - 12*k), 22*k, 22*k)
        from PyQt5.QtGui import QFont
        f = QFont(famb); f.setPixelSize(max(14, int(26*k))); f.setLetterSpacing(QFont.AbsoluteSpacing, 6*k); p.setFont(f); p.setPen(QColor('#ff9a3a'))
        p.drawText(QRectF(0, 34*k, W, 50*k), Qt.AlignCenter, 'OKUL YÖNETİMİ')
        f2 = QFont(fam); f2.setPixelSize(max(12, int(22*k))); p.setFont(f2); p.setPen(QColor('#9fb3cc'))
        p.drawText(QRectF(0, 34*k, W - 50*k, 50*k), Qt.AlignVCenter | Qt.AlignRight, time.strftime('%H.%M'))
        bas = str(self.m.get('baslik') or '').strip(); met = str(self.m.get('metin') or '').strip()
        ust = 110*k; alt = self.ok.y() - 30*k; x0 = W*0.08; gen = W*0.84
        ry = self.m.get('resim_yol')   # K-415: fotoğraf: yazı varsa üstte büyük, altta yazı; yoksa alanın tamamı
        if ry and os.path.isfile(ry):
            if getattr(self, '_rp', (None, None))[0] != ry: self._rp = (ry, QPixmap(ry))
            pm = self._rp[1]
            if not pm.isNull():
                yaziH = 0 if not (bas or met) else (alt - ust) * (0.26 if not (bas and met) else 0.36)
                ra = QRectF(x0, ust, gen, alt - ust - yaziH - (16*k if yaziH else 0))
                s_ = min(ra.width()/pm.width(), ra.height()/pm.height()); w_, h_ = pm.width()*s_, pm.height()*s_
                rr = QRectF(ra.center().x() - w_/2, ra.top() + (ra.height() - h_)/2, w_, h_)
                p.setRenderHint(QPainter.SmoothPixmapTransform); p.drawPixmap(rr, pm, QRectF(pm.rect()))
                p.setPen(QPen(QColor('#ff9a3a'), max(2, 3*k))); p.setBrush(Qt.NoBrush); p.drawRoundedRect(rr.adjusted(-2, -2, 2, 2), 8*k, 8*k)
                ust = ra.bottom() + 16*k
                if not yaziH: p.end(); return
        fl = int(Qt.AlignHCenter | Qt.AlignVCenter | Qt.TextWordWrap)
        if bas:
            r1 = QRectF(x0, ust, gen, (alt - ust)*0.34); r2 = QRectF(x0, r1.bottom() + 20*k, gen, alt - r1.bottom() - 20*k)
            fb = self.sigdir(p, r1, bas, famb, True, 96*k, 22*k, fl)
            p.setFont(fb); p.setPen(QColor('#ffffff')); p.drawText(r1, fl, bas)
        else: r2 = QRectF(x0, ust, gen, alt - ust)
        if met:
            fm = self.sigdir(p, r2, met, fam, False, 60*k, 14*k, fl)
            p.setFont(fm); p.setPen(QColor('#ffe3c6')); p.drawText(r2, fl, met)
        p.end()
    def mousePressEvent(self, e): e.accept()   # arkadaki tahtaya dokunma gitmez

class MessageBar(QFrame):
    """Panelden gelen mesaj: tahtanın üstünde şerit (yazıyı kapatmaz)."""
    KIND = {'bilgi': ('#1f3c73', '#eaf2ff', 'Okul yönetimi', 'Tamam'), 'not': ('#5a4610', '#fff3d1', 'Not', 'Tamam'),
            'pdf': ('#0f4a43', '#e2f6ef', 'Belge', 'Kapat'), 'hata': ('#6e1c1c', '#ffecec', 'Hatalı soru', 'Sınıfa okudum'),
            'surum': ('#3a2d72', '#efeaff', 'Yeni sürüm yüklendi', 'Yeniden başlat')}
    def __init__(self, main):
        super().__init__(main); self.main = main; self.setObjectName('msgbar'); self.setMaximumHeight(280)
        row = QHBoxLayout(self); row.setContentsMargins(16, 10, 10, 10); row.setSpacing(10)
        self.text = QLabel(); self.text.setWordWrap(True); self.text.setTextFormat(Qt.RichText); row.addWidget(self.text, 1)
        self.count = QLabel(); row.addWidget(self.count)
        self.next = QPushButton('Sonraki'); self.next.clicked.connect(main.next_message); row.addWidget(self.next)
        self.open = QPushButton('Aç'); self.open.setObjectName('primary'); self.open.clicked.connect(main.open_message_pdf); row.addWidget(self.open)
        self.ok = QPushButton(); self.ok.clicked.connect(main.ack_message); row.addWidget(self.ok)
        for b in (self.next, self.open, self.ok): b.setMinimumHeight(46); b.setFocusPolicy(Qt.NoFocus)
    def show_msg(self, m, i, n):
        bg, fg, title, ok = self.KIND.get(m.get('tur'), self.KIND['bilgi'])
        self.setStyleSheet('QFrame#msgbar{background:%s;border-radius:12px;} QFrame#msgbar QLabel{color:%s;background:transparent;font-size:19px;}' % (bg, fg))
        esc = lambda t: html_escape(str(t or '')).replace('\n', '<br>')
        head = title
        if m.get('tur') == 'pdf': head = 'Belge: ' + str((m.get('pdf') or {}).get('ad') or 'PDF')
        if m.get('baslik'): head += ' · ' + str(m['baslik'])
        body = esc(m.get('metin'))
        self.text.setText('<b>%s</b>%s' % (esc(head), ('<br>' + body) if body else ''))
        self.count.setText('%d/%d' % (i + 1, n) if n > 1 else ''); self.count.setVisible(n > 1); self.next.setVisible(n > 1)
        self.open.setText('Sonra' if m.get('tur') == 'surum' else 'Aç'); self.open.setObjectName('' if m.get('tur') == 'surum' else 'primary')
        self.ok.setObjectName('primary' if m.get('tur') == 'surum' else '')
        for b in (self.open, self.ok): b.style().unpolish(b); b.style().polish(b)
        self.open.setVisible(m.get('tur') == 'surum' or (m.get('tur') == 'pdf' and bool(m.get('pdf_yol')))); self.ok.setText(ok); self.show()

class TriangleDialog(QDialog):
    """Ölçülü üçgen: ne bilindiğini seç, değerleri gir, tahtaya koy."""
    def __init__(self, main):
        super().__init__(main); self.main = main; self.setWindowTitle('Ölçülü üçgen'); self.setModal(True)
        from PyQt5.QtWidgets import QLineEdit, QCheckBox
        scr = QApplication.primaryScreen().availableGeometry(); self.resize(min(860, scr.width()-60), min(760, scr.height()-60))
        box = QVBoxLayout(self); box.setContentsMargins(22, 18, 22, 18); box.setSpacing(10)
        t = QLabel('Ölçülü üçgen'); t.setStyleSheet('font-size:21px;font-weight:600;'); box.addWidget(t)
        box.addWidget(QLabel('Ne biliniyor?'))
        row = QHBoxLayout(); row.setSpacing(6); box.addLayout(row); self.mode_buttons = {}
        for key, name, _ in TRI_MODES:
            b = QPushButton(name); b.setCheckable(True); b.setMinimumHeight(46); b.clicked.connect(lambda checked=False, k=key: self.set_mode(k)); row.addWidget(b); self.mode_buttons[key] = b
        body = QHBoxLayout(); body.setSpacing(18); box.addLayout(body)
        left = QVBoxLayout(); left.setSpacing(8); body.addLayout(left, 3)
        self.grid = QGridLayout(); self.grid.setVerticalSpacing(8); self.grid.setHorizontalSpacing(12); left.addLayout(self.grid)
        self.labels = []; self.fields = []
        for i in range(3):
            l = QLabel(); e = QLineEdit(); e.setMinimumHeight(50); e.setStyleSheet('font-size:21px;'); e.installEventFilter(self); e.setAttribute(Qt.WA_InputMethodEnabled, False); e.textChanged.connect(self.check)
            self.grid.addWidget(l, i, 0); self.grid.addWidget(e, i, 1); self.labels.append(l); self.fields.append(e)
        self.result = QLabel(); self.result.setWordWrap(True); self.result.setStyleSheet('font-size:16px;'); left.addWidget(self.result)
        cfg = main.tri_cfg if hasattr(main, 'tri_cfg') else {}
        self.opts = {}
        for key, name, on in (('names', 'Köşe adları (A, B, C)', True), ('sides', 'Verilen kenarlar', True), ('angles', 'Verilen açılar', True),
                              ('calc', 'Hesaplanan değerler', False), ('height', 'Yükseklik (C’den)', False), ('bisector', 'Açıortay (A’dan)', False), ('median', 'Kenarortay (A’dan)', False)):
            c = QCheckBox(name); c.setChecked(cfg.get(key, on)); left.addWidget(c); self.opts[key] = c
        left.addStretch(1)
        right = QVBoxLayout(); body.addLayout(right, 2)
        self.pad = NumPad(self, self.key); right.addWidget(self.pad); right.addStretch(1)
        btns = QHBoxLayout(); box.addLayout(btns)
        no = QPushButton('Vazgeç'); no.setMinimumHeight(50); no.clicked.connect(self.reject); btns.addWidget(no)
        self.ok = QPushButton('Tahtaya koy'); self.ok.setObjectName('primary'); self.ok.setMinimumHeight(50); self.ok.clicked.connect(self.place); btns.addWidget(self.ok)
        self.target = None; self.set_mode(cfg.get('mode', 'sas'))
    def eventFilter(self, o, e):
        if e.type() in (QEvent.FocusIn, QEvent.MouseButtonPress) and o in self.fields: self.target = o
        return False
    def key(self, k):
        t = self.target or next((f for f in self.fields if f.isVisible()), None)
        if t is None: return
        if k == '⌫': t.backspace()
        elif k == 'Temizle': t.clear()
        else: t.insert(k)
    def set_mode(self, key):
        self.mode = key
        for k, b in self.mode_buttons.items(): b.setChecked(k == key)
        names = dict((k, f) for k, _, f in TRI_MODES)[key]
        for i in range(3):
            vis = i < len(names); self.labels[i].setVisible(vis); self.fields[i].setVisible(vis)
            if vis: self.labels[i].setText(names[i] + ('  (derece)' if 'açı' in names[i] else '')); self.labels[i].setStyleSheet('font-size:18px;')
        self.target = self.fields[0]; self.fields[0].setFocus(); self.check()
    def values(self):
        n = len(dict((k, f) for k, _, f in TRI_MODES)[self.mode]); out = []
        for f in self.fields[:n]:
            t = f.text().strip().replace(',', '.').replace('°', '')
            try: out.append(float(t))
            except ValueError: return None
        return out
    def check(self):
        v = self.values()
        if v is None: self.result.setText('Değerleri girin.'); self.result.setStyleSheet('font-size:16px;color:#a9b9cf;'); self.ok.setEnabled(False); return None
        sol = triangle_solve(self.mode, v)
        if isinstance(sol, str): self.result.setText(sol); self.result.setStyleSheet('font-size:16px;color:#ff8a95;'); self.ok.setEnabled(False); return None
        a, b, c, A, B, C = sol
        txt = 'Geçerli üçgen · ' + ('|AB| ≈ %s · |BC| ≈ %s · |CA| ≈ %s · ' % (fmt_num(c), fmt_num(a), fmt_num(b)) if self.mode != 'aaa' else '') + 'A ≈ %s° · B ≈ %s° · C ≈ %s°' % (fmt_num(A, 1), fmt_num(B, 1), fmt_num(C, 1))
        self.result.setText('✓ ' + txt); self.result.setStyleSheet('font-size:16px;color:#4ade80;'); self.ok.setEnabled(True); return sol
    def place(self):
        sol = self.check()
        if sol is None: return
        opts = {k: c.isChecked() for k, c in self.opts.items()}; self.main.tri_cfg = dict(opts, mode=self.mode)
        b = self.main.board; vis = b.visibleRegion().boundingRect(); size = min(vis.width(), vis.height())/b.scale*.42
        self.main.pending_triangle = triangle_marks(sol, self.mode, opts, size, okunur_renk(self.main), max(2, self.main.width.value()))
        self.main.pending_label = None; self.accept(); self.main.set_tool('place_tri')


# ---------------------------------------------------------------------------
# Şablonlar: koordinat düzlemi, sayı doğrusu, izometrik, milimetrik (yeni boş tahta)
TEMPLATES = [('koordinat', 'Koordinat düzlemi'), ('sayi', 'Sayı doğrusu'), ('izometrik', 'İzometrik'), ('milimetrik', 'Milimetrik')]

def make_template(key, width=960, height=540):
    doc = fitz.open(); page = doc.new_page(width=width, height=height); sh = page.new_shape()
    dark = (.2, .25, .33); light = (.84, .88, .94)
    def label(x, y, t, size=8):
        page.insert_text((x - fitz.get_text_length(t, fontsize=size)/2, y), t, fontsize=size, color=dark)
    if key == 'koordinat':
        u = 24; cx, cy = width/2, height/2
        for i in range(-int(cx//u), int(cx//u) + 1): sh.draw_line((cx + i*u, 0), (cx + i*u, height))
        for j in range(-int(cy//u), int(cy//u) + 1): sh.draw_line((0, cy + j*u), (width, cy + j*u))
        sh.finish(color=light, width=.6)
        sh.draw_line((8, cy), (width - 8, cy)); sh.draw_line((cx, height - 8), (cx, 8))
        sh.draw_polyline([(width - 18, cy - 5), (width - 8, cy), (width - 18, cy + 5)]); sh.draw_polyline([(cx - 5, 18), (cx, 8), (cx + 5, 18)])
        sh.finish(color=dark, width=1.4)
        for i in range(-int(cx//u) + 1, int(cx//u)):
            if i: sh.draw_line((cx + i*u, cy - 3), (cx + i*u, cy + 3)); label(cx + i*u, cy + 13, str(i))
        for j in range(-int(cy//u) + 1, int(cy//u)):
            if j: sh.draw_line((cx - 3, cy - j*u), (cx + 3, cy - j*u)); page.insert_text((cx - 6 - fitz.get_text_length(str(j), fontsize=8), cy - j*u + 3), str(j), fontsize=8, color=dark)
        sh.finish(color=dark, width=1); label(cx - 7, cy + 13, '0'); label(width - 14, cy - 8, 'x', 11); label(cx + 12, 16, 'y', 11)
    elif key == 'sayi':
        for yy, n in ((height*.25, 10), (height*.5, 10), (height*.75, 10)):
            x0, x1 = 40, width - 40; step = (x1 - x0)/(2*n + 2)
            sh.draw_line((x0 - 10, yy), (x1 + 10, yy)); sh.draw_polyline([(x1, yy - 5), (x1 + 10, yy), (x1, yy + 5)]); sh.draw_polyline([(x0, yy - 5), (x0 - 10, yy), (x0, yy + 5)])
            for i in range(-n, n + 1):
                x = width/2 + i*step; big = i == 0
                sh.draw_line((x, yy - (8 if big else 5)), (x, yy + (8 if big else 5))); label(x, yy + 20, str(i), 9)
        sh.finish(color=dark, width=1.3)
    elif key == 'izometrik':
        u = 24; hrow = u*math.sqrt(3)/2; j = 0; y = 0.0
        while y <= height + 1:
            off = (u/2) if j % 2 else 0; x = off
            while x <= width + 1: sh.draw_circle((x, y), 1.3); x += u
            y += hrow; j += 1
        sh.finish(color=None, fill=(.45, .53, .66))
    elif key == 'milimetrik':
        mm = 72/25.4
        for i in range(int(width/mm) + 1):
            x = i*mm; w_ = .9 if i % 10 == 0 else .55 if i % 5 == 0 else .25
            sh.draw_line((x, 0), (x, height)); sh.finish(color=(.93, .55, .45) if i % 10 == 0 else (.96, .78, .72), width=w_)
        for i in range(int(height/mm) + 1):
            y = i*mm; w_ = .9 if i % 10 == 0 else .55 if i % 5 == 0 else .25
            sh.draw_line((0, y), (width, y)); sh.finish(color=(.93, .55, .45) if i % 10 == 0 else (.96, .78, .72), width=w_)
    sh.commit(); doc.set_metadata({'title': APP_NAME, 'keywords': 'UMAL-template:' + key}); return doc

class TemplateDialog(QDialog):
    def __init__(self, main):
        super().__init__(main); self.main = main; self.setWindowTitle('Şablonlar'); self.setModal(True)
        box = QVBoxLayout(self); box.setContentsMargins(22, 18, 22, 18); box.setSpacing(12)
        t = QLabel('Şablonlar · seçilen zeminle yeni boş tahta açılır'); t.setStyleSheet('font-size:19px;font-weight:600;'); box.addWidget(t)
        g = QGridLayout(); g.setSpacing(14); box.addLayout(g)
        for i, (key, name) in enumerate(TEMPLATES):
            d = make_template(key); pix = d[0].get_pixmap(matrix=fitz.Matrix(.36, .36), alpha=False); d.close()
            b = QPushButton(name); b.setIcon(QIcon(QPixmap.fromImage(QImage(pix.samples, pix.width, pix.height, pix.stride, QImage.Format_RGB888).copy())))
            b.setIconSize(QSize(pix.width, pix.height)); b.setStyleSheet('QPushButton{padding:10px;font-size:17px;}'); b.setMinimumHeight(pix.height + 24)
            b.clicked.connect(lambda checked=False, k=key, n=name: self.pick(k, n)); g.addWidget(b, i//2, i % 2)
        c = QPushButton('Vazgeç'); c.setMinimumHeight(48); c.clicked.connect(self.reject); box.addWidget(c)
    def pick(self, key, name):
        m = self.main; self.accept(); m.start_tab(name); m.replace(make_template(key)); m.tabs_changed(); m.set_tool('pen')

