# Grafik çizici: y = f(x) (log, ln, üstel, sin/cos/tan, mutlak değer, kök…) → yeni tahta sekmesinde vektör grafik
import re as _re
_SUB = str.maketrans('₀₁₂₃₄₅₆₇₈₉', '0123456789')
def graph_compile(expr):
    """Öğretmenin yazdığını güvenli Python ifadesine çevirir. Döner: (işlev, hata)."""
    s0 = expr.strip()
    s = s0.lower().replace(' ', '').replace('−', '-').replace('·', '*').replace('×', '*').replace('÷', '/')
    s = _re.sub(r'^(y|f\(x\))=', '', s)
    if not s: return None, 'Fonksiyonu yazın.'
    s = _re.sub(r'(\d),(\d)', r'\1.\2', s)
    s = s.replace('²', '**2').replace('³', '**3').replace('π', 'pi').replace('^', '**')
    s = _re.sub(r'log([₀-₉]+)\(', lambda m: 'logb(%s,' % m.group(1).translate(_SUB), s)
    s = _re.sub(r'log_(\d+(?:\.\d+)?)\(', r'logb(\1,', s)
    s = _re.sub(r'(?<![a-z])log\(', 'lg(', s)
    s = s.replace('√(', 'sqrt(').replace('kök(', 'nroot(')   # K-352: ⁿ√ şablonu kök(n, x)
    s = _re.sub(r'√(\d+(?:\.\d+)?|x)', r'sqrt(\1)', s)
    for _ in range(3): s = _re.sub(r'\|([^|]+)\|', r'abs(\1)', s)
    s = _re.sub(r'(\d|\))(?=[a-z(])', r'\1*', s)
    s = _re.sub(r'(?<![a-z])x(?=[\d(a-z])', 'x*', s)
    s = _re.sub(r'(?<![a-z])pi(?=[\dx(a-z])', 'pi*', s)
    s = _re.sub(r'(?<![a-z])e(?=[\dx(])', 'e*', s)
    if _re.search(r'[^0-9a-z+\-*/().,]', s): return None, 'Anlaşılmayan işaret var.'
    names = set(_re.findall(r'[a-z]+', s)) - {'x', 'sin', 'cos', 'tan', 'sqrt', 'lg', 'ln', 'logb', 'abs', 'pi', 'e', 'cot', 'nroot'}
    if names: return None, 'Tanınmayan: ' + ', '.join(sorted(names))
    ns = dict(sin=math.sin, cos=math.cos, tan=math.tan, cot=lambda v: 1/math.tan(v), sqrt=math.sqrt, lg=math.log10, ln=math.log,
              logb=lambda b_, v: math.log(v, b_), abs=abs, pi=math.pi, e=math.e,
              nroot=lambda n_, v: math.copysign(abs(v)**(1/n_), v) if v < 0 and int(n_) == n_ and int(n_) % 2 == 1 else v**(1/n_))
    try: code = compile(s, '<f>', 'eval')
    except SyntaxError: return None, 'Yazım hatası (parantezleri denetleyin).'
    def f(x):
        try:
            v = eval(code, {'__builtins__': {}}, dict(ns, x=x))
            if isinstance(v, complex) or v != v or abs(v) > 1e12: return None
            return float(v)
        except (ValueError, ZeroDivisionError, OverflowError, TypeError): return None
        except Exception: return None
    try: eval(code, {'__builtins__': {}}, dict(ns, x=1.37))
    except (NameError, SyntaxError, TypeError): return None, 'Yazım hatası.'
    except Exception: pass
    return f, None

def grafik_latex(ifade):
    """K-350: Grafik çizicide öğretmenin yazdığı fonksiyonu kitap yazımına çevirir (x^2 → x², 1/(x-2) → kesir, √(x) → kök)."""
    import re
    s = ifade.strip().replace('**', '^').replace('−', '-').replace('×', '*').replace('÷', '/')
    s = re.sub(r'^(y|f\(x\))\s*=\s*', '', s)
    s = s.replace('²', '^2').replace('³', '^3').replace('ˣ', '^x').replace('π', 'pi')
    s = re.sub(r'log([₀-₉]+)', lambda m: 'log_' + m.group(1).translate(str.maketrans('₀₁₂₃₄₅₆₇₈₉', '0123456789')), s)
    def grup(t, i):   # t[i] == '(' → eşleşen ')' konumu
        d = 0
        for j in range(i, len(t)):
            d += {'(': 1, ')': -1}.get(t[j], 0)
            if d == 0: return j
        return len(t) - 1
    def islenen_sag(t, i):   # i'den başlayan işlenen: (…), sayı, harf dizisi(+(…)), √…
        if i < len(t) and t[i] == '(':
            j = grup(t, i); return t[i+1:j], j + 1, True
        m = re.match(r'(sqrt|√|log_\d+|log|ln|sin|cos|tan|cot|abs)?\s*', t[i:])
        if m and m.group(1) and i + m.end() < len(t) and t[i + m.end()] == '(':
            j = grup(t, i + m.end()); return t[i:j+1], j + 1, False
        m = re.match(r'\d+(?:[.,]\d+)?|[a-z]', t[i:])
        if m: return m.group(0), i + m.end(), False
        return '', i, False
    def cevir(t):
        out = ''; i = 0
        while i < len(t):
            c = t[i]
            if t.startswith('kök(', i):   # ⁿ√: kök(n, x)
                k = i + 3; j = grup(t, k); ic = t[k+1:j]; d_ = 0; vir = -1
                for q, ch in enumerate(ic):
                    d_ += {'(': 1, ')': -1}.get(ch, 0)
                    if ch == ',' and d_ == 0: vir = q; break
                out += ('\\sqrt[' + cevir(ic[:vir]) + ']{' + cevir(ic[vir+1:]) + '}') if vir >= 0 else '\\sqrt{' + cevir(ic) + '}'; i = j + 1; continue
            if t.startswith('sqrt(', i) or t.startswith('√(', i):
                k = t.index('(', i); j = grup(t, k); out += '\\sqrt{' + cevir(t[k+1:j]) + '}'; i = j + 1; continue
            if c == '√':
                a, i2, _ = islenen_sag(t, i + 1); out += '\\sqrt{' + cevir(a) + '}'; i = i2; continue
            if c == '^':
                a, i2, par = islenen_sag(t, i + 1); out += '^{' + cevir(a) + '}'; i = i2; continue
            if c == '/':
                # sol işlenen: son eklenen parça (…) ya da sayı/harf/üs
                sol = re.search(r'(\\left\(.*\\right\)|\([^()]*\)|\\sqrt\{[^{}]*\}|[0-9a-z.,]+(?:\^\{[^{}]*\})?)$', out)
                a, i2, _ = islenen_sag(t, i + 1)
                if sol:
                    pay = sol.group(1); out = out[:sol.start()]
                    if pay.startswith('(') and pay.endswith(')'): pay = pay[1:-1]
                    out += '\\frac{' + pay + '}{' + cevir(a) + '}'; i = i2; continue
            if t.startswith('log_', i):
                m = re.match(r'log_(\d+)', t[i:]); out += '\\log_{' + m.group(1) + '}'; i += m.end(); continue
            m = re.match(r'(sin|cos|tan|cot|ln|log|abs|pi)', t[i:])
            if m:
                out += {'pi': '\\pi ', 'abs': ''}.get(m.group(1), '\\' + m.group(1) + ' '); i += m.end(); continue
            if c == '*':
                prev = out.rstrip()[-1:] ; nxt = t[i+1:i+2]
                out += '' if (prev.isdigit() and (nxt.isalpha() or nxt == '(')) else '\\cdot '; i += 1; continue
            out += c; i += 1
        return out
    return cevir(s.replace(' ', ''))

GRAFIK_PARAM = ('a', 'b', 'c', 'k')   # kaydırıcılı harfler (K-352)
GRAFIK_RENK = ('#22e8ff', '#ffb020', '#ff6b9a')
GRAFIK_ISARET = (('kok', 'Kökler'), ('ykes', 'y eksenini kestiği nokta'), ('tepe', 'Tepe noktası'), ('simetri', 'Simetri ekseni'),
                 ('asimptot', 'Asimptot'), ('kesisim', 'Kesişim'), ('teget', 'Teğet'), ('alan', 'Alan'), ('tablo', 'Değer tablosu'))

def grafik_parametreler(ifade):
    """Fonksiyonda geçen kaydırıcı harfleri (a, b, c, k) — sin, tan, abs gibi adların içindekiler sayılmaz."""
    import re
    s = re.sub(r'(sin|cos|tan|cot|abs|sqrt|ln|log|kök|pi)', ' ', ifade.lower())
    return [p for p in GRAFIK_PARAM if re.search(r'(?<![a-zçğıöşü])%s(?![a-zçğıöşü])' % p, s)]

def grafik_yerlestir(ifade, degerler):
    """Kaydırıcı harflerin yerine değerleri koyar: 2a·x → 2(1.5)·x."""
    import re
    s = ifade
    for p, v in (degerler or {}).items():
        s = re.sub(r'(?<![a-zçğıöşü])%s(?![a-zçğıöşü])' % p, '(%s)' % fmt_num(v, 2).replace(',', '.'), s)
    return s

def grafik_goster(ifade, degerler):
    """Etiket için: kaydırıcı değerleri yerine konmuş, sadeleşmiş yazı (a=−1, b=1, c=1 → −x² + x + 1)."""
    import re
    s = ifade.replace('−', '-').replace('*', '·').replace(' ', '')
    for p, v in (degerler or {}).items():
        t = fmt_num(v, 2).replace(',', '.')
        s = re.sub(r'(?<![a-zçğıöşü])%s·?(?=[a-z(√])' % p, 'K%s·' % t, s)   # katsayı
        s = re.sub(r'(?<![a-zçğıöşü])%s(?![a-zçğıöşü])' % p, '(%s)' % t, s)
    s = re.sub(r'K1·', '', s); s = re.sub(r'K-1·', '-', s); s = re.sub(r'K0·[^+\-]*', '0', s)
    s = re.sub(r'K(-?[\d.]+)·', r'\1', s)
    s = re.sub(r'\+\((-[\d.]+)\)', r'\1', s); s = re.sub(r'\((\d[\d.]*)\)', r'\1', s); s = re.sub(r'^\((-[\d.]+)\)', r'\1', s)
    s = re.sub(r'([+\-])0(?![\d.])', '', s); s = re.sub(r'^0\+', '', s); s = s.replace('+-', '-').replace('--', '+')
    return s or '0'

def grafik_derle(ifade, degerler=None):
    """graph_compile + kutu (□) denetimi + kaydırıcı değerleri. Döner: (işlev, hata)."""
    if '□' in ifade: return None, 'Kutuları doldurun.'
    return graph_compile(grafik_yerlestir(ifade, degerler))

GRAFIK_H = 540   # grafik sayfanın üst kısmı; altı kara tahta yazı alanı (Atlas'ın cevabı oraya yazılır, grafiğin üstüne binmez)
def degme_noktalari(fn, x0, x1, N, yr):
    """K-366: fn'in sıfıra işaret değiştirmeden değdiği yerler (çift kök / teğet eğriler). Örneklerde |fn| yerel en küçükse
    altın oranla incelir; değer ~0 ise nokta sayılır. Sıradan (işaret değiştiren) kökler başka yerde bulunur."""
    out = []; xs = [x0 + (x1 - x0)*k/N for k in range(N + 1)]; vs = [fn(x) for x in xs]
    tol = max(1e-9, abs(yr)*1e-6)
    for k in range(1, N):
        a, b, c = vs[k-1], vs[k], vs[k+1]
        if None in (a, b, c) or a*c < 0 or abs(b) > abs(yr)*0.02: continue
        if not (abs(b) <= abs(a) and abs(b) <= abs(c)): continue
        lo_, hi_ = xs[k-1], xs[k+1]
        for _ in range(80):
            c1 = hi_ - (hi_ - lo_)*.618; c2 = lo_ + (hi_ - lo_)*.618; f1, f2 = fn(c1), fn(c2)
            if f1 is None or f2 is None: break
            if abs(f1) < abs(f2): hi_ = c2
            else: lo_ = c1
        xm = (lo_ + hi_)/2; vm = fn(xm)
        if vm is not None and abs(vm) < tol*10 and (fn(xm - (x1 - x0)/N) or 0)*(fn(xm + (x1 - x0)/N) or 0) >= 0:
            if all(abs(xm - q) > (x1 - x0)/200 for q in out): out.append(xm)
    return out

def graph_build(funcs, isaret=None, W=960, H=GRAFIK_H, ek=None, bilgi=None, alt=540):
    """K-352: kara tahta görünümlü grafik. funcs: [(yazı, işlev, renk)] ya da (yazı, işlev, renk, 'soluk').
    isaret: tek işaret ('kok', 'ykes', 'tepe', 'simetri', 'asimptot', 'kesisim', 'teget', 'alan', 'tablo') — yalnız o gösterilir.
    ek: {'teget': x0, 'alan': (a, b), 'iz': x, 'gorunum': (x0, x1, lo, hi)}. bilgi: dict verilirse doldurulur
    (gorunum, egriler [sayfa noktaları, renk], ozellikler, tablo, isaret_tablosu). Döner: fitz belge."""
    ek = ek or {}
    asil = [f for f in funcs if len(f) < 4]; tum = list(funcs)
    xs_try = [i/25 for i in range(-250, 251)]
    pos_only = all(all(fn(x) is None for x in xs_try if x <= 0) and any(fn(x) is not None for x in xs_try if x > 0) for _, fn, _, *r in asil) if asil else False
    keys = []
    for _, fn, _, *r in asil:
        prev = None
        for x in xs_try:
            v = fn(x)
            if prev is not None:
                pv = prev[1]
                if (v is None) != (pv is None): keys.append(x)
                elif v is not None and pv is not None and abs(v - pv) < 5 and pv*v <= 0: keys.append(x)
            prev = (x, v)
        vals = [(x, fn(x)) for x in xs_try]
        for (xa, a), (xb, b), (xc_, c) in zip(vals, vals[1:], vals[2:]):
            if None not in (a, b, c) and (b - a)*(c - b) < 0 and abs(c - a) < 5: keys.append(xb)
    if keys and len(keys) <= 10:
        x0, x1 = min(keys) - 2.5, max(keys) + 2.5
        if x1 - x0 < 9: c_ = (x0 + x1)/2; x0, x1 = c_ - 4.5, c_ + 4.5
        if x1 - x0 > 22: x0, x1 = max(x0, -11), min(x1, 11)
    else: x0, x1 = (-2.0, 12.0) if pos_only else (-7.0, 7.0)
    if pos_only: x0 = max(x0, -1.5)
    ys = []
    for _, fn, _, *r in (asil or tum):
        for i in range(401):
            v = fn(x0 + (x1 - x0)*i/400)
            if v is not None and abs(v) < 60: ys.append(v)
    ys.sort()
    lo, hi = (ys[int(len(ys)*.05)], ys[int(len(ys)*.95)]) if ys else (-5, 5)
    lo, hi = min(lo, 0), max(hi, 0); span = max(4.0, hi - lo); lo -= span*.15; hi += span*.15
    lo, hi = max(lo, -15), min(hi, 15)
    m = 40; pw, ph = W - 2*m, H - 2*m
    if ek.get('gorunum'): x0, x1, lo, hi = ek['gorunum']   # kaydırıcıyla oynarken görüntü sabit kalsın
    else:
        ux, uy = pw/(x1 - x0), ph/(hi - lo)
        if .55 < ux/uy < 1.8:   # birimler yakınsa eşit al
            unit = min(ux, uy); xc, yc = (x0 + x1)/2, (lo + hi)/2
            x0, x1 = xc - pw/unit/2, xc + pw/unit/2; lo, hi = yc - ph/unit/2, yc + ph/unit/2
    ux, uy = pw/(x1 - x0), ph/(hi - lo)
    X = lambda x: m + (x - x0)*ux; Y = lambda y: m + (hi - y)*uy
    doc = fitz.open(); page = doc.new_page(width=W, height=H + alt)
    zemin = BOARD_FILLS['kt_kareli']; page.draw_rect(page.rect, color=None, fill=zemin)
    sh = page.new_shape()
    for gx in range(0, W + 1, 24): sh.draw_line((gx, 0), (gx, H + alt))
    for gy in range(0, H + alt + 1, 24): sh.draw_line((0, gy), (W, gy))
    sh.finish(color=(1, 1, 1), width=.6, stroke_opacity=.06); sh.commit()
    fonts = pdf_fonts(); beyaz = (1, 1, 1); soluk_b = (.78, .84, .9)
    dv = next((q for q in ('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', '/usr/share/fonts/dejavu/DejaVuSans.ttf', os.path.join(os.environ.get('WINDIR', 'C:\\Windows'), 'Fonts', 'seguisym.ttf')) if os.path.isfile(q)), None)
    pop = fitz.Font(fontfile=fonts['m']) if fonts['m'] else None
    def olc_(t, size):
        f = fonts['m']
        if pop is not None and dv and any(not pop.has_glyph(ord(ch)) for ch in t): f = dv
        return fitz.Font(fontfile=f).text_length(t, fontsize=size) if f else fitz.get_text_length(t, fontsize=size)
    def text(x, y, t, size, color=soluk_b, anchor='c'):
        f = fonts['m']
        if pop is not None and dv and any(not pop.has_glyph(ord(ch)) for ch in t): f = dv
        wdt = olc_(t, size)
        xx = x - wdt/2 if anchor == 'c' else x - wdt if anchor == 'r' else x
        if f: page.insert_text((xx, y), t, fontsize=size, fontname='umalm' if f == fonts['m'] else 'umaldv', fontfile=f, color=color)
        else: page.insert_text((xx, y), t, fontsize=size, color=color)
    def rgb(c): q = QColor(c); return (q.redF(), q.greenF(), q.blueF())
    def hap(x, y, t, col, ust=True, sag=True):   # yuvarlak etiket (koyu zemin, renkli kenar)
        w_ = olc_(t, 12) + 20; h_ = 22
        lx = x + 12 if sag else x - 12 - w_; ly = y - 14 - h_ if ust else y + 12
        lx = min(max(lx, 4), W - w_ - 4); ly = min(max(ly, 4), H - h_ - 4)
        page.draw_rect(fitz.Rect(lx, ly, lx + w_, ly + h_), color=rgb(col), fill=(.055, .125, .22), width=1.4, radius=.5)
        text(lx + w_/2, ly + 15.5, t, 12, beyaz)
    def nokta(x, y, col):
        page.draw_circle((X(x), Y(y)), 9, color=None, fill=rgb(col), fill_opacity=.22)
        page.draw_circle((X(x), Y(y)), 4.6, color=beyaz, fill=rgb(col), width=1.6)
    def kesik(xa, ya, xb, yb, col, w=1.3):
        page.draw_line((xa, ya), (xb, yb), color=rgb(col), width=w, dashes='[5 4] 0', stroke_opacity=.9)
    # eksenler
    step = next(k for k in (1, 2, 5, 10, 20) if k*ux >= 30); stepy = next(k for k in (1, 2, 5, 10, 20) if k*uy >= 26)
    ax_y = Y(0) if lo < 0 < hi else (Y(lo) if lo >= 0 else Y(hi)); ax_x = X(0) if x0 < 0 < x1 else X(x0)
    sh = page.new_shape()
    sh.draw_line((m - 10, ax_y), (W - m + 12, ax_y)); sh.draw_line((ax_x, H - m + 10), (ax_x, m - 12))
    sh.draw_polyline([(W - m + 3, ax_y - 6), (W - m + 12, ax_y), (W - m + 3, ax_y + 6)]); sh.draw_polyline([(ax_x - 6, m - 3), (ax_x, m - 12), (ax_x + 6, m - 3)])
    for i in range(math.ceil(x0/step)*step, math.floor(x1) + 1, step):
        if i: sh.draw_line((X(i), ax_y - 4), (X(i), ax_y + 4))
    for j in range(math.ceil(lo/stepy)*stepy, math.floor(hi) + 1, stepy):
        if j: sh.draw_line((ax_x - 4, Y(j)), (ax_x + 4, Y(j)))
    sh.finish(color=beyaz, width=1.5, stroke_opacity=.85); sh.commit()
    for i in range(math.ceil(x0/step)*step, math.floor(x1) + 1, step):
        if i: text(X(i), ax_y + 17, str(i).replace('-', '−'), 10.5)
    for j in range(math.ceil(lo/stepy)*stepy, math.floor(hi) + 1, stepy):
        if j: text(ax_x - 8, Y(j) + 4, str(j).replace('-', '−'), 10.5, anchor='r')
    text(W - m + 6, ax_y - 10, 'x', 14, beyaz); text(ax_x + 12, m - 2, 'y', 14, beyaz)
    # eğriler
    N = 1600; yr = hi - lo; egriler = []; asimptotlar = []; ornek = []
    for f_ in tum:
        label, fn, col = f_[0], f_[1], f_[2]; soluk = len(f_) > 3
        pts = [(x0 + (x1 - x0)*i/N, fn(x0 + (x1 - x0)*i/N)) for i in range(N + 1)]
        if not soluk: ornek.append((label, fn, col, pts))
        parcalar = []; seg = []; asym = []
        def flush():
            if len(seg) > 1: parcalar.append([(X(a), Y(b)) for a, b in seg])
            seg.clear()
        for (xa, ya), (xb, yb) in zip(pts, pts[1:]):
            if ya is None or yb is None:
                if ya is not None and yb is None and abs(ya) > yr: asym.append(xb)
                if ya is None and yb is not None and abs(yb) > yr: asym.append(xa)
                flush(); continue
            if abs(yb - ya) > yr*1.5 and ya*yb < 0: asym.append((xa + xb)/2); flush(); continue
            inside_a, inside_b = lo <= ya <= hi, lo <= yb <= hi
            if inside_a and not seg: seg.append((xa, ya))
            if inside_a and inside_b: seg.append((xb, yb))
            elif inside_a and not inside_b:
                yy = hi if yb > hi else lo; xx = xa + (xb - xa)*(yy - ya)/(yb - ya); seg.append((xx, yy)); flush()
            elif not inside_a and inside_b:
                yy = hi if ya > hi else lo; xx = xa + (xb - xa)*(yy - ya)/(yb - ya); seg.extend([(xx, yy), (xb, yb)])
        flush()
        for p_ in parcalar:
            if soluk: page.draw_polyline(p_, color=rgb(col), width=2.2, dashes='[6 5] 0', stroke_opacity=.45, closePath=False)
            else:
                page.draw_polyline(p_, color=rgb(col), width=9, stroke_opacity=.16, closePath=False, lineCap=1, lineJoin=1)   # parıltı
                page.draw_polyline(p_, color=rgb(col), width=3.4, closePath=False, lineCap=1, lineJoin=1)
        if not soluk:
            egriler.append((parcalar, col))
            for xa in sorted(set(round(v, 2) for v in asym)):
                xv = round(xa*2)/2 if abs(xa*2 - round(xa*2)) < .03 else xa; asimptotlar.append((xv, col))
    def refine(g, a, b):
        ga = g(a)
        for _ in range(48):
            c = (a + b)/2; gc = g(c)
            if gc is None: return None
            if (gc < 0) == (ga < 0): a, ga = c, gc
            else: b = c
        return (a + b)/2
    ozellik = {'kok': [], 'ykes': [], 'tepe': [], 'kesisim': [], 'asimptot': asimptotlar}
    for label, fn, col, pts in ornek:
        for (xa, ya), (xb, yb) in zip(pts, pts[1:]):
            if ya is None or yb is None or abs(yb - ya) > yr: continue
            if ya == 0 or ya*yb < 0:
                r = xa if ya == 0 else refine(fn, xa, xb)
                if r is not None and all(abs(r - d[0]) > (x1 - x0)/200 for d in ozellik['kok'] if d[2] == col): ozellik['kok'].append((r, 0.0, col))
        for r in degme_noktalari(fn, x0, x1, N, yr):   # K-366: x eksenine değen kök (çift kök, ör. (x − 1)²): işaret değişmez
            if all(abs(r - d[0]) > (x1 - x0)/200 for d in ozellik['kok'] if d[2] == col): ozellik['kok'].append((r, 0.0, col))
        if x0 < 0 < x1:
            v = fn(0)
            if v is not None and lo < v < hi: ozellik['ykes'].append((0.0, v, col))
        for i in range(1, len(pts) - 1):
            (xa, ya), (xb, yb), (xc_, yc_) = pts[i-1], pts[i], pts[i+1]
            if None in (ya, yb, yc_) or abs(yc_ - ya) > yr*.5: continue
            if (yb - ya)*(yc_ - yb) < 0:
                a_, b_ = xa, xc_
                for _ in range(60):
                    c1 = b_ - (b_ - a_)*.618; c2 = a_ + (b_ - a_)*.618; f1, f2 = fn(c1), fn(c2)
                    if f1 is None or f2 is None: break
                    if (f1 < f2) == (yb < ya): b_ = c2
                    else: a_ = c1
                xe = (a_ + b_)/2; ye = fn(xe)
                if ye is not None and lo < ye < hi: ozellik['tepe'].append((xe, ye, col))
    if len(ornek) >= 2:
        for i in range(len(ornek)):
            for j in range(i + 1, len(ornek)):
                f, g = ornek[i][1], ornek[j][1]
                def d(x, f=f, g=g):
                    a, b = f(x), g(x); return None if a is None or b is None else a - b
                prev = None
                for k_ in range(N + 1):
                    x = x0 + (x1 - x0)*k_/N; v = d(x)
                    if v is not None and prev is not None and prev[1]*v < 0 and abs(v - prev[1]) < yr:
                        r = refine(d, prev[0], x)
                        if r is not None and f(r) is not None and lo < f(r) < hi: ozellik['kesisim'].append((r, f(r), '#ffffff'))
                    if v == 0 and f(x) is not None and lo < f(x) < hi: ozellik['kesisim'].append((x, f(x), '#ffffff'))
                    prev = (x, v) if v is not None else None
                for r in degme_noktalari(d, x0, x1, N, yr):   # K-366: birbirine değen (teğet) eğriler: fark işaret değiştirmez
                    if f(r) is not None and lo < f(r) < hi and all(abs(r - q[0]) > (x1 - x0)/200 for q in ozellik['kesisim']): ozellik['kesisim'].append((r, f(r), '#ffffff'))
    # değer tablosu ve türevin işareti (ilk fonksiyon)
    tablo = []; isaret_tab = []
    if ornek:
        fn = ornek[0][1]; bas = math.ceil(max(x0, -3)); son = min(math.floor(x1), bas + 6)
        for x in range(bas, son + 1):
            v = fn(x)
            if v is not None: tablo.append((x, v))
        dfn = lambda x: (lambda a, b: None if a is None or b is None else (b - a)/2e-4)(fn(x - 1e-4), fn(x + 1e-4))
        kr = sorted(t[0] for t in ozellik['tepe'] if t[2] == ornek[0][2])
        sinirlar = [x0] + kr + [x1]
        for a, b in zip(sinirlar, sinirlar[1:]):
            dv_ = dfn((a + b)/2)
            if dv_ is not None: isaret_tab.append((a, b, '+' if dv_ > 0 else '−'))
    # seçilen işaret: yalnız o
    if isaret in ('kok', 'ykes', 'tepe', 'kesisim'):
        for x, y, col in ozellik[isaret][:12]:
            if isaret == 'tepe':
                kesik(X(x), ax_y, X(x), Y(y), col); kesik(ax_x, Y(y), X(x), Y(y), col)
            nokta(x, y, col if isaret != 'kesisim' else '#ffffff')
            t = ('x = ' + fmt_num(x)) if isaret == 'kok' else ('(%s, %s)' % (fmt_num(x), fmt_num(y))) if isaret != 'tepe' else ('T(%s, %s)' % (fmt_num(x), fmt_num(y)))
            hap(X(x), Y(y), t, col if isaret != 'kesisim' else '#22e8ff', ust=isaret != 'tepe' or y > (lo + hi)/2, sag=X(x) < W*.7)
    elif isaret == 'simetri':
        for x, y, col in ozellik['tepe'][:3]:
            kesik(X(x), m - 4, X(x), H - m + 4, col, 1.6); hap(X(x), m + 26, 'x = ' + fmt_num(x), col, ust=False)
    elif isaret == 'asimptot':
        for xv, col in asimptotlar[:4]:
            kesik(X(xv), m - 4, X(xv), H - m + 4, col, 1.6); hap(X(xv), m + 26, 'x = ' + fmt_num(xv), col, ust=False)
    elif isaret == 'teget' and ornek:
        fn, col = ornek[0][1], ornek[0][2]; xt = ek.get('teget', (x0 + x1)/2); yt = fn(xt)
        if yt is not None:
            eg = (lambda a, b: None if a is None or b is None else (b - a)/2e-4)(fn(xt - 1e-4), fn(xt + 1e-4))
            if eg is not None:
                xa, xb = x0, x1
                page.draw_line((X(xa), Y(yt + eg*(xa - xt))), (X(xb), Y(yt + eg*(xb - xt))), color=(1, 1, 1), width=2, stroke_opacity=.9)
                nokta(xt, yt, '#ffffff'); hap(X(xt), Y(yt), 'eğim = ' + fmt_num(eg), '#ffffff', sag=X(xt) < W*.7)
                ozellik['teget'] = [(xt, yt, eg)]
    elif isaret == 'alan' and ornek:
        fn, col = ornek[0][1], ornek[0][2]; a, b = ek.get('alan', (max(x0, 0), min(x1, 2)))
        a, b = min(a, b), max(a, b); n_ = 200; poly = [(X(a), Y(0))]; top = 0.0
        for i in range(n_ + 1):
            x = a + (b - a)*i/n_; v = fn(x)
            if v is None: continue
            v = min(max(v, lo), hi); poly.append((X(x), Y(v)))
            if i: top += v*(b - a)/n_
        poly.append((X(b), Y(0)))
        if len(poly) > 3:
            page.draw_polyline(poly, color=None, fill=rgb(col), fill_opacity=.28, closePath=True)
            hap(X((a + b)/2), Y(0), 'alan ≈ ' + fmt_num(abs(top), 2), col, ust=False)
            ozellik['alan'] = [(a, b, top)]
    elif isaret == 'tablo':
        for x, v in tablo:
            if lo < v < hi: nokta(x, v, ornek[0][2])
    if ek.get('iz') is not None and ornek:   # parmakla iz sürme
        fn, col = ornek[0][1], ornek[0][2]; xi = ek['iz']; yi = fn(xi)
        if yi is not None and lo < yi < hi:
            kesik(X(xi), ax_y, X(xi), Y(yi), '#ffffff', 1); kesik(ax_x, Y(yi), X(xi), Y(yi), '#ffffff', 1)
            nokta(xi, yi, col); hap(X(xi), Y(yi), '(%s, %s)' % (fmt_num(xi), fmt_num(yi)), col, sag=X(xi) < W*.7)
    # fonksiyon adları sol üstte, kitap yazımıyla
    yy = m + 6
    for label, fn, col, pts in ornek:
        try: kt = formul_diz(formul_coz('y = ' + grafik_latex(label)), 15, olc_)
        except Exception: kt = None
        lx = m + 16
        if kt is None: text(lx + 18, yy + 14, 'y = ' + label, 14, rgb(col), 'l'); yy += 24; continue
        base = yy + max(14.0, kt.a)
        page.draw_circle((lx + 5, base - 5), 5, color=None, fill=rgb(col))
        for o in kt.op:
            if o[0] == 't': text(lx + 18 + o[1], base + o[2], o[3], o[4], rgb(col), 'l')
            else: page.draw_line((lx + 18 + o[1], base + o[2]), (lx + 18 + o[3], base + o[4]), color=rgb(col), width=max(.9, o[5]))
        yy = base + kt.d + 12
    doc.set_metadata({'title': 'Grafik — ' + APP_NAME, 'keywords': 'UMAL-graph'})
    if bilgi is not None:
        bilgi.update(gorunum=(x0, x1, lo, hi), egriler=egriler, ozellik=ozellik, tablo=tablo, isaret_tablosu=isaret_tab, W=W, H=H, m=m)
    return doc

def formul_pixmap(latex, boy=30, renk='#eef6ff'):
    """Kitap yazımıyla tek satır formül (Grafik çizicide alanın altındaki önizleme)."""
    h, op = cevap_diz('$' + latex + '$', 4000, boy, _atlas_olc)
    xs = [o[1] + _atlas_olc(o[3], o[4]) for o in op if o[0] == 't'] + [o[3] for o in op if o[0] == 'l']
    w = int(max(xs or [10]) + 12)
    im = QImage(w, max(1, int(h + boy*0.5)), QImage.Format_ARGB32_Premultiplied); im.fill(Qt.transparent)
    p = QPainter(im); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing); c = QColor(renk)
    for o in op:
        if o[0] == 't':
            x = o[1]; p.setPen(c)
            for parca, f in _atlas_kos(o[3], o[4]): p.setFont(f); p.drawText(QPointF(x + 4, o[2]), parca); x += _atlas_olc(parca, o[4])
        elif o[0] == 'l': p.setPen(QPen(c, o[5], Qt.SolidLine, Qt.RoundCap)); p.drawLine(QPointF(o[1] + 4, o[2]), QPointF(o[3] + 4, o[4]))
    p.end(); return QPixmap.fromImage(im)

def grafik_resmi(doc, genislik):
    r_ = doc[0].rect; z = genislik/r_.width; pix = doc[0].get_pixmap(matrix=fitz.Matrix(z, z), alpha=False, clip=fitz.Rect(0, 0, r_.width, min(r_.height, GRAFIK_H)))
    return QPixmap.fromImage(QImage(pix.samples, pix.width, pix.height, pix.stride, QImage.Format_RGB888).copy())

GRAFIK_STIL = ('QDialog{background:qlineargradient(x1:0,y1:0,x2:0,y2:1,stop:0 #112540,stop:1 #0b182b);} QLabel{color:#eef6ff;}'
               'QPushButton{color:#eef6ff;background:#13233a;border:1.5px solid #2a4468;border-radius:12px;font-size:20px;padding:6px;}'
               'QPushButton:pressed{background:#1d3150;} QPushButton#sablon{border-color:#22e8ff;color:#7ff6ff;background:#0e2a3e;}'
               'QPushButton#cip{border-radius:18px;padding:8px 14px;font-size:17px;background:#0a1628;}'
               'QPushButton#cip:checked{border-color:#ffb020;color:#ffd27a;background:#2a1d06;}'
               'QPushButton#birincil{background:#22e8ff;color:#04202a;border-color:#22e8ff;font-weight:700;}'
               'QLineEdit{background:#0a1628;color:#eef6ff;border:2px solid #2a4468;border-radius:14px;padding:8px 12px;font-size:24px;}'
               'QLineEdit:focus{border-color:#22e8ff;} QCheckBox{color:#cfe3f7;font-size:16px;}'
               'QSlider::groove:horizontal{height:8px;background:#1d3150;border-radius:4px;} QSlider::handle:horizontal{width:24px;margin:-8px 0;border-radius:12px;background:#22e8ff;}')

class GraphDialog(QDialog):
    """K-352: Grafik çizici — kitap yazımı, kutulu şablonlar (log tabanı ve içi ayrı), 3 fonksiyon, kaydırıcılar,
    dokununca yalnız o işaret (kökler, tepe noktası…), parmakla iz sürme; kara tahta görünümü."""
    COLORS = GRAFIK_RENK
    SABLON = [('xⁿ', '^(□)'), ('□/□', '(□)/(□)'), ('√□', '√(□)'), ('ⁿ√□', 'kök(□,□)'), ('|□|', '|□|'), ('log□(□)', 'log_□(□)'),
              ('ln(□)', 'ln(□)'), ('e^□', 'e^(□)'), ('aˣ', '□^x'), ('sin', 'sin(□)'), ('cos', 'cos(□)'), ('tan', 'tan(□)')]
    TUS = ['x', 'π', '(', ')', ',', '⌫', '7', '8', '9', '+', '−', '·', '4', '5', '6', '1', '2', '3', '0', '◀', '▶', 'Temizle']
    def __init__(self, main):
        super().__init__(main); self.main = main; self.setWindowTitle('Grafik çizici'); self.setModal(True); self.setStyleSheet(GRAFIK_STIL)
        from PyQt5.QtWidgets import QLineEdit, QCheckBox, QSlider
        scr = QApplication.primaryScreen().availableGeometry(); self.resize(min(1860, scr.width()-30), min(1020, scr.height()-30))
        box = QHBoxLayout(self); box.setContentsMargins(22, 18, 22, 18); box.setSpacing(22)
        left = QVBoxLayout(); left.setSpacing(8); box.addLayout(left, 0)
        t = QLabel('Grafik çizici'); t.setStyleSheet('font-size:30px;font-weight:800;color:#7ff6ff;'); left.addWidget(t)
        a_ = QLabel('Kitaptaki gibi yazın; şablondaki kutulara dokunup doldurun.'); a_.setStyleSheet('font-size:15px;color:#9fb3cc;'); left.addWidget(a_)
        cfg = getattr(main, 'graph_cfg', {}) or {}; self.fields = []; self.errs = []; self.onizler = []
        for i, col in enumerate(self.COLORS):
            row = QHBoxLayout(); dot = QLabel('●'); dot.setStyleSheet('color:%s;font-size:26px;' % col); row.addWidget(dot)
            pre = QLabel('y ='); pre.setStyleSheet('font-size:22px;'); row.addWidget(pre)
            e = QLineEdit(cfg.get('f%d' % i, 'x² − 4x + 3' if i == 0 else '')); e.setMinimumHeight(52); e.setMinimumWidth(500)
            e.setPlaceholderText(('ikinci' if i == 1 else 'üçüncü') + ' fonksiyon (isteğe bağlı)' if i else 'fonksiyon'); e.installEventFilter(self); e.textChanged.connect(self.alan_degisti)
            e.setAttribute(Qt.WA_InputMethodEnabled, False)   # kendi şablon klavyesi var
            row.addWidget(e, 1); left.addLayout(row); self.fields.append(e)
            oz = QLabel(); oz.setMinimumHeight(4); oz.setStyleSheet('padding-left:40px;'); left.addWidget(oz); self.onizler.append(oz)
            er = QLabel(''); er.setStyleSheet('color:#ff8a95;font-size:14px;padding-left:40px;'); er.hide(); left.addWidget(er); self.errs.append(er)
        e_ = QLabel('Şablonlar'); e_.setStyleSheet('font-size:14px;color:#9fb3cc;'); left.addWidget(e_)
        kb = QGridLayout(); kb.setSpacing(7); left.addLayout(kb)
        for i, (ad, ek_) in enumerate(self.SABLON):
            b = QPushButton(ad); b.setObjectName('sablon'); b.setFocusPolicy(Qt.NoFocus); b.setMinimumHeight(50)
            b.clicked.connect(lambda c=False, s_=ek_: self.ekle(s_)); kb.addWidget(b, i//6, i % 6)
        kb2 = QGridLayout(); kb2.setSpacing(7); left.addLayout(kb2)
        for i, k in enumerate(self.TUS):
            b = QPushButton(k); b.setFocusPolicy(Qt.NoFocus); b.setMinimumHeight(48)
            b.clicked.connect(lambda c=False, k_=k: self.tus(k_)); kb2.addWidget(b, i//6, i % 6, 1, 2 if k == 'Temizle' else 1)
        self.param_kutu = QVBoxLayout(); self.param_kutu.setSpacing(4); left.addLayout(self.param_kutu)
        self.sliders = {}; self.degerler = dict(cfg.get('param') or {}); self.ilk_deger = None
        self.soluk_cb = QCheckBox('Kaydırırken önceki hâli soluk kalsın'); self.soluk_cb.setChecked(True); self.soluk_cb.toggled.connect(self.later); self.soluk_cb.hide(); left.addWidget(self.soluk_cb)
        self.ek_kutu = QHBoxLayout(); left.addLayout(self.ek_kutu)   # teğet / alan kaydırıcıları
        self.ek_sl = {}
        left.addStretch(1)
        right = QVBoxLayout(); right.setSpacing(10); box.addLayout(right, 1)
        cips = QHBoxLayout(); cips.setSpacing(8); right.addLayout(cips); self.cipler = {}
        for k, ad in GRAFIK_ISARET:
            b = QPushButton(ad); b.setObjectName('cip'); b.setCheckable(True); b.setFocusPolicy(Qt.NoFocus)
            b.clicked.connect(lambda c=False, k_=k: self.isaret_sec(k_)); cips.addWidget(b); self.cipler[k] = b
        cips.addStretch(1)
        self.isaret = cfg.get('isaret'); self.iz = None
        if self.isaret in self.cipler: self.cipler[self.isaret].setChecked(True)
        orta = QHBoxLayout(); right.addLayout(orta, 1)
        self.preview = QLabel(); self.preview.setAlignment(Qt.AlignCenter); self.preview.setStyleSheet('background:#1d262d;border-radius:16px;border:2px solid #2a4468;')
        self.preview.setMinimumSize(600, 400); self.preview.setMouseTracking(False); self.preview.installEventFilter(self); orta.addWidget(self.preview, 1)
        self.tablo = QLabel(); self.tablo.setStyleSheet('background:#0a1628;border:1.5px solid #2a4468;border-radius:12px;padding:10px;font-size:19px;color:#eef6ff;')
        self.tablo.setAlignment(Qt.AlignTop); self.tablo.setMinimumWidth(190); self.tablo.hide(); orta.addWidget(self.tablo)
        ipucu = QLabel('Grafiğin üstünde parmağınızı gezdirin: noktanın (x, y) değeri görünür.'); ipucu.setStyleSheet('font-size:14px;color:#6f86a6;'); right.addWidget(ipucu)
        btns = QHBoxLayout(); right.addLayout(btns); btns.addStretch(1)
        no = QPushButton('Vazgeç'); no.setMinimumHeight(54); no.setMinimumWidth(150); no.clicked.connect(self.reject); btns.addWidget(no)
        self.ok = QPushButton('Tahtaya aç'); self.ok.setObjectName('birincil'); self.ok.setMinimumHeight(54); self.ok.setMinimumWidth(200); self.ok.clicked.connect(self.open_board); btns.addWidget(self.ok)
        self.target = self.fields[0]; self.timer = QTimer(self); self.timer.setSingleShot(True); self.timer.setInterval(120); self.timer.timeout.connect(self.redraw)
        self.bilgi = {}; self.gorunum = None
        QTimer.singleShot(0, self.alan_degisti)
    # --- yazım ---
    def eventFilter(self, o, e):
        if e.type() in (QEvent.FocusIn, QEvent.MouseButtonPress) and o in self.fields: self.target = o
        pv = getattr(self, 'preview', None)
        if pv is not None and o is pv and e.type() in (QEvent.MouseButtonPress, QEvent.MouseMove) and (e.buttons() & Qt.LeftButton):
            self.iz_sur(e.pos()); return True
        if pv is not None and o is pv and e.type() == QEvent.MouseButtonRelease: return True
        return False
    def kutuya_git(self, t, bas=0):
        i = t.text().find('□', bas)
        if i >= 0: t.setSelection(i, 1); return True
        return False
    def ekle(self, s_):
        t = self.target; pos = t.cursorPosition(); sec = t.selectedText()
        if sec == '□': t.del_()
        pos = t.cursorPosition(); t.insert(s_); t.setFocus()
        self.kutuya_git(t, pos) or t.setCursorPosition(pos + len(s_))
    def tus(self, k):
        t = self.target
        if k == '⌫': t.backspace()
        elif k == 'Temizle': t.clear()
        elif k == '◀': t.cursorBackward(False)
        elif k == '▶':
            if not self.kutuya_git(t, t.cursorPosition() + (1 if t.selectedText() == '□' else 0)): t.cursorForward(False)
        else:
            t.insert(k)
            if '□' in t.text() and t.text().find('□', t.cursorPosition()) >= 0 and k not in ('(', ')'): pass
        t.setFocus()
    def alan_degisti(self, *a):
        # kaydırıcılar: a, b, c, k
        par = []
        for e in self.fields:
            for p_ in grafik_parametreler(e.text()):
                if p_ not in par: par.append(p_)
        if list(self.sliders) != par:
            from PyQt5.QtWidgets import QSlider
            while self.param_kutu.count():
                it = self.param_kutu.takeAt(0); l_ = it.layout()
                if l_ is not None:
                    while l_.count():
                        w_ = l_.takeAt(0).widget()
                        if w_: w_.deleteLater()
            self.sliders = {}
            for p_ in par:
                row = QHBoxLayout(); ad = QLabel(p_); ad.setStyleSheet('font-size:24px;font-style:italic;min-width:26px;'); row.addWidget(ad)
                sl = QSlider(Qt.Horizontal); sl.setRange(-50, 50); sl.setValue(int(round(self.degerler.get(p_, 1.0)*10))); row.addWidget(sl, 1)
                dg = QLabel(); dg.setStyleSheet('font-size:20px;min-width:52px;'); row.addWidget(dg)
                sl.valueChanged.connect(lambda v, p__=p_, d_=dg: self.param_degisti(p__, v, d_)); self.param_degisti(p_, sl.value(), dg, False)
                self.param_kutu.addLayout(row); self.sliders[p_] = sl
            self.soluk_cb.setVisible(bool(par)); self.ilk_deger = None
        for i, e in enumerate(self.fields):
            txt = e.text().strip()
            if not txt: self.onizler[i].clear(); self.onizler[i].setFixedHeight(4); continue
            try: pm = formul_pixmap('y = ' + grafik_latex(txt), 30, self.COLORS[i])
            except Exception: pm = None
            if pm is not None: self.onizler[i].setPixmap(pm); self.onizler[i].setFixedHeight(pm.height())
        self.gorunum = None; self.later()
    def param_degisti(self, p_, v, etiket, yeniden=True):
        if yeniden and self.ilk_deger is None: self.ilk_deger = dict(self.degerler)   # ilk kaydırmadaki hâl soluk kalır
        self.degerler[p_] = v/10; etiket.setText(fmt_num(v/10, 1))
        if yeniden: self.later()
    def isaret_sec(self, k):
        self.isaret = None if self.isaret == k else k
        for k_, b in self.cipler.items(): b.setChecked(k_ == self.isaret)
        self.ek_kaydiricilar(); self.iz = None; self.later()
    def ek_kaydiricilar(self):
        from PyQt5.QtWidgets import QSlider
        while self.ek_kutu.count():
            w_ = self.ek_kutu.takeAt(0).widget()
            if w_: w_.deleteLater()
        self.ek_sl = {}
        g = self.gorunum or self.bilgi.get('gorunum')
        if self.isaret not in ('teget', 'alan') or not g: return
        x0, x1 = g[0], g[1]
        adlar = (('x₀', (x0 + x1)/2),) if self.isaret == 'teget' else (('a', max(x0, 0.0)), ('b', min(x1, 2.0)))
        for ad, v in adlar:
            l = QLabel(ad); l.setStyleSheet('font-size:20px;font-style:italic;'); self.ek_kutu.addWidget(l)
            sl = QSlider(Qt.Horizontal); sl.setRange(int(x0*10), int(x1*10)); sl.setValue(int(v*10)); sl.valueChanged.connect(self.later)
            self.ek_kutu.addWidget(sl, 1); self.ek_sl[ad] = sl
    def later(self, *a): self.timer.start()
    def funcs(self, degerler=None):
        out = []; ok = True; deg = self.degerler if degerler is None else degerler
        for i, e in enumerate(self.fields):
            txt = e.text().strip(); self.errs[i].hide()
            if not txt: continue
            fn, err = grafik_derle(txt, deg)
            if err: self.errs[i].setText(err); self.errs[i].show(); ok = False; continue
            if not any(fn(k/10) is not None for k in range(-100, 101)): self.errs[i].setText('Bu aralıkta tanımlı değil.'); self.errs[i].show(); ok = False; continue
            out.append((grafik_goster(txt, deg) if self.sliders else txt, fn, self.COLORS[i]))
        return out, ok
    def ek(self):
        d = {}
        if self.isaret == 'teget' and 'x₀' in self.ek_sl: d['teget'] = self.ek_sl['x₀'].value()/10
        if self.isaret == 'alan' and 'a' in self.ek_sl: d['alan'] = (self.ek_sl['a'].value()/10, self.ek_sl['b'].value()/10)
        if self.iz is not None: d['iz'] = self.iz
        if self.gorunum and (self.sliders or self.iz is not None or self.isaret): d['gorunum'] = self.gorunum
        return d
    def tum_funcs(self, fs):
        if self.sliders and self.ilk_deger is not None and self.soluk_cb.isChecked():
            eski, _ = self.funcs(self.ilk_deger)
            return fs + [(t, f, c, 'soluk') for t, f, c in eski]
        return fs
    def redraw(self):
        fs, ok = self.funcs(); self.ok.setEnabled(bool(fs) and ok)
        if not fs: self.preview.setText('Fonksiyonu yazın'); self.tablo.hide(); return
        self.bilgi = {}
        doc = graph_build(self.tum_funcs(fs), self.isaret, ek=self.ek(), bilgi=self.bilgi)
        if self.gorunum is None: self.gorunum = self.bilgi.get('gorunum'); self.ek_kaydiricilar() if self.isaret in ('teget', 'alan') and not self.ek_sl else None
        self.preview.setPixmap(grafik_resmi(doc, max(300, self.preview.width() - 12))); doc.close()
        if self.isaret == 'tablo':
            satir = ''.join('<tr><td style="padding:3px 16px 3px 4px">%s</td><td>%s</td></tr>' % (fmt_num(x).replace('-', '−'), fmt_num(v, 2).replace('-', '−')) for x, v in self.bilgi.get('tablo', []))
            it = '<br>'.join('(%s, %s): f′ %s' % (fmt_num(a, 1).replace('-', '−'), fmt_num(b, 1).replace('-', '−'), s) for a, b, s in self.bilgi.get('isaret_tablosu', []))
            self.tablo.setText('<b style="color:#7ff6ff">x &nbsp;&nbsp; y</b><table>%s</table><br><span style="font-size:15px;color:#9fb3cc">%s</span>' % (satir, it)); self.tablo.show()
        else: self.tablo.hide()
    def iz_sur(self, pos):
        pm = self.preview.pixmap(); g = self.bilgi.get('gorunum')
        if pm is None or pm.isNull() or not g: return
        ox = (self.preview.width() - pm.width())/2; k = pm.width()/self.bilgi['W']; m = self.bilgi['m']
        px = (pos.x() - ox)/k; x0, x1 = g[0], g[1]
        self.iz = x0 + (px - m)/(self.bilgi['W'] - 2*m)*(x1 - x0)
        if self.gorunum is None: self.gorunum = g
        self.later()
    def resizeEvent(self, e): super().resizeEvent(e); self.later()
    def open_board(self):
        fs, ok = self.funcs()
        if not fs or not ok: return
        m = self.main
        m.graph_cfg = dict(f0=self.fields[0].text(), f1=self.fields[1].text(), f2=self.fields[2].text(), param=dict(self.degerler), isaret=self.isaret)
        durum = dict(f=[e.text().strip() for e in self.fields], param=dict(self.degerler), isaret=None)
        self.accept()
        grafik_tahtaya(m, durum, canlandir=True)

def grafik_durum_derle(durum):
    fs = []
    for i, t in enumerate(durum.get('f') or []):
        if not t: continue
        fn, err = grafik_derle(t, durum.get('param'))
        if fn is not None: fs.append((grafik_goster(t, durum.get('param')) if grafik_parametreler(t) else t, fn, GRAFIK_RENK[i % 3]))
    return fs

def grafik_belge(durum, bilgi=None):
    import json as _j
    doc = graph_build(grafik_durum_derle(durum), durum.get('isaret'), ek=durum.get('ek') or {}, bilgi=bilgi, alt=max(540, int(durum.get('alt') or 540)))
    doc.set_metadata({'title': 'Grafik — ' + APP_NAME, 'keywords': 'UMAL-graph', 'subject': 'UMAL-grafik:' + _j.dumps({k: durum.get(k) for k in ('f', 'param', 'isaret', 'ek', 'alt')}, ensure_ascii=False)})
    return doc

def grafik_yazi_yeri(m):
    """Grafik sayfasında bir sonraki yazının başlayacağı y: grafiğin ve önceki yazıların altı."""
    y0 = GRAFIK_H + 90.0   # İncele şeridi grafiğin hemen altında: yazı onun altından başlar
    for s_ in m.marks.get(m.page, []):
        p_ = s_.get('points') or []
        if s_.get('tool') not in ('whiteout', 'geo', 'compass') and p_ and max(q[1] for q in p_) > GRAFIK_H: y0 = max(y0, max(q[1] for q in p_) + 28)
    return y0

def grafik_sayfa_uzat(m, alt_y):
    """Grafik sayfası yazıya yetmiyorsa aşağı uzatılır (yazılar yerinde kalır)."""
    try:
        if m.doc[m.page].rect.height >= alt_y + 24: return True
        d = grafik_durumu(m.doc)
        if not d: return False
        d['alt'] = int(math.ceil((alt_y + 120 - GRAFIK_H)/120.0)*120); m.board.finish()
        old = m.doc; m.doc = grafik_belge(d); old.close(); m.changed(); m.render(); m.place_overlays(); return True
    except Exception as e:
        print('grafik uzat:', e); return False

def grafik_durumu(doc):
    import json as _j
    s = (doc.metadata or {}).get('subject') or ''
    if not s.startswith('UMAL-grafik:'): return None
    try: return _j.loads(s[len('UMAL-grafik:'):])
    except ValueError: return None

def grafik_tahtaya(m, durum, canlandir=False):
    """Grafiği yeni sekmede kara tahta görünümünde açar; kalem beyaz; sağda İncele, köşede Atlas. canlandir: eğri soldan sağa çizilir."""
    bilgi = {}; doc = grafik_belge(durum, bilgi)
    fs = grafik_durum_derle(durum)
    name = 'y = ' + atlas_guzel(fs[0][0]) if fs else 'Grafik'
    m.start_tab(name if len(name) < 28 else name[:26] + '…')
    if canlandir and bilgi.get('egriler'):
        bos = dict(durum); bos['f'] = []
        m.replace(doc); m.tabs_changed(); m.set_tool('pen'); m.color = '#ffffff'; m.refresh_colors()
        GrafikCanlandir(m, bilgi)
    else:
        m.replace(doc); m.tabs_changed(); m.set_tool('pen'); m.color = '#ffffff'; m.refresh_colors()
    QTimer.singleShot(0, m.place_overlays)

class GrafikCanlandir(QWidget):
    """Tahtaya açılırken eğrileri soldan sağa çizer (1,4 sn), sonra kaybolur; asıl grafik altta hazırdır."""
    def __init__(self, m, bilgi):
        super().__init__(m.board); self.m = m; self.bilgi = bilgi; self.t0 = time.monotonic()
        self.setAttribute(Qt.WA_TransparentForMouseEvents); self.setGeometry(m.board.rect()); self.show(); self.raise_()
        self.zm = QTimer(self); self.zm.setInterval(30); self.zm.timeout.connect(self.tik); self.zm.start()
    def tik(self):
        if time.monotonic() - self.t0 > 1.5: self.zm.stop(); self.deleteLater(); return
        self.update()
    def paintEvent(self, e):
        t = min(1.0, (time.monotonic() - self.t0)/1.4); b = self.m.board; k = b.scale; W = self.bilgi['W']; m_ = self.bilgi['m']
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        sinir = m_ + (W - 2*m_)*t
        # çizilmemiş kısmı zeminle ört (eğri sağdan gizli), çizilen kısım üstte parlasın
        renk = QColor.fromRgbF(*BOARD_FILLS['kt_kareli'])
        for parcalar, col in self.bilgi['egriler']:
            for pts in parcalar:
                kalan = [q for q in pts if q[0] > sinir]
                if len(kalan) > 1:
                    p.setPen(QPen(renk, 14*k, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)); p.drawPolyline(QPolygonF([QPointF(x*k, y*k) for x, y in kalan]))
        for parcalar, col in self.bilgi['egriler']:
            for pts in parcalar:
                ciz = [q for q in pts if q[0] <= sinir]
                if len(ciz) > 1:
                    p.setPen(QPen(QColor(col), 4*k, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)); p.drawPolyline(QPolygonF([QPointF(x*k, y*k) for x, y in ciz]))
        p.end()

GRAFIK_ISARET_KISA = {'kok': 'Kökler', 'ykes': 'y-kesişim', 'tepe': 'Tepe', 'simetri': 'Simetri', 'asimptot': 'Asimptot', 'kesisim': 'Kesişim', 'tablo': 'Değer tablosu'}

class GrafikIncele(QFrame):
    """K-352/K-358: grafik sekmesinde grafiğin hemen altında yatay İncele şeridi (grafiği kapatmaz): dokununca yalnız o işaret
    grafikte görünür; değer tablosu şeridin ikinci satırında; Atlas köşede yardım önerir."""
    def __init__(self, m):
        super().__init__(m.scroll); self.m = m; self.setObjectName('grafikIncele')
        self.setStyleSheet('#grafikIncele{background:rgba(10,22,40,225);border:2px solid #22e8ff66;border-radius:16px;} QLabel{color:#eef6ff;}'
                           'QPushButton{color:#eef6ff;background:#0a1628;border:1.5px solid #2a4468;border-radius:12px;font-size:17px;padding:8px 14px;}'
                           'QPushButton:checked{border-color:#ffb020;color:#ffd27a;background:#2a1d06;} QPushButton#tam{border-color:#22e8ff;color:#7ff6ff;}')
        v = QVBoxLayout(self); v.setContentsMargins(12, 8, 12, 8); v.setSpacing(6)
        r1 = QHBoxLayout(); r1.setSpacing(8); v.addLayout(r1)
        t = QLabel('İncele'); t.setStyleSheet('font-size:19px;font-weight:800;color:#7ff6ff;padding-right:4px;'); r1.addWidget(t)
        self.dug = {}
        for k, ad in GRAFIK_ISARET:
            if k in ('teget', 'alan'): continue   # kaydırıcılı olanlar Grafik çizicide
            b = QPushButton(GRAFIK_ISARET_KISA.get(k, ad)); b.setCheckable(True); b.setFocusPolicy(Qt.NoFocus); b.clicked.connect(lambda c=False, k_=k: self.sec(k_)); r1.addWidget(b); self.dug[k] = b
        self.duzen_b = QPushButton('Düzenle'); self.duzen_b.setObjectName('tam'); self.duzen_b.setFocusPolicy(Qt.NoFocus); self.duzen_b.clicked.connect(self.duzenle); r1.addWidget(self.duzen_b)
        self.r2 = QWidget(); r2 = QHBoxLayout(self.r2); r2.setContentsMargins(0, 0, 0, 0); r2.setSpacing(10); v.addWidget(self.r2)
        self.tablo = QLabel(); self.tablo.setStyleSheet('font-size:17px;'); r2.addWidget(self.tablo, 1)
        self.yaz_b = QPushButton('Tabloyu tahtaya yaz'); self.yaz_b.setObjectName('tam'); self.yaz_b.setFocusPolicy(Qt.NoFocus); self.yaz_b.clicked.connect(self.tablo_yaz); r2.addWidget(self.yaz_b)
        self.r2.hide(); self.hide()
        self.atlas = GrafikAtlas(m, self)
        try: m.scroll.verticalScrollBar().valueChanged.connect(lambda _v: self.isVisible() and self.yerlestir())
        except Exception: pass
    def yerlestir(self):
        """Grafiğin alt kenarının hemen altına; grafik ekrandan taşıyorsa ekranın altına (alt çubuğun üstüne)."""
        m = self.m; vp = m.scroll.viewport().geometry(); k = m.board.scale or 1
        self.adjustSize(); w = min(self.sizeHint().width(), vp.width() - 32); self.resize(w, self.sizeHint().height())
        gy = m.board.mapTo(m.scroll, QPoint(0, int(GRAFIK_H*k))).y() + 8
        y = min(gy, vp.bottom() - self.height() - 56)
        if gy < vp.top() - self.height() + 4: self.move(vp.x() + (vp.width() - w)//2, -2000)   # yazı alanına inildi: şerit grafikle birlikte yukarıda kalır
        else: self.move(vp.x() + (vp.width() - w)//2, max(vp.top() + 8, y))
        at = self.atlas
        if at.isVisible(): at.adjustSize(); at.move(vp.right() - at.width() - 24, max(vp.top() + 8, min(self.y(), vp.bottom() - 56) - at.height() - 10)); at.raise_()
        self.raise_()
    def durum(self): return grafik_durumu(self.m.doc) if getattr(self.m, 'doc', None) is not None else None
    def esitle(self):
        d = self.durum()
        if not d: self.hide(); self.atlas.hide(); return False
        for k, b in self.dug.items(): b.setChecked(d.get('isaret') == k)
        return True
    def sec(self, k):
        d = self.durum()
        if not d: return
        d['isaret'] = None if d.get('isaret') == k else k
        bilgi = {}; m = self.m; m.board.finish()
        old = m.doc; m.doc = grafik_belge(d, bilgi); old.close()   # yazılar (kalem) yerinde kalır
        m.changed(); m.render(); self.esitle(); self.bilgi = bilgi
        if d['isaret'] == 'tablo':
            tb = bilgi.get('tablo', []); td = '<td style="padding:1px 10px;text-align:center;border-left:1px solid #2a4468">%s</td>'
            self.tablo.setText('<table cellspacing="0"><tr><td style="padding:1px 10px;color:#7ff6ff"><b>x</b></td>' + ''.join(td % fmt_num(x).replace('-', '−') for x, _ in tb) + '</tr>'
                               '<tr><td style="padding:1px 10px;color:#7ff6ff"><b>y</b></td>' + ''.join(td % fmt_num(y, 2).replace('-', '−') for _, y in tb) + '</tr></table>')
            self.r2.show()
        else: self.r2.hide()
        self.atlas.oner(d, bilgi); m.place_overlays()
    def tablo_yaz(self):
        bilgi = getattr(self, 'bilgi', {}) or {}
        satir = '\n'.join('$x = %s$  →  $y = %s$' % (fmt_num(x).replace(',', '.'), fmt_num(y, 2).replace(',', '.')) for x, y in bilgi.get('tablo', []))
        if bilgi.get('tablo'): atlas_tablo_yaz(self.m, bilgi['tablo'])
        elif satir: atlas_murekkep_yaz(self.m, 'Değer tablosu:\n' + satir, sag=True)
    def duzenle(self):
        d = self.durum() or {}; f = d.get('f') or []
        self.m.graph_cfg = dict(f0=f[0] if f else '', f1=f[1] if len(f) > 1 else '', f2=f[2] if len(f) > 2 else '', param=d.get('param') or {})
        self.m.open_graph()

class GrafikAtlas(QFrame):
    """Köşedeki küçük Atlas: seçilen işarete göre yardım önerir; Anlat → Atlas paneli adım adım anlatır."""
    def __init__(self, m, incele):
        super().__init__(m.scroll); self.m = m; self.incele = incele; self.setObjectName('grafikAtlas')
        self.setStyleSheet('#grafikAtlas{background:transparent;} QLabel#balon{background:#0e2038;border:2px solid #22e8ff;border-radius:18px;padding:12px 14px;font-size:18px;color:#eef6ff;}'
                           'QPushButton{color:#7ff6ff;background:#0a1628;border:1.5px solid #22e8ff;border-radius:12px;font-size:16px;padding:6px 12px;font-weight:700;}'
                           'QPushButton#p{background:#22e8ff;color:#04202a;}')
        h = QHBoxLayout(self); h.setContentsMargins(0, 0, 0, 0); h.setSpacing(4)
        sol = QVBoxLayout(); sol.setSpacing(6); h.addLayout(sol)
        self.balon = QLabel(); self.balon.setObjectName('balon'); self.balon.setWordWrap(True); self.balon.setFixedWidth(380); sol.addWidget(self.balon)
        d = QHBoxLayout(); sol.addLayout(d)
        self.anlat = QPushButton('Anlat'); self.anlat.setObjectName('p'); self.anlat.clicked.connect(lambda: self.sor('anlat')); d.addWidget(self.anlat)
        b2 = QPushButton('Benzer soru'); b2.clicked.connect(lambda: self.sor('benzer')); d.addWidget(b2)
        b3 = QPushButton('Kapat'); b3.clicked.connect(self.hide); d.addWidget(b3); d.addStretch(1)
        self.maskot = AtlasMaskot(self); self.maskot.setFixedSize(120, 122); h.addWidget(self.maskot, 0, Qt.AlignBottom)
        self.hide(); self.soru = ''
    def oner(self, d, bilgi):
        k = d.get('isaret'); oz = bilgi.get('ozellik') or {}; f = (grafik_durum_derle(d) or [('', None, '')])[0][0]
        fx = 'y = ' + atlas_guzel(f)
        if k == 'tepe' and oz.get('tepe'): x, y, _ = oz['tepe'][0]; mt = 'Tepe noktası <b style="color:#ffd27a">T(%s, %s)</b>. Nasıl bulunduğunu adım adım anlatayım mı?' % (fmt_num(x), fmt_num(y)); self.soru = '%s fonksiyonunun tepe noktasının nasıl bulunduğunu adım adım anlat.' % fx
        elif k == 'kok' and oz.get('kok'): mt = 'Kökler: <b style="color:#ffd27a">%s</b>. Nasıl bulunduğunu anlatayım mı?' % ', '.join('x = ' + fmt_num(r[0]) for r in oz['kok'][:4]); self.soru = '%s fonksiyonunun köklerini adım adım bul.' % fx
        elif k == 'ykes' and oz.get('ykes'): mt = 'y eksenini <b style="color:#ffd27a">(0, %s)</b> noktasında keser. Neden x = 0 yazdığımızı anlatayım mı?' % fmt_num(oz['ykes'][0][1]); self.soru = '%s fonksiyonunun y eksenini kestiği noktanın nasıl bulunduğunu anlat.' % fx
        elif k == 'asimptot': mt = 'Asimptotlar kesikli çizgiyle gösterildi. Neden oluştuklarını anlatayım mı?'; self.soru = '%s fonksiyonunun asimptotlarını açıkla.' % fx
        elif k == 'simetri': mt = 'Simetri ekseni tepe noktasından geçer. Anlatayım mı?'; self.soru = '%s fonksiyonunun simetri eksenini açıkla.' % fx
        elif k == 'kesisim': mt = ('Kesişim noktaları işaretlendi. Denklemi kurup çözeyim mi?' if oz.get('kesisim') else 'Bu aralıkta kesişim görünmüyor. Denklemi kurup inceleyeyim mi?'); self.soru = 'Grafikteki fonksiyonların kesişim noktalarını denklem kurarak bul: ' + ', '.join('y = ' + atlas_guzel(t) for t, _, _ in grafik_durum_derle(d))
        elif k == 'tablo': mt = 'Değer tablosu altta. Tablodan grafiğin nasıl çizildiğini anlatayım mı?'; self.soru = '%s fonksiyonu için değer tablosu yap ve grafiğin nasıl çizildiğini anlat.' % fx
        else: self.hide(); return
        # K-362: grafikten sayısal bulunan değerler soruya eklenir (yapay zekâ yanlış kök / kesişim uydurmasın)
        def nk(t): return '(%s, %s)' % (fmt_num(t[0], 2), fmt_num(t[1], 2))
        olgu = {'kok': ('Kökler', lambda t: 'x = ' + fmt_num(t[0], 2)), 'kesisim': ('Kesişim noktaları', nk), 'tepe': ('Tepe noktası', nk), 'ykes': ('y eksenini kestiği nokta', nk)}
        if k in olgu and oz.get(k):
            ad, bic = olgu[k]
            self.soru += (' (Grafikten sayısal olarak hesaplanan %s: %s. Cevabın bu değerlerle uyuşmalı. Değerler tam sayı değilse '
                          'yaklaşık değer ver ve tam çıkmadığını söyle; bulduğun değerleri iki denklemde yerine koyarak doğrula.)') % (ad, '; '.join(bic(t) for t in oz[k][:6]))
        self.fx = fx; self.balon.setText(mt); self.maskot.ifade('konusma'); QTimer.singleShot(1600, lambda: self.maskot.ifade('mutluluk'))
        self.adjustSize(); self.show(); self.raise_()
    def sor(self, tur):
        if getattr(self.m, '_sinav_su_an', False): self.m.show_toast("Sınav saatinde Atlas'a sor kapalı."); return
        q = self.soru if tur == 'anlat' else '%s fonksiyonuna benzer 3 soru üret, çözümleriyle.' % getattr(self, 'fx', '')
        self.hide(); self.m.atlas_sor_ac(); pn = self.m.atlas_panel
        pn.brans = 'Matematik'; QTimer.singleShot(0, lambda: pn.sor(q))

def atlas_murekkep_yaz(m, metin, sag=False):
    """Metni el yazısıyla kalem çizgisi olarak tahtada boş bir yere yazar (grafik sekmesinde sağ üst boşluk)."""
    b = m.board; k = b.scale or 1; sayfa = m.doc[m.page].rect; vis = b.visibleRegion().boundingRect()
    boy = 22.0 if (m.doc.metadata or {}).get("keywords") == "UMAL-graph" else 30.0/k; renk = okunur_renk(m)
    gen = min(320.0, sayfa.width*0.4)
    cz, h = murekkep_cizgileri(metin, gen, boy, renk, max(1.2, min(2.4, m.width.value()*0.7)), os.path.join(UI_FONT_DIR, 'ReliefSingleLineSVG-Regular.svg'), atlas_guzel)
    if not cz: return
    x0 = sayfa.width - gen - 300/k if sag else max(16.0, vis.left()/k + 24); y0 = max(16.0, vis.top()/k + 60/k)
    if (m.doc.metadata or {}).get('keywords') == 'UMAL-graph':   # grafiğin altındaki yazı alanına; öncekilerin altına
        x0 = 40.0; y0 = grafik_yazi_yeri(m); grafik_sayfa_uzat(m, y0 + h)
    m.checkpoint(); ms = m.marks.setdefault(m.page, [])
    for c in cz: ms.append(dict(c, points=[[x0 + q[0], y0 + q[1]] for q in c['points']]))
    m.changed(); b.update()
    try:
        bar = m.scroll.verticalScrollBar(); alt = y0 + h + 20
        if y0*k < bar.value() or alt*k > bar.value() + m.scroll.viewport().height(): bar.setValue(int(max(0, min(y0*k - 60, alt*k - m.scroll.viewport().height() + 40))))
    except Exception: pass
    m.show_toast('Tahtaya yazıldı · Akıllı seçimle taşıyabilirsiniz')

def atlas_tablo_yaz(m, tablo):
    """Değer tablosunu ders kitabı gibi yatay tablo olarak (x satırı, y satırı, çizgileriyle) el yazısıyla yazar
    ve görünür yere kaydırır. Grafik sekmesinde grafiğin altındaki yazı alanına, öncekilerin altına."""
    b = m.board; k = b.scale or 1; sayfa = m.doc[m.page].rect; vis = b.visibleRegion().boundingRect()
    grafik = (m.doc.metadata or {}).get('keywords') == 'UMAL-graph'
    renk = okunur_renk(m)
    kal = max(1.2, min(2.4, m.width.value()*0.7)); yol = os.path.join(UI_FONT_DIR, 'ReliefSingleLineSVG-Regular.svg')
    boy = 26.0; sat_h = 50.0; bas_g = 64.0
    n = len(tablo); gen = min(sayfa.width - 80, bas_g + n*max(64.0, min(96.0, (sayfa.width - 80 - bas_g)/max(1, n))))
    hucre = (gen - bas_g)/max(1, n)
    if grafik:
        x0 = 40.0; y0 = grafik_yazi_yeri(m); grafik_sayfa_uzat(m, y0 + boy*1.8 + 2*sat_h + 20)
    else:
        x0 = max(16.0, vis.left()/k + 24); y0 = max(16.0, vis.top()/k + 60/k)
    out = []
    def yazi(t, cx, cy, sol=None):   # hücrenin ortasına (ya da sola) tek satır yazı
        cz, _h = murekkep_cizgileri(t, 400, boy, renk, kal, yol, lambda u: u)
        if not cz: return
        xs = [q[0] for c in cz for q in c['points']]; ys = [q[1] for c in cz for q in c['points']]
        dx = (sol if sol is not None else cx - (max(xs) + min(xs))/2) - (min(xs) if sol is not None else 0); dy = cy - (max(ys) + min(ys))/2
        for c in cz: out.append(dict(c, points=[[q[0] + dx, q[1] + dy] for q in c['points']]))
    def cizgi(a, b_):
        out.append(dict(tool='pen', color=renk, width=kal*0.8, points=[list(a), list(b_)]))
    yazi('Değer tablosu', 0, y0 + boy*0.6, sol=x0); y0 += boy*1.8
    for i in range(3): cizgi((x0, y0 + i*sat_h), (x0 + gen, y0 + i*sat_h))
    cizgi((x0, y0), (x0, y0 + 2*sat_h)); cizgi((x0 + gen, y0), (x0 + gen, y0 + 2*sat_h))
    cizgi((x0 + bas_g, y0), (x0 + bas_g, y0 + 2*sat_h))
    yazi('x', x0 + bas_g/2, y0 + sat_h/2); yazi('y', x0 + bas_g/2, y0 + sat_h*1.5)
    for j, (x, y) in enumerate(tablo):
        cx = x0 + bas_g + hucre*(j + 0.5)
        if j: cizgi((x0 + bas_g + hucre*j, y0), (x0 + bas_g + hucre*j, y0 + 2*sat_h))
        yazi(fmt_num(x).replace('−', '-'), cx, y0 + sat_h/2); yazi(fmt_num(y, 2).replace('−', '-'), cx, y0 + sat_h*1.5)
    m.checkpoint(); m.marks.setdefault(m.page, []).extend(out)
    m.changed(); b.update()
    alt = y0 + 2*sat_h + 20; ust = y0 - boy*2
    try:
        bar = m.scroll.verticalScrollBar()
        if ust*k < bar.value() or alt*k > bar.value() + m.scroll.viewport().height(): bar.setValue(int(max(0, alt*k - m.scroll.viewport().height() + 40)))
    except Exception: pass
    m.show_toast('Değer tablosu tahtaya yazıldı · Akıllı seçimle taşıyabilirsiniz')

class Ruler(QWidget):
    """Cetvel: sayfanın üstünde yarı saydam; gövdeden sürüklenir, sağ uçtaki tutamakla
    döndürülür (15°'lere yapışır), sol uçtaki × ile kalkar. Çizgiler sayfanın gerçek
    santimetresiyle; kenarına yakın çizilen kalem çizgisi kenara yapışır."""
    L, W, KNOB = 760, 86, 22
    def __init__(self, main):
        super().__init__(main.scroll); self.main = main; self.angle = 0.0; self.drag = None
        vp = main.scroll.viewport().geometry(); self.c = QPointF(vp.center().x(), vp.y() + vp.height()*.62)
        self.setCursor(Qt.SizeAllCursor); self.hide()
    def corners(self):
        a = math.radians(self.angle); ca, sa = math.cos(a), math.sin(a); L, W = self.L/2, self.W/2
        return [QPointF(self.c.x() + ca*x - sa*y, self.c.y() + sa*x + ca*y) for x, y in ((-L, -W), (L, -W), (L, W), (-L, W))]
    def local(self, x, y):
        a = math.radians(self.angle); return QPointF(self.c.x() + math.cos(a)*x - math.sin(a)*y, self.c.y() + math.sin(a)*x + math.cos(a)*y)
    def place(self):
        pts = self.corners(); xs = [q.x() for q in pts]; ys = [q.y() for q in pts]
        r = QRect(int(min(xs))-4, int(min(ys))-4, int(max(xs)-min(xs))+9, int(max(ys)-min(ys))+9)
        self.setGeometry(r)
        poly = QPolygonF([q - QPointF(r.topLeft()) for q in pts]); self.setMask(QRegion(poly.toPolygon())); self.update()
    def edge_for(self, vp, off):
        """Kalem başlangıcı kenara yakınsa o kenarın çizgisi: ((ox,oy),(dx,dy),(t0,t1)), görüntü koordinatında."""
        a = math.radians(self.angle); dx, dy = math.cos(a), math.sin(a); nx, ny = -dy, dx
        for side in (-1, 1):   # üst kenar, alt kenar (dışa doğru kalem kalınlığı kadar)
            o = self.local(0, side*(self.W/2 + off))
            dist = (vp.x() - o.x())*nx + (vp.y() - o.y())*ny; along = (vp.x() - o.x())*dx + (vp.y() - o.y())*dy
            if abs(dist) <= 36 and abs(along) <= self.L/2 + 10 and side*dist >= -14:
                return ((o.x(), o.y()), (dx, dy), (-self.L/2, self.L/2))
        return None
    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); p.translate(-QPointF(self.geometry().topLeft()))
        p.translate(self.c); p.rotate(self.angle); L, W = self.L/2, self.W/2
        p.setPen(QPen(QColor('#b78a00'), 1.6)); p.setBrush(QColor(234, 179, 8, 92)); p.drawRoundedRect(QRectF(-L, -W, 2*L, 2*W), 10, 10)
        cm = 28.3465*self.main.board.scale; mm = cm/10; n = int((2*L - 40)/mm)
        f = p.font(); f.setPixelSize(13); f.setBold(True); p.setFont(f)
        for i in range(n + 1):   # üst kenar: santimetre ve milimetre çizgileri
            x = -L + 20 + i*mm; big = i % 10 == 0; mid = i % 5 == 0
            if mm < 3.5 and not (big or mid): continue
            p.setPen(QPen(QColor('#5c4400'), 1.4 if big else 1)); p.drawLine(QPointF(x, -W), QPointF(x, -W + (20 if big else 13 if mid else 8)))
            if big: p.drawText(QRectF(x - 20, -W + 20, 40, 18), Qt.AlignCenter, str(i//10))
        for i in range(n + 1):   # alt kenar da ölçülü
            x = -L + 20 + i*mm; big = i % 10 == 0
            if mm < 3.5 and i % 5: continue
            p.setPen(QPen(QColor('#5c4400'), 1.4 if big else 1)); p.drawLine(QPointF(x, W), QPointF(x, W - (14 if big else 8)))
        k = QPointF(L - 30, 4)   # döndürme tutamağı
        p.setPen(QPen(QColor('#b78a00'), 2)); p.setBrush(QColor(255, 255, 255, 230)); p.drawEllipse(k, self.KNOB, self.KNOB)
        p.setPen(QPen(QColor('#7a5b00'), 2.4)); p.drawArc(QRectF(k.x()-10, k.y()-10, 20, 20), 40*16, 280*16)
        p.drawLine(k + QPointF(7, -9), k + QPointF(10, -3)); p.drawLine(k + QPointF(10, -3), k + QPointF(4, -2))
        x_ = QPointF(-L + 28, 6)   # kaldır
        p.setPen(QPen(QColor('#b42318'), 2.6)); p.setBrush(QColor(255, 255, 255, 220)); p.drawEllipse(x_, 15, 15)
        p.drawLine(x_ + QPointF(-6, -6), x_ + QPointF(6, 6)); p.drawLine(x_ + QPointF(-6, 6), x_ + QPointF(6, -6))
        if self.drag and self.drag[0] == 'rotate':
            p.setPen(QColor('#3d2a00')); f.setPixelSize(18); p.setFont(f); p.drawText(QRectF(-60, -12, 120, 30), Qt.AlignCenter, '%d°' % round((-self.angle) % 360))
    def to_local(self, q):
        a = math.radians(-self.angle); d = q - self.c
        return QPointF(math.cos(a)*d.x() - math.sin(a)*d.y(), math.sin(a)*d.x() + math.cos(a)*d.y())
    def mousePressEvent(self, e):
        q = QPointF(e.pos()) + QPointF(self.geometry().topLeft()); l = self.to_local(q)
        if math.hypot(l.x() - (-self.L/2 + 28), l.y() - 6) < 22: self.main.toggle_ruler(False); return
        if math.hypot(l.x() - (self.L/2 - 30), l.y() - 4) < self.KNOB + 10:
            self.drag = ('rotate', math.degrees(math.atan2(q.y() - self.c.y(), q.x() - self.c.x())) - self.angle)
        else: self.drag = ('move', q - self.c)
    def mouseMoveEvent(self, e):
        if not self.drag: return
        q = QPointF(e.pos()) + QPointF(self.geometry().topLeft())
        if self.drag[0] == 'move': self.c = q - self.drag[1]
        else:
            a = math.degrees(math.atan2(q.y() - self.c.y(), q.x() - self.c.x())) - self.drag[1]
            near = round(a/15)*15; self.angle = near if abs(a - near) < 2.5 else a   # 0°, 15°, 30°, 45°, 90°…
        self.place()
    def mouseReleaseEvent(self, e): self.drag = None; self.update()

class FloatingBell(QWidget):
    """Tahtanın üstünde yüzen zil saati: ders, kalan süre, saat aralığı, ilerleme.
    Ders boyunca sade; son 5 dakikada sarı, son 1 dakikada kırmızı ve nabız gibi atar
    (teneffüste altın tonları). Dokun: küçük hap ↔ büyük kutu; sürükle: taşı."""
    BIG = (236, 124); SMALL = (196, 46)
    def __init__(self, main):
        super().__init__(main.scroll); self.main = main; self.small = False; self.offset = None
        self.press = None; self.moved = False; self.now = None; self.state = None
        self.setCursor(Qt.PointingHandCursor)
        self.timer = QTimer(self); self.timer.timeout.connect(self.tick); self.timer.start(500); self.tick()
    def phase(self, st):
        if st['left'] is None: return None
        if st['left'] <= 60 and st['kind'] in ('lesson', 'break'): return 'son1'
        if st['left'] <= 300 and st['kind'] in ('lesson', 'break'): return 'son5'
        return 'normal'
    def tick(self):
        import datetime
        st = bell_state(self.now or datetime.datetime.now()); self.state = st; ph = self.phase(st)
        show = ph is not None and not getattr(self.main, 'overlay_mode', False) and getattr(self.main, 'exam_screen', None) is None   # sınav sayacı varken köşe saati yok
        big = ph in ('son5', 'son1') or not self.small
        w, h = self.BIG if big else self.SMALL
        if (self.width(), self.height()) != (w, h): self.setFixedSize(w, h); self.place()
        if show != self.isVisible(): self.setVisible(show); self.main.place_overlays()
        self.timer.setInterval(50 if ph == 'son1' else 500)
        if show: self.raise_(); self.update()
    def place(self):
        vp = self.main.scroll.viewport().geometry()
        if self.offset is None: x, y = vp.right() - self.width() - 14, vp.y() + 14
        else: x, y = vp.right() - self.offset[0] - self.width(), vp.y() + self.offset[1]
        self.move(max(vp.x(), min(x, vp.right() - self.width())), max(vp.y(), min(y, vp.bottom() - self.height())))
    def colors(self, st, ph):
        brk = st['kind'] == 'break'
        if ph == 'son1': return QColor('#ff6b7a'), QColor(255, 107, 122, 40), QColor('#bb1826')
        if ph == 'son5': return QColor('#ffc526'), QColor(255, 197, 38, 30), QColor('#8a6514')
        if brk: return QColor('#e7c46a'), QColor(201, 154, 46, 26), QColor('#8a6514')
        return QColor('#ffffff'), QColor(14, 28, 50, 205), QColor('#1d4f8f')
    def font(self, px, bold=False):
        from PyQt5.QtGui import QFont
        f = QFont(ui_fonts().get('Poppins-Regular') or 'DejaVu Sans'); f.setPixelSize(px); f.setBold(bold); return f
    def paintEvent(self, e):
        st = self.state
        if st is None or st['left'] is None: return
        ph = self.phase(st); fg, bg, tagc = self.colors(st, ph)
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing)
        W, H = self.width(), self.height(); r = QRectF(1.5, 1.5, W-3, H-3)
        if ph == 'son1':   # nabız: çerçeve dışına yayılan hafif ışık
            k = (math.sin(time.monotonic()*5.2) + 1)/2
            for i in range(3): c = QColor(fg); c.setAlpha(int(70*k/(i+1))); p.setPen(QPen(c, 2)); p.setBrush(Qt.NoBrush); p.drawRoundedRect(r.adjusted(-i, -i, i, i).adjusted(2, 2, -2, -2), 16, 16)
        base = QColor(14, 28, 50, 215); p.setPen(Qt.NoPen); p.setBrush(base); p.drawRoundedRect(r, 16, 16)
        p.setBrush(bg); p.drawRoundedRect(r, 16, 16)
        border = QColor(fg) if ph in ('son5', 'son1') else QColor(255, 255, 255, 45)
        p.setPen(QPen(border, 2 if ph in ('son5', 'son1') else 1)); p.setBrush(Qt.NoBrush); p.drawRoundedRect(r, 16, 16)
        l = st['left']; cd = ('%d:%02d:%02d' % (l//3600, l%3600//60, l%60)) if l >= 3600 else ('%d:%02d' % (l//60, l%60))
        label = 'zile kalan' if st['kind'] in ('lesson', 'prep') else 'derse kalan' if st['kind'] == 'break' else 'okula kalan'
        p.setFont(self.font(12, True)); tw = p.fontMetrics().horizontalAdvance(st['tag']) + 16
        if H < 60:   # küçük hap: etiket + süre
            tr = QRectF(10, (H-22)/2, tw, 22); p.setPen(Qt.NoPen); p.setBrush(tagc); p.drawRoundedRect(tr, 11, 11)
            p.setPen(Qt.white); p.drawText(tr, Qt.AlignCenter, st['tag'])
            p.setPen(fg); p.setFont(self.font(20, True)); p.drawText(QRectF(tr.right()+8, 0, W-tr.right()-14, H), Qt.AlignVCenter|Qt.AlignLeft, cd); return
        tr = QRectF((W-tw)/2, 10, tw, 22); p.setPen(Qt.NoPen); p.setBrush(tagc); p.drawRoundedRect(tr, 11, 11)
        p.setPen(Qt.white); p.drawText(tr, Qt.AlignCenter, st['tag'])
        p.setPen(fg); p.setFont(self.font(40 if l < 3600 else 32, True)); p.drawText(QRectF(0, 32, W, 48), Qt.AlignCenter, cd)
        sub = QColor(fg) if ph else QColor('#9fb3cf'); sub.setAlpha(200 if ph in ('son5', 'son1') else 255)
        p.setPen(sub); p.setFont(self.font(12)); p.drawText(QRectF(0, 80, W, 18), Qt.AlignCenter, label + ('  ·  ' + st['span'].replace(' – ', '–') if st['span'] else ''))
        bar = QRectF(18, H-17, W-36, 5); p.setPen(Qt.NoPen); p.setBrush(QColor(255, 255, 255, 30)); p.drawRoundedRect(bar, 2.5, 2.5)
        fill = QColor('#ff6b7a') if ph == 'son1' else QColor('#ffc526') if ph == 'son5' or st['kind'] == 'break' else QColor('#3d8bff')
        if st['frac'] > 0: p.setBrush(fill); p.drawRoundedRect(QRectF(bar.x(), bar.y(), bar.width()*min(1, st['frac']), bar.height()), 2.5, 2.5)
    def mousePressEvent(self, e): self.press = (e.globalPos(), self.pos()); self.moved = False
    def mouseMoveEvent(self, e):
        if self.press is None: return
        d = e.globalPos() - self.press[0]
        if self.moved or abs(d.x()) + abs(d.y()) > 10:
            self.moved = True; vp = self.main.scroll.viewport().geometry(); q = self.press[1] + d
            self.offset = (vp.right() - q.x() - self.width(), q.y() - vp.y()); self.place(); self.main.place_overlays()
    def mouseReleaseEvent(self, e):
        if self.press is not None and not self.moved: self.small = not self.small; self.tick(); self.main.place_overlays()
        self.press = None

class BellClock(QWidget):
    """Saat ve zile kalan süre: üst şeritte, PDF sekmelerinin sağında, tek satır."""
    W, H = 700, 42
    def __init__(self, parent=None, show_time=True):
        super().__init__(parent); self.show_time = show_time
        if not show_time: self.W = 450   # saat/tarih sol paneldeki büyük saatte; "Sonra" satırı yok
        self.setFixedSize(self.W, self.H); self.setAttribute(Qt.WA_TranslucentBackground)
        self.timer = QTimer(self); self.timer.timeout.connect(self.tick); self.timer.start(500)
        self.now = None   # tests can pin a time
        self.chimed = None; self.sound_dir = None
        if not show_time: self.fit_width()
    WARN_S = 300   # dersin bitmesine 5 dk kala hoş bir ses
    def fit_width(self, st=None):
        """Kutu içeriği kadar: ders dışında yalnızca etiket (boş uzun kutu kalmaz)."""
        import datetime
        from PyQt5.QtGui import QFontMetrics
        st = st or bell_state(self.now or datetime.datetime.now())
        tw = QFontMetrics(self.font(12, True)).horizontalAdvance(st['tag']) + 14
        if st['left'] is None: w = int(tw + 28)
        else:
            l = st['left']; cd = ('%d:%02d:%02d' % (l//3600, l%3600//60, l%60)) if l >= 3600 else ('%d:%02d' % (l//60, l%60))
            label = 'zile kalan' if st['kind'] in ('lesson','prep') else 'derse kalan' if st['kind'] == 'break' else 'okula kalan'
            w = 12 + 190 + 12 + QFontMetrics(self.font(22, True)).horizontalAdvance('0:00:00' if l >= 3600 else '00:00') + 6 + QFontMetrics(self.font(12)).horizontalAdvance(label) + 14
        if w != self.width(): self.setFixedWidth(w)
    def tick(self):
        import datetime
        now = self.now or datetime.datetime.now(); st = bell_state(now)
        # Yalnızca 5. dakikaya girerken bir kez (uygulama ders sonuna yakın açılırsa çalmaz).
        if st['kind'] == 'lesson' and st['left'] is not None and self.WARN_S - 30 < st['left'] <= self.WARN_S:
            key = (now.date(), st['tag'])
            if key != self.chimed:
                self.chimed = key
                try: play_sound(warn_chime_file(self.sound_dir or tempfile.gettempdir()))
                except Exception: pass
        if not self.show_time: self.fit_width(st)
        self.update()
    @staticmethod
    def font(px, bold=False):
        from PyQt5.QtGui import QFont
        f = QFont(ui_fonts().get('Poppins-Regular') or 'DejaVu Sans'); f.setPixelSize(px); f.setBold(bold); return f
    def paintEvent(self, e):
        import datetime
        now = self.now or datetime.datetime.now(); st = bell_state(now)
        if not self.show_time and st['left'] is None:   # ders dışı: yalnızca etiket, ortada
            p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); W_ = self.width()
            p.setPen(QPen(QColor(255, 255, 255, 30), 1)); p.setBrush(QColor(255, 255, 255, 14)); p.drawRoundedRect(QRectF(.5, .5, W_-1, self.H-1), 14, 14)
            p.setFont(self.font(12, True)); tw = p.fontMetrics().horizontalAdvance(st['tag'])+14
            p.setPen(Qt.NoPen); p.setBrush(QColor('#3a5577')); r_ = QRectF((W_-tw)/2, (self.H-22)/2, tw, 22); p.drawRoundedRect(r_, 11, 11)
            p.setPen(Qt.white); p.drawText(r_, Qt.AlignCenter, st['tag']); p.end(); return
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.TextAntialiasing)
        urgent = st['kind'] == 'lesson' and st['left'] is not None and st['left'] <= 120
        accent = QColor('#e23b4d') if urgent else QColor('#c99a2e') if st['kind'] == 'break' else QColor('#3a5577')
        p.setPen(QPen(accent, 1.5)); p.setBrush(QColor(255, 255, 255, 14)); p.drawRoundedRect(QRectF(.75, .75, self.width()-1.5, self.H-1.5), 14, 14)
        muted = QColor('#8fa3bd'); H = self.H; x = 12
        def text(s_, px, color, bold=False, top=0, h=H, align=Qt.AlignLeft|Qt.AlignVCenter, width=None):
            p.setPen(color); p.setFont(self.font(px, bold)); w = width or p.fontMetrics().horizontalAdvance(s_)
            p.drawText(QRectF(x, top, w, h), align, s_); return w
        # saat + saniye, altında tarih yok (yer kazanmak için tarih sağ uçta)
        if self.show_time:
            x += text(now.strftime('%H:%M'), 26, Qt.white, True); x += 2
            x += text(':%02d' % now.second, 13, muted, top=4) + 12
            p.setPen(QPen(QColor('#3a5577'), 1)); p.drawLine(QPointF(x, 8), QPointF(x, H-8)); x += 12
        # ders etiketi + saat aralığı (üstte), ilerleme çubuğu (altta)
        tagc = QColor('#8a6514') if st['kind'] == 'break' else QColor('#1d4f8f') if st['kind'] in ('lesson','prep','before') else QColor('#3a5577')
        p.setFont(self.font(12, True)); tw = p.fontMetrics().horizontalAdvance(st['tag'])+14
        p.setPen(Qt.NoPen); p.setBrush(tagc); p.drawRoundedRect(QRectF(x, 5, tw, 20), 10, 10)
        p.setPen(Qt.white); p.drawText(QRectF(x, 5, tw, 20), Qt.AlignCenter, st['tag'])
        block = 190
        p.setPen(muted); p.setFont(self.font(12)); p.drawText(QRectF(x+tw+6, 5, block-tw-6, 20), Qt.AlignLeft|Qt.AlignVCenter, st['span'])
        if st['left'] is not None:
            bar = QColor('#e23b4d') if urgent else QColor('#ffc526') if st['kind'] == 'break' else QColor('#3d8bff')
            p.setPen(Qt.NoPen); p.setBrush(QColor('#26405f')); p.drawRoundedRect(QRectF(x, 30, block, 5), 2.5, 2.5)
            if st['frac'] > 0: p.setBrush(bar); p.drawRoundedRect(QRectF(x, 30, block*min(1, st['frac']), 5), 2.5, 2.5)
        x += block + 12
        if st['left'] is not None:
            l = st['left']; cd = ('%d:%02d:%02d' % (l//3600, l%3600//60, l%60)) if l >= 3600 else ('%d:%02d' % (l//60, l%60))
            color = QColor('#ff6b7a') if urgent else QColor('#ffc526') if st['kind'] == 'break' else Qt.white
            x += text(cd, 22, color, True) + 6
            label = 'zile kalan' if st['kind'] in ('lesson','prep') else 'derse kalan' if st['kind'] == 'break' else 'okula kalan'
            x += text(label, 12, muted) + 12
        # sağda: tarih (üst) ve sıradaki ders (alt)
        rest = self.width() - x - 10
        p.setPen(muted); p.setFont(self.font(12))
        if self.show_time:
            date = '%s · %d %s' % (TR_DAYS[now.weekday()], now.day, TR_MONTHS[now.month-1])
            p.drawText(QRectF(x, 3, rest, 18), Qt.AlignRight|Qt.AlignVCenter, date)
            p.drawText(QRectF(x, 21, rest, 18), Qt.AlignRight|Qt.AlignVCenter, p.fontMetrics().elidedText(st['next'], Qt.ElideRight, int(rest)))

        p.end()

def warn_chime_file(folder):
    """Dersin bitmesine 5 dk kala: yumuşak, yükselen üç notalı çan (bir kez üretilir)."""
    import wave, struct
    path = os.path.join(folder, 'ders-uyari.wav')
    if os.path.isfile(path): return path
    os.makedirs(folder, exist_ok=True)
    rate = 44100; frames = []
    notes = [(0.0, 523.25), (0.32, 659.25), (0.64, 783.99)]   # C5 → E5 → G5
    for i in range(int(rate*2.8)):
        t = i/rate; v = 0.0
        for start, f in notes:
            dt = t-start
            if dt < 0: continue
            env = min(1, dt/.012)*math.exp(-dt*2.2)
            v += env*(math.sin(2*math.pi*f*dt) + .3*math.sin(2*math.pi*2*f*dt) + .1*math.sin(2*math.pi*3*f*dt))
        frames.append(struct.pack('<h', int(max(-1, min(1, v*.22))*32767)))
    with wave.open(path, 'wb') as w:
        w.setnchannels(1); w.setsampwidth(2); w.setframerate(rate); w.writeframes(b''.join(frames))
    return path

def rapt_sound_file(folder):
    """Short paper 'rapt' (slap + soft thump), generated once."""
    import wave, struct, random
    path = os.path.join(folder, 'rapt.wav')
    if os.path.isfile(path): return path
    os.makedirs(folder, exist_ok=True); rate = 44100; rng = random.Random(3); frames = []
    for i in range(int(rate*.16)):
        t = i/rate
        v = rng.uniform(-1, 1)*math.exp(-t*55)*.55 + math.sin(2*math.pi*140*t)*math.exp(-t*30)*.6
        frames.append(struct.pack('<h', int(max(-1, min(1, v*.5))*32767)))
    with wave.open(path, 'wb') as w:
        w.setnchannels(1); w.setsampwidth(2); w.setframerate(rate); w.writeframes(b''.join(frames))
    return path

def paint_postit(p, rect, pix, color, tilt=0, shadow=True):
    """A paper note: colour, tape strip, the captured picture inside."""
    p.save(); p.translate(rect.center()); p.rotate(tilt); r = QRectF(-rect.width()/2, -rect.height()/2, rect.width(), rect.height())
    if shadow: p.setPen(Qt.NoPen); p.setBrush(QColor(0, 0, 0, 70)); p.drawRect(r.translated(4, 5))
    p.setPen(Qt.NoPen); p.setBrush(QColor(color)); p.drawRect(r)
    m = max(6, r.width()*.05); top = max(10, r.height()*.1)
    inner = QRectF(r.left()+m, r.top()+top, r.width()-2*m, r.height()-top-m)
    if pix is not None and not pix.isNull():
        s = min(inner.width()/pix.width(), inner.height()/pix.height()); w, h = pix.width()*s, pix.height()*s
        p.setRenderHint(QPainter.SmoothPixmapTransform)
        p.drawPixmap(QRectF(inner.center().x()-w/2, inner.center().y()-h/2, w, h), pix, QRectF(pix.rect()))
    p.setBrush(QColor(255, 255, 255, 140)); tw = r.width()*.32
    p.rotate(-2); p.drawRect(QRectF(-tw/2, r.top()-6, tw, 14)); p.restore()

class PostItCard(QWidget):
    W = 300   # wide enough that a question stays readable on the board
    def __init__(self, pano, pix, color, name, tilt):
        super().__init__(pano.holder); self.pano, self.pix, self.color, self.name, self.tilt = pano, pix, color, name, tilt
        # Height follows the picture, so the whole question shows (no tiny strip).
        paper = self.W-24; m = max(6, paper*.05); inner = paper-2*m
        ratio = pix.height()/max(1, pix.width()) if pix is not None and not pix.isNull() else .6
        self.H = int(max(140, min(420, inner*ratio + max(10, (inner*ratio+30)*.1) + m + 30)))
        self.pending = False; self.setFixedSize(self.W, self.H); self.setCursor(Qt.PointingHandCursor)
        self.setToolTip('Dokunun: büyür · sağ üstteki ×: kaldırır')
    def close_rect(self): return QRectF(self.W-36, 4, 30, 30)
    def paintEvent(self, e):
        if self.pending: return
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        paint_postit(p, QRectF(10, 12, self.W-24, self.H-26), self.pix, self.color, self.tilt)
        c = self.close_rect(); p.setPen(Qt.NoPen); p.setBrush(QColor(18, 32, 52, 200)); p.drawEllipse(c)
        p.setPen(QPen(Qt.white, 2.4, Qt.SolidLine, Qt.RoundCap)); d = 7
        p.drawLine(QPointF(c.center().x()-d, c.center().y()-d), QPointF(c.center().x()+d, c.center().y()+d))
        p.drawLine(QPointF(c.center().x()+d, c.center().y()-d), QPointF(c.center().x()-d, c.center().y()+d)); p.end()
    def mouseReleaseEvent(self, e):
        if self.pending: return
        if self.close_rect().adjusted(-8, -8, 8, 8).contains(QPointF(e.pos())): self.pano.main.remove_postit(self)
        else: self.pano.main.show_postit(self)

class PostItPano(QScrollArea):
    """Post-it panosu: a narrow column right of the board."""
    TILTS = (-3, 2, -1.5, 3)
    def __init__(self, main):
        super().__init__(); self.main = main; self.cards = []
        self.setFixedWidth(PostItCard.W+18); self.setWidgetResizable(True); self.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.holder = QWidget(); self.box = QVBoxLayout(self.holder); self.box.setContentsMargins(4, 6, 4, 6); self.box.setSpacing(4)
        head = QHBoxLayout(); head.setContentsMargins(4, 0, 0, 0)
        title = QLabel('Post-it panosu'); title.setStyleSheet('color:#8fa3bd;font-size:13px;'); head.addWidget(title, 1)
        hide = QPushButton('Gizle  ›'); hide.setToolTip('Panoyu gizle (post-it\'ler silinmez)'); hide.setFixedHeight(38)
        hide.setStyleSheet('QPushButton{padding:0 12px;min-height:38px;max-height:38px;font-size:14px;}')
        hide.clicked.connect(lambda: self.main.set_pano_hidden(True)); head.addWidget(hide)
        self.box.addLayout(head); self.box.addStretch(); self.setWidget(self.holder)
    def add(self, pix, color, name, pending=False):
        card = PostItCard(self, pix, color, name, self.TILTS[len(self.cards) % len(self.TILTS)]); card.pending = pending
        self.box.insertWidget(self.box.count()-1, card); self.cards.append(card); return card
    def remove(self, card):
        if card in self.cards: self.cards.remove(card)
        card.hide(); card.deleteLater()
    def clear(self):
        for c in list(self.cards): self.remove(c)

class PostItFlight(QWidget):
    """Peel off (lift and tilt), shrink, fly to the board, land."""
    def __init__(self, parent, pix, color, start, end, tilt, done):
        super().__init__(parent); self.pix, self.color, self.start, self.end, self.tilt, self.done = pix, color, QRectF(start), QRectF(end), tilt, done
        self.setAttribute(Qt.WA_TransparentForMouseEvents); self.setGeometry(parent.rect()); self.t = 0; self.show(); self.raise_()
        self.anim = QVariantAnimation(self); self.anim.setStartValue(0.0); self.anim.setEndValue(1.0); self.anim.setDuration(720)
        self.anim.valueChanged.connect(self.step); self.anim.finished.connect(self.finish); self.anim.start()
    def step(self, v): self.t = v; self.update()
    def finish(self): self.hide(); self.deleteLater(); self.done()
    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); t = self.t
        if t < .3:   # peel: lift a little, tilt, paper colour comes in
            u = t/.3; r = self.start; c = r.center(); k = 1+.05*u
            rect = QRectF(c.x()-r.width()*k/2, c.y()-r.height()*k/2-10*u, r.width()*k, r.height()*k); rot = -6*u
            col = QColor(self.color); col.setAlpha(int(255*u))
            p.save(); p.translate(rect.center()); p.rotate(rot); p.setPen(Qt.NoPen); p.setBrush(QColor(0, 0, 0, int(60*u)))
            p.drawRect(QRectF(-rect.width()/2+6, -rect.height()/2+8, rect.width(), rect.height())); p.setBrush(Qt.white)
            p.drawRect(QRectF(-rect.width()/2, -rect.height()/2, rect.width(), rect.height())); p.restore()
            paint_postit(p, rect, self.pix, col.name() if u > .5 else '#ffffff', rot, shadow=False)
        else:        # fly with a small overshoot, then land
            u = QEasingCurve(QEasingCurve.OutBack).valueForProgress((t-.3)/.7)
            s0 = self.start; s0 = QRectF(s0.center().x()-s0.width()*.525, s0.center().y()-s0.height()*.525-10, s0.width()*1.05, s0.height()*1.05)
            e = QRectF(self.end.x()+10, self.end.y()+12, self.end.width()-24, self.end.height()-26)
            lerp = lambda a, b: a+(b-a)*u
            rect = QRectF(lerp(s0.x(), e.x()), lerp(s0.y(), e.y()), max(10, lerp(s0.width(), e.width())), max(10, lerp(s0.height(), e.height())))
            paint_postit(p, rect, self.pix, self.color, lerp(-6, self.tilt))
        p.end()

class PostItBig(QWidget):
    """Tap a post-it: it opens large over the board; tap again to put it back."""
    def __init__(self, scroll, pix, color):
        super().__init__(scroll); self.pix, self.color = pix, color; vp = scroll.viewport().geometry()
        # Card sized to the picture: as large as fits, small paper margins.
        mw, mh = vp.width()*.82, vp.height()*.8
        sc = min((mw-60)/max(1, pix.width()), (mh-90)/max(1, pix.height()), 3.0)
        w = int(pix.width()*sc+60); h = int(pix.height()*sc+90)
        self.setGeometry(vp.x()+(vp.width()-w)//2, vp.y()+(vp.height()-h)//2, w, h); self.setCursor(Qt.PointingHandCursor)
        self.setToolTip('Dokunun: küçülür'); self.show(); self.raise_()
    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        paint_postit(p, QRectF(14, 18, self.width()-30, self.height()-36), self.pix, self.color, 0); p.end()
    def mouseReleaseEvent(self, e): self.hide(); self.deleteLater()

class ThemePicker(QWidget):
    """Touch-sized theme chooser with live colour + pattern previews."""
    def __init__(self, main):
        super().__init__(main, Qt.Popup|Qt.FramelessWindowHint)
        self.main = main; self.setAttribute(Qt.WA_TranslucentBackground)
        outer = QVBoxLayout(self); outer.setContentsMargins(0, 0, 0, 0)
        panel = QWidget(); panel.setObjectName('picker'); outer.addWidget(panel)
        panel.setStyleSheet('QWidget#picker{background:#0b1426;border:1px solid #2a3b57;border-radius:18px;} QLabel{background:transparent;color:#e8eefc;}')
        layout = QVBoxLayout(panel); layout.setContentsMargins(18, 14, 18, 18); layout.setSpacing(12)
        title = QLabel('Tema seçin'); title.setStyleSheet('font-size:19px;font-weight:bold;color:#9fb3d1;'); layout.addWidget(title)
        grid = QGridLayout(); grid.setSpacing(12); layout.addLayout(grid)
        for i, key in enumerate(THEME_ORDER):
            t = THEMES[key]; tile = main.theme_tile(key)
            b = QPushButton(); b.setFixedSize(176, 118); b.setCursor(Qt.PointingHandCursor); b.setToolTip(t['name'])
            current = key == main.theme
            b.setStyleSheet('''QPushButton{border:%s;border-radius:14px;background-color:%s;background-image:url("%s");text-align:left;min-height:118px;max-height:118px;min-width:176px;max-width:176px;padding:0;}
                QPushButton:hover{border:2px solid %s;}''' % ('3px solid %s' % t['selb'] if current else '1px solid %s' % t['border'], t['view'], tile.replace('\\\\','/'), t['selb']))
            inner = QVBoxLayout(b); inner.setContentsMargins(10, 8, 10, 8); inner.addStretch()
            chip = QLabel(('✓  ' if current else '')+t['name']); chip.setWordWrap(True)
            chip.setStyleSheet('QLabel{background:qlineargradient(x1:0,y1:0,x2:0,y2:1,stop:0 %s,stop:1 %s);color:white;font-size:%dpx;font-weight:bold;border-radius:10px;padding:6px 10px;}' % (t['sel2'], t['sel'], 14 if len(t['name']) > 14 else 17))
            inner.addWidget(chip)
            b.clicked.connect(lambda checked=False, k=key: (self.main.apply_theme(k), self.close()))
            grid.addWidget(b, i//4, i % 4)

class ScreenToolbar(QWidget):
    def __init__(self, session):
        # A normal independent window stays reachable from the taskbar when
        # the main window is hidden, unlike tool windows grouped by some WMs.
        super().__init__(None,Qt.Window|Qt.WindowStaysOnTopHint)
        self.session=session;self.drag_from=None
        self.setWindowTitle('Ekrana yaz • Ümraniye Merkez Anadolu Lisesi')
        self.setWindowIcon(QIcon(LOGO))
    # Frameless panel: drag from any empty area (buttons keep their clicks).
    def mousePressEvent(self,e):
        if e.button()==Qt.LeftButton:self.drag_from=e.globalPos()-self.frameGeometry().topLeft()
    def mouseMoveEvent(self,e):
        if self.drag_from is not None:self.move(e.globalPos()-self.drag_from)
    def mouseReleaseEvent(self,e):self.drag_from=None
    def moveEvent(self,e):
        super().moveEvent(e)
        if self is self.session.toolbar:self.session.update_mask()
    def resizeEvent(self,e):
        super().resizeEvent(e)
        if self is self.session.toolbar:self.session.update_mask()
    def closeEvent(self,event):
        event.ignore(); self.session.leave()

class ScreenSession:
    """Independent screen-coordinate strokes and history, retained across mode switches."""
    overlay_mode=True
    @property
    def color(self): return self._color
    @color.setter
    def color(self, value):
        self._color = value
        if hasattr(self,'tools'): paint_tool_buttons(self.tools, self.tool_labels, self.tool, value)
