        self.main=main
        self.doc=fitz.open(); self.doc.new_page(width=1920,height=1080)
        self.page=0; self.tool='pen'; self.color='#e8132b'; self.backdrop=None
        self.marks={};self.undo_stack=[];self.redo_stack=[];self.dirty=False
        self.toolbar=ScreenToolbar(self)
