        self.toolbar.setWindowFlags(Qt.Window|Qt.FramelessWindowHint|Qt.WindowStaysOnTopHint)
        self.toolbar.setStyleSheet('''QWidget{background:#0a203e;color:white;font-family:"DejaVu Sans";font-size:13px;}
            QWidget#panel{border:1px solid #526780;border-radius:10px;}
            QPushButton#primary{background:#c61d2d;border:1px solid #e23b4d;font-weight:bold;font-size:14px;}
            QPushButton,QSpinBox{background:#203957;border:1px solid #526780;border-radius:8px;padding:0;}
            QPushButton:checked{background:#bc1b2b;border:2px solid #e23b4d;} QPushButton:hover{background:#365575;}''')
        self.floating.setStyleSheet('''QWidget{background:#0a203e;color:white;font-family:"DejaVu Sans";font-size:14px;}
            QPushButton{background:#203957;border:1px solid #526780;border-radius:7px;padding:9px;min-height:25px;}
            QPushButton:hover{background:#365575;}''')
        # Compact vertical panel on the left: icon-only buttons in two
        # columns; names are shown as tooltips. No full-width top band.
        outer=QHBoxLayout(self.toolbar);outer.setContentsMargins(0,0,0,0);outer.setSpacing(4);outer.setAlignment(Qt.AlignTop)
        panel=QWidget();panel.setObjectName('panel');outer.addWidget(panel)
        layout=QVBoxLayout(panel);layout.setContentsMargins(8,6,8,8);layout.setSpacing(6)
        grip=QLabel('⋮⋮');grip.setAlignment(Qt.AlignCenter);grip.setToolTip('Sürükleyerek taşıyın');grip.setStyleSheet('color:#8fa3bd;font-size:15px;')
        layout.addWidget(grip)
        grid=QGridLayout();grid.setSpacing(6);layout.addLayout(grid)
        def icon_button(label):
            b=QPushButton();b.setIcon(tool_icon(label));b.setIconSize(QSize(28,28));b.setFixedSize(54,54)
            b.setToolTip(label);b.setAccessibleName(label);return b
        # Only this panel stays on screen: "Masaüstünü kullan" keeps it
        # visible (no separate floating window); Kalem returns to writing.
        to_pdf=QPushButton("PDF'ye yaz");to_pdf.setIcon(tool_icon("PDF'ye yaz"));to_pdf.setIconSize(QSize(26,26))
        to_pdf.setObjectName('primary');to_pdf.setFixedHeight(54);to_pdf.setToolTip('Ekran modunu kapatıp PDF üzerine kalemle yazın')
        to_pdf.clicked.connect(self.write_on_pdf);grid.addWidget(to_pdf,0,0,1,2)
        self.tools={};self.tool_labels={}
        for i,(key,label) in enumerate([('pen','Kalem'),('highlight','Fosforlu'),('eraser','Silgi'),('smart','Akıllı seçim')]):
            b=icon_button(label);b.setCheckable(True);b.clicked.connect(lambda checked=False,k=key:self.set_tool(k))
            grid.addWidget(b,1+i//2,i%2);self.tools[key]=b;self.tool_labels[key]=label
        self.tools['pen'].setChecked(True)
        paint_tool_buttons(self.tools,self.tool_labels,self.tool,self.color)
        for i,(label,fn) in enumerate([('Geri al',self.undo),('İleri al',self.redo),('Tümünü sil',self.clear),('Notları PDF kaydet',self.save_notes)]):
            b=icon_button(label);b.clicked.connect(lambda checked=False,fn=fn:fn());grid.addWidget(b,3+i//2,i%2)
        self.mode=icon_button('Masaüstünü kullan');self.mode.setCheckable(True)
        self.mode.toggled.connect(self.set_passthrough)
        grid.addWidget(self.mode,5,0)
        dash=icon_button('Kesikli çizgi');dash.setCheckable(True);dash.clicked.connect(lambda checked=False:self.set_tool('dash'))
        grid.addWidget(dash,5,1);self.tools['dash']=dash;self.tool_labels['dash']='Kesikli çizgi'
        area=icon_button('Alan silgisi');area.setCheckable(True);area.clicked.connect(lambda checked=False:self.set_tool('area_eraser'))
        grid.addWidget(area,6,0);self.tools['area_eraser']=area;self.tool_labels['area_eraser']='Alan silgisi'
        # Kalem stili: the button shows the current style; tap opens the
